var A2L_QUESTIONS=[{id:"a2l_1",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 significa la 'L' en la clasificaci\xF3n A2L de ASHRAE?",opciones:["Liquid (l\xEDquido)","Lower flammability (inflamabilidad menor) \u2014 velocidad de llama \u226410 cm/s","Large (grande)","Low pressure (baja presi\xF3n)"],respuesta_correcta:1,explicacion:"La 'L' en A2L indica Lower flammability \u2014 inflamabilidad menor con velocidad de llama de 10 cm/s o menos. Diferente a A2 que tiene velocidad de llama entre 10-46 cm/s.",question:"What does the 'L' in ASHRAE's A2L classification mean?",options:["Liquid","Lower flammability \u2014 burning velocity \u226410 cm/s","Large","Low pressure"],explanation:"The 'L' in A2L indicates Lower flammability \u2014 mildly flammable with a burning velocity of 10 cm/s or less. Different from A2 which has a burning velocity between 10-46 cm/s."},{id:"a2l_2",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-22?",opciones:["A2L","A2","A1","B1"],respuesta_correcta:2,explicacion:"R-22 es A1 \u2014 baja toxicidad y sin inflamabilidad. Por eso fue tan ampliamente usado durante d\xE9cadas. Aunque tiene ODP=0.055 y GWP=1,810.",question:"What is the ASHRAE classification of R-22?",options:["A2L","A2","A1","B1"],explanation:"R-22 is A1 \u2014 low toxicity and non-flammable. This is why it was so widely used for decades. Although it has ODP=0.055 and GWP=1,810."},{id:"a2l_3",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-290 (propano)?",opciones:["A2L","A2","A1","A3"],respuesta_correcta:3,explicacion:"R-290 (propano) es A3 \u2014 altamente inflamable. Velocidad de llama 46 cm/s, MIE de solo 0.25 mJ. Por eso est\xE1 limitado a cargas muy peque\xF1as en equipos herm\xE9ticamente sellados.",question:"What is the ASHRAE classification of R-290 (propane)?",options:["A2L","A2","A1","A3"],explanation:"R-290 (propane) is A3 \u2014 highly flammable. Burning velocity 46 cm/s, MIE of only 0.25 mJ. This is why it is limited to very small charges in hermetically sealed equipment."},{id:"a2l_4",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-410A?",opciones:["A2L","A2","A1","B1"],respuesta_correcta:2,explicacion:"R-410A es A1 \u2014 baja toxicidad, sin inflamabilidad. A pesar de ser A1, tiene GWP=2,088 lo cual lo hace ambientalmente problem\xE1tico aunque seguro desde punto de vista de inflamabilidad.",question:"What is the ASHRAE classification of R-410A?",options:["A2L","A2","A1","B1"],explanation:"R-410A is A1 \u2014 low toxicity, non-flammable. Despite being A1, it has GWP=2,088 which makes it environmentally problematic even though safe from a flammability standpoint."},{id:"a2l_5",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-717 (amoniaco)?",opciones:["A2L","B2L","A1","B3"],respuesta_correcta:1,explicacion:"R-717 (amoniaco) es B2L \u2014 mayor toxicidad (B) y levemente inflamable (2L). Es altamente eficiente pero su toxicidad limita su uso a instalaciones industriales con personal capacitado.",question:"What is the ASHRAE classification of R-717 (ammonia)?",options:["A2L","B2L","A1","B3"],explanation:"R-717 (ammonia) is B2L \u2014 higher toxicity (B) and mildly flammable (2L). It is highly efficient but its toxicity limits its use to industrial facilities with trained personnel."},{id:"a2l_6",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 indica la letra 'B' en clasificaciones ASHRAE como B1, B2L?",opciones:["Baja toxicidad","Mayor nivel de toxicidad para humanos","Baja presi\xF3n de operaci\xF3n","Blends (mezclas)"],respuesta_correcta:1,explicacion:"La letra B en clasificaciones ASHRAE indica MAYOR toxicidad para humanos. A = baja toxicidad. B = mayor toxicidad. Los refrigerantes B requieren m\xE1s precauciones de ventilaci\xF3n y protecci\xF3n personal.",question:"What does the letter 'B' indicate in ASHRAE classifications like B1, B2L?",options:["Low toxicity","Higher level of human toxicity","Low operating pressure","Blends (mixtures)"],explanation:"The letter B in ASHRAE classifications indicates HIGHER toxicity for humans. A = low toxicity. B = higher toxicity. Class B refrigerants require more ventilation and personal protection precautions."},{id:"a2l_7",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1ntas clases de inflamabilidad existen en el sistema ASHRAE?",opciones:["2 clases: 1 y 2","3 clases: 1, 2, 3","4 clases: 1, 2L, 2, 3","5 clases"],respuesta_correcta:2,explicacion:"Existen 4 clases de inflamabilidad ASHRAE: 1 (sin propagaci\xF3n de llama), 2L (levemente inflamable, \u226410 cm/s), 2 (baja inflamabilidad), y 3 (alta inflamabilidad). La 2L fue agregada espec\xEDficamente para los nuevos A2L.",question:"How many flammability classes exist in the ASHRAE system?",options:["2 classes: 1 and 2","3 classes: 1, 2, 3","4 classes: 1, 2L, 2, 3","5 classes"],explanation:"There are 4 ASHRAE flammability classes: 1 (no flame propagation), 2L (mildly flammable, \u226410 cm/s), 2 (lower flammability), and 3 (higher flammability). Class 2L was added specifically for the new A2L refrigerants."},{id:"a2l_8",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 prueba est\xE1ndar usa ASHRAE para determinar la inflamabilidad de un refrigerante?",opciones:["ASTM E-681 modificado por ASHRAE","UL 508 est\xE1ndar de equipos","NFPA 70 c\xF3digo el\xE9ctrico","ISO 9001 calidad"],respuesta_correcta:0,explicacion:"La inflamabilidad de los refrigerantes se determina con la prueba ASTM E-681 modificada por ASHRAE. La llama debe ser continua extendida en arco de 90\xB0 para que el refrigerante sea clasificado como inflamable.",question:"What standard test does ASHRAE use to determine a refrigerant's flammability?",options:["ASTM E-681 modified by ASHRAE","UL 508 equipment standard","NFPA 70 electrical code","ISO 9001 quality"],explanation:"Refrigerant flammability is determined with the ASTM E-681 test modified by ASHRAE. The flame must be continuously sustained in a 90\xB0 arc for the refrigerant to be classified as flammable."},{id:"a2l_9",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 refrigerante A2L tiene clasificaci\xF3n ASHRAE A1 aunque tenga bajo GWP?",opciones:["R-32","R-1234yf","R-466A","R-454B"],respuesta_correcta:2,explicacion:"R-466A es el \xFAnico entre los nuevos refrigerantes de bajo GWP que logra clasificaci\xF3n A1 (no inflamable). GWP=733, significativamente menor que R-410A (2,088) pero sin las complicaciones de seguridad de los A2L.",question:"Which A2L refrigerant has an ASHRAE A1 classification despite having low GWP?",options:["R-32","R-1234yf","R-466A","R-454B"],explanation:"R-466A is the only new low-GWP refrigerant that achieves A1 (non-flammable) classification. GWP=733, significantly lower than R-410A (2,088) but without the safety complications of A2L."},{id:"a2l_10",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el n\xFAmero de serie de la norma ASHRAE que asigna clasificaciones de seguridad a refrigerantes?",opciones:["ASHRAE 15","ASHRAE 34","ASHRAE 62.1","ASHRAE 90.1"],respuesta_correcta:1,explicacion:"ASHRAE Standard 34 asigna designaciones y clasificaciones de seguridad a todos los refrigerantes (toxicidad e inflamabilidad). Tambi\xE9n establece los Refrigerant Concentration Limits (RCL).",question:"What is the number of the ASHRAE standard that assigns safety classifications to refrigerants?",options:["ASHRAE 15","ASHRAE 34","ASHRAE 62.1","ASHRAE 90.1"],explanation:"ASHRAE Standard 34 assigns designations and safety classifications to all refrigerants (toxicity and flammability). It also establishes the Refrigerant Concentration Limits (RCL)."},{id:"a2l_11",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el GWP del R-32?",opciones:["2,088","1,430","675","466"],respuesta_correcta:2,explicacion:"R-32 tiene GWP=675. Comparado con R-410A (2,088), es una reducci\xF3n del 68%. R-32 es el principal competidor de R-454B para reemplazar R-410A en sistemas residenciales.",question:"What is the GWP of R-32?",options:["2,088","1,430","675","466"],explanation:"R-32 has GWP=675. Compared to R-410A (2,088), this is a 68% reduction. R-32 is the main competitor to R-454B as a replacement for R-410A in residential systems."},{id:"a2l_12",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el GWP del R-454B?",opciones:["675","466","2,088","733"],respuesta_correcta:1,explicacion:"R-454B tiene GWP=466, la reducci\xF3n m\xE1s dram\xE1tica entre los sucesores del R-410A \u2014 una mejora del 78%. Por eso es el refrigerante aprobado por los principales fabricantes en USA para equipos nuevos desde 2025.",question:"What is the GWP of R-454B?",options:["675","466","2,088","733"],explanation:"R-454B has GWP=466, the most dramatic reduction among R-410A successors \u2014 a 78% improvement. This is why it is the refrigerant approved by major manufacturers in the USA for new equipment starting in 2025."},{id:"a2l_13",categoria:"A2L_CONCEPTOS",pregunta:"\xBFDe qu\xE9 componentes est\xE1 formado el R-454B?",opciones:["R-32 + R-125","R-32 + R-1234yf","R-32 + R-134a","R-125 + R-1234yf"],respuesta_correcta:1,explicacion:"R-454B = R-32 (31.6%) + R-1234yf (68.4%). La combinaci\xF3n de HFC + HFO logra: GWP bajo (466), presiones similares a R-410A, y clasificaci\xF3n A2L.",question:"What components make up R-454B?",options:["R-32 + R-125","R-32 + R-1234yf","R-32 + R-134a","R-125 + R-1234yf"],explanation:"R-454B = R-32 (31.6%) + R-1234yf (68.4%). The combination of HFC + HFO achieves: low GWP (466), pressures similar to R-410A, and A2L classification."},{id:"a2l_14",categoria:"A2L_CONCEPTOS",pregunta:"\xBFDe qu\xE9 componentes est\xE1 formado el R-452B?",opciones:["R-32 + R-1234yf (2 componentes)","R-32 + R-125 + R-1234yf (3 componentes)","R-32 + R-134a + R-125","R-410A + R-1234yf"],respuesta_correcta:1,explicacion:"R-452B = R-32 + R-125 + R-1234yf (mezcla ternaria de tres componentes). GWP=676, muy similar al R-32 puro pero con la ventaja de permitir topped off en caso de fugas peque\xF1as.",question:"What components make up R-452B?",options:["R-32 + R-1234yf (2 components)","R-32 + R-125 + R-1234yf (3 components)","R-32 + R-134a + R-125","R-410A + R-1234yf"],explanation:"R-452B = R-32 + R-125 + R-1234yf (ternary blend of three components). GWP=676, very similar to pure R-32 but with the advantage of allowing topped-off in case of small leaks."},{id:"a2l_15",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 es un refrigerante HFO?",opciones:["Hydrofluorocarbon \u2014 contiene H, F y C con solo enlaces simples","Hydrofluoroolefin \u2014 contiene H, F y C con al menos un doble enlace de carbono","Hydrocarbon fluoride \u2014 derivado del propano","High Frequency Oil \u2014 aceite especial para A2L"],respuesta_correcta:1,explicacion:"HFO (Hydrofluoroolefin) = contiene H, F y C con al menos un DOBLE ENLACE de carbono. Este doble enlace es lo que les da bajo GWP (se degradan r\xE1pido en la atm\xF3sfera) y tambi\xE9n los hace levemente inflamables.",question:"What is an HFO refrigerant?",options:["Hydrofluorocarbon \u2014 contains H, F and C with only single bonds","Hydrofluoroolefin \u2014 contains H, F and C with at least one carbon double bond","Hydrocarbon fluoride \u2014 derived from propane","High Frequency Oil \u2014 special oil for A2L"],explanation:"HFO (Hydrofluoroolefin) = contains H, F, and C with at least one DOUBLE BOND of carbon. This double bond is what gives them low GWP (they degrade quickly in the atmosphere) and also makes them mildly flammable."},{id:"a2l_16",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la diferencia qu\xEDmica entre HFC y HFO?",opciones:["Solo el n\xFAmero de \xE1tomos de fl\xFAor","Los HFO tienen al menos un doble enlace de carbono (olefin), los HFC solo tienen enlaces simples","Los HFC son m\xE1s pesados","No hay diferencia qu\xEDmica, solo comercial"],respuesta_correcta:1,explicacion:"HFC = solo enlaces simples entre carbonos (saturado). HFO = al menos un doble enlace de carbono (insaturado/olefin). Esta diferencia estructural hace que los HFO se degraden mucho m\xE1s r\xE1pido en la atm\xF3sfera, resultando en GWP muy bajo.",question:"What is the chemical difference between HFC and HFO?",options:["Only the number of fluorine atoms","HFOs have at least one carbon double bond (olefin), HFCs only have single bonds","HFCs are heavier","There is no chemical difference, only commercial"],explanation:"HFC = only single bonds between carbons (saturated). HFO = at least one carbon double bond (unsaturated/olefin). This structural difference causes HFOs to degrade much faster in the atmosphere, resulting in very low GWP."},{id:"a2l_17",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 refrigerante A2L es el principal usado en A/C automotriz nuevo?",opciones:["R-32","R-454B","R-1234yf","R-452B"],respuesta_correcta:2,explicacion:"R-1234yf es el refrigerante A2L usado en A/C automotriz, reemplazando al R-134a (GWP=1,430). R-1234yf tiene GWP<1 y aunque es levemente inflamable (A2L), su MIE extremadamente alto (5,000-10,000 mJ) lo hace muy dif\xEDcil de encender.",question:"Which A2L refrigerant is primarily used in new automotive A/C?",options:["R-32","R-454B","R-1234yf","R-452B"],explanation:"R-1234yf is the A2L refrigerant used in automotive A/C, replacing R-134a (GWP=1,430). R-1234yf has GWP<1 and although mildly flammable (A2L), its extremely high MIE (5,000-10,000 mJ) makes it very difficult to ignite."},{id:"a2l_18",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la presi\xF3n de succi\xF3n del R-32 a 45\xB0F de temperatura de evaporaci\xF3n?",opciones:["68-75 PSI (igual que R-22)","118-125 PSI (igual que R-410A)","133 PSI (ligeramente mayor que R-410A)","50 PSI (menor que R-22)"],respuesta_correcta:2,explicacion:"R-32 a 45\xB0F de saturaci\xF3n: aproximadamente 133 PSI. Es ligeramente MAYOR que R-410A (130 PSI) a la misma temperatura. Las herramientas y manifolds deben estar rated para estas presiones.",question:"What is the suction pressure of R-32 at 45\xB0F evaporating temperature?",options:["68-75 PSI (same as R-22)","118-125 PSI (same as R-410A)","133 PSI (slightly higher than R-410A)","50 PSI (lower than R-22)"],explanation:"R-32 at 45\xB0F saturation: approximately 133 PSI. This is slightly HIGHER than R-410A (130 PSI) at the same temperature. Tools and manifolds must be rated for these pressures."},{id:"a2l_19",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la presi\xF3n de alta (descarga) del R-454B a 120\xB0F de temperatura de condensaci\xF3n?",opciones:["250-260 PSI (igual que R-22)","400-420 PSI (igual que R-410A)","~397 PSI (liquid) / ~386 PSI (vapor)","500+ PSI"],respuesta_correcta:2,explicacion:"R-454B a 120\xB0F: Liquid pressure ~397 PSI, Vapor pressure ~386 PSI. Muy similar al R-410A, por eso la transici\xF3n no requiere cambios dr\xE1sticos en dise\xF1o de sistemas aunque s\xED componentes certificados A2L.",question:"What is the high-side (discharge) pressure of R-454B at 120\xB0F condensing temperature?",options:["250-260 PSI (same as R-22)","400-420 PSI (same as R-410A)","~397 PSI (liquid) / ~386 PSI (vapor)","500+ PSI"],explanation:"R-454B at 120\xB0F: Liquid pressure ~397 PSI, Vapor pressure ~386 PSI. Very similar to R-410A, so the transition does not require drastic changes in system design although A2L-certified components are needed."},{id:"a2l_20",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el aceite lubricante correcto para sistemas con R-32 o R-454B?",opciones:["Aceite mineral (MO)","Aceite alquilbenceno (AB)","Aceite POE (Polyolester)","Aceite PAG"],respuesta_correcta:2,explicacion:"Los refrigerantes HFC y HFO (R-32, R-454B, R-452B, R-1234yf) requieren aceite POE (Polyolester). El aceite mineral NO es miscible con HFCs \u2014 se acumula en el evaporador causando problemas de transferencia de calor.",question:"What is the correct lubricant oil for R-32 or R-454B systems?",options:["Mineral oil (MO)","Alkylbenzene oil (AB)","POE oil (Polyolester)","PAG oil"],explanation:"HFC and HFO refrigerants (R-32, R-454B, R-452B, R-1234yf) require POE (Polyolester) oil. Mineral oil is NOT miscible with HFCs \u2014 it accumulates in the evaporator causing heat transfer problems."},{id:"a2l_21",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el LFL (Lower Flammability Limit) del R-32?",opciones:["6.2%","14.4%","3.9%","2.1%"],respuesta_correcta:1,explicacion:"R-32 tiene LFL=14.4%. Para comparar: propano (A3)=2.1%, R-1234yf=6.2%, amoniaco=15%. El LFL alto del R-32 significa que necesita alta concentraci\xF3n para encenderse, haci\xE9ndolo m\xE1s seguro que los A3.",question:"What is the LFL (Lower Flammability Limit) of R-32?",options:["6.2%","14.4%","3.9%","2.1%"],explanation:"R-32 has LFL=14.4%. For comparison: propane (A3)=2.1%, R-1234yf=6.2%, ammonia=15%. The high LFL of R-32 means it needs a high concentration to ignite, making it safer than A3 refrigerants."},{id:"a2l_22",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el LFL del R-454B?",opciones:["14.4%","11.8%","6.2%","2.1%"],respuesta_correcta:1,explicacion:"R-454B tiene LFL=11.8%, ligeramente menor que R-32 (14.4%) pero mucho mayor que propano (2.1%). A\xFAn as\xED, requiere concentraci\xF3n significativa antes de volverse inflamable.",question:"What is the LFL of R-454B?",options:["14.4%","11.8%","6.2%","2.1%"],explanation:"R-454B has LFL=11.8%, slightly lower than R-32 (14.4%) but much higher than propane (2.1%). It still requires significant concentration before becoming flammable."},{id:"a2l_23",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el LFL del R-1234yf?",opciones:["14.4%","11.8%","6.2%","2.1%"],respuesta_correcta:2,explicacion:"R-1234yf tiene LFL=6.2%. Aunque es m\xE1s bajo que R-32 (14.4%), su MIE extremadamente alto (5,000-10,000 mJ) lo hace de los m\xE1s dif\xEDciles de encender entre los A2L.",question:"What is the LFL of R-1234yf?",options:["14.4%","11.8%","6.2%","2.1%"],explanation:"R-1234yf has LFL=6.2%. Although lower than R-32 (14.4%), its extremely high MIE (5,000-10,000 mJ) makes it one of the most difficult to ignite among A2L refrigerants."},{id:"a2l_24",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 es el MIE (Minimum Ignition Energy)?",opciones:["La presi\xF3n m\xEDnima para operar el sistema","La energ\xEDa el\xE9ctrica m\xEDnima en milijoules para encender la mezcla refrigerante-aire","La temperatura m\xEDnima de almacenamiento","El voltaje m\xEDnimo del equipo el\xE9ctrico"],respuesta_correcta:1,explicacion:"MIE = Minimum Ignition Energy = energ\xEDa m\xEDnima de chispa (mJ) necesaria para encender una mezcla refrigerante-aire. MIE alto = m\xE1s dif\xEDcil de encender. R-1234yf: 5,000-10,000 mJ (muy dif\xEDcil). R-290 propano: 0.25 mJ (muy f\xE1cil).",question:"What is MIE (Minimum Ignition Energy)?",options:["The minimum pressure to operate the system","The minimum electrical energy in millijoules to ignite the refrigerant-air mixture","The minimum storage temperature","The minimum voltage of the electrical equipment"],explanation:"MIE = Minimum Ignition Energy = minimum spark energy (mJ) needed to ignite a refrigerant-air mixture. High MIE = harder to ignite. R-1234yf: 5,000-10,000 mJ (very difficult). R-290 propane: 0.25 mJ (very easy)."},{id:"a2l_25",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el MIE del R-32?",opciones:["0.25 mJ (igual que propano)","5,000-10,000 mJ (igual que R-1234yf)","30-100 mJ","0.38 mJ"],respuesta_correcta:2,explicacion:"R-32 tiene MIE=30-100 mJ. Para comparar: propano (A3)=0.25 mJ, R-1234yf=5,000-10,000 mJ. Una buj\xEDa de alto voltaje produce 20-30 mJ \u2014 en el l\xEDmite inferior del rango de R-32.",question:"What is the MIE of R-32?",options:["0.25 mJ (same as propane)","5,000-10,000 mJ (same as R-1234yf)","30-100 mJ","0.38 mJ"],explanation:"R-32 has MIE=30-100 mJ. For comparison: propane (A3)=0.25 mJ, R-1234yf=5,000-10,000 mJ. A high-voltage spark plug produces 20-30 mJ \u2014 at the lower range of R-32."},{id:"a2l_26",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la temperatura de auto-ignici\xF3n del R-32?",opciones:["200\xB0C (392\xB0F)","405\xB0C (761\xB0F)","648\xB0C (1,198\xB0F)","100\xB0C (212\xB0F)"],respuesta_correcta:2,explicacion:"R-32 tiene temperatura de auto-ignici\xF3n de 648\xB0C (1,198\xB0F). Esta temperatura extremadamente alta significa que superficies calientes de equipos HVAC normales (generalmente <200\xB0C) no pueden encenderlo.",question:"What is the auto-ignition temperature of R-32?",options:["200\xB0C (392\xB0F)","405\xB0C (761\xB0F)","648\xB0C (1,198\xB0F)","100\xB0C (212\xB0F)"],explanation:"R-32 has an auto-ignition temperature of 648\xB0C (1,198\xB0F). This extremely high temperature means that hot surfaces of normal HVAC equipment (generally <200\xB0C) cannot ignite it."},{id:"a2l_27",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la velocidad de llama del R-32?",opciones:["46 cm/s (igual que propano)","6.7 cm/s (\u226410 cm/s \u2014 A2L)","23 cm/s (A2)","0 cm/s (A1)"],respuesta_correcta:1,explicacion:"R-32 tiene velocidad de llama de 6.7 cm/s, dentro del l\xEDmite A2L (\u226410 cm/s). Comparado: propano (A3)=46 cm/s. Esta baja velocidad hace que el fuego de R-32 se propague lentamente y sea menos probable que se extienda.",question:"What is the burning velocity of R-32?",options:["46 cm/s (same as propane)","6.7 cm/s (\u226410 cm/s \u2014 A2L)","23 cm/s (A2)","0 cm/s (A1)"],explanation:"R-32 has a burning velocity of 6.7 cm/s, within the A2L limit (\u226410 cm/s). Compared: propane (A3)=46 cm/s. This low velocity means R-32 fire propagates slowly and is less likely to spread."},{id:"a2l_28",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el calor de combusti\xF3n del R-32 vs R-290 propano?",opciones:["Son iguales","R-32: ~3,869 BTU/lb. Propano: ~19,905 BTU/lb","R-32 libera m\xE1s energ\xEDa que propano","El calor de combusti\xF3n no aplica a refrigerantes"],respuesta_correcta:1,explicacion:"R-32 libera ~3,869 BTU/lb si se quema. El propano libera ~19,905 BTU/lb \u2014 m\xE1s de 5 veces m\xE1s energ\xEDa. Esto significa que un incendio de R-32 tiene MUCHO menor probabilidad de propagarse a materiales cercanos.",question:"What is the heat of combustion of R-32 vs R-290 propane?",options:["They are equal","R-32: ~3,869 BTU/lb. Propane: ~19,905 BTU/lb","R-32 releases more energy than propane","Heat of combustion does not apply to refrigerants"],explanation:"R-32 releases ~3,869 BTU/lb if burned. Propane releases ~19,905 BTU/lb \u2014 more than 5 times more energy. This means an R-32 fire has MUCH lower probability of spreading to nearby materials."},{id:"a2l_29",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el RCL (Refrigerant Concentration Limit) del R-32 en PPM?",opciones:["140,000 PPM","50,000 PPM","36,000 PPM","5,300 PPM"],respuesta_correcta:2,explicacion:"R-32 tiene RCL=36,000 PPM. Comparado: R-410A (A1)=140,000 PPM, R-290 propano (A3)=5,300 PPM. El A2L tiene RCL intermedio entre los extremos de A1 y A3.",question:"What is the RCL (Refrigerant Concentration Limit) of R-32 in PPM?",options:["140,000 PPM","50,000 PPM","36,000 PPM","5,300 PPM"],explanation:"R-32 has RCL=36,000 PPM. Compared: R-410A (A1)=140,000 PPM, R-290 propane (A3)=5,300 PPM. A2L has an intermediate RCL between A1 and A3 extremes."},{id:"a2l_30",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el RCL del R-454B?",opciones:["36,000 PPM","19,000 PPM","50,000 PPM","140,000 PPM"],respuesta_correcta:1,explicacion:"R-454B tiene RCL=19,000 PPM, m\xE1s restrictivo que R-32 (36,000 PPM). Esto refleja su LFL m\xE1s bajo (11.8% vs 14.4%). El RCL es el l\xEDmite m\xE1s restrictivo entre toxicidad, asfixia e inflamabilidad.",question:"What is the RCL of R-454B?",options:["36,000 PPM","19,000 PPM","50,000 PPM","140,000 PPM"],explanation:"R-454B has RCL=19,000 PPM, more restrictive than R-32 (36,000 PPM). This reflects its lower LFL (11.8% vs 14.4%). The RCL is the most restrictive limit between toxicity, asphyxiation, and flammability."},{id:"a2l_31",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 protocolo internacional regula la eliminaci\xF3n de refrigerantes que agotan el ozono?",opciones:["Protocolo de Kioto (1997)","Protocolo de Montreal (1987)","Acuerdo de Par\xEDs (2015)","Enmienda de Kigali (2016)"],respuesta_correcta:1,explicacion:"El Protocolo de Montreal (1987) fue el primer acuerdo internacional para eliminar CFCs y HCFCs. La Enmienda de Kigali (2016) lo extendi\xF3 para incluir la reducci\xF3n gradual de HFCs de alto GWP.",question:"What international protocol regulates the phase-out of ozone-depleting refrigerants?",options:["Kyoto Protocol (1997)","Montreal Protocol (1987)","Paris Agreement (2015)","Kigali Amendment (2016)"],explanation:"The Montreal Protocol (1987) was the first international agreement to phase out CFCs and HCFCs. The Kigali Amendment (2016) extended it to include the gradual phase-down of high-GWP HFCs."},{id:"a2l_32",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 enmienda al Protocolo de Montreal incluy\xF3 la reducci\xF3n de HFCs?",opciones:["Enmienda de Londres (1990)","Enmienda de Copenhague (1992)","Enmienda de Kigali (2016)","Enmienda de Pek\xEDn (1999)"],respuesta_correcta:2,explicacion:"La Enmienda de Kigali (2016) fue espec\xEDficamente dise\xF1ada para reducir gradualmente la producci\xF3n y uso de HFCs, que aunque no afectan el ozono, tienen alto GWP. Los A2L como R-32 y R-454B son alternativas con menor GWP.",question:"What amendment to the Montreal Protocol included the phase-down of HFCs?",options:["London Amendment (1990)","Copenhagen Amendment (1992)","Kigali Amendment (2016)","Beijing Amendment (1999)"],explanation:"The Kigali Amendment (2016) was specifically designed to gradually reduce the production and use of HFCs, which although they don't affect the ozone layer, have high GWP. A2L refrigerants like R-32 and R-454B are alternatives with lower GWP."},{id:"a2l_33",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el ODP del R-32?",opciones:["0.055 (igual que R-22)","0","1.0","0.01"],respuesta_correcta:1,explicacion:"R-32 tiene ODP=0 \u2014 no da\xF1a la capa de ozono porque es un HFC (no contiene cloro). Esto lo diferencia fundamentalmente de R-22 (HCFC, ODP=0.055) que ten\xEDa efecto destructivo en el ozono.",question:"What is the ODP of R-32?",options:["0.055 (same as R-22)","0","1.0","0.01"],explanation:"R-32 has ODP=0 \u2014 it does not damage the ozone layer because it is an HFC (does not contain chlorine). This fundamentally differentiates it from R-22 (HCFC, ODP=0.055) which had a destructive effect on ozone."},{id:"a2l_34",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPor qu\xE9 los HFO tienen GWP tan bajo (menor a 1)?",opciones:["Porque son m\xE1s pesados que el aire","Su doble enlace de carbono hace que se degraden muy r\xE1pidamente en la trop\xF3sfera (d\xEDas vs a\xF1os)","Porque no contienen carbono","Porque son naturales"],respuesta_correcta:1,explicacion:"Los HFO se degradan en la trop\xF3sfera en d\xEDas o semanas gracias a su doble enlace de carbono (reacciona con el radical OH). Comparado: los HFC tardan a\xF1os o d\xE9cadas en degradarse, por eso tienen GWP alto.",question:"Why do HFOs have such low GWP (less than 1)?",options:["Because they are heavier than air","Their carbon double bond causes them to degrade very rapidly in the troposphere (days vs years)","Because they do not contain carbon","Because they are natural"],explanation:"HFOs degrade in the troposphere in days or weeks thanks to their carbon double bond (reacts with the OH radical). Compared: HFCs take years or decades to degrade, which is why they have high GWP."},{id:"a2l_35",categoria:"A2L_CONCEPTOS",pregunta:"\xBFEn qu\xE9 a\xF1o se prohibi\xF3 la producci\xF3n e importaci\xF3n de R-22 en USA?",opciones:["2010","2015","2020","2025"],respuesta_correcta:2,explicacion:"El 1 de enero de 2020 se prohibi\xF3 la producci\xF3n e importaci\xF3n de R-22 en USA. Desde 2010 ya no se pod\xEDa usar en equipos NUEVOS. El R-22 recuperado puede seguir us\xE1ndose para servicio de equipos existentes.",question:"In what year was the production and import of R-22 banned in the USA?",options:["2010","2015","2020","2025"],explanation:"On January 1, 2020, the production and import of R-22 was banned in the USA. Since 2010, it could no longer be used in NEW equipment. Recovered R-22 can continue to be used for servicing existing equipment."},{id:"a2l_36",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el GWP base de referencia contra el que se comparan todos los refrigerantes?",opciones:["R-11 con GWP=1","CO2 (R-744) con GWP=1","R-22 con GWP=1","Metano con GWP=1"],respuesta_correcta:1,explicacion:"El CO2 (R-744) tiene GWP=1 y es la referencia base. Todo los dem\xE1s se miden comparando cu\xE1nto calentamiento produce 1 kg del refrigerante vs 1 kg de CO2 en un per\xEDodo de 100 a\xF1os.",question:"What is the baseline GWP reference against which all refrigerants are compared?",options:["R-11 with GWP=1","CO2 (R-744) with GWP=1","R-22 with GWP=1","Methane with GWP=1"],explanation:"CO2 (R-744) has GWP=1 and is the baseline reference. All others are measured by comparing how much warming 1 kg of the refrigerant produces vs 1 kg of CO2 over a 100-year period."},{id:"a2l_37",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPor qu\xE9 el R-410A se considera un 'super contaminante' clim\xE1tico?",opciones:["Porque da\xF1a el ozono","Porque tiene GWP=2,088 \u2014 2,088 veces m\xE1s potente que el CO2 como gas de efecto invernadero","Porque es t\xF3xico para humanos","Porque es m\xE1s pesado que el aire"],respuesta_correcta:1,explicacion:"R-410A tiene GWP=2,088. Esto significa que 1 kg de R-410A liberado a la atm\xF3sfera tiene el mismo efecto de calentamiento que 2,088 kg de CO2. Por eso la EPA lo est\xE1 eliminando y reemplazando con A2L de menor GWP.",question:"Why is R-410A considered a climate 'super pollutant'?",options:["Because it damages the ozone layer","Because it has GWP=2,088 \u2014 2,088 times more potent than CO2 as a greenhouse gas","Because it is toxic to humans","Because it is heavier than air"],explanation:"R-410A has GWP=2,088. This means 1 kg of R-410A released to the atmosphere has the same warming effect as 2,088 kg of CO2. This is why the EPA is phasing it out and replacing it with lower-GWP A2L refrigerants."},{id:"a2l_38",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el GWP del R-404A y por qu\xE9 se est\xE1 eliminando agresivamente?",opciones:["GWP=675 (igual que R-32)","GWP=2,088 (igual que R-410A)","GWP=3,920 \u2014 uno de los m\xE1s altos entre refrigerantes comunes","GWP<1 (igual que R-1234yf)"],respuesta_correcta:2,explicacion:"R-404A tiene GWP=3,920, uno de los m\xE1s altos entre los refrigerantes comunes. Se usa en refrigeraci\xF3n comercial (supermercados) y est\xE1 siendo reemplazado agresivamente por R-448A, R-449A y R-449B.",question:"What is the GWP of R-404A and why is it being aggressively phased out?",options:["GWP=675 (same as R-32)","GWP=2,088 (same as R-410A)","GWP=3,920 \u2014 one of the highest among common refrigerants","GWP<1 (same as R-1234yf)"],explanation:"R-404A has GWP=3,920, one of the highest among common refrigerants. It is used in commercial refrigeration (supermarkets) and is being aggressively replaced by R-448A, R-449A, and R-449B."},{id:"a2l_39",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 programa de la EPA eval\xFAa y aprueba sustitutos para refrigerantes que agotan el ozono?",opciones:["Secci\xF3n 608 \u2014 recuperaci\xF3n de refrigerantes","SNAP (Significant New Alternatives Policy) \u2014 Secci\xF3n 612","SNAP 23 \u2014 lista de aprobados 2023","Programa ARI 700"],respuesta_correcta:1,explicacion:"SNAP (Significant New Alternatives Policy) bajo la Secci\xF3n 612 de la Clean Air Act eval\xFAa sustitutos para sustancias que agotan el ozono y genera listas de sustitutos aceptables e inaceptables por sector industrial.",question:"What EPA program evaluates and approves substitutes for ozone-depleting refrigerants?",options:["Section 608 \u2014 refrigerant recovery","SNAP (Significant New Alternatives Policy) \u2014 Section 612","SNAP 23 \u2014 2023 approved list","ARI 700 Program"],explanation:"SNAP (Significant New Alternatives Policy) under Section 612 of the Clean Air Act evaluates substitutes for ozone-depleting substances and generates lists of acceptable and unacceptable substitutes by industrial sector."},{id:"a2l_40",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1les refrigerantes aprob\xF3 EPA SNAP 23 para A/C residencial y comercial ligero?",opciones:["Solo R-32","R-452B, R-454A, R-454B, R-454C, R-457A y R-32 (todos sujetos a condiciones)","Cualquier A2L sin restricciones","Solo R-1234yf"],respuesta_correcta:1,explicacion:"SNAP 23 aprob\xF3 para A/C residencial/comercial ligero: R-452B, R-454A, R-454B, R-454C, R-457A, y R-32. Todos sujetos a condiciones de uso espec\xEDficas incluyendo requisitos de instalaci\xF3n A2L.",question:"Which refrigerants did EPA SNAP 23 approve for residential and light commercial A/C?",options:["Only R-32","R-452B, R-454A, R-454B, R-454C, R-457A, and R-32 (all subject to conditions)","Any A2L without restrictions","Only R-1234yf"],explanation:"SNAP 23 approved for residential/light commercial A/C: R-452B, R-454A, R-454B, R-454C, R-457A, and R-32. All subject to specific use conditions including A2L installation requirements."},{id:"a2l_41",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el extinguidor correcto para trabajar con refrigerantes A2L?",opciones:["Clase A \u2014 combustibles s\xF3lidos","Clase B (polvo seco) o ABC","Clase C \u2014 equipos el\xE9ctricos","Clase D \u2014 metales combustibles"],respuesta_correcta:1,explicacion:"Clase B (polvo seco, Dry Powder) o ABC. La Clase B cubre gases y l\xEDquidos inflamables. Siempre tenerlo disponible y SABER USARLO antes de comenzar cualquier trabajo con refrigerante inflamable.",question:"What is the correct fire extinguisher for working with A2L refrigerants?",options:["Class A \u2014 solid combustibles","Class B (dry powder) or ABC","Class C \u2014 electrical equipment","Class D \u2014 combustible metals"],explanation:"Class B (dry powder) or ABC. Class B covers flammable gases and liquids. Always have it available and KNOW HOW TO USE IT before beginning any work with flammable refrigerant."},{id:"a2l_42",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPor qu\xE9 los refrigerantes son peligrosos en espacios confinados aunque no sean inflamables?",opciones:["Solo son peligrosos si son inflamables","Desplazan el ox\xEDgeno del aire, pudiendo causar asfixia por falta de ox\xEDgeno","Solo son peligrosos si son t\xF3xicos","No son peligrosos en espacios confinados"],respuesta_correcta:1,explicacion:"TODOS los refrigerantes (A1, A2L, A3) pueden causar asfixia en espacios confinados al desplazar el ox\xEDgeno del aire. La mayor\xEDa de accidentes mortales con refrigerantes son por ASFIXIA, no por toxicidad directa.",question:"Why are refrigerants dangerous in confined spaces even if they are not flammable?",options:["They are only dangerous if flammable","They displace oxygen from the air, potentially causing asphyxiation from lack of oxygen","They are only dangerous if toxic","They are not dangerous in confined spaces"],explanation:"ALL refrigerants (A1, A2L, A3) can cause asphyxiation in confined spaces by displacing oxygen from the air. Most fatal refrigerant accidents are from ASPHYXIATION, not from direct toxicity."},{id:"a2l_43",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 equipo de protecci\xF3n personal b\xE1sico se usa al trabajar con refrigerantes?",opciones:["Solo guantes de hule","Gafas de seguridad y guantes como m\xEDnimo","Solo mascarilla N95","No se requiere PPE especial para refrigerantes"],respuesta_correcta:1,explicacion:"El PPE m\xEDnimo para trabajo con refrigerantes incluye gafas de seguridad (protecci\xF3n contra salpicaduras de refrigerante l\xEDquido que puede causar quemaduras/congelaci\xF3n) y guantes. Para A2L a\xF1adir protecci\xF3n adicional seg\xFAn SDS del refrigerante espec\xEDfico.",question:"What basic personal protective equipment is used when working with refrigerants?",options:["Only rubber gloves","Safety glasses and gloves at minimum","Only N95 mask","No special PPE required for refrigerants"],explanation:"Minimum PPE for refrigerant work includes safety glasses (protection against liquid refrigerant splashes that can cause burns/frostbite) and gloves. For A2L, add additional protection per the specific refrigerant's SDS."},{id:"a2l_44",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 puede causar el refrigerante l\xEDquido al contacto con la piel o los ojos?",opciones:["Nada \u2014 los refrigerantes son seguros en piel","Quemaduras por fr\xEDo (congelaci\xF3n) en piel y posiblemente ceguera en ojos","Solo irritaci\xF3n leve temporal","Solo problemas si es t\xF3xico"],respuesta_correcta:1,explicacion:"El refrigerante l\xEDquido al vaporizar r\xE1pidamente en la piel causa QUEMADURAS POR FR\xCDO (frostbite). En los ojos puede causar da\xF1o serio o ceguera. Siempre usar gafas de seguridad y guantes al manipular refrigerante l\xEDquido.",question:"What can liquid refrigerant cause upon contact with skin or eyes?",options:["Nothing \u2014 refrigerants are safe on skin","Cold burns (frostbite) on skin and possibly blindness in eyes","Only mild temporary irritation","Only a problem if toxic"],explanation:"Liquid refrigerant rapidly vaporizing on skin causes COLD BURNS (frostbite). In the eyes it can cause serious damage or blindness. Always wear safety glasses and gloves when handling liquid refrigerant."},{id:"a2l_45",categoria:"A2L_CONCEPTOS",pregunta:"\xBFA qu\xE9 temperatura m\xE1xima deben almacenarse los cilindros de refrigerante?",opciones:["50\xB0F (10\xB0C)","100\xB0F (38\xB0","C) 125\xB0F (52\xB0C)","150\xB0F (66\xB0C)"],respuesta_correcta:2,explicacion:"Los cilindros de refrigerante deben almacenarse a menos de 125\xB0F (52\xB0C). A temperaturas mayores la presi\xF3n interna puede aumentar dr\xE1sticamente y causar ruptura del cilindro.",question:"What is the maximum temperature at which refrigerant cylinders should be stored?",options:["50\xB0F (10\xB0C)","100\xB0F (38\xB0C)","125\xB0F (52\xB0C)","150\xB0F (66\xB0C)"],explanation:"Refrigerant cylinders must be stored below 125\xB0F (52\xB0C). At higher temperatures, internal pressure can increase drastically and cause cylinder rupture."},{id:"a2l_46",categoria:"A2L_CONCEPTOS",pregunta:"\xBFHasta qu\xE9 porcentaje de su capacidad m\xE1xima se puede llenar un tanque de recuperaci\xF3n?",opciones:["60%","70%","80%","100%"],respuesta_correcta:2,explicacion:"Los tanques de recuperaci\xF3n NO deben llenarse m\xE1s del 80% de su capacidad. El 20% restante permite la expansi\xF3n del refrigerante sin que el tanque alcance presiones peligrosas.",question:"To what percentage of maximum capacity can a recovery tank be filled?",options:["60%","70%","80%","100%"],explanation:"Recovery tanks must NOT be filled beyond 80% of their capacity. The remaining 20% allows for refrigerant expansion without the tank reaching dangerous pressures."},{id:"a2l_47",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 indica la f\xF3rmula (WC \xD7 0.80) + TW en el contexto de cilindros de recuperaci\xF3n?",opciones:["La presi\xF3n m\xE1xima de trabajo del cilindro","El peso m\xE1ximo permitido de refrigerante en el cilindro incluyendo el peso del cilindro vac\xEDo","El volumen de agua que cabe en el cilindro","La fecha de pr\xF3xima recertificaci\xF3n"],respuesta_correcta:1,explicacion:"WC (Water Capacity) \xD7 0.80 + TW (Tare Weight) = peso m\xE1ximo total del cilindro lleno al 80%. WC est\xE1 estampado en el collar del cilindro. Esta f\xF3rmula determina cu\xE1ndo DEJAR DE recuperar antes de llenar demasiado.",question:"What does the formula (WC x 0.80) + TW indicate in the context of recovery cylinders?",options:["The maximum working pressure of the cylinder","The maximum allowable weight of refrigerant in the cylinder including the empty cylinder weight","The water volume that fits in the cylinder","The next recertification date"],explanation:"WC (Water Capacity) x 0.80 + TW (Tare Weight) = maximum total weight of the filled cylinder at 80%. WC is stamped on the cylinder collar. This formula determines when to STOP recovering before overfilling."},{id:"a2l_48",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCada cu\xE1ntos a\xF1os deben someterse a prueba hidrost\xE1tica los cilindros de recuperaci\xF3n DOT?",opciones:["2 a\xF1os","3 a\xF1os","5 a\xF1os","10 a\xF1os"],respuesta_correcta:2,explicacion:"Los cilindros de recuperaci\xF3n DOT deben someterse a prueba hidrost\xE1tica cada 5 a\xF1os. La fecha de fabricaci\xF3n y la fecha de retest est\xE1n estampadas en el collar del cilindro. Un cilindro vencido no puede usarse legalmente.",question:"How often must DOT recovery cylinders undergo hydrostatic testing?",options:["2 years","3 years","5 years","10 years"],explanation:"DOT recovery cylinders must undergo hydrostatic testing every 5 years. The manufacture date and retest date are stamped on the cylinder collar. An expired cylinder cannot be legally used."},{id:"a2l_49",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 color tienen los cilindros de recuperaci\xF3n DOT est\xE1ndar?",opciones:["Azul y blanco","Gris y amarillo","Verde y rojo","Negro y naranja"],respuesta_correcta:1,explicacion:"Los cilindros de recuperaci\xF3n DOT son color gris (cuerpo) y amarillo (tapa/collar). Los A2L a\xF1aden una banda roja para identificarlos como inflamables. NUNCA usar cilindros de color diferente a los aprobados DOT.",question:"What color are standard DOT recovery cylinders?",options:["Blue and white","Gray and yellow","Green and red","Black and orange"],explanation:"DOT recovery cylinders are gray (body) and yellow (cap/collar). A2L cylinders add a red band to identify them as flammable. NEVER use cylinders of different color than DOT-approved ones."},{id:"a2l_50",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 es una 'SDS' y cu\xE1ndo debes consultarla?",opciones:["System Data Sheet \u2014 especificaciones del sistema","Safety Data Sheet \u2014 antes de trabajar con cualquier refrigerante o qu\xEDmico nuevo","Standard Design Specification \u2014 para instalaciones","Service Data Sheet \u2014 manual de servicio del equipo"],respuesta_correcta:1,explicacion:"SDS (Safety Data Sheet, antes MSDS) contiene: toxicidad, inflamabilidad, primeros auxilios, manejo seguro, incompatibilidades, y procedimientos de emergencia. SIEMPRE consultarla antes de trabajar con un refrigerante o qu\xEDmico nuevo.",question:"What is an 'SDS' and when should you consult it?",options:["System Data Sheet \u2014 system specifications","Safety Data Sheet \u2014 before working with any new refrigerant or chemical","Standard Design Specification \u2014 for installations","Service Data Sheet \u2014 equipment service manual"],explanation:"SDS (Safety Data Sheet, formerly MSDS) contains: toxicity, flammability, first aid, safe handling, incompatibilities, and emergency procedures. ALWAYS consult it before working with a new refrigerant or chemical."},{id:"a2l_51",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 herramientas deben usarse cuando se trabaja con refrigerantes A2L, A2 o A3?",opciones:["Cualquier herramienta certificada UL","Solo herramientas certificadas spark-free (sin chispa, sin arco) para ambiente inflamable","Solo herramientas manuales, sin el\xE9ctricas","Cualquier herramienta disponible en el cami\xF3n"],respuesta_correcta:1,explicacion:"Con refrigerantes A2L/A2/A3: SOLO herramientas certificadas para ambiente inflamable (spark-free) seg\xFAn NFPA 70 y NEC. Las herramientas comunes pueden generar chispas que enciendan el refrigerante.",question:"What tools must be used when working with A2L, A2, or A3 refrigerants?",options:["Any UL-certified tool","Only spark-free certified tools for flammable environments","Only hand tools, no electrical","Any tool available in the truck"],explanation:"With A2L/A2/A3 refrigerants: ONLY tools certified for flammable environments (spark-free) per NFPA 70 and NEC. Common tools can generate sparks that ignite the refrigerant."},{id:"a2l_52",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 herramienta mide el nivel de evacuaci\xF3n con precisi\xF3n en micrones?",opciones:["Man\xF3metro del manifold (en pulgadas Hg)","Medidor digital de micrones (digital micron gauge)","Term\xF3metro digital","Amper\xEDmetro"],respuesta_correcta:1,explicacion:"El medidor digital de micrones (micron gauge) es la \xFAnica herramienta que puede medir con precisi\xF3n niveles de vac\xEDo profundo. Los manifolds anal\xF3gicos miden en pulgadas Hg \u2014 demasiado imprecisos para vac\xEDos profundos.",question:"What tool measures evacuation level with precision in microns?",options:["Manifold gauge (in inches Hg)","Digital micron gauge","Digital thermometer","Ammeter"],explanation:"The digital micron gauge is the only tool that can precisely measure deep vacuum levels. Analog manifolds measure in inches Hg \u2014 too imprecise for deep vacuum measurements."},{id:"a2l_53",categoria:"A2L_CONCEPTOS",pregunta:"\xBFD\xF3nde debe colocarse el medidor de micrones durante la evacuaci\xF3n?",opciones:["Junto a la bomba de vac\xEDo","Tan cerca del sistema como sea posible (no en la bomba)","No importa el lugar","Solo al final de la evacuaci\xF3n"],respuesta_correcta:1,explicacion:"El micr\xF3metro debe estar tan cerca del SISTEMA como sea posible (idealmente en el puerto del core removal tool). Colocarlo en la bomba solo mide que la bomba funciona, no el nivel real del sistema.",question:"Where should the micron gauge be placed during evacuation?",options:["Next to the vacuum pump","As close to the system as possible (not at the pump)","Location does not matter","Only at the end of evacuation"],explanation:"The micron gauge must be as close to the SYSTEM as possible (ideally on the core removal tool port). Placing it at the pump only measures that the pump works, not the actual system level."},{id:"a2l_54",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 hoses (mangueras) son las m\xE1s eficientes para evacuaci\xF3n?",opciones:["1/4 pulgada \u2014 las m\xE1s comunes en manifolds","3/8 pulgada o 1/2 pulgada vacuum-rated con cores removidos","Cualquier manguera del manifold existente","Solo mangueras especiales de evacuaci\xF3n"],respuesta_correcta:1,explicacion:"Para evacuaci\xF3n eficiente: mangueras 3/8&quot; o 1/2&quot; vacuum-rated con cores Schrader removidos. Una manguera 1/4&quot; con cores provee ~0.2 CFM a la bomba. Con 2 mangueras 1/2&quot; sin cores puedes llegar a 6 CFM.",question:"What hoses are the most efficient for evacuation?",options:["1/4 inch \u2014 the most common on manifolds","3/8 inch or 1/2 inch vacuum-rated with cores removed","Any existing manifold hose","Only special evacuation hoses"],explanation:'For efficient evacuation: 3/8" or 1/2" vacuum-rated hoses with Schrader cores removed. A 1/4" hose with cores provides ~0.2 CFM to the pump. With 2 half-inch hoses without cores you can reach 6 CFM.'},{id:"a2l_55",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPara qu\xE9 se usa el core removal tool durante el servicio?",opciones:["Para cambiar el refrigerante del sistema","Para remover los cores Schrader de las v\xE1lvulas de servicio, permitiendo mayor flujo","Para medir la presi\xF3n del sistema","Para agregar aceite al compresor"],respuesta_correcta:1,explicacion:"El core removal tool permite remover los cores Schrader de las v\xE1lvulas de servicio sin liberar refrigerante. Sin cores, el flujo para evacuaci\xF3n y recuperaci\xF3n aumenta dr\xE1sticamente (de 0.2 CFM a varios CFM).",question:"What is the core removal tool used for during service?",options:["To change the system refrigerant","To remove Schrader cores from service valves, allowing greater flow","To measure system pressure","To add oil to the compressor"],explanation:"The core removal tool allows removing Schrader cores from service valves without releasing refrigerant. Without cores, flow for evacuation and recovery increases dramatically (from 0.2 CFM to several CFM)."},{id:"a2l_56",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 tipo de manifold se requiere para trabajar con sistemas A2L?",opciones:["Cualquier manifold existente \u2014 son universales","Manifold specifically rated para refrigerantes inflamables y para las presiones del A2L espec\xEDfico","Solo manifolds digitales","Solo manifolds de 4 v\xE1lvulas"],respuesta_correcta:1,explicacion:"Los manifolds para A2L deben estar: (1) rated para refrigerantes inflamables (materiales y sellados apropiados), y (2) rated para las presiones del refrigerante espec\xEDfico. El R-32 opera a presiones mayores que R-22.",question:"What type of manifold is required for working with A2L systems?",options:["Any existing manifold \u2014 they are universal","Manifold specifically rated for flammable refrigerants and for the pressures of the specific A2L","Only digital manifolds","Only 4-valve manifolds"],explanation:"Manifolds for A2L must be: (1) rated for flammable refrigerants (appropriate materials and seals), and (2) rated for the pressures of the specific refrigerant. R-32 operates at pressures higher than R-22."},{id:"a2l_57",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 tipo de aceite debe usarse en la bomba de vac\xEDo para mejores resultados?",opciones:["Cualquier aceite disponible \u2014 10W30 funciona","Aceite de alta calidad espec\xEDfico para bomba de vac\xEDo, cambiado antes de cada trabajo","Aceite sint\xE9tico de motor","No se requiere aceite \u2014 las bombas modernas son sin aceite"],respuesta_correcta:1,explicacion:"Usar aceite de ALTA CALIDAD espec\xEDfico para bomba de vac\xEDo y cambiarlo ANTES de cada trabajo de evacuaci\xF3n. El aceite contaminado o degradado reduce la capacidad de vac\xEDo. El color del aceite indica si debe cambiarse.",question:"What type of oil should be used in a vacuum pump for best results?",options:["Any available oil \u2014 10W30 works","High-quality vacuum pump specific oil, changed before each job","Synthetic motor oil","Not required \u2014 modern pumps are oil-free"],explanation:"Use HIGH QUALITY vacuum pump specific oil and change it BEFORE each evacuation job. Contaminated or degraded oil reduces vacuum capability. The oil color indicates if it needs changing."},{id:"a2l_58",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1ndo debe cambiarse el aceite de la bomba de vac\xEDo?",opciones:["Solo cuando se ve muy oscuro","Antes de cada evacuaci\xF3n y cuando se contamina con humedad durante el trabajo","Solo una vez al a\xF1o","Solo cuando la bomba no llega al vac\xEDo requerido"],respuesta_correcta:1,explicacion:"El aceite de bomba de vac\xEDo debe cambiarse: ANTES de cada evacuaci\xF3n importante (para asegurar m\xE1xima eficiencia) y DURANTE el trabajo si se contamina con humedad (el aceite se ver\xE1 turbio o muy oscuro).",question:"When should vacuum pump oil be changed?",options:["Only when it looks very dark","Before each evacuation and when contaminated with moisture during the job","Only once a year","Only when the pump cannot reach the required vacuum"],explanation:"Vacuum pump oil should be changed: BEFORE each important evacuation (to ensure maximum efficiency) and DURING the job if it becomes contaminated with moisture (oil will look cloudy or very dark)."},{id:"a2l_59",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 es un 'gas ballast' en una bomba de vac\xEDo?",opciones:["Un cilindro de nitr\xF3geno conectado a la bomba","Una v\xE1lvula que permite entrada de aire durante evacuaci\xF3n para prevenir condensaci\xF3n de vapores de agua en el aceite","Un filtro especial para A2L","El tanque de recuperaci\xF3n de la bomba"],respuesta_correcta:1,explicacion:"El gas ballast es una v\xE1lvula que permite entrada de aire a la bomba durante evacuaci\xF3n. Esto previene que el vapor de agua se condense en el aceite de la bomba. La v\xE1lvula DEBE cerrarse para alcanzar el nivel final de vac\xEDo profundo.",question:"What is a 'gas ballast' on a vacuum pump?",options:["A nitrogen cylinder connected to the pump","A valve that allows air intake during evacuation to prevent condensation of water vapor in the oil","A special filter for A2L","The pump's recovery tank"],explanation:"The gas ballast is a valve that allows air entry into the pump during evacuation. This prevents water vapor from condensing in the pump oil. The valve MUST be closed to reach the final deep vacuum level."},{id:"a2l_60",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 es la escala de 'micrones' y c\xF3mo se relaciona con pulgadas Hg?",opciones:["Es una medida de temperatura","Una unidad de presi\xF3n muy peque\xF1a: presi\xF3n atmosf\xE9rica = 760,000 micrones. A 29.98 inHg = ~500 micrones","Es una medida de di\xE1metro de tuber\xEDa","No se relaciona con pulgadas Hg"],respuesta_correcta:1,explicacion:"Micrones = unidad de presi\xF3n muy peque\xF1a. Presi\xF3n atmosf\xE9rica = 760,000 micrones = 0 inHg. El objetivo de evacuaci\xF3n (500 micrones) equivale aproximadamente a 29.98 inHg. Los manifolds anal\xF3gicos no pueden medir esta diferencia \u2014 necesitas micr\xF3metro digital.",question:"What is the 'micron' scale and how does it relate to inches Hg?",options:["It is a temperature measurement","A very small pressure unit: atmospheric pressure = 760,000 microns. At 29.98 inHg = ~500 microns","It is a pipe diameter measurement","It is not related to inches Hg"],explanation:"Microns = very small pressure unit. Atmospheric pressure = 760,000 microns = 0 inHg. The evacuation target (500 microns) equals approximately 29.98 inHg. Analog manifolds cannot measure this difference \u2014 you need a digital micron gauge."},{id:"a2l_61",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 es la 'recuperaci\xF3n' (recovery) de refrigerante?",opciones:["Ventilar el refrigerante al exterior de forma controlada","Transferir el refrigerante de un sistema sellado a un cilindro de recuperaci\xF3n aprobado DOT","Reciclar el refrigerante dentro del mismo sistema","Enviar el refrigerante al fabricante para reciclaje"],respuesta_correcta:1,explicacion:"Recovery = transferir el refrigerante desde el sistema sellado a un cilindro de recuperaci\xF3n aprobado DOT. NO es ventilarlo ni tirarlo. El proceso minimiza la liberaci\xF3n de refrigerante al ambiente.",question:"What is refrigerant 'recovery'?",options:["Venting the refrigerant outdoors in a controlled manner","Transferring refrigerant from a sealed system to a DOT-approved recovery cylinder","Recycling the refrigerant within the same system","Sending the refrigerant to the manufacturer for recycling"],explanation:"Recovery = transferring refrigerant from the sealed system to a DOT-approved recovery cylinder. It is NOT venting or discarding it. The process minimizes refrigerant release to the environment."},{id:"a2l_62",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la diferencia entre 'recycling' y 'reclamation'?",opciones:["Son lo mismo con diferente nombre","Recycling = limpieza b\xE1sica en campo para reusar en el mismo sistema. Reclamation = purificaci\xF3n a est\xE1ndar ARI 700 en instalaci\xF3n certificada para vender como nuevo","Recycling es legal, reclamation no","Reclamation es m\xE1s barato"],respuesta_correcta:1,explicacion:"Recycling = pasar por filtro-drier en campo para reducir contaminantes \u2014 puede reutilizarse en el mismo sistema o del mismo propietario. Reclamation = proceso industrial que purifica el refrigerante al est\xE1ndar ARI 700 (como nuevo) para reventa.",question:"What is the difference between 'recycling' and 'reclamation'?",options:["They are the same with different names","Recycling = basic field cleaning for reuse in the same system. Reclamation = purification to ARI 700 standard at a certified facility for resale as new","Recycling is legal, reclamation is not","Reclamation is cheaper"],explanation:"Recycling = basic field filtering through a filter-drier to reduce contaminants \u2014 can be reused in the same system or by the same owner. Reclamation = industrial process that purifies the refrigerant to ARI 700 standard (like new) for resale."},{id:"a2l_63",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1les refrigerantes est\xE1n EXENTOS del mandato de recuperaci\xF3n de la EPA bajo Secci\xF3n 608?",opciones:["Todos los A2L est\xE1n exentos","R-290 (propano) y R-600a (isobutano) \u2014 hidrocarburos naturales","Solo R-32 est\xE1 exento","Ninguno \u2014 todos deben recuperarse"],respuesta_correcta:1,explicacion:"R-290 (propano) y R-600a (isobutano) son hidrocarburos naturales EXENTOS del mandato de recuperaci\xF3n de la EPA. Para m\xE1s informaci\xF3n sobre sustitutos exentos: epa.gov/snap.",question:"Which refrigerants are EXEMPT from the EPA recovery mandate under Section 608?",options:["All A2L are exempt","R-290 (propane) and R-600a (isobutane) \u2014 natural hydrocarbons","Only R-32 is exempt","None \u2014 all must be recovered"],explanation:"R-290 (propane) and R-600a (isobutane) are natural hydrocarbons EXEMPT from the EPA recovery mandate. For more information on exempt substitutes: epa.gov/snap."},{id:"a2l_64",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 nivel de evacuaci\xF3n se requiere para recuperaci\xF3n de sistemas de ALTA presi\xF3n post-1993 con MENOS de 200 lb?",opciones:["4 pulgadas Hg","10 pulgadas Hg","15 pulgadas Hg","0 PSI"],respuesta_correcta:1,explicacion:"Para sistemas de alta presi\xF3n post-Nov 1993 con menos de 200 lb de refrigerante: se requiere evacuar a 10 pulgadas Hg. Si la carga es 200 lb o m\xE1s: 15 pulgadas Hg. Equipos pre-1993: solo 4 pulgadas Hg.",question:"What evacuation level is required for recovery of post-1993 HIGH pressure systems with LESS than 200 lb?",options:["4 inches Hg","10 inches Hg","15 inches Hg","0 PSI"],explanation:"For post-Nov 1993 high-pressure systems with less than 200 lb of refrigerant: evacuation to 10 inches Hg is required. If the charge is 200 lb or more: 15 inches Hg. Pre-1993 equipment: only 4 inches Hg."},{id:"a2l_65",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPor qu\xE9 se recomienda recuperar el refrigerante en estado VAPOR en lugar de l\xEDquido cuando es posible?",opciones:["La recuperaci\xF3n en vapor es m\xE1s r\xE1pida","La recuperaci\xF3n en vapor minimiza la p\xE9rdida de aceite del sistema, aunque es m\xE1s lenta","La recuperaci\xF3n en l\xEDquido est\xE1 prohibida","No hay diferencia entre vapor y l\xEDquido"],respuesta_correcta:1,explicacion:"Recuperaci\xF3n en vapor es M\xC1S LENTA pero minimiza la p\xE9rdida de aceite del sistema. La recuperaci\xF3n en l\xEDquido es m\xE1s r\xE1pida pero arrastra aceite del compresor hacia el cilindro de recuperaci\xF3n.",question:"Why is it recommended to recover refrigerant in VAPOR state rather than liquid when possible?",options:["Vapor recovery is faster","Vapor recovery minimizes oil loss from the system, although it is slower","Liquid recovery is prohibited","There is no difference between vapor and liquid"],explanation:"Vapor recovery is SLOWER but minimizes oil loss from the system. Liquid recovery is faster but carries compressor oil into the recovery cylinder."},{id:"a2l_66",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 debe hacer el t\xE9cnico con el cilindro de A2L recuperado antes de iniciar reparaciones?",opciones:["Dejarlo junto al equipo para referencia","Moverlo a una distancia segura del \xE1rea de trabajo antes de cualquier trabajo con fuego o chispa","Vaciarlo completamente primero","Guardarlo en un cuarto cerrado"],respuesta_correcta:1,explicacion:"Despu\xE9s de recuperar A2L: mover el cilindro a DISTANCIA SEGURA del \xE1rea de trabajo ANTES de usar soplete o cualquier herramienta que genere chispa. El cilindro con refrigerante inflamable es una fuente de peligro si hay fuego.",question:"What must the technician do with the A2L recovery cylinder before starting repairs?",options:["Leave it next to the equipment for reference","Move it to a safe distance from the work area before any work with fire or sparks","Empty it completely first","Store it in a closed room"],explanation:"After recovering A2L: move the cylinder to a SAFE DISTANCE from the work area BEFORE using a torch or any tool that generates sparks. The cylinder with flammable refrigerant is a hazard source near fire."},{id:"a2l_67",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPor qu\xE9 se recomienda el 'nitrogen sweep' despu\xE9s de recuperar A2L y antes de soldar?",opciones:["Para verificar que el sistema est\xE1 vac\xEDo","El aceite del sistema puede retener vapores de refrigerante inflamable \u2014 el nitr\xF3geno los desplaza","Para lubricar las tuber\xEDas antes de soldar","Solo es necesario en sistemas grandes"],respuesta_correcta:1,explicacion:"Despu\xE9s de recuperar A2L, el aceite POE del sistema puede retener vapores de refrigerante inflamable. El nitrogen sweep (purga con nitr\xF3geno seco a baja presi\xF3n) desplaza estos vapores, haciendo seguro el uso de soplete.",question:"Why is 'nitrogen sweep' recommended after recovering A2L and before brazing?",options:["To verify the system is empty","System oil can retain flammable refrigerant vapors \u2014 nitrogen displaces them","To lubricate the pipes before brazing","Only necessary in large systems"],explanation:"After recovering A2L, the system's POE oil can retain flammable refrigerant vapors. Nitrogen sweep (purge with dry nitrogen at low pressure) displaces these vapors, making torch use safe."},{id:"a2l_68",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1les son los componentes b\xE1sicos de un setup de recuperaci\xF3n?",opciones:["Solo la m\xE1quina de recuperaci\xF3n","M\xE1quina de recuperaci\xF3n + cilindro DOT + mangueras + pre-filtro drier + escala","Solo la m\xE1quina y el cilindro","Solo manifold y mangueras"],respuesta_correcta:1,explicacion:"Setup b\xE1sico de recuperaci\xF3n: (1) m\xE1quina de recuperaci\xF3n, (2) cilindro DOT aprobado, (3) mangueras 1/4&quot; o 3/8&quot;, (4) pre-filtro drier (filtra part\xEDculas), (5) escala de refrigerante para monitorear cu\xE1nto se recuper\xF3.",question:"What are the basic components of a recovery setup?",options:["Only the recovery machine","Recovery machine + DOT cylinder + hoses + pre-filter drier + scale","Only the machine and cylinder","Only manifold and hoses"],explanation:'Basic recovery setup: (1) recovery machine, (2) DOT-approved cylinder, (3) 1/4" or 3/8" hoses, (4) pre-filter drier (filters particles), (5) refrigerant scale to monitor how much was recovered.'},{id:"a2l_69",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPor qu\xE9 se deben purgar las mangueras de servicio antes de comenzar la recuperaci\xF3n?",opciones:["Para verificar que no hay fugas","Para eliminar el aire atrapado en las mangueras que contaminar\xEDa el refrigerante y aumentar\xEDa la presi\xF3n en el cilindro","Solo para manifolds viejos","No es necesario purgar mangueras"],respuesta_correcta:1,explicacion:"SIEMPRE purgar el aire de las mangueras antes de recuperar. El aire en las mangueras entra al cilindro de recuperaci\xF3n como no-condensable, aumenta la presi\xF3n y contamina el refrigerante haci\xE9ndolo m\xE1s dif\xEDcil de reclamar.",question:"Why must service hoses be purged before starting recovery?",options:["To verify there are no leaks","To eliminate trapped air in the hoses that would contaminate the refrigerant and increase cylinder pressure","Only for old manifolds","Purging hoses is not necessary"],explanation:"ALWAYS purge air from hoses before recovering. Air in the hoses enters the recovery cylinder as non-condensable, increases pressure, and contaminates the refrigerant making it harder to reclaim."},{id:"a2l_70",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 pasa con el refrigerante recuperado si la presi\xF3n del cilindro sube despu\xE9s de aislar el sistema de la m\xE1quina?",opciones:["Es normal \u2014 el proceso est\xE1 completo","Puede indicar que hay refrigerante adicional atrapado en el aceite del sistema vaporiz\xE1ndose \u2014 puede ser necesario reiniciar la m\xE1quina","Solo indica que el cilindro est\xE1 lleno","El cilindro debe reemplazarse"],respuesta_correcta:1,explicacion:"Si la presi\xF3n sube despu\xE9s de aislar: el refrigerante atrapado en el aceite del sistema se est\xE1 vaporizando. Puede necesitarse reiniciar la m\xE1quina de recuperaci\xF3n para recuperar este refrigerante adicional hasta estabilizar la presi\xF3n.",question:"What happens if the recovery cylinder pressure rises after isolating the system from the machine?",options:["It is normal \u2014 the process is complete","It may indicate additional refrigerant trapped in the system oil vaporizing \u2014 may need to restart the machine","Only indicates the cylinder is full","The cylinder must be replaced"],explanation:"If pressure rises after isolating: refrigerant trapped in the system oil is vaporizing. The recovery machine may need to be restarted to recover this additional refrigerant until pressure stabilizes."},{id:"a2l_71",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 es 'label matching' en instalaci\xF3n de sistemas A2L?",opciones:["Verificar que la etiqueta del cilindro coincida con el manifold","Verificar que TODOS los componentes est\xE9n dise\xF1ados y certificados para A2L antes de proceder","Hacer que las etiquetas coincidan visualmente","Verificar n\xFAmero de modelo con el manual"],respuesta_correcta:1,explicacion:"Label matching = verificar que CADA componente (evaporador, condensador, compresor, TXV, v\xE1lvulas, drier, etc.) est\xE9 certificado A2L. Si cualquier componente NO est\xE1 rated para A2L, la instalaci\xF3n NO puede proceder.",question:"What is 'label matching' in A2L system installation?",options:["Verify the cylinder label matches the manifold","Verify that ALL components are designed and certified for A2L before proceeding","Make labels match visually","Verify model number with manual"],explanation:"Label matching = verify that EACH component (evaporator, condenser, compressor, TXV, valves, drier, etc.) is A2L certified. If any component is NOT rated for A2L, installation CANNOT proceed."},{id:"a2l_72",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el orden correcto de operaciones al instalar un sistema A2L nuevo?",opciones:["Cargar refrigerante \u2192 prueba de fugas \u2192 evacuar","Evaluar sitio \u2192 label matching \u2192 instalar \u2192 prueba N2 \u2192 evacuar \u2192 decay test \u2192 cargar \u2192 etiqueta UL","Instalar \u2192 evacuar \u2192 cargar \u2192 verificar","Solo instalar y encender"],respuesta_correcta:1,explicacion:"Orden correcto: (1) Evaluar sitio para A2L, (2) label matching, (3) instalar con purga N2 durante brazado, (4) prueba presi\xF3n N2 (60 min, cero ca\xEDda), (5) evacuaci\xF3n a 500 micrones, (6) decay test, (7) cargar refrigerante, (8) etiqueta UL.",question:"What is the correct order of operations when installing a new A2L system?",options:["Charge refrigerant \u2192 leak test \u2192 evacuate","Evaluate site \u2192 label matching \u2192 install \u2192 N2 test \u2192 evacuate \u2192 decay test \u2192 charge \u2192 UL label","Install \u2192 evacuate \u2192 charge \u2192 verify","Just install and power on"],explanation:"Correct order: (1) Evaluate site for A2L, (2) label matching, (3) install with N2 purge during brazing, (4) N2 pressure test (60 min, zero drop), (5) evacuation to 500 microns, (6) decay test, (7) charge refrigerant, (8) UL label."},{id:"a2l_73",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 presi\xF3n y tiempo m\xEDnimo se requieren para la prueba de presi\xF3n de una nueva instalaci\xF3n A2L?",opciones:["100 PSI por 30 minutos","Presi\xF3n de datos de la placa por m\xEDnimo 60 minutos \u2014 sin ca\xEDda de presi\xF3n","150 PSI por 15 minutos","10 PSI por 10 minutos"],respuesta_correcta:1,explicacion:"Prueba de presi\xF3n A2L: presurizar con nitr\xF3geno seco a la presi\xF3n m\xE1s baja de las placas de datos de los componentes, por m\xEDnimo 60 minutos. CERO ca\xEDda de presi\xF3n durante la prueba para considerar que pas\xF3.",question:"What pressure and minimum time are required for the pressure test of a new A2L installation?",options:["100 PSI for 30 minutes","Data plate pressure for minimum 60 minutes \u2014 no pressure drop","150 PSI for 15 minutes","10 PSI for 10 minutes"],explanation:"A2L pressure test: pressurize with dry nitrogen to the lowest data plate pressure of the components, for minimum 60 minutes. ZERO pressure drop during the test to be considered passing."},{id:"a2l_74",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 criterio debe cumplir el vacuum decay test en una instalaci\xF3n A2L?",opciones:["La presi\xF3n no debe subir en absoluto","La presi\xF3n no debe subir m\xE1s de 1,500 micrones en 10 minutos despu\xE9s de aislar de la bomba","Solo alcanzar 500 micrones es suficiente","La presi\xF3n puede subir hasta 5,000 micrones"],respuesta_correcta:1,explicacion:"Vacuum decay test: despu\xE9s de 500 micrones, aislar el sistema de la bomba. La presi\xF3n NO debe subir m\xE1s de 1,500 micrones en 10 minutos. Si sube m\xE1s: hay fuga o humedad \u2014 investigar antes de cargar refrigerante.",question:"What criteria must the vacuum decay test meet in an A2L installation?",options:["Pressure must not rise at all","Pressure must not rise more than 1,500 microns in 10 minutes after isolating from the pump","Only reaching 500 microns is sufficient","Pressure can rise up to 5,000 microns"],explanation:"Vacuum decay test: after reaching 500 microns, isolate the system from the pump. Pressure must NOT rise more than 1,500 microns in 10 minutes. If it rises more: there is a leak or moisture \u2014 investigate before charging refrigerant."},{id:"a2l_75",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 informaci\xF3n m\xEDnima requiere la etiqueta permanente UL en sistemas A2L?",opciones:["Solo el tipo de refrigerante","Nombre del contratista, nivel de vac\xEDo, presi\xF3n de prueba, fecha, tipo de refrigerante, y carga total (lb y oz)","Solo la fecha de instalaci\xF3n","Solo el n\xFAmero de certificaci\xF3n del t\xE9cnico"],respuesta_correcta:1,explicacion:"La etiqueta permanente UL requerida en sistemas A2L debe incluir: nombre del contratista/t\xE9cnico, nivel de vac\xEDo alcanzado, presi\xF3n de prueba, fecha de prueba y evacuaci\xF3n, tipo de refrigerante, y carga total (libras y onzas).",question:"What minimum information does the permanent UL label on A2L systems require?",options:["Only the refrigerant type","Contractor name, vacuum level, test pressure, date, refrigerant type, and total charge (lb and oz)","Only the installation date","Only the technician's certification number"],explanation:"The required permanent UL label on A2L systems must include: contractor/technician name, vacuum level achieved, test pressure, test and evacuation date, refrigerant type, and total charge (pounds and ounces)."},{id:"a2l_76",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 protecci\xF3n requieren las tuber\xEDas A2L instaladas dentro de paredes o pisos?",opciones:["Ninguna especial","Strike plates u otros escudos para prevenir perforaciones accidentales","Solo aislamiento t\xE9rmico","Solo deben estar bien soldadas"],respuesta_correcta:1,explicacion:"Tuber\xEDas A2L dentro de paredes/pisos deben estar protegidas con STRIKE PLATES (planchas met\xE1licas) u otros escudos para prevenir perforaciones accidentales que causar\xEDan fugas de refrigerante inflamable.",question:"What protection do A2L tubing installed inside walls or floors require?",options:["None special","Strike plates or other shields to prevent accidental punctures","Only thermal insulation","Only need to be well brazed"],explanation:"A2L tubing inside walls/floors must be protected with STRIKE PLATES (metal plates) or other shields to prevent accidental punctures that would cause leaks of flammable refrigerant."},{id:"a2l_77",categoria:"A2L_CONCEPTOS",pregunta:"\xBFC\xF3mo se carga el R-454B correctamente?",opciones:["En estado gaseoso igual que refrigerante puro","En estado L\xCDQUIDO del cilindro \u2014 es mezcla zeotr\xF3pica que fracciona si se carga en gas","En cualquier estado","Solo con equipo especializado"],respuesta_correcta:1,explicacion:"R-454B SIEMPRE debe cargarse en estado L\xCDQUIDO del cilindro. Como mezcla zeotr\xF3pica, si se carga en gas el R-32 m\xE1s vol\xE1til sale primero, cambiando la composici\xF3n de la mezcla y afectando el desempe\xF1o del sistema.",question:"How is R-454B correctly charged?",options:["In vapor state like a pure refrigerant","In LIQUID state from the cylinder \u2014 it is a zeotropic blend that fractionates if charged as vapor","In any state","Only with specialized equipment"],explanation:"R-454B must ALWAYS be charged in LIQUID state from the cylinder. As a zeotropic blend, if charged as gas the more volatile R-32 exits first, changing the blend composition and affecting system performance."},{id:"a2l_78",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPuede el R-32 cargarse en estado gaseoso?",opciones:["No \u2014 igual que R-454B debe ser siempre l\xEDquido","S\xED \u2014 es refrigerante puro que no fracciona, puede cargarse como gas o l\xEDquido","Solo en emergencias","Solo con cilindros especiales"],respuesta_correcta:1,explicacion:"R-32 ES refrigerante puro (un solo componente) \u2014 NO fracciona. Puede cargarse como gas o como l\xEDquido sin cambiar su composici\xF3n. Esta es una ventaja operacional sobre mezclas como R-454B.",question:"Can R-32 be charged in vapor state?",options:["No \u2014 same as R-454B, must always be liquid","Yes \u2014 it is a pure refrigerant that does not fractionate, can be charged as gas or liquid","Only in emergencies","Only with special cylinders"],explanation:"R-32 IS a pure refrigerant (single component) \u2014 it does NOT fractionate. It can be charged as gas or liquid without changing its composition. This is an operational advantage over blends like R-454B."},{id:"a2l_79",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 debe incluirse en el cargo final de la etiqueta permanente cuando se completa una instalaci\xF3n A2L?",opciones:["Solo el tipo de refrigerante","El tipo de refrigerante Y el peso total en libras y onzas que qued\xF3 en el sistema","Solo el n\xFAmero de cilindros usados","Solo el costo del refrigerante usado"],respuesta_correcta:1,explicacion:"La etiqueta permanente debe registrar el tipo de refrigerante Y el peso total (en libras y onzas) cargado en el sistema al finalizar la instalaci\xF3n. Cualquier recarga futura tambi\xE9n debe documentarse en esa etiqueta.",question:"What must be included in the final charge on the permanent label when completing an A2L installation?",options:["Only the refrigerant type","The refrigerant type AND total weight in pounds and ounces remaining in the system","Only the number of cylinders used","Only the cost of refrigerant used"],explanation:"The permanent label must record the refrigerant type AND total weight (in pounds and ounces) charged into the system upon completing installation. Any future recharge must also be documented on that label."},{id:"a2l_80",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 documentaci\xF3n debe entregarse al propietario al finalizar una instalaci\xF3n A2L?",opciones:["Solo la factura","Los manuales de instalaci\xF3n y servicio del fabricante, revisando con el propietario","Solo la garant\xEDa","Solo el n\xFAmero de serie"],respuesta_correcta:1,explicacion:"Al finalizar instalaci\xF3n A2L: los manuales de instalaci\xF3n y servicio DEBEN entregarse al propietario (o quedar con el equipo). El t\xE9cnico debe tomarse tiempo para revisar la documentaci\xF3n con el propietario.",question:"What documentation must be delivered to the owner upon completing an A2L installation?",options:["Only the invoice","The manufacturer's installation and service manuals, reviewing with the owner","Only the warranty","Only the serial number"],explanation:"Upon completing A2L installation: the installation and service manuals MUST be delivered to the owner (or remain with the equipment). The technician should take time to review the documentation with the owner."},{id:"a2l_81",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 cubre espec\xEDficamente la Secci\xF3n 608 de la Clean Air Act?",opciones:["Calidad del aire en ciudades","Manejo de refrigerantes \u2014 proh\xEDbe ventilar, requiere recuperaci\xF3n, certifica t\xE9cnicos y equipos","Emisiones de veh\xEDculos","Producci\xF3n de sustancias qu\xEDmicas"],respuesta_correcta:1,explicacion:"Secci\xF3n 608 de la CAA regula el manejo de refrigerantes: proh\xEDbe la ventilaci\xF3n intencional, requiere recuperaci\xF3n antes de trabajar en sistemas, y exige certificaci\xF3n a t\xE9cnicos que manejan refrigerantes regulados.",question:"What does Section 608 of the Clean Air Act specifically cover?",options:["Urban air quality","Refrigerant handling \u2014 prohibits venting, requires recovery, certifies technicians and equipment","Vehicle emissions","Chemical substance production"],explanation:"Section 608 of the CAA regulates refrigerant handling: prohibits intentional venting, requires recovery before working on systems, and requires certification for technicians who handle regulated refrigerants."},{id:"a2l_82",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 cubre la Secci\xF3n 612 de la Clean Air Act?",opciones:["Certificaci\xF3n de t\xE9cnicos EPA 608","Evaluaci\xF3n y aprobaci\xF3n de sustitutos para sustancias que agotan el ozono (programa SNAP)","Regulaci\xF3n de emisiones industriales","Manejo de residuos qu\xEDmicos"],respuesta_correcta:1,explicacion:"Secci\xF3n 612 = programa SNAP. Requiere que la EPA eval\xFAe alternativas para refrigerantes que agotan el ozono y genere listas de sustitutos aceptables e inaceptables. De aqu\xED salen las aprobaciones de nuevos A2L.",question:"What does Section 612 of the Clean Air Act cover?",options:["EPA 608 technician certification","Evaluation and approval of substitutes for ozone-depleting substances (SNAP program)","Industrial emissions regulation","Chemical waste management"],explanation:"Section 612 = SNAP program. Requires the EPA to evaluate alternatives for ozone-depleting refrigerants and generate lists of acceptable and unacceptable substitutes. This is where approvals for new A2L refrigerants come from."},{id:"a2l_83",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1les refrigerantes est\xE1n regulados bajo la Secci\xF3n 608?",opciones:["Solo CFCs y HCFCs","CFCs, HCFCs, HFCs y HFOs \u2014 todos deben recuperarse","Solo los que da\xF1an el ozono","Solo los que tienen GWP>1,000"],respuesta_correcta:1,explicacion:"La Secci\xF3n 608 regula CFCs, HCFCs, HFCs y HFOs \u2014 todos deben recuperarse antes de hacer servicio. No est\xE1 permitido ventilar intencionalmente ninguno de estos refrigerantes bajo ninguna circunstancia.",question:"Which refrigerants are regulated under Section 608?",options:["Only CFCs and HCFCs","CFCs, HCFCs, HFCs, and HFOs \u2014 all must be recovered","Only those that damage the ozone layer","Only those with GWP>1,000"],explanation:"Section 608 regulates CFCs, HCFCs, HFCs, and HFOs \u2014 all must be recovered before service. Intentional venting of any of these refrigerants is not permitted under any circumstances."},{id:"a2l_84",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 cubre ASHRAE Standard 15?",opciones:["Clasificaciones de seguridad de refrigerantes","Dise\xF1o, construcci\xF3n, instalaci\xF3n y operaci\xF3n de equipos HVAC comerciales \u2014 incluye restricciones A2L","Procedimientos de recuperaci\xF3n","Certificaci\xF3n de t\xE9cnicos"],respuesta_correcta:1,explicacion:"ASHRAE Standard 15 cubre dise\xF1o, construcci\xF3n, instalaci\xF3n y operaci\xF3n de equipos HVAC comerciales y cuartos de m\xE1quinas. Fue actualizado para incluir restricciones espec\xEDficas para A2L.",question:"What does ASHRAE Standard 15 cover?",options:["Refrigerant safety classifications","Design, construction, installation, and operation of commercial HVAC equipment \u2014 includes A2L restrictions","Recovery procedures","Technician certification"],explanation:"ASHRAE Standard 15 covers design, construction, installation, and operation of commercial HVAC equipment and mechanical rooms. It was updated to include specific restrictions for A2L."},{id:"a2l_85",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el prop\xF3sito espec\xEDfico de ASHRAE Standard 15.2?",opciones:["Es id\xE9ntico al 15","Standard NUEVO espec\xEDficamente para aplicaciones residenciales A2L","Cubre solo aplicaciones industriales","Cubre solo automotriz"],respuesta_correcta:1,explicacion:"ASHRAE Standard 15.2 fue creado espec\xEDficamente para aplicaciones residenciales de A2L. Es el companion residencial del ASHRAE 15 (comercial). Contiene restricciones para instalaci\xF3n, servicio y disposici\xF3n de A2L en viviendas.",question:"What is the specific purpose of ASHRAE Standard 15.2?",options:["It is identical to 15","NEW standard specifically for residential A2L applications","Covers only industrial applications","Covers only automotive"],explanation:"ASHRAE Standard 15.2 was created specifically for residential A2L applications. It is the residential companion to ASHRAE 15 (commercial). It contains restrictions for installation, service, and disposal of A2L in dwellings."},{id:"a2l_86",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 establece ASHRAE Standard 34?",opciones:["Los procedimientos de instalaci\xF3n HVAC","Las designaciones y clasificaciones de seguridad (toxicidad e inflamabilidad) de refrigerantes y RCLs","Los procedimientos de recuperaci\xF3n","Los est\xE1ndares de certificaci\xF3n"],respuesta_correcta:1,explicacion:"ASHRAE Standard 34 establece: designaciones num\xE9ricas de refrigerantes (ej: R-32), clasificaciones de seguridad ASHRAE (A1, A2L, A2, A3, B1, B2L, etc.), y los Refrigerant Concentration Limits (RCL) para cada refrigerante.",question:"What does ASHRAE Standard 34 establish?",options:["HVAC installation procedures","The designations and safety classifications (toxicity and flammability) of refrigerants and RCLs","Recovery procedures","Certification standards"],explanation:"ASHRAE Standard 34 establishes: numeric designations for refrigerants (e.g., R-32), ASHRAE safety classifications (A1, A2L, A2, A3, B1, B2L, etc.), and Refrigerant Concentration Limits (RCL) for each refrigerant."},{id:"a2l_87",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 cubre UL Standard 60335-2-40 (3a edici\xF3n)?",opciones:["Equipos industriales solamente","A/C, bombas de calor y deshumidificadores \u2014 la 3a edici\xF3n (2019) agreg\xF3 especificaciones para A2L","Solo motores el\xE9ctricos","Solo equipos de refrigeraci\xF3n comercial"],respuesta_correcta:1,explicacion:"UL 60335-2-40, 3a edici\xF3n (2019), cubre dise\xF1o y especificaciones de prueba para A/C, bombas de calor y deshumidificadores. La 3a edici\xF3n espec\xEDficamente agreg\xF3 requerimientos para equipos con refrigerantes A2L.",question:"What does UL Standard 60335-2-40 (3rd edition) cover?",options:["Industrial equipment only","A/C, heat pumps, and dehumidifiers \u2014 the 3rd edition (2019) added A2L specifications","Only electric motors","Only commercial refrigeration equipment"],explanation:"UL 60335-2-40, 3rd edition (2019), covers design and test specifications for A/C, heat pumps, and dehumidifiers. The 3rd edition specifically added requirements for equipment with A2L refrigerants."},{id:"a2l_88",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 cubre el Code of Federal Regulations T\xEDtulo 49?",opciones:["Solo transporte a\xE9reo","Transporte de materiales peligrosos incluyendo gases inflamables en TODOS los medios de transporte","Solo producci\xF3n de refrigerantes","Solo almacenamiento de qu\xEDmicos"],respuesta_correcta:1,explicacion:"CFR T\xEDtulo 49 (DOT) regula el transporte de HAZMAT en todos los medios \u2014 carretera, ferrocarril, aire, agua. Incluye clasificaci\xF3n, embalaje, marcado, documentaci\xF3n y capacitaci\xF3n para materiales peligrosos incluyendo gases inflamables.",question:"What does Code of Federal Regulations Title 49 cover?",options:["Only air transport","Transportation of hazardous materials including flammable gases in ALL modes of transport","Only refrigerant production","Only chemical storage"],explanation:"CFR Title 49 (DOT) regulates HAZMAT transportation in all modes \u2014 road, rail, air, water. Includes classification, packaging, marking, documentation, and training for hazardous materials including flammable gases."},{id:"a2l_89",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1ntos a\xF1os de vigencia tiene la certificaci\xF3n EPA 608?",opciones:["2 a\xF1os","5 a\xF1os","10 a\xF1os","Es permanente \u2014 no expira"],respuesta_correcta:3,explicacion:"La certificaci\xF3n EPA 608 es PERMANENTE \u2014 nunca expira. Una vez obtenida es v\xE1lida de por vida. Diferente a OSHA-10 (expira en 5 a\xF1os) o NATE (requiere renovaci\xF3n cada 2 a\xF1os).",question:"How many years is EPA 608 certification valid?",options:["2 years","5 years","10 years","It is permanent \u2014 it does not expire"],explanation:"EPA 608 certification is PERMANENT \u2014 it never expires. Once obtained, it is valid for life. Different from OSHA-10 (expires in 5 years) or NATE (requires renewal every 2 years)."},{id:"a2l_90",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es la penalidad m\xE1xima por ventilar intencionalmente refrigerante?",opciones:["$500 por incidente","$5,000 por d\xEDa","$44,539 por violaci\xF3n","$10,000 por libra"],respuesta_correcta:2,explicacion:"La EPA puede imponer multas de hasta $44,539 por d\xEDa por cada violaci\xF3n de las regulaciones de refrigerantes de la Secci\xF3n 608. Las violaciones tambi\xE9n pueden resultar en procesamiento criminal.",question:"What is the maximum penalty for intentionally venting refrigerant?",options:["$500 per incident","$5,000 per day","$44,539 per violation","$10,000 per pound"],explanation:"The EPA can impose fines of up to $44,539 per day for each violation of the Section 608 refrigerant regulations. Violations can also result in criminal prosecution."},{id:"a2l_91",categoria:"A2L_CONCEPTOS",pregunta:"\xBFEn qu\xE9 posici\xF3n deben almacenarse los cilindros A2L?",opciones:["Horizontal para ahorrar espacio","Vertical (upright) para que el dispositivo de alivio est\xE9 en contacto con el espacio de vapor","Cualquier posici\xF3n","Solo con cadenas de seguridad"],respuesta_correcta:1,explicacion:"Cilindros A2L DEBEN almacenarse VERTICALES. Esto asegura que el dispositivo de alivio de presi\xF3n est\xE9 en contacto con el espacio de vapor (no l\xEDquido). Si el dispositivo se activa sobre l\xEDquido, liberar\xEDa m\xE1s refrigerante.",question:"In what position should A2L cylinders be stored?",options:["Horizontal to save space","Vertical (upright) so the relief device contacts the vapor space","Any position","Only with safety chains"],explanation:"A2L cylinders MUST be stored VERTICAL. This ensures the pressure relief device contacts the vapor space (not liquid). If the device activates over liquid, it would release more refrigerant."},{id:"a2l_92",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 proh\xEDbe OSHA para almacenamiento de cilindros de refrigerante inflamable?",opciones:["Almacenamiento en racks al aire libre","Almacenamiento en lockers cerrados, contenedores o espacios confinados sin ventilaci\xF3n","Almacenamiento en cuartos ventilados","Almacenamiento en el cami\xF3n de servicio"],respuesta_correcta:1,explicacion:"OSHA proh\xEDbe almacenar cilindros de refrigerante inflamable en lockers cerrados, contenedores o espacios confinados sin ventilaci\xF3n. Si se usa un enclosure, DEBE ser seguro y ventilado.",question:"What does OSHA prohibit for storage of flammable refrigerant cylinders?",options:["Storage in outdoor racks","Storage in closed lockers, containers, or confined spaces without ventilation","Storage in ventilated rooms","Storage in service trucks"],explanation:"OSHA prohibits storing flammable refrigerant cylinders in closed lockers, containers, or confined spaces without ventilation. If an enclosure is used, it MUST be safe and ventilated."},{id:"a2l_93",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 requisitos de ventilaci\xF3n aplican al almacenamiento de A2L?",opciones:["No se requiere ventilaci\xF3n especial","El \xE1rea de almacenamiento debe tener ventilaci\xF3n adecuada para prevenir acumulaci\xF3n de vapores inflamables","Solo en grandes almacenes","Solo si se almacenan m\xE1s de 100 lb"],respuesta_correcta:1,explicacion:"El almacenamiento de refrigerantes inflamables requiere ventilaci\xF3n adecuada para prevenir que una posible fuga cree concentraciones inflamables. La ventilaci\xF3n puede ser natural o mec\xE1nica seg\xFAn los requisitos locales.",question:"What ventilation requirements apply to A2L storage?",options:["No special ventilation required","The storage area must have adequate ventilation to prevent accumulation of flammable vapors","Only in large warehouses","Only if storing more than 100 lb"],explanation:"Flammable refrigerant storage requires adequate ventilation to prevent a possible leak from creating flammable concentrations. Ventilation can be natural or mechanical per local requirements."},{id:"a2l_94",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 placard NFPA identifica los peligros en instalaciones de almacenamiento de refrigerantes A2L?",opciones:["NFPA 10 \u2014 extinguidores","NFPA 704 \u2014 identificaci\xF3n de peligros (diamante de colores)","NFPA 13 \u2014 sprinklers","NFPA 70 \u2014 c\xF3digo el\xE9ctrico"],respuesta_correcta:1,explicacion:"NFPA 704 = diamante de cuatro colores: azul (health), rojo (flammability), amarillo (reactivity), blanco (special). Requerido en instalaciones de almacenamiento para identificar peligros de los materiales almacenados.",question:"What NFPA placard identifies hazards at A2L refrigerant storage facilities?",options:["NFPA 10 \u2014 fire extinguishers","NFPA 704 \u2014 hazard identification (color diamond)","NFPA 13 \u2014 sprinklers","NFPA 70 \u2014 electrical code"],explanation:"NFPA 704 = four-color diamond: blue (health), red (flammability), yellow (reactivity), white (special). Required at storage facilities to identify hazards of stored materials."},{id:"a2l_95",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 registros debe tener una instalaci\xF3n que almacena refrigerantes A2L?",opciones:["Solo un inventario de cantidad","Plan de Manejo de Materiales Peligrosos (HMMP), inventario HMIS, y SDS de cada refrigerante","Solo las facturas de compra","No se requieren registros especiales"],respuesta_correcta:1,explicacion:"Para almacenamiento de A2L se requiere: Plan de Manejo de Materiales Peligrosos (HMMP), Hazardous Materials Inventory Statement (HMIS) onsite, y hojas SDS actualizadas para cada tipo de refrigerante almacenado.",question:"What records must a facility storing A2L refrigerants maintain?",options:["Only a quantity inventory","Hazardous Materials Management Plan (HMMP), HMIS inventory, and SDS for each refrigerant","Only purchase invoices","No special records required"],explanation:"For A2L storage, the following are required: Hazardous Materials Management Plan (HMMP), Hazardous Materials Inventory Statement (HMIS) on-site, and updated SDS sheets for each type of refrigerant stored."},{id:"a2l_96",categoria:"A2L_CONCEPTOS",pregunta:"\xBFCu\xE1l es el extinguidor requerido en veh\xEDculos que transportan A2L seg\xFAn DOT?",opciones:["Clase A (combustibles s\xF3lidos)","Clase B (polvo seco \u2014 Dry Powder)","Clase C (el\xE9ctrico)","Cualquier extinguidor disponible"],respuesta_correcta:1,explicacion:"DOT requiere que los veh\xEDculos que transportan gases inflamables (incluyendo A2L) lleven extinguidor Clase B (Dry Powder). Este tipo espec\xEDfico es efectivo para gases y l\xEDquidos inflamables.",question:"What fire extinguisher is required in vehicles transporting A2L per DOT?",options:["Class A (solid combustibles)","Class B (dry powder)","Class C (electrical)","Any available extinguisher"],explanation:"DOT requires vehicles transporting flammable gases (including A2L) to carry a Class B (Dry Powder) fire extinguisher. This specific type is effective for flammable gases and liquids."},{id:"a2l_97",categoria:"A2L_CONCEPTOS",pregunta:"\xBFA qu\xE9 distancia m\xEDnima est\xE1 prohibido fumar al transportar gases inflamables seg\xFAn DOT?",opciones:["10 pies","25 pies","50 pies","100 pies"],respuesta_correcta:1,explicacion:"DOT proh\xEDbe fumar dentro de 25 pies de gases inflamables durante el transporte. Tambi\xE9n requiere: inventario escrito de los gases, SDS para cada refrigerante, y medidas de seguridad contra acceso no autorizado.",question:"At what minimum distance is smoking prohibited when transporting flammable gases per DOT?",options:["10 feet","25 feet","50 feet","100 feet"],explanation:"DOT prohibits smoking within 25 feet of flammable gases during transport. It also requires: written inventory of gases, SDS for each refrigerant, and security measures against unauthorized access."},{id:"a2l_98",categoria:"A2L_CONCEPTOS",pregunta:"\xBFEn qu\xE9 posici\xF3n pueden transportarse los cilindros A2L en veh\xEDculos de servicio?",opciones:["Solo vertical","Solo horizontal con valva hacia arriba","Pueden transportarse horizontalmente \u2014 la v\xE1lvula de alivio debe estar en posici\xF3n 12 en punto","En cualquier posici\xF3n"],respuesta_correcta:2,explicacion:"Los cilindros A2L PUEDEN transportarse horizontalmente (caben en los racks est\xE1ndar de los camiones de servicio). La mejor pr\xE1ctica es asegurarse de que la v\xE1lvula de alivio est\xE9 en posici\xF3n de 12 en punto (hacia arriba).",question:"In what position can A2L cylinders be transported in service vehicles?",options:["Only vertical","Only horizontal with valve facing up","Can be transported horizontally \u2014 the relief valve should be in the 12 o'clock position","In any position"],explanation:"A2L cylinders CAN be transported horizontally (they fit in standard service truck racks). Best practice is to ensure the relief valve is in the 12 o'clock (upward) position."},{id:"a2l_99",categoria:"A2L_CONCEPTOS",pregunta:"\xBFPor qu\xE9 los cilindros A2L requieren v\xE1lvula de alivio en lugar de disco de ruptura?",opciones:["Solo por regulaci\xF3n cosm\xE9tica","La v\xE1lvula abre y CIERRA \u2014 previene liberaci\xF3n total del contenido. El disco se destruye permanentemente liberando todo el contenido","Son m\xE1s baratas de fabricar","No hay diferencia pr\xE1ctica"],respuesta_correcta:1,explicacion:"V\xE1lvula de alivio: ABRE cuando la presi\xF3n excede el l\xEDmite y CIERRA cuando baja \u2014 previene liberaci\xF3n total. Disco de ruptura: se destruye permanentemente al activarse liberando todo el contenido. Para A2L inflamables, la v\xE1lvula es mucho m\xE1s segura.",question:"Why do A2L cylinders require a relief valve instead of a rupture disc?",options:["Only for cosmetic regulation","The valve opens and CLOSES \u2014 prevents total release of contents. A rupture disc permanently destroys itself releasing all contents","They are cheaper to manufacture","There is no practical difference"],explanation:"Relief valve: OPENS when pressure exceeds the limit and CLOSES when it drops \u2014 prevents total release. Rupture disc: permanently destroys itself when activated, releasing all contents. For flammable A2L, the valve is much safer."},{id:"a2l_100",categoria:"A2L_CONCEPTOS",pregunta:"\xBFQu\xE9 regulaciones adem\xE1s del DOT pueden aplicar al transporte de A2L en algunos estados?",opciones:["Solo el DOT aplica \u2014 los estados no pueden regular m\xE1s","Algunos estados requieren placards en el veh\xEDculo y ventilaci\xF3n adicional dependiendo del volumen transportado","Los estados no pueden regular el transporte de refrigerantes","Solo aplica en California"],respuesta_correcta:1,explicacion:"Adem\xE1s del DOT federal, ALGUNOS ESTADOS pueden requerir placards adicionales en el veh\xEDculo y/o ventilaci\xF3n dependiendo del volumen de gas inflamable transportado. SIEMPRE verificar regulaciones estatales y locales adem\xE1s del DOT.",question:"What regulations besides DOT may apply to A2L transportation in some states?",options:["Only DOT applies \u2014 states cannot regulate further","Some states require vehicle placards and additional ventilation depending on the volume transported","States cannot regulate refrigerant transport","Only applies in California"],explanation:"In addition to federal DOT, SOME STATES may require additional vehicle placards and/or ventilation depending on the volume of flammable gas transported. ALWAYS verify state and local regulations in addition to DOT."},{id:"a2l_101",categoria:"A2L_CAMPO",pregunta:"Un t\xE9cnico llega a servicio de un minisplit que usa R-32. \xBFCu\xE1l es el PRIMER paso antes de abrir el sistema?",opciones:["Conectar el manifold inmediatamente","Evaluar el \xE1rea para fuentes de ignici\xF3n, ventilar el espacio, y tener el extinguidor listo antes de comenzar","Solo apagar el equipo","Solo revisar el termostato"],respuesta_correcta:1,explicacion:"PRIMERO: evaluar el \xE1rea para fuentes de ignici\xF3n (chispas, llamas, superficies calientes), asegurar ventilaci\xF3n adecuada, y tener el extinguidor Clase B disponible. Solo entonces comenzar el trabajo con el sistema A2L.",question:"A technician arrives to service a minisplit that uses R-32. What is the FIRST step before opening the system?",options:["Connect the manifold immediately","Evaluate the area for ignition sources, ventilate the space, and have the extinguisher ready before starting","Only turn off the equipment","Only check the thermostat"],explanation:"FIRST: evaluate the area for ignition sources (sparks, flames, hot surfaces), ensure adequate ventilation, and have the Class B fire extinguisher available. Only then begin work on the A2L system."},{id:"a2l_102",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo determinas si un sistema residencial nuevo usa R-454B o R-410A?",opciones:["Por el color del equipo","Por la placa de datos (nameplate) del equipo \u2014 siempre indica el tipo de refrigerante","Por el color de las mangueras del manifold","Por el a\xF1o de fabricaci\xF3n solamente"],respuesta_correcta:1,explicacion:"La placa de datos (nameplate) del equipo SIEMPRE indica el tipo de refrigerante, la carga en oz/lb, y otras especificaciones. Es la fuente definitiva \u2014 nunca asumir el refrigerante sin verificar la placa.",question:"How do you determine if a new residential system uses R-454B or R-410A?",options:["By the equipment color","By the equipment nameplate (data plate) \u2014 it always indicates the refrigerant type","By the manifold hose color","By the year of manufacture only"],explanation:"The equipment nameplate ALWAYS indicates the refrigerant type, charge in oz/lb, and other specifications. It is the definitive source \u2014 never assume the refrigerant without checking the nameplate."},{id:"a2l_103",categoria:"A2L_CAMPO",pregunta:"Un sistema R-454B tiene presi\xF3n de succi\xF3n de 112 PSI. La l\xEDnea de succi\xF3n mide 55\xB0F. \xBFCu\xE1l es el superheat?",opciones:["No se puede calcular con A2L","Superheat = 55\xB0F - 45\xB0F = 10\xB0F (usando la tabla P/T vapor del R-454B)","Superheat = 55\xB0F - 40\xB0F = 15\xB0F","Los A2L no tienen superheat"],respuesta_correcta:1,explicacion:"Para mezclas zeotr\xF3picas como R-454B: usar la columna VAPOR (dew point) de la tabla P/T para calcular superheat. A 112 PSI vapor \u2248 45\xB0F de saturaci\xF3n. Superheat = 55\xB0F - 45\xB0F = 10\xB0F.",question:"An R-454B system has a suction pressure of 112 PSI. The suction line measures 55\xB0F. What is the superheat?",options:["Cannot be calculated with A2L","Superheat = 55\xB0F - 45\xB0F = 10\xB0F (using the R-454B vapor P/T chart)","Superheat = 55\xB0F - 40\xB0F = 15\xB0F","A2L refrigerants don't have superheat"],explanation:"For zeotropic blends like R-454B: use the VAPOR (dew point) column of the P/T chart to calculate superheat. At 112 PSI vapor \u2248 45\xB0F saturation. Superheat = 55\xB0F - 45\xB0F = 10\xB0F."},{id:"a2l_104",categoria:"A2L_CAMPO",pregunta:"Al cargar R-454B, \xBFen qu\xE9 posici\xF3n debe estar el cilindro y en qu\xE9 estado debe estar el refrigerante?",opciones:["Cilindro vertical, cargar en gas","Cilindro invertido, cargar en L\xCDQUIDO para prevenir fraccionamiento","Cilindro en cualquier posici\xF3n, gas o l\xEDquido igual","Cilindro horizontal, cargar en gas"],respuesta_correcta:1,explicacion:"R-454B debe cargarse en L\xCDQUIDO para prevenir fraccionamiento. Para obtener l\xEDquido del cilindro: invertirlo (si es cilindro sin dip tube) o usar el dip tube si lo tiene. Luego controlar el flujo con la v\xE1lvula del manifold.",question:"When charging R-454B, what position should the cylinder be in and in what state should the refrigerant be?",options:["Cylinder vertical, charge as gas","Cylinder inverted, charge as LIQUID to prevent fractionation","Cylinder in any position, gas or liquid equally","Cylinder horizontal, charge as gas"],explanation:"R-454B must be charged as LIQUID to prevent fractionation. To get liquid from the cylinder: invert it (if it has no dip tube) or use the dip tube if it has one. Then control flow with the manifold valve."},{id:"a2l_105",categoria:"A2L_CAMPO",pregunta:"Un sistema R-32 tiene superheat de evaporador de 5\xB0F. \xBFQu\xE9 indica esto?",opciones:["El sistema est\xE1 perfectamente cargado","El superheat est\xE1 demasiado BAJO \u2014 riesgo de que refrigerante l\xEDquido llegue al compresor","El sistema necesita m\xE1s refrigerante","El condensador est\xE1 sucio"],respuesta_correcta:1,explicacion:"Superheat de 5\xB0F es DEMASIADO BAJO. El sistema necesita suficiente superheat (t\xEDpicamente 8-15\xB0F para sistemas residenciales) para asegurar que solo vapor seco llega al compresor. L\xEDquido al compresor puede causar falla catastr\xF3fica.",question:"An R-32 system has an evaporator superheat of 5\xB0F. What does this indicate?",options:["The system is perfectly charged","Superheat is too LOW \u2014 risk of liquid refrigerant reaching the compressor","The system needs more refrigerant","The condenser is dirty"],explanation:"Superheat of 5\xB0F is TOO LOW. The system needs sufficient superheat (typically 8-15\xB0F for residential systems) to ensure only dry vapor reaches the compressor. Liquid to the compressor can cause catastrophic failure."},{id:"a2l_106",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 puede indicar burbujas en la mirilla (sight glass) de un sistema R-454B en operaci\xF3n normal?",opciones:["El sistema funciona perfectamente","Refrigerante insuficiente (bajo subcooling o baja carga)","El sistema tiene exceso de refrigerante","Las burbujas son normales en A2L"],respuesta_correcta:1,explicacion:"Burbujas en la mirilla indican que el refrigerante llega en mezcla gas-l\xEDquido a la v\xE1lvula de expansi\xF3n \u2014 generalmente por BAJA CARGA de refrigerante o subcooling insuficiente. Investigar causa antes de a\xF1adir refrigerante.",question:"What can bubbles in the sight glass of an R-454B system during normal operation indicate?",options:["The system is working perfectly","Insufficient refrigerant (low subcooling or low charge)","The system has excess refrigerant","Bubbles are normal in A2L"],explanation:"Bubbles in the sight glass indicate refrigerant is arriving at the expansion valve as a gas-liquid mixture \u2014 generally from LOW CHARGE or insufficient subcooling. Investigate the cause before adding refrigerant."},{id:"a2l_107",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es el indicador visual de que un cilindro A2L tiene refrigerante inflamable?",opciones:["Color azul del cilindro","Banda roja en la parte superior del cilindro","Etiqueta amarilla","No hay indicador visual est\xE1ndar"],respuesta_correcta:1,explicacion:"Los cilindros con refrigerante inflamable DEBEN tener una BANDA ROJA en la parte superior. AHRI Guideline N establece que todos los cilindros deben ser color gris/verde claro, pero los inflamables a\xF1aden la banda roja.",question:"What is the visual indicator that an A2L cylinder contains flammable refrigerant?",options:["Blue cylinder color","Red band on the top of the cylinder","Yellow label","No standard visual indicator"],explanation:"Cylinders with flammable refrigerant MUST have a RED BAND on the top. AHRI Guideline N establishes that all cylinders should be light gray/green, but flammable ones add the red band."},{id:"a2l_108",categoria:"A2L_CAMPO",pregunta:"Un t\xE9cnico descubre que un sistema nuevo R-454B tiene una presi\xF3n de baja de 80 PSI y la temperatura de saturaci\xF3n correspondiente es 30\xB0F. La l\xEDnea de succi\xF3n mide 45\xB0F. \xBFCu\xE1l es el superheat?",opciones:["15\xB0F","25\xB0F","30\xB0F","45\xB0F"],respuesta_correcta:0,explicacion:"Superheat = temperatura de l\xEDnea de succi\xF3n - temperatura de saturaci\xF3n = 45\xB0F - 30\xB0F = 15\xB0F. Este valor (15\xB0F) est\xE1 dentro del rango normal t\xEDpico para sistemas residenciales (8-20\xB0F depending on system).",question:"A technician discovers a new R-454B system has a low-side pressure of 80 PSI and the corresponding saturation temperature is 30\xB0F. The suction line measures 45\xB0F. What is the superheat?",options:["15\xB0F","25\xB0F","30\xB0F","45\xB0F"],explanation:"Superheat = suction line temperature - saturation temperature = 45\xB0F - 30\xB0F = 15\xB0F. This value (15\xB0F) is within the normal typical range for residential systems (8-20\xB0F depending on system)."},{id:"a2l_109",categoria:"A2L_CAMPO",pregunta:"Al revisar un sistema R-32, la presi\xF3n de alta es 350 PSI y la temperatura de la l\xEDnea l\xEDquida es 95\xB0F. La temperatura de saturaci\xF3n a 350 PSI es 110\xB0F. \xBFCu\xE1l es el subcooling?",opciones:["15\xB0F","25\xB0F","5\xB0F","110\xB0F"],respuesta_correcta:0,explicacion:"Subcooling = temperatura de saturaci\xF3n - temperatura de l\xEDnea l\xEDquida = 110\xB0F - 95\xB0F = 15\xB0F. Un subcooling de 15\xB0F es t\xEDpicamente bueno para sistemas residenciales, indicando que hay suficiente l\xEDquido subenfriado llegando a la v\xE1lvula de expansi\xF3n.",question:"When checking an R-32 system, the high-side pressure is 350 PSI and the liquid line temperature is 95\xB0F. The saturation temperature at 350 PSI is 110\xB0F. What is the subcooling?",options:["15\xB0F","25\xB0F","5\xB0F","110\xB0F"],explanation:"Subcooling = saturation temperature - liquid line temperature = 110\xB0F - 95\xB0F = 15\xB0F. A subcooling of 15\xB0F is typically good for residential systems, indicating sufficient subcooled liquid is reaching the expansion valve."},{id:"a2l_110",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 precauci\xF3n especial aplica cuando uses soplete para soldar en un sistema que previamente ten\xEDa R-32?",opciones:["Ninguna \u2014 solo soldar normalmente","Recuperar el R-32, hacer nitrogen sweep, verificar con detector de gases que el \xE1rea est\xE9 libre de vapores antes de usar soplete","Solo apagar el sistema","Solo asegurarse de que no haya fugas"],respuesta_correcta:1,explicacion:"Antes de soldar en sistema previo con R-32: (1) recuperar completamente, (2) nitrogen sweep para desplazar vapores en el aceite, (3) verificar con detector que el \xE1rea est\xE9 libre de vapores inflamables. El aceite POE puede retener R-32 que se libera con el calor.",question:"What special precaution applies when using a torch to braze on a system that previously had R-32?",options:["None \u2014 just braze normally","Recover the R-32, perform nitrogen sweep, verify with gas detector that the area is free of vapors before using torch","Only turn off the system","Only make sure there are no leaks"],explanation:"Before brazing on a system that previously had R-32: (1) recover completely, (2) nitrogen sweep to displace vapors in the oil, (3) verify with detector that the area is free of flammable vapors. POE oil can retain R-32 that is released with heat."},{id:"a2l_111",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo calculas el peso m\xE1ximo que puedes poner en un cilindro de recuperaci\xF3n?",opciones:["El cilindro puede llenarse completamente","(Water Capacity \xD7 0.80) + Tare Weight = peso m\xE1ximo total del cilindro","Solo pesar el refrigerante recuperado","No es necesario calcular \u2014 la m\xE1quina para autom\xE1ticamente"],respuesta_correcta:1,explicacion:"F\xF3rmula: (WC \xD7 0.80) + TW = peso m\xE1ximo permitido. WC (Water Capacity) y TW (Tare Weight) est\xE1n estampados en el collar del cilindro. El 80% asegura espacio para expansi\xF3n del refrigerante.",question:"How do you calculate the maximum weight you can put in a recovery cylinder?",options:["The cylinder can be filled completely","(Water Capacity \xD7 0.80) + Tare Weight = maximum allowed total weight of the cylinder","Only weigh the recovered refrigerant","Not necessary to calculate \u2014 the machine stops automatically"],explanation:"Formula: (WC x 0.80) + TW = maximum allowed weight. WC (Water Capacity) and TW (Tare Weight) are stamped on the cylinder collar. The 80% ensures space for refrigerant expansion."},{id:"a2l_112",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 indican las letras 'WC' y 'TW' en el collar de un cilindro DOT?",opciones:["Working Capacity y Total Weight","Water Capacity (capacidad de agua en lbs) y Tare Weight (peso del cilindro vac\xEDo)","Work Condition y Transfer Weight","Weight Certified y Tank Weight"],respuesta_correcta:1,explicacion:"WC = Water Capacity (capacidad de agua en lbs) \u2014 indica el volumen del cilindro. TW = Tare Weight (peso del cilindro vac\xEDo en lbs). Estos dos valores se usan para calcular cu\xE1nto refrigerante puede caber.",question:"What do the letters 'WC' and 'TW' on the collar of a DOT cylinder indicate?",options:["Working Capacity and Total Weight","Water Capacity (water capacity in lbs) and Tare Weight (empty cylinder weight)","Work Condition and Transfer Weight","Weight Certified and Tank Weight"],explanation:"WC = Water Capacity (water capacity in lbs) \u2014 indicates the cylinder volume. TW = Tare Weight (empty cylinder weight in lbs). These two values are used to calculate how much refrigerant can fit."},{id:"a2l_113",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 debe hacer el t\xE9cnico si el sistema de A2L tiene fuga activa al llegar al trabajo?",opciones:["Comenzar el trabajo con cuidado extra","EVACUAR el \xE1rea, VENTILAR, verificar que est\xE9 libre de fuentes de ignici\xF3n y vapores inflamables antes de regresar a dar servicio","Solo abrir ventanas y continuar","Solo apagar el equipo"],respuesta_correcta:1,explicacion:"Con fuga activa de A2L: EVACUAR inmediatamente, VENTILAR el \xE1rea, y verificar con detector de gases que el \xE1rea est\xE9 libre de vapores inflamables Y fuentes de ignici\xF3n antes de regresar. No asumir que la concentraci\xF3n es segura.",question:"What should the technician do if the A2L system has an active leak upon arrival?",options:["Begin work with extra care","EVACUATE the area, VENTILATE, verify free of ignition sources and flammable vapors before returning to service","Only open windows and continue","Only turn off the equipment"],explanation:"With active A2L leak: EVACUATE immediately, VENTILATE the area, and verify with a gas detector that the area is free of flammable vapors AND ignition sources before returning. Do not assume the concentration is safe."},{id:"a2l_114",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo verificas con un detector electr\xF3nico que el \xE1rea est\xE1 libre de vapores A2L antes de usar soplete?",opciones:["No es posible verificar con detector \u2014 solo confiar en el olfato","Usar el detector en modo refrigerante, revisar m\xFAltiples puntos bajos del \xE1rea (los vapores se acumulan en puntos bajos)","Solo verificar cerca del equipo","Los detectores no funcionan para A2L"],respuesta_correcta:1,explicacion:"Los vapores de A2L son m\xE1s pesados que el aire y se acumulan en PUNTOS BAJOS. Verificar con detector en los puntos m\xE1s bajos del \xE1rea (pisos, rincones, s\xF3tanos) antes de usar soplete o cualquier fuente de ignici\xF3n.",question:"How do you verify with an electronic detector that the area is free of A2L vapors before using a torch?",options:["Cannot verify with detector \u2014 just trust your sense of smell","Use the detector in refrigerant mode, check multiple low points in the area (vapors accumulate at low points)","Only check near the equipment","Detectors don't work for A2L"],explanation:"A2L vapors are heavier than air and accumulate at LOW POINTS. Verify with the detector at the lowest points in the area (floors, corners, basements) before using a torch or any ignition source."},{id:"a2l_115",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 herramienta usa el t\xE9cnico para verificar que el sistema A2L tiene voltaje CERO antes de trabajar?",opciones:["Solo el interruptor del panel","Mult\xEDmetro para verificar ausencia de voltaje \u2014 despu\xE9s del lockout/tagout","El term\xF3metro digital","El medidor de presi\xF3n"],respuesta_correcta:1,explicacion:"OBLIGATORIO: despu\xE9s de aplicar lockout/tagout (LOTO), verificar con MULT\xCDMETRO que NO hay voltaje presente. El t\xE9cnico debe tener la \xFAnica llave del candado LOTO. Nunca asumir que el sistema est\xE1 de-energizado solo porque el switch est\xE1 apagado.",question:"What tool does the technician use to verify the A2L system has ZERO voltage before working?",options:["Only the panel switch","Multimeter to verify absence of voltage \u2014 after lockout/tagout","The digital thermometer","The pressure gauge"],explanation:"MANDATORY: after applying lockout/tagout (LOTO), verify with a MULTIMETER that NO voltage is present. The technician must have the only key to the LOTO padlock. Never assume the system is de-energized just because the switch is off."},{id:"a2l_116",categoria:"A2L_CAMPO",pregunta:"Un t\xE9cnico nota que un sistema R-454B nuevo del a\xF1o pasado ya necesita recarga por segunda vez. \xBFQu\xE9 debe hacer?",opciones:["Recargar \u2014 es normal en sistemas nuevos","Encontrar y reparar la fuga ANTES de recargar \u2014 recargar sin reparar viola regulaciones de fuga","Solo a\xF1adir la cantidad perdida","Reemplazar el compresor"],respuesta_correcta:1,explicacion:"Recargar sin reparar la fuga viola las regulaciones EPA. PRIMERO localizar y reparar la fuga, LUEGO recargar. Un sistema que necesita recarga frecuente es evidencia de fuga \u2014 legalmente debe repararse.",question:"A technician notices a new R-454B system from last year already needs recharging for the second time. What should be done?",options:["Recharge \u2014 it is normal in new systems","Find and repair the leak BEFORE recharging \u2014 recharging without repairing violates leak regulations","Only add the lost amount","Replace the compressor"],explanation:"ALWAYS locate and repair the leak BEFORE recharging. EPA regulations require leak repair. Recharging without repairing is wasting refrigerant, money, and potentially violating leak regulations if the system exceeds the annual threshold."},{id:"a2l_117",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 s\xEDmbolo ISO debe aparecer en la placa del equipo cuando usa refrigerante inflamable?",opciones:["ISO 9001 \u2014 calidad","ISO 7010-W021 \u2014 s\xEDmbolo de llama (tri\xE1ngulo amarillo con llama)","ISO 14001 \u2014 ambiental","No se requiere s\xEDmbolo especial"],respuesta_correcta:1,explicacion:"El s\xEDmbolo ISO 7010-W021 (tri\xE1ngulo amarillo con llama negra) DEBE estar en la placa de datos de equipos con refrigerante inflamable, cerca de donde se indica el tipo y cantidad de refrigerante.",question:"What ISO symbol must appear on the equipment nameplate when it uses flammable refrigerant?",options:["ISO 9001 \u2014 quality","ISO 7010-W021 \u2014 flame symbol (yellow triangle with flame)","ISO 14001 \u2014 environmental","No special symbol required"],explanation:"The ISO 7010-W021 symbol (yellow triangle with black flame) MUST be on the data plate of equipment with flammable refrigerant, near where the refrigerant type and quantity are indicated."},{id:"a2l_118",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 debe escribir el t\xE9cnico en la etiqueta del equipo cuando va a desechar un sistema A2L?",opciones:["Nada \u2014 no se requiere documentaci\xF3n para desecho","Que el equipo fue descomisionado y el refrigerante fue recuperado, con fecha y firma del t\xE9cnico","Solo el n\xFAmero de serie","Solo la fecha"],respuesta_correcta:1,explicacion:"Al descomisionar equipo A2L: la etiqueta DEBE indicar que fue descomisionado y el refrigerante fue recuperado. Debe estar fechada y firmada por el t\xE9cnico. Esta documentaci\xF3n es legalmente requerida.",question:"What must the technician write on the equipment label when decommissioning an A2L system?",options:["Nothing \u2014 no documentation required for disposal","That the equipment was decommissioned and the refrigerant was recovered, with date and technician signature","Only the serial number","Only the date"],explanation:"When decommissioning A2L equipment: the label MUST indicate it was decommissioned and the refrigerant was recovered. It must be dated and signed by the technician. This documentation is legally required."},{id:"a2l_119",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 deben incluir los componentes de reemplazo para un sistema A2L en campo?",opciones:["Cualquier componente del mismo tama\xF1o f\xEDsico","Solo partes OEM especificadas por el fabricante \u2014 certificadas para operar en ambiente A2L inflamable","Cualquier componente certificado UL","Solo verificar que el voltaje sea correcto"],respuesta_correcta:1,explicacion:"SOLO partes OEM del fabricante. Partes de terceros no certificadas para A2L pueden no estar dise\xF1adas para operar seguramente en ambiente inflamable y podr\xEDan convertirse en fuente de ignici\xF3n si fallan.",question:"What must replacement components for an A2L system in the field include?",options:["Any component of the same physical size","Only OEM parts specified by the manufacturer \u2014 certified to operate in A2L flammable environment","Any UL-certified component","Only verify correct voltage"],explanation:"ONLY OEM parts from the manufacturer. Third-party parts not certified for A2L may not be designed to operate safely in a flammable environment and could become an ignition source if they fail."},{id:"a2l_120",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo debe descargarse un capacitor en un sistema A2L para evitar riesgo de ignici\xF3n?",opciones:["Con destornillador directamente en los terminales \u2014 m\xE1s r\xE1pido","Con resistor o herramienta de descarga que no genere chispa","No es necesario descargarlo","Solo esperar que se descargue solo con tiempo"],respuesta_correcta:1,explicacion:"En sistemas A2L, el cortocircuito directo del capacitor con destornillador est\xE1 PROHIBIDO \u2014 genera chispa que puede encender el refrigerante. Usar un resistor o descargador especial que disipe la energ\xEDa sin chispa.",question:"How should a capacitor be discharged in an A2L system to avoid ignition risk?",options:["With a screwdriver directly on the terminals \u2014 faster","With a resistor or discharge tool that does not generate a spark","It is not necessary to discharge it","Just wait for it to discharge on its own over time"],explanation:"In A2L systems, direct short-circuiting the capacitor with a screwdriver is PROHIBITED \u2014 it generates a spark that can ignite the refrigerant. Use a resistor or special discharger that dissipates energy without sparking."},{id:"a2l_121",categoria:"A2L_CAMPO",pregunta:"Un sistema R-32 tiene presi\xF3n de baja muy alta y presi\xF3n de alta baja. \xBFQu\xE9 componente es sospechoso?",opciones:["Compresor en perfectas condiciones","V\xE1lvulas del compresor defectuosas o compresor con p\xE9rdida de compresi\xF3n","TXV atascada cerrada","Condensador sucio"],respuesta_correcta:1,explicacion:"Presiones de baja alta Y alta baja simult\xE1neamente indica que el compresor no est\xE1 comprimiendo efectivamente \u2014 v\xE1lvulas del compresor defectuosas o p\xE9rdida de compresi\xF3n interna. El compresor no puede crear la diferencia de presi\xF3n necesaria.",question:"An R-32 system has very high low-side pressure and low high-side pressure. What component is suspect?",options:["Compressor in perfect condition","Defective compressor valves or compressor with compression loss","TXV stuck closed","Dirty condenser"],explanation:"Simultaneously high low-side pressure AND low high-side pressure indicates the compressor is not compressing effectively \u2014 defective compressor valves or internal compression loss. The compressor cannot create the necessary pressure differential."},{id:"a2l_122",categoria:"A2L_CAMPO",pregunta:"Un sistema R-454B tiene presiones normales pero la temperatura de salida de aire es m\xE1s alta de lo normal. \xBFQu\xE9 verificar primero?",opciones:["Agregar refrigerante inmediatamente","Verificar el airflow (flujo de aire) \u2014 puede estar restringido por filtro sucio, bobina congelada, o ventilador defectuoso","Reemplazar el compresor","Verificar el termostato"],respuesta_correcta:1,explicacion:"Si las presiones son normales pero el enfriamiento es insuficiente, el problema m\xE1s probable es AIRFLOW restringido: filtro sucio, bobina congelada, ventilador que no gira correctamente, o ductos obstruidos. Verificar airflow antes de asumir problemas de refrigerante.",question:"An R-454B system has normal pressures but the supply air temperature is higher than normal. What to check first?",options:["Add refrigerant immediately","Check airflow \u2014 it may be restricted by dirty filter, frozen coil, or defective fan","Replace the compressor","Check the thermostat"],explanation:"If pressures are normal but cooling is insufficient, the most likely problem is RESTRICTED AIRFLOW: dirty filter, frozen coil, fan not spinning correctly, or blocked ductwork. Verify airflow before assuming refrigerant problems."},{id:"a2l_123",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 indica una temperatura de suction line muy caliente (alto superheat de sistema) en un sistema R-32?",opciones:["El sistema tiene exceso de refrigerante","El sistema est\xE1 bajo en refrigerante \u2014 la l\xEDnea de succi\xF3n se calienta porque el refrigerante se vaporiz\xF3 antes del final del evaporador","El condensador est\xE1 trabajando bien","El compresor est\xE1 en buen estado"],respuesta_correcta:1,explicacion:"Alto superheat de sistema generalmente indica BAJA CARGA de refrigerante. El refrigerante se evapora antes de llegar al final del evaporador, y el vapor restante se sigue calentando (superheating) en el evaporador y la l\xEDnea de succi\xF3n.",question:"What does a very hot suction line temperature (high system superheat) indicate in an R-32 system?",options:["The system has excess refrigerant","The system is low on refrigerant \u2014 the suction line gets hot because refrigerant evaporated before the end of the evaporator","The condenser is working well","The compressor is in good condition"],explanation:"High system superheat generally indicates LOW REFRIGERANT CHARGE. The refrigerant evaporates before reaching the end of the evaporator, and the remaining vapor continues heating (superheating) in the evaporator and suction line."},{id:"a2l_124",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 causa presi\xF3n de alta excesivamente elevada en un sistema R-454B funcionando?",opciones:["Baja carga de refrigerante","Condensador sucio/bloqueado, exceso de refrigerante, o presencia de no-condensables (aire)","Compresor defectuoso","TXV mal calibrada"],respuesta_correcta:1,explicacion:"Presi\xF3n de alta excesiva puede ser por: condensador sucio/bloqueado (m\xE1s com\xFAn), exceso de carga de refrigerante, presencia de no-condensables (aire en el sistema), o temperatura ambiente extremadamente alta.",question:"What causes excessively high discharge pressure in a running R-454B system?",options:["Low refrigerant charge","Dirty/blocked condenser, excess refrigerant, or presence of non-condensables (air)","Defective compressor","Miscalibrated TXV"],explanation:"Excessive high-side pressure can be from: dirty/blocked condenser (most common), excess refrigerant charge, presence of non-condensables (air in the system), or extremely high ambient temperature."},{id:"a2l_125",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo distingues una fuga de A2L de una fuga de A1 durante diagn\xF3stico?",opciones:["No hay diferencia \u2014 mismo proceso","Mismos m\xE9todos de detecci\xF3n, pero debes usar detector espec\xEDfico para el refrigerante del sistema Y tomar precauciones extra de seguridad antes de iniciar","Los A2L no se pueden detectar con detector electr\xF3nico","Los A2L son indetectables"],respuesta_correcta:1,explicacion:"Los m\xE9todos de detecci\xF3n son similares (detector electr\xF3nico, agua jabonosa, UV), pero: (1) usar detector certificado para el refrigerante espec\xEDfico, (2) verificar el \xE1rea para fuentes de ignici\xF3n ANTES de iniciar la b\xFAsqueda de fugas, (3) los vapores A2L se acumulan en puntos bajos.",question:"How do you distinguish an A2L leak from an A1 leak during diagnosis?",options:["There is no difference \u2014 same process","Same detection methods, but you must use a detector specific to the system's refrigerant AND take extra safety precautions before starting","A2L cannot be detected with electronic detector","A2L are undetectable"],explanation:"Detection methods are similar (electronic detector, soapy water, UV), but: (1) use a detector certified for the specific refrigerant, (2) check the area for ignition sources BEFORE starting the leak search, (3) A2L vapors accumulate at low points."},{id:"a2l_126",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 indica una presi\xF3n de baja negativamente baja (vac\xEDo) en un sistema en funcionamiento?",opciones:["El sistema funciona perfectamente","Posibles causas: refrigerante muy bajo, TXV atascada cerrada, o filtro drier muy restringido","El compresor est\xE1 fallando","El condensador est\xE1 sucio"],respuesta_correcta:1,explicacion:"Presi\xF3n de baja bajo lo normal o negativa indica restricci\xF3n severa en el lado de baja: filtro drier bloqueado, TXV atascada cerrada, refrigerante extremadamente bajo, o l\xEDnea de l\xEDquido restringida. Diagnosticar y eliminar cada posibilidad.",question:"What does a negatively low (vacuum) low-side pressure indicate in a running system?",options:["The system is working perfectly","Possible causes: very low refrigerant, TXV stuck closed, or very restricted filter drier","The compressor is failing","The condenser is dirty"],explanation:"Very low or negative low-side pressure indicates severe restriction on the low side: blocked filter drier, TXV stuck closed, extremely low refrigerant, or restricted liquid line. Diagnose and eliminate each possibility."},{id:"a2l_127",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 es el 'hunting' de una TXV y c\xF3mo se manifiesta en las presiones?",opciones:["Cuando el t\xE9cnico no puede encontrar la v\xE1lvula","Cuando la TXV oscila constantemente abriendo y cerrando \u2014 las presiones fluct\xFAan continuamente sin estabilizarse","Solo ocurre en sistemas A2L","Una v\xE1lvula que est\xE1 atascada cerrada"],respuesta_correcta:1,explicacion:"TXV 'hunting' = la v\xE1lvula oscila (abre/cierra) continuamente sin estabilizarse, causando fluctuaciones constantes en las presiones del sistema. Puede indicar: TXV sobredimensionada, bulbo de la TXV mal posicionado, o superheat incorrectamente ajustado.",question:"What is TXV 'hunting' and how does it manifest in the pressures?",options:["When the technician cannot find the valve","When the TXV constantly oscillates opening and closing \u2014 pressures fluctuate continuously without stabilizing","Only occurs in A2L systems","A valve that is stuck closed"],explanation:"TXV 'hunting' = the valve oscillates (opens/closes) continuously without stabilizing, causing constant fluctuations in system pressures. Can indicate: oversized TXV, improperly positioned TXV bulb, or incorrectly adjusted TXV superheat."},{id:"a2l_128",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo verificas si hay no-condensables (aire) en un sistema de A2L?",opciones:["No se puede verificar en campo","Comparar la presi\xF3n del sistema APAGADO y estabilizado con la presi\xF3n de saturaci\xF3n de la tabla P/T a la temperatura ambiente \u2014 si la presi\xF3n es mayor, hay no-condensables","Solo enviar el refrigerante al laboratorio","Los no-condensables no afectan los A2L"],respuesta_correcta:1,explicacion:"Con el sistema APAGADO y estabilizado (presi\xF3n igual en alta y baja): verificar la presi\xF3n de saturaci\xF3n de la tabla P/T a la temperatura ambiente actual. Si la presi\xF3n del sistema es MAYOR que la de saturaci\xF3n, hay no-condensables (aire) en el sistema.",question:"How do you verify if there are non-condensables (air) in an A2L system?",options:["Cannot be verified in the field","Compare the system pressure when OFF and stabilized with the saturation pressure from the P/T chart at the ambient temperature \u2014 if pressure is higher, there are non-condensables","Only send the refrigerant to the lab","Non-condensables don't affect A2L"],explanation:"With the system OFF and stabilized (pressure equalized on high and low sides): check the P/T chart saturation pressure at the current ambient temperature. If the system pressure is HIGHER than saturation, there are non-condensables (air) in the system."},{id:"a2l_129",categoria:"A2L_CAMPO",pregunta:"Un sistema R-32 tiene subcooling de 2\xB0F. \xBFQu\xE9 problema puede indicar?",opciones:["Subcooling excelente","Subcooling demasiado bajo \u2014 puede indicar baja carga de refrigerante o problema en el condensador","Subcooling demasiado alto","No hay problema con 2\xB0F"],respuesta_correcta:1,explicacion:"Subcooling de 2\xB0F es DEMASIADO BAJO. El subcooling insuficiente indica que el refrigerante no est\xE1 completamente subenfriado como l\xEDquido \u2014 puede haber burbujas de vapor en la l\xEDnea l\xEDquida causando ineficiencia y posible da\xF1o a la TXV.",question:"An R-32 system has a subcooling of 2\xB0F. What problem could this indicate?",options:["Excellent subcooling","Subcooling too low \u2014 may indicate low refrigerant charge or condenser problem","Subcooling too high","No problem with 2\xB0F"],explanation:"Subcooling of 2\xB0F is TOO LOW. Insufficient subcooling indicates the refrigerant is not fully subcooled as liquid \u2014 there may be vapor bubbles in the liquid line causing inefficiency and possible TXV damage."},{id:"a2l_130",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 indica un compresor que cicla frecuentemente (on/off) en un sistema R-454B?",opciones:["Funcionamiento normal","Posibles causas: sistema sobredimensionado, refrigerante incorrecto, presostato defectuoso, o problema de carga de calor insuficiente","El compresor est\xE1 en perfectas condiciones","Solo indica cambios de temperatura ambiente"],respuesta_correcta:1,explicacion:"Ciclado frecuente puede indicar: sistema sobredimensionado para el espacio, refrigerante incorrecto en el sistema, presostato o termostato defectuoso, o carga de calor insuficiente para el tama\xF1o del sistema.",question:"What does a compressor that cycles frequently (on/off) in an R-454B system indicate?",options:["Normal operation","Possible causes: oversized system, incorrect refrigerant, defective pressure switch, or insufficient heat load","The compressor is in perfect condition","Only indicates ambient temperature changes"],explanation:"Frequent cycling can indicate: system oversized for the space, incorrect refrigerant in the system, defective pressure switch or thermostat, or insufficient heat load for the system size."},{id:"a2l_131",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1les son los tres m\xE9todos principales para cargar un sistema de refrigeraci\xF3n?",opciones:["Solo por peso con escala","Carga cr\xEDtica por peso (escala), por superheat, y por subcooling","Solo por superheat","Solo leer las presiones del manifold"],respuesta_correcta:1,explicacion:"Los tres m\xE9todos principales son: (1) Carga cr\xEDtica por peso \u2014 m\xE1s precisa, especialmente para sistemas nuevos, (2) Por superheat \u2014 usa tabla de superheat del fabricante, (3) Por subcooling \u2014 usa tabla de subcooling del fabricante. El fabricante especifica cu\xE1l usar para su sistema.",question:"What are the three main methods for charging a refrigeration system?",options:["Only by weight with scale","Critical charge by weight (scale), by superheat, and by subcooling","Only by superheat","Only read manifold pressures"],explanation:"The three main methods are: (1) Critical charge by weight \u2014 most precise, especially for new systems, (2) By superheat \u2014 uses the manufacturer's superheat chart, (3) By subcooling \u2014 uses the manufacturer's subcooling chart. The manufacturer specifies which to use for their system."},{id:"a2l_132",categoria:"A2L_CAMPO",pregunta:"\xBFPara qu\xE9 tipo de sistema es m\xE1s apropiado el m\xE9todo de carga por SUPERHEAT?",opciones:["Sistemas con TXV","Sistemas con dispositivos de metering fijos (pist\xF3n/cap tube) en condiciones est\xE1ndar","Sistemas comerciales grandes","Sistemas A2L \xFAnicamente"],respuesta_correcta:1,explicacion:"El m\xE9todo de carga por superheat es m\xE1s apropiado para sistemas con dispositivos de metering FIJO (pist\xF3n o cap tube), donde la carga correcta se refleja en el superheat de evaporador. Los sistemas con TXV generalmente se cargan por subcooling.",question:"For what type of system is the SUPERHEAT charging method most appropriate?",options:["Systems with TXV","Systems with fixed metering devices (piston/cap tube) under standard conditions","Large commercial systems","A2L systems only"],explanation:"The superheat charging method is most appropriate for systems with FIXED metering devices (piston or cap tube), where the correct charge is reflected in the evaporator superheat. Systems with TXV are generally charged by subcooling."},{id:"a2l_133",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 el m\xE9todo de carga por peso es especialmente importante en sistemas nuevos A2L?",opciones:["Solo porque es m\xE1s r\xE1pido","Los A2L tienen restricciones de carga m\xE1xima \u2014 la carga exacta del fabricante asegura no exceder l\xEDmites de seguridad y garant\xEDa","El peso no importa para A2L","Solo para sistema de 3 toneladas o m\xE1s"],respuesta_correcta:1,explicacion:"Los sistemas A2L tienen restricciones de carga m\xE1xima (m1 o m2) basadas en el volumen del espacio. La carga exacta del fabricante (por peso) asegura: (1) m\xE1xima eficiencia, (2) no exceder l\xEDmites de seguridad de A2L, y (3) mantener la garant\xEDa del fabricante.",question:"Why is the weight charging method especially important in new A2L systems?",options:["Only because it is faster","A2L have maximum charge restrictions \u2014 the manufacturer's exact charge ensures safety limits and warranty are not exceeded","Weight doesn't matter for A2L","Only for 3-ton systems or larger"],explanation:"A2L systems have maximum charge restrictions (m1 or m2) based on the space volume. The manufacturer's exact charge (by weight) ensures: (1) maximum efficiency, (2) not exceeding A2L safety limits, and (3) maintaining the manufacturer's warranty."},{id:"a2l_134",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 verifica el t\xE9cnico ANTES de cargar un sistema A2L para asegurar que el airflow es correcto?",opciones:["Nada \u2014 cargar directamente","Verificar el airflow seg\xFAn los requisitos del fabricante antes de cargar","Solo verificar que el filtro est\xE9 limpio","Solo medir la temperatura de salida de aire"],respuesta_correcta:1,explicacion:"ANTES de cargar: verificar que el airflow del sistema coincide con los requisitos del fabricante. Un airflow incorrecto afectar\xE1 tanto el superheat como el subcooling, dando lecturas falsas que llevar\xEDan a una carga incorrecta.",question:"What does the technician verify BEFORE charging an A2L system to ensure airflow is correct?",options:["Nothing \u2014 charge directly","Verify airflow per manufacturer requirements before charging","Only verify the filter is clean","Only measure supply air temperature"],explanation:"BEFORE charging: verify that the system airflow matches the manufacturer's requirements. Incorrect airflow will affect both superheat and subcooling, giving false readings that would lead to incorrect charging."},{id:"a2l_135",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 es el 'critical charge' y cu\xE1ndo se usa?",opciones:["La carga m\xE1xima permitida por EPA","Cargar el sistema por peso exactamente seg\xFAn especificaciones del fabricante \u2014 especialmente importante en sistemas con l\xEDneas de longitud espec\xEDfica","La carga de emergencia cuando el sistema pierde todo el refrigerante","Solo para sistemas de muy alta presi\xF3n"],respuesta_correcta:1,explicacion:"Critical charge = cargar por peso exactamente la cantidad especificada por el fabricante. Es el m\xE9todo m\xE1s preciso y especialmente importante para: sistemas nuevos A2L, sistemas con longitud espec\xEDfica de l\xEDneas de tuber\xEDa, o sistemas donde el fabricante lo especifique.",question:"What is 'critical charge' and when is it used?",options:["The maximum charge allowed by EPA","Charging the system by exact weight per manufacturer specifications \u2014 especially important in systems with specific line lengths","The emergency charge when the system loses all refrigerant","Only for very high pressure systems"],explanation:"Critical charge = charging by exact weight per manufacturer specifications. It is the most precise method and especially important for: new A2L systems, systems with specific pipe length, or systems where the manufacturer specifies it."},{id:"a2l_136",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1ndo se recomienda a\xF1adir refrigerante con el cilindro en ICE (hielo) durante recuperaci\xF3n?",opciones:["Siempre \u2014 el hielo es mejor","Para acelerar la recuperaci\xF3n poniendo el cilindro en hielo, bajando su presi\xF3n interna y creando mayor diferencia de presi\xF3n para transferencia","Solo para sistemas muy grandes","Solo cuando hace calor extremo"],respuesta_correcta:1,explicacion:"Colocar el cilindro de recuperaci\xF3n en hielo durante la recuperaci\xF3n baja su temperatura y presi\xF3n interna. Esto crea mayor diferencia de presi\xF3n entre el sistema y el cilindro, acelerando el proceso de recuperaci\xF3n.",question:"When is it recommended to place the cylinder in ICE during recovery?",options:["Always \u2014 ice is always better","To speed up recovery by placing the cylinder in ice, lowering its internal pressure and creating greater pressure differential for transfer","Only for very large systems","Only in extreme heat"],explanation:"Placing the recovery cylinder in ice during recovery lowers its temperature and internal pressure. This creates a greater pressure differential between the system and the cylinder, speeding up the recovery process."},{id:"a2l_137",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es la diferencia entre 'subcooling de condensador' y 'subcooling de sistema'?",opciones:["Son exactamente lo mismo","Subcooling de condensador = medido en la salida del condensador. Subcooling de sistema = puede diferir por p\xE9rdidas de presi\xF3n en la l\xEDnea l\xEDquida","El de sistema siempre es mayor","Solo aplica a sistemas A1"],respuesta_correcta:1,explicacion:"Subcooling de condensador = temperatura de saturaci\xF3n (alta) - temperatura de l\xEDnea l\xEDquida en la SALIDA del condensador. Subcooling de sistema puede ser diferente si se mide en otro punto de la l\xEDnea l\xEDquida donde la presi\xF3n ya cay\xF3.",question:"What is the difference between 'condenser subcooling' and 'system subcooling'?",options:["They are exactly the same","Condenser subcooling = measured at condenser outlet. System subcooling = may differ due to pressure losses in the liquid line","System subcooling is always higher","Only applies to A1 systems"],explanation:"Condenser subcooling = saturation temperature (high side) - liquid line temperature at the condenser OUTLET. System subcooling may differ if measured at another point on the liquid line where pressure has already dropped."},{id:"a2l_138",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 le indica al t\xE9cnico una lectura de SUBCOOLING alta en un sistema R-32?",opciones:["El sistema est\xE1 perfectamente cargado","Posible sobrecarga de refrigerante o condensador muy eficiente (temperatura ambiente baja)","El sistema necesita m\xE1s refrigerante","El compresor est\xE1 fallando"],respuesta_correcta:1,explicacion:"Subcooling alto puede indicar: sobrecarga de refrigerante (a\xF1adir m\xE1s refrigerante del especificado), temperatura ambiente muy baja (condensaci\xF3n m\xE1s eficiente), o condensador sobredimensionado para las condiciones actuales.",question:"What does a HIGH subcooling reading indicate to the technician in an R-32 system?",options:["The system is perfectly charged","Possible refrigerant overcharge or very efficient condenser (low ambient temperature)","The system needs more refrigerant","The compressor is failing"],explanation:"High subcooling can indicate: refrigerant overcharge (adding more refrigerant than specified), very low ambient temperature (more efficient condensation), or oversized condenser for current conditions."},{id:"a2l_139",categoria:"A2L_CAMPO",pregunta:"Al a\xF1adir R-32 a un sistema que perdi\xF3 refrigerante por fuga reparada, \xBFc\xF3mo cargas correctamente?",opciones:["A\xF1adir hasta que las presiones parezcan normales","Primero reparar la fuga, luego cargar por peso la diferencia (cantidad especificada por fabricante menos lo que qued\xF3)","A\xF1adir un poco y ver c\xF3mo funciona","Solo cargar hasta que desaparezcan las burbujas en la mirilla"],respuesta_correcta:1,explicacion:"Proceso correcto: (1) PRIMERO reparar y verificar la fuga, (2) medir cu\xE1nto refrigerante queda si es posible, (3) cargar la diferencia para alcanzar la carga total especificada por el fabricante. Si no se puede medir el residual, recuperar todo y recargar completamente.",question:"When adding R-32 to a system that lost refrigerant from a repaired leak, how do you charge correctly?",options:["Add until pressures look normal","First repair the leak, then charge by weight the difference (manufacturer-specified amount minus what remained)","Add a little and see how it works","Only charge until sight glass bubbles disappear"],explanation:"Correct procedure: (1) FIRST repair and verify the leak, (2) measure how much refrigerant remains if possible, (3) charge the difference to reach the total charge specified by the manufacturer. If residual cannot be measured, recover everything and recharge completely."},{id:"a2l_140",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 el airflow incorrecto hace que el diagn\xF3stico de carga de refrigerante sea dif\xEDcil?",opciones:["No tiene efecto en el diagn\xF3stico","El airflow inadecuado cambia el superheat y subcooling de manera similar a una carga incorrecta, pudiendo llevar a diagn\xF3stico err\xF3neo","Solo afecta el confort, no el diagn\xF3stico","Solo en sistemas A2L"],respuesta_correcta:1,explicacion:"Airflow bajo causa superheat alto (similar a baja carga) y airflow alto causa superheat bajo (similar a sobrecarga). Siempre verificar airflow ANTES de diagnosticar la carga de refrigerante para evitar a\xF1adir o quitar refrigerante innecesariamente.",question:"Why does incorrect airflow make refrigerant charge diagnosis difficult?",options:["It has no effect on diagnosis","Inadequate airflow changes superheat and subcooling similarly to an incorrect charge, potentially leading to misdiagnosis","Only affects comfort, not diagnosis","Only in A2L systems"],explanation:"Low airflow causes high superheat (similar to low charge) and high airflow causes low superheat (similar to overcharge). Always verify airflow BEFORE diagnosing refrigerant charge to avoid unnecessarily adding or removing refrigerant."},{id:"a2l_141",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es el objetivo de la evacuaci\xF3n (pulling vacuum) antes de cargar refrigerante?",opciones:["Solo verificar que no hay fugas","Remover aire, humedad y otros no-condensables del sistema que da\xF1ar\xEDan el refrigerante y los componentes","Solo verificar que el sistema est\xE1 bien instalado","Reducir la presi\xF3n para cargar m\xE1s refrigerante"],respuesta_correcta:1,explicacion:"La evacuaci\xF3n remueve: (1) aire y no-condensables (que elevan artificialmente la presi\xF3n de alta), (2) humedad (que reacciona con el refrigerante y aceite formando \xE1cidos corrosivos). El \xFAnico objeto en el sistema debe ser refrigerante y aceite.",question:"What is the purpose of evacuation (pulling vacuum) before charging refrigerant?",options:["Only to verify there are no leaks","To remove air, moisture, and other non-condensables from the system that would damage the refrigerant and components","Only to verify the system is properly installed","To reduce pressure to charge more refrigerant"],explanation:"Evacuation removes: (1) air and non-condensables (which artificially raise high-side pressure), (2) moisture (which reacts with refrigerant and oil forming corrosive acids). The only substances in the system should be refrigerant and oil."},{id:"a2l_142",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 son los 'no-condensables' en el contexto de sistemas HVAC?",opciones:["Aceites que no se condensan","Gases (principalmente aire y nitr\xF3geno) que no se condensan a vapor en el ciclo de refrigeraci\xF3n \u2014 causan presiones altas artificialmente","Refrigerante en estado vapor","Contaminantes s\xF3lidos"],respuesta_correcta:1,explicacion:"No-condensables = gases que no se condensan en el ciclo de refrigeraci\xF3n (principalmente aire y nitr\xF3geno). Si est\xE1n en el sistema, se acumulan en el condensador elevando artificialmente la presi\xF3n de alta, reduciendo eficiencia y potencialmente da\xF1ando el compresor.",question:"What are 'non-condensables' in the context of HVAC systems?",options:["Oils that don't condense","Gases (primarily air and nitrogen) that don't condense in the refrigeration cycle \u2014 cause artificially high pressures","Refrigerant in vapor state","Solid contaminants"],explanation:"Non-condensables = gases that don't condense in the refrigeration cycle (primarily air and nitrogen). If present in the system, they accumulate in the condenser artificially raising high-side pressure, reducing efficiency, and potentially damaging the compressor."},{id:"a2l_143",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 fen\xF3meno ocurre con el agua durante una evacuaci\xF3n profunda?",opciones:["El agua se congela y queda en el sistema","La presi\xF3n reducida baja el punto de ebullici\xF3n del agua a temperatura ambiente, permitiendo que se evapore y sea removida por la bomba de vac\xEDo","El agua no puede removerse por vac\xEDo","El agua solo se remueve con calor"],respuesta_correcta:1,explicacion:"En un vac\xEDo profundo, el punto de ebullici\xF3n del agua baja dr\xE1sticamente (el agua hierve a temperatura ambiente bajo 500 micrones). Esto permite que la humedad se evapore y sea removida por la bomba de vac\xEDo \u2014 el proceso de DEHYDRATION.",question:"What phenomenon occurs with water during a deep evacuation?",options:["Water freezes and stays in the system","The reduced pressure lowers water's boiling point to ambient temperature, allowing it to evaporate and be removed by the vacuum pump","Water cannot be removed by vacuum","Water is only removed with heat"],explanation:"In a deep vacuum, water's boiling point drops drastically (water boils at ambient temperature below 500 microns). This allows moisture to evaporate and be removed by the vacuum pump \u2014 the DEHYDRATION process."},{id:"a2l_144",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1les son las dos etapas de la evacuaci\xF3n?",opciones:["Solo una etapa: vac\xEDo profundo","Degassing (remoci\xF3n de aire y no-condensables) primero, luego Dehydration (remoci\xF3n de humedad)","Dehydration primero, luego Degassing","Solo la etapa final de 500 micrones"],respuesta_correcta:1,explicacion:"Evacuaci\xF3n en dos etapas: (1) DEGASSING \u2014 remoci\xF3n de aire y no-condensables mientras la presi\xF3n baja hasta ~5,000 micrones, (2) DEHYDRATION \u2014 remoci\xF3n de humedad a medida que el vac\xEDo se profundiza por debajo de 5,000 micrones hacia 500 micrones.",question:"What are the two stages of evacuation?",options:["Only one stage: deep vacuum","Degassing (removal of air and non-condensables) first, then Dehydration (removal of moisture)","Dehydration first, then Degassing","Only the final 500-micron stage"],explanation:"Evacuation in two stages: (1) DEGASSING \u2014 removal of air and non-condensables while pressure drops to ~5,000 microns, (2) DEHYDRATION \u2014 removal of moisture as the vacuum deepens below 5,000 microns toward 500 microns."},{id:"a2l_145",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 NO se puede evaluar la evacuaci\xF3n por el sonido de la bomba o tiempo?",opciones:["S\xED se puede \u2014 una bomba ruidosa indica mal vac\xEDo","El nivel real de vac\xEDo solo se determina con un micr\xF3metro digital \u2014 el sonido y el tiempo no son indicadores confiables del nivel de vac\xEDo alcanzado","Solo para sistemas grandes","Solo si la bomba es nueva"],respuesta_correcta:1,explicacion:"El sonido de la bomba y el tiempo no correlacionan confiablemente con el nivel de vac\xEDo. Una bomba puede sonar 'bien' pero no alcanzar el vac\xEDo requerido por aceite contaminado. SIEMPRE medir con micr\xF3metro digital.",question:"Why can't evacuation be evaluated by the pump sound or time?",options:["Yes you can \u2014 a noisy pump indicates bad vacuum","The actual vacuum level is only determined with a digital micron gauge \u2014 sound and time are not reliable indicators of the vacuum level achieved","Only for large systems","Only if the pump is new"],explanation:"Pump sound and time do not reliably correlate with vacuum level. A pump may sound 'fine' but not reach the required vacuum due to contaminated oil. ALWAYS measure with a digital micron gauge."},{id:"a2l_146",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 indica si la presi\xF3n sube r\xE1pidamente despu\xE9s de aislar el sistema de la bomba de vac\xEDo?",opciones:["El sistema complet\xF3 la evacuaci\xF3n correctamente","Hay una FUGA en el sistema \u2014 el sistema no puede mantener el vac\xEDo","El sistema tiene humedad","La bomba es demasiado peque\xF1a"],respuesta_correcta:1,explicacion:"Si la presi\xF3n sube R\xC1PIDO y continuamente despu\xE9s de aislar: hay una FUGA en el sistema. Si la presi\xF3n sube LENTAMENTE y se estabiliza: hay humedad (la humedad se evapora hasta equilibrio). Si no sube o sube muy poco: evacuaci\xF3n exitosa.",question:"What does it indicate if pressure rises rapidly after isolating the system from the vacuum pump?",options:["The system completed evacuation correctly","There is a LEAK in the system \u2014 the system cannot maintain vacuum","The system has moisture","The pump is too small"],explanation:"If pressure rises FAST and continuously after isolating: there is a LEAK in the system. If pressure rises SLOWLY and stabilizes: there is moisture (moisture evaporates to equilibrium). If it doesn't rise or rises very little: evacuation successful."},{id:"a2l_147",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1ndo se debe cambiar el aceite de la bomba de vac\xEDo durante una evacuaci\xF3n larga?",opciones:["Solo al final de la evacuaci\xF3n","Cuando el aceite se ve turbio u oscuro durante la evacuaci\xF3n \u2014 los contaminantes del sistema degradan el aceite","Solo una vez al a\xF1o","Nunca durante una evacuaci\xF3n \u2014 solo antes"],respuesta_correcta:1,explicacion:"Durante evacuaciones largas o en sistemas muy h\xFAmedos/contaminados, el aceite puede degradarse y aparecer turbio. Cuando el aceite se contamina DURANTE la evacuaci\xF3n, cambiarlo inmediatamente y continuar para lograr el vac\xEDo requerido.",question:"When should vacuum pump oil be changed during a long evacuation?",options:["Only at the end of evacuation","When the oil looks cloudy or dark during evacuation \u2014 contaminants from the system degrade the oil","Only once a year","Never during evacuation \u2014 only before"],explanation:"During long evacuations or on very humid/contaminated systems, the oil can degrade and appear cloudy. When oil becomes contaminated DURING evacuation, change it immediately and continue to achieve the required vacuum."},{id:"a2l_148",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 es la 'triple evacuaci\xF3n' y cu\xE1ndo la requieren algunos fabricantes A2L?",opciones:["Evacuar tres veces el mismo sistema sin nitr\xF3geno","Evacuar \u2192 romper el vac\xEDo con nitr\xF3geno (hasta 0 PSI) \u2192 repetir 3 veces. Remueve humedad y contaminantes m\xE1s efectivamente","Solo es necesaria en sistemas de alta humedad","Solo para sistemas de m\xE1s de 5 toneladas"],respuesta_correcta:1,explicacion:"Triple evacuaci\xF3n: (1) evacuar a ~1,000-2,000 micrones, (2) romper vac\xEDo con nitr\xF3geno seco hasta presi\xF3n atmosf\xE9rica, (3) repetir el proceso 2 veces m\xE1s. Remueve humedad y no-condensables m\xE1s efectivamente que una sola evacuaci\xF3n. Algunos fabricantes A2L la requieren.",question:"What is 'triple evacuation' and when do some A2L manufacturers require it?",options:["Evacuate three times the same system without nitrogen","Evacuate \u2192 break vacuum with nitrogen (to 0 PSI) \u2192 repeat 3 times. Removes moisture and contaminants more effectively","Only necessary in high-humidity systems","Only for systems over 5 tons"],explanation:"Triple evacuation: (1) evacuate to ~1,000-2,000 microns, (2) break vacuum with dry nitrogen to atmospheric pressure, (3) repeat the process 2 more times. Removes moisture and non-condensables more effectively than a single evacuation. Some A2L manufacturers require it."},{id:"a2l_149",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo saber si los residuos de aceite A1 previo en las l\xEDneas afectar\xE1n el sistema A2L nuevo?",opciones:["No afecta \u2014 todos los aceites son iguales","Si quedan residuos significativos de aceite mineral en un sistema que se convertir\xE1 a A2L, pueden contaminar el aceite POE y causar problemas \u2014 algunos fabricantes requieren flush con N2","Solo es problema en sistemas peque\xF1os","Solo si el sistema ten\xEDa R-22"],respuesta_correcta:1,explicacion:"El aceite mineral previo puede contaminar el aceite POE del nuevo sistema A2L. Si el sistema tuvo R-22 (aceite mineral) y se convierte a R-454B (POE), algunos fabricantes requieren nitrogen sweep o flush para remover residuos de aceite mineral de las l\xEDneas.",question:"How do you know if residual A1 oil in existing lines will affect the new A2L system?",options:["It doesn't affect \u2014 all oils are the same","If significant mineral oil residue remains in a system being converted to A2L, it can contaminate the POE oil and cause problems \u2014 some manufacturers require N2 flush","Only a problem in small systems","Only if the system had R-22"],explanation:"Residual mineral oil can contaminate the POE oil in the new A2L system. If the system had R-22 (mineral oil) and is being converted to R-454B (POE), some manufacturers require nitrogen sweep or flush to remove mineral oil residue from the lines."},{id:"a2l_150",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 es importante cerrar el gas ballast de la bomba de vac\xEDo para el vaciado final?",opciones:["El gas ballast no importa","El gas ballast abierto permite entrada de aire que previene alcanzar el vac\xEDo profundo final \u2014 debe cerrarse para la etapa final","El gas ballast siempre debe estar cerrado","El gas ballast solo aplica a sistemas grandes"],respuesta_correcta:1,explicacion:"El gas ballast permite entrada de aire durante la evacuaci\xF3n para prevenir condensaci\xF3n en el aceite. Sin embargo, con el ballast abierto NO se puede alcanzar el vac\xEDo profundo final. Cerrar el ballast para la etapa final (por debajo de 5,000 micrones) para alcanzar 500 micrones.",question:"Why is it important to close the gas ballast on the vacuum pump for the final vacuum pull?",options:["The gas ballast doesn't matter","An open gas ballast allows air intake that prevents reaching the final deep vacuum \u2014 it must be closed for the final stage","The gas ballast should always be closed","The gas ballast only applies to large systems"],explanation:"The gas ballast allows air entry during evacuation to prevent condensation in the oil. However, with the ballast open the final deep vacuum CANNOT be achieved. Close the ballast for the final stage (below 5,000 microns) to reach 500 microns."},{id:"a2l_151",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1ndo es obligatorio el nitrogen sweep despu\xE9s de recuperar A2L?",opciones:["Solo si vas a usar soplete","Siempre despu\xE9s de recuperar A2L si vas a abrir el sistema con cualquier herramienta o trabajo que pueda generar chispa o calor","Solo en sistemas grandes","Solo si el sistema ten\xEDa fuga grande"],respuesta_correcta:1,explicacion:"El nitrogen sweep es obligatorio SIEMPRE que se vaya a hacer trabajo que pueda generar chispa, arco el\xE9ctrico, o calor \u2014 no solo al soldar. Esto incluye: soldadura, cambio de componentes el\xE9ctricos, y cualquier trabajo donde se abra el sistema en un \xE1rea con posible acumulaci\xF3n de vapores.",question:"When is nitrogen sweep mandatory after recovering A2L?",options:["Only if using a torch","Always after recovering A2L if you will open the system with any tool or work that could generate sparks or heat","Only in large systems","Only if the system had a large leak"],explanation:"Nitrogen sweep is mandatory WHENEVER work will be done that could generate sparks, electrical arcs, or heat \u2014 not just when brazing. This includes: brazing, electrical component changes, and any work where the system is opened in an area with possible vapor accumulation."},{id:"a2l_152",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 indica la NFPA 704 diamante rojo n\xFAmero 3 para un refrigerante?",opciones:["Sin riesgo de inflamabilidad","Inflamabilidad alta \u2014 el material puede encenderse bajo la mayor\xEDa de condiciones de temperatura ambiente","Solo levemente inflamable","Inflamabilidad moderada solo a temperaturas elevadas"],respuesta_correcta:1,explicacion:"NFPA 704 diamante rojo: 0=no inflamable, 1=requiere calentamiento significativo para encenderse, 2=requiere calentamiento moderado, 3=puede encenderse bajo la mayor\xEDa de condiciones de temperatura ambiente, 4=vaporizar\xE1 y quemar\xE1 r\xE1pidamente. Los A2L generalmente clasifican como 1-2.",question:"What does the NFPA 704 red diamond number 3 indicate for a refrigerant?",options:["No flammability risk","High flammability \u2014 the material can ignite under most ambient temperature conditions","Only mildly flammable","Moderate flammability only at elevated temperatures"],explanation:"NFPA 704 red diamond: 0=non-flammable, 1=requires significant heating to ignite, 2=requires moderate heating, 3=can ignite under most ambient temperature conditions, 4=will vaporize and burn rapidly. A2L generally classify as 1-2."},{id:"a2l_153",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 significa que un sistema A2L requiere 'active mitigation' para exceder la carga m1?",opciones:["Solo instalar un extinguidor adicional","Instalar sensores activos de refrigerante, ventilaci\xF3n mec\xE1nica activa, y/o sistemas de pump down autom\xE1tico antes de poder instalar la carga m2 mayor","Solo agregar m\xE1s R-32 al sistema","No tiene implicaciones especiales"],respuesta_correcta:1,explicacion:"Para exceder la carga m1 (carga sin mitigaci\xF3n), se deben instalar estrategias de mitigaci\xF3n activa antes de colocar la carga m2 mayor. Estas incluyen: sensores activos de refrigerante, ventilaci\xF3n mec\xE1nica activa, pump down autom\xE1tico, o combinaciones de estas medidas.",question:"What does it mean that an A2L system requires 'active mitigation' to exceed the m1 charge?",options:["Only install an additional extinguisher","Install active refrigerant sensors, active mechanical ventilation, and/or automatic pump-down systems before being able to install the larger m2 charge","Only add more R-32 to the system","No special implications"],explanation:"To exceed the m1 charge (charge without mitigation), active mitigation strategies must be installed before placing the larger m2 charge. These include: active refrigerant sensors, active mechanical ventilation, automatic pump-down, or combinations of these measures."},{id:"a2l_154",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 restricciones aplican al almacenamiento de A2L en un cuarto de m\xE1quinas sin sistema de sprinklers?",opciones:["No hay restricciones especiales","Hay un l\xEDmite de peso m\xE1ximo de refrigerante inflamable que se puede almacenar por \xE1rea de control \u2014 instalar sprinklers permite aumentar ese l\xEDmite","Solo se requiere ventilaci\xF3n","Solo para almacenamiento de m\xE1s de 500 lb"],respuesta_correcta:1,explicacion:"Los c\xF3digos (OSHA, DOT, locales) limitan el peso de refrigerante inflamable almacenado por \xE1rea de control SIN sprinklers. Con sistema de sprinklers activo instalado, ese l\xEDmite puede incrementarse. La cantidad exacta depende del refrigerante y el c\xF3digo local aplicable.",question:"What restrictions apply to A2L storage in a mechanical room without a sprinkler system?",options:["No special restrictions","There is a maximum weight limit of flammable refrigerant that can be stored per control area \u2014 installing sprinklers allows increasing that limit","Only ventilation is required","Only for storage of more than 500 lb"],explanation:"Codes (OSHA, DOT, local) limit the weight of flammable refrigerant stored per control area WITHOUT sprinklers. With an active sprinkler system installed, that limit can be increased. The exact amount depends on the refrigerant and applicable local code."},{id:"a2l_155",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1ndo se activa el vent del purgador en un sistema que usa A2L?",opciones:["Nunca \u2014 los A2L no tienen purgadores","Los purgadores NO se usan en sistemas A2L de alta presi\xF3n. Solo en sistemas de baja presi\xF3n (Tipo III). Para A2L, los no-condensables se previenen con buena evacuaci\xF3n","Solo en sistemas grandes","Solo en invierno"],respuesta_correcta:1,explicacion:"Los purgadores son espec\xEDficos de sistemas de BAJA PRESI\xD3N (Tipo III/chillers), donde el sistema opera al vac\xEDo y el aire entra por fugas. Los sistemas A2L de alta presi\xF3n (R-32, R-454B) NO usan purgadores \u2014 previenen no-condensables con buena evacuaci\xF3n.",question:"When does the purger vent activate in a system using A2L?",options:["Never \u2014 A2L systems don't have purgers","Purgers are NOT used in high-pressure A2L systems. Only in low-pressure (Type III) systems. For A2L, non-condensables are prevented with proper evacuation","Only in large systems","Only in winter"],explanation:"Purgers are specific to LOW PRESSURE (Type III/chiller) systems, where the system operates in vacuum and air enters through leaks. High-pressure A2L systems (R-32, R-454B) do NOT use purgers \u2014 they prevent non-condensables with proper evacuation."},{id:"a2l_156",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 verificaci\xF3n debe hacer el t\xE9cnico al reutilizar tuber\xEDas existentes para un nuevo sistema A2L?",opciones:["No es necesaria ninguna verificaci\xF3n","Verificar que las tuber\xEDas cumplen est\xE1ndares, son el tama\xF1o correcto para el nuevo sistema, est\xE1n limpias, y pasan prueba de presi\xF3n con nitr\xF3geno","Solo verificar el di\xE1metro","Solo verificar que no tienen fugas visibles"],respuesta_correcta:1,explicacion:"Para reutilizar tuber\xEDas: (1) verificar que cumplen los est\xE1ndares aplicables, (2) son el tama\xF1o y longitud correctos para el nuevo sistema, (3) est\xE1n limpias (sin contaminaci\xF3n, sin aceite mineral excesivo si era R-22), (4) pasan prueba de presi\xF3n con nitr\xF3geno.",question:"What verification must the technician perform when reusing existing tubing for a new A2L system?",options:["No verification is necessary","Verify that the tubing meets standards, is the correct size for the new system, is clean, and passes the nitrogen pressure test","Only verify the diameter","Only verify no visible leaks"],explanation:"To reuse tubing: (1) verify it meets applicable standards, (2) is the correct size and length for the new system, (3) is clean (no contamination, no excessive mineral oil if it was R-22), (4) passes the nitrogen pressure test."},{id:"a2l_157",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es el l\xEDmite de trace gas A2L para detecci\xF3n de fugas seg\xFAn ASHRAE 34?",opciones:["Sin l\xEDmite \u2014 solo unos pocos oz","No debe exceder 25% del LFL del refrigerante espec\xEDfico","Solo 1 oz m\xE1ximo","No se permite trace gas A2L"],respuesta_correcta:1,explicacion:"Al usar A2L como trace gas para detecci\xF3n de fugas: la cantidad NO debe exceder el 25% del LFL del refrigerante. Por ejemplo, si el LFL del R-32 es 14.4% del volumen del aire, el trace gas no debe crear concentraci\xF3n mayor al 3.6% en el \xE1rea.",question:"What is the trace gas A2L limit for leak detection according to ASHRAE 34?",options:["No limit \u2014 only a few oz","Must not exceed 25% of the LFL of the specific refrigerant","Only 1 oz maximum","Trace gas A2L is not allowed"],explanation:"When using A2L as trace gas for leak detection: the amount must NOT exceed 25% of the LFL of the refrigerant. For example, if R-32's LFL is 14.4% of air volume, the trace gas must not create concentration above 3.6% in the area."},{id:"a2l_158",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 se\xF1alizaci\xF3n debe tener un equipo A2L en el exterior de la unidad?",opciones:["Solo la placa de datos normal","Advertencia: 'Risk of Fire or Explosion. Flammable Refrigerant Used. To Be Repaired Only by Trained Service Personnel. Do Not Puncture Refrigerant Tubing'","Solo el s\xEDmbolo ISO","Solo el n\xFAmero de modelo"],respuesta_correcta:1,explicacion:"Los equipos con refrigerante inflamable deben tener etiqueta de advertencia que incluya: 'Warning \u2014 Risk of Fire or Explosion. Flammable Refrigerant Used. To Be Repaired Only by Trained Service Personnel. Do Not Puncture Refrigerant Tubing.'",question:"What signage must A2L equipment have on the exterior of the unit?",options:["Only the normal data plate","Warning: 'Risk of Fire or Explosion. Flammable Refrigerant Used. To Be Repaired Only by Trained Service Personnel. Do Not Puncture Refrigerant Tubing'","Only the ISO symbol","Only the model number"],explanation:"Equipment with flammable refrigerant must have a warning label that includes: 'Warning \u2014 Risk of Fire or Explosion. Flammable Refrigerant Used. To Be Repaired Only by Trained Service Personnel. Do Not Puncture Refrigerant Tubing.'"},{id:"a2l_159",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 los sistemas A2L requieren componentes el\xE9ctricos 'intrinsically safe' (IS)?",opciones:["Solo por est\xE9tica","Para prevenir que una falla el\xE9ctrica genere suficiente energ\xEDa para encender el refrigerante A2L \u2014 los contactores y capacitores son dise\xF1ados para contener cualquier chispa","Solo para reducir el consumo de electricidad","Solo es requerimiento est\xE9tico"],respuesta_correcta:1,explicacion:"Los componentes IS (intrinsically safe) est\xE1n dise\xF1ados para que NO puedan liberar suficiente energ\xEDa el\xE9ctrica o t\xE9rmica para encender una mezcla de A2L-aire. Los contactores y capacitores est\xE1n sellados para contener cualquier chispa dentro del enclosure.",question:"Why do A2L systems require 'intrinsically safe' (IS) electrical components?",options:["Only for aesthetics","To prevent an electrical failure from generating enough energy to ignite the A2L refrigerant \u2014 contactors and capacitors are designed to contain any spark","Only to reduce electricity consumption","Only an aesthetic requirement"],explanation:"IS (intrinsically safe) components are designed so they CANNOT release enough electrical or thermal energy to ignite an A2L-air mixture. Contactors and capacitors are sealed to contain any spark within the enclosure."},{id:"a2l_160",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1les son los 4 factores que hacen a los A2L significativamente m\xE1s seguros que los A3?",opciones:["Son m\xE1s baratos y f\xE1ciles de conseguir","MIE m\xE1s alto, LFL m\xE1s alto, menor calor de combusti\xF3n, y menor velocidad de llama","Solo son m\xE1s seguros porque la EPA los aprob\xF3","Solo por su menor GWP"],respuesta_correcta:1,explicacion:"Los 4 factores de seguridad A2L vs A3: (1) MIE m\xE1s ALTO = m\xE1s dif\xEDciles de encender, (2) LFL m\xE1s ALTO = requieren mayor concentraci\xF3n para inflamarse, (3) Calor de combusti\xF3n m\xE1s BAJO = menos energ\xEDa si se queman, (4) Velocidad de llama m\xE1s BAJA = fuego se propaga m\xE1s lentamente.",question:"What are the 4 factors that make A2L significantly safer than A3?",options:["They are cheaper and easier to obtain","Higher MIE, higher LFL, lower heat of combustion, and lower burning velocity","Only safer because EPA approved them","Only due to their lower GWP"],explanation:"The 4 A2L safety factors vs A3: (1) HIGHER MIE = harder to ignite, (2) HIGHER LFL = requires higher concentration to ignite, (3) LOWER heat of combustion = less energy if burned, (4) LOWER burning velocity = fire propagates more slowly."},{id:"a2l_161",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 el aceite mineral NO puede usarse con refrigerantes A2L como R-32 o R-454B?",opciones:["Solo por costo \u2014 el POE es m\xE1s barato","El aceite mineral no es miscible con HFCs/HFOs \u2014 no se mezcla con el refrigerante y puede acumularse en el evaporador causando mala transferencia de calor y falla del compresor","Solo por razones de garant\xEDa","El aceite mineral funciona igual que POE para A2L"],respuesta_correcta:1,explicacion:"Los HFCs y HFOs requieren aceite POE porque: el aceite mineral NO es miscible con estos refrigerantes. Si se usa mineral, el aceite se separa del refrigerante y se acumula en el evaporador, reduciendo la transferencia de calor y eventualmente drenando el compresor de lubricaci\xF3n.",question:"Why can mineral oil NOT be used with A2L refrigerants like R-32 or R-454B?",options:["Only cost \u2014 POE is cheaper","Mineral oil is not miscible with HFCs/HFOs \u2014 it does not mix with the refrigerant and can accumulate in the evaporator causing poor heat transfer and compressor failure","Only for warranty reasons","Mineral oil works the same as POE for A2L"],explanation:"HFCs and HFOs require POE oil because: mineral oil is NOT miscible with these refrigerants. If mineral is used, the oil separates from the refrigerant and accumulates in the evaporator, reducing heat transfer and eventually draining the compressor of lubrication."},{id:"a2l_162",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 el aceite POE debe manejarse con cuidado y no exponerse al aire libre?",opciones:["Solo porque es costoso","El POE es MUY higrosc\xF3pico \u2014 absorbe humedad del aire r\xE1pidamente. Una vez saturado de humedad puede formar \xE1cidos que da\xF1an el sistema","Por razones est\xE9ticas","Solo en climas h\xFAmedos"],respuesta_correcta:1,explicacion:"El POE es extremadamente higrosc\xF3pico \u2014 absorbe humedad del aire incluso a trav\xE9s de recipientes pl\xE1sticos. La exposici\xF3n recomendada al aire libre es de m\xE1ximo 15 minutos. Humedad en el POE puede causar hidr\xF3lisis, formando \xE1cidos y sludge que tapan componentes del sistema.",question:"Why must POE oil be handled carefully and not exposed to open air?",options:["Only because it is costly","POE is VERY hygroscopic \u2014 it absorbs moisture from air rapidly. Once saturated with moisture it can form acids that damage the system","For aesthetic reasons","Only in humid climates"],explanation:"POE is extremely hygroscopic \u2014 it absorbs moisture from air even through plastic containers. Recommended open-air exposure is maximum 15 minutes. Moisture in POE can cause hydrolysis, forming acids and sludge that clog system components."},{id:"a2l_163",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 es la 'hidr\xF3lisis' del aceite POE y cu\xE1ndo ocurre?",opciones:["Una limpieza especial del aceite","La descomposici\xF3n del POE por presencia de agua, formando \xE1cidos org\xE1nicos y alcohol \u2014 puede causar obstrucciones en v\xE1lvulas y filtros","Una propiedad de lubricaci\xF3n","Solo en sistemas de alta presi\xF3n"],respuesta_correcta:1,explicacion:"Hidr\xF3lisis = descomposici\xF3n del POE en presencia de agua, produciendo \xE1cidos org\xE1nicos, esters, y alcohol. Los \xE1cidos pueden corroer metales, da\xF1ar el barniz del motor del compresor, y tapar orificios de v\xE1lvulas y filtros.",question:"What is POE oil 'hydrolysis' and when does it occur?",options:["A special oil cleaning","The decomposition of POE in the presence of water, forming organic acids and alcohol \u2014 can cause blockages in valves and filters","A lubrication property","Only in high-pressure systems"],explanation:"Hydrolysis = decomposition of POE in the presence of water, producing organic acids, esters, and alcohol. The acids can corrode metals, damage the compressor motor varnish, and clog valve orifices and filters."},{id:"a2l_164",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 aceite se usa principalmente en sistemas de A/C automotriz con R-1234yf?",opciones:["Aceite mineral","Aceite POE","Aceite PAG (Polyalkylene Glycol)","Aceite alquilbenceno (AB)"],respuesta_correcta:2,explicacion:"R-1234yf en automotriz usa aceite PAG (Polyalkylene Glycol), igual que usaba con R-134a. El PAG es extremadamente higrosc\xF3pico y NO es miscible con refrigerantes que contengan cloro. Se usa espec\xEDficamente en sistemas automotrices.",question:"What oil is primarily used in automotive A/C systems with R-1234yf?",options:["Mineral oil","POE oil","PAG oil (Polyalkylene Glycol)","Alkylbenzene oil (AB)"],explanation:"R-1234yf in automotive uses PAG (Polyalkylene Glycol) oil, same as with R-134a. PAG is extremely hygroscopic and is NOT miscible with chlorine-containing refrigerants. It is used specifically in automotive systems."},{id:"a2l_165",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1nto tiempo m\xE1ximo se recomienda exposici\xF3n del aceite POE al aire libre?",opciones:["1 hora","15 minutos m\xE1ximo","No importa el tiempo","Solo 5 minutos"],respuesta_correcta:1,explicacion:"El aceite POE solo debe exponerse al aire libre por un m\xE1ximo de 15 minutos. Despu\xE9s de este tiempo, la absorci\xF3n de humedad puede ser significativa. Siempre cerrar el recipiente inmediatamente y almacenar en contenedor sellado de metal o vidrio.",question:"What is the maximum recommended exposure time for POE oil to open air?",options:["1 hour","15 minutes maximum","Time doesn't matter","Only 5 minutes"],explanation:"POE oil should only be exposed to open air for a maximum of 15 minutes. After this time, moisture absorption can be significant. Always close the container immediately and store in sealed metal or glass containers."},{id:"a2l_166",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 debe hacer el t\xE9cnico si sospecha que el aceite POE del sistema est\xE1 contaminado con humedad?",opciones:["Continuar operando \u2014 se limpiar\xE1 solo","Recuperar el refrigerante en tanque separado, drenar el aceite contaminado, limpiar el sistema, instalar nuevos filtros-drier, y a\xF1adir aceite POE nuevo y refrigerante","Solo cambiar el filtro-drier","Solo a\xF1adir m\xE1s aceite nuevo"],respuesta_correcta:1,explicacion:"Si el aceite POE est\xE1 contaminado con humedad o \xE1cidos: (1) recuperar refrigerante en tanque separado (no mezclar), (2) drenar aceite contaminado, (3) flush del sistema, (4) instalar nuevos filtros-drier (succi\xF3n y l\xEDquido), (5) a\xF1adir aceite POE nuevo limpio, (6) recargar refrigerante.",question:"What should the technician do if POE oil in the system is suspected to be contaminated with moisture?",options:["Continue operating \u2014 it will clean itself","Recover the refrigerant in a separate tank, drain the contaminated oil, clean the system, install new filter-driers, and add new POE oil and refrigerant","Only change the filter-drier","Only add more new oil"],explanation:"If POE oil is contaminated with moisture or acids: (1) recover refrigerant in a SEPARATE tank (don't mix), (2) drain contaminated oil, (3) system flush, (4) install new filter-driers (suction and liquid), (5) add clean new POE oil, (6) recharge refrigerant."},{id:"a2l_167",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 los aceites de refrigeraci\xF3n NO deben mezclarse entre s\xED?",opciones:["Solo por costo","La mezcla de aceites puede no lubriar correctamente el compresor o no ser miscible con el refrigerante del sistema","Solo si son de diferente marca","Los aceites pueden mezclarse sin problema"],respuesta_correcta:1,explicacion:"Los aceites de refrigeraci\xF3n tienen diferentes propiedades de viscosidad, miscibilidad con refrigerantes, y compatibilidad con materiales. Mezclarlos puede resultar en lubricaci\xF3n deficiente y/o incompatibilidad con el refrigerante, causando problemas de retorno de aceite al compresor.",question:"Why should refrigeration oils NOT be mixed with each other?",options:["Only because of cost","Mixing oils may not properly lubricate the compressor or may not be miscible with the system refrigerant","Only if they are different brands","Oils can be mixed without problem"],explanation:"Refrigeration oils have different viscosity properties, miscibility with refrigerants, and material compatibility. Mixing them can result in poor lubrication and/or incompatibility with the refrigerant, causing oil return problems to the compressor."},{id:"a2l_168",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 aceite lubricante es compatible con R-22 (HCFC)?",opciones:["Solo POE","Aceite mineral (MO) o Alquilbenceno (AB) son compatibles con HCFCs como R-22","Solo PAG","Cualquier aceite sirve para R-22"],respuesta_correcta:1,explicacion:"R-22 (HCFC) es compatible con aceite mineral (MO) y aceite alquilbenceno (AB). El aceite mineral es el m\xE1s tradicional con R-22. El AB tiene mejor miscibilidad en aplicaciones de baja temperatura.",question:"What lubricant oil is compatible with R-22 (HCFC)?",options:["Only POE","Mineral oil (MO) or Alkylbenzene (AB) are compatible with HCFCs like R-22","Only PAG","Any oil works for R-22"],explanation:"R-22 (HCFC) is compatible with mineral oil (MO) and alkylbenzene oil (AB). Mineral oil is the most traditional with R-22. AB has better miscibility in low-temperature applications."},{id:"a2l_169",categoria:"A2L_CAMPO",pregunta:"Al cambiar de R-22 (con aceite mineral) a R-454B (con POE), \xBFqu\xE9 se debe hacer con el aceite?",opciones:["Se puede dejar el aceite mineral \u2014 no hay problema","El aceite mineral debe ser removido. Algunos fabricantes requieren nitrogen sweep o flush de l\xEDneas para eliminar residuos de mineral antes de instalar el sistema R-454B","Solo a\xF1adir POE encima del mineral","El R-454B funciona bien con aceite mineral"],respuesta_correcta:1,explicacion:"La conversi\xF3n de R-22 a R-454B requiere remover el aceite mineral. Residuos de aceite mineral son incompatibles con el POE del nuevo sistema y con el R-454B. Verificar las instrucciones del fabricante del nuevo sistema para los pasos espec\xEDficos de limpieza de l\xEDneas.",question:"When changing from R-22 (with mineral oil) to R-454B (with POE), what must be done with the oil?",options:["The mineral oil can be left \u2014 no problem","The mineral oil must be removed. Some manufacturers require nitrogen sweep or line flush to eliminate mineral residue before installing the R-454B system","Only add POE on top of the mineral","R-454B works well with mineral oil"],explanation:"Converting from R-22 to R-454B requires removing the mineral oil. Mineral oil residue is incompatible with the new system's POE oil and with R-454B. Check the new system manufacturer's instructions for specific line cleaning steps."},{id:"a2l_170",categoria:"A2L_CAMPO",pregunta:"\xBFEn qu\xE9 contenedores debe almacenarse el aceite POE?",opciones:["Cualquier contenedor \u2014 incluyendo pl\xE1stico","Contenedores de metal o vidrio herm\xE9ticamente sellados \u2014 el POE puede absorber humedad incluso a trav\xE9s de pl\xE1stico","Solo en latas de aluminio","Solo en los contenedores originales del fabricante"],respuesta_correcta:1,explicacion:"El aceite POE debe almacenarse en contenedores de METAL o VIDRIO herm\xE9ticamente sellados. El POE es tan higrosc\xF3pico que puede absorber humedad incluso a trav\xE9s de contenedores pl\xE1sticos con el tiempo. Nunca usar contenedores pl\xE1sticos para almacenamiento a largo plazo.",question:"In what containers should POE oil be stored?",options:["Any container \u2014 including plastic","Metal or glass containers hermetically sealed \u2014 POE can absorb moisture even through plastic","Only in aluminum cans","Only in the manufacturer's original containers"],explanation:"POE oil must be stored in METAL or GLASS containers hermetically sealed. POE is so hygroscopic that it can absorb moisture even through plastic containers over time. Never use plastic containers for long-term storage."},{id:"a2l_171",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es la funci\xF3n principal del filtro-drier (filter-drier) en un sistema de refrigeraci\xF3n?",opciones:["Filtrar solo part\xEDculas s\xF3lidas","Filtrar part\xEDculas Y absorber humedad del refrigerante en el sistema sellado","Solo filtrar el aceite","Regular el flujo de refrigerante"],respuesta_correcta:1,explicacion:"El filtro-drier tiene dos funciones: (1) FILTRAR part\xEDculas s\xF3lidas (metales, suciedad) a trav\xE9s de screens y material filtrante, y (2) ABSORBER humedad (y \xE1cidos) a trav\xE9s del core desecante. Protege al compresor y a la v\xE1lvula de expansi\xF3n.",question:"What is the primary function of the filter-drier in a refrigeration system?",options:["Filter only solid particles","Filter particles AND absorb moisture from the refrigerant in the sealed system","Only filter the oil","Regulate refrigerant flow"],explanation:"The filter-drier has two functions: (1) FILTER solid particles (metals, dirt) through screens and filter media, and (2) ABSORB moisture (and acids) through the desiccant core. It protects the compressor and expansion valve."},{id:"a2l_172",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1ndo DEBE reemplazarse el filtro-drier en un sistema?",opciones:["Solo cuando se bloquea completamente","Siempre que el sistema se abre para reparaci\xF3n, Y cuando hay evidencia de contaminaci\xF3n de humedad o \xE1cidos","Solo una vez al a\xF1o","Solo despu\xE9s de cambio de compresor"],respuesta_correcta:1,explicacion:"El filtro-drier DEBE reemplazarse: (1) SIEMPRE que el sistema se abra para reparaci\xF3n (ya que se expone al aire y absorbe humedad), (2) cuando hay evidencia de humedad o \xE1cidos en el sistema, y (3) despu\xE9s de un burnout de compresor.",question:"When MUST the filter-drier be replaced in a system?",options:["Only when completely blocked","Whenever the system is opened for repair, AND when there is evidence of moisture or acid contamination","Only once a year","Only after compressor replacement"],explanation:"The filter-drier MUST be replaced: (1) WHENEVER the system is opened for repair (since it is exposed to air and absorbs moisture), (2) when there is evidence of moisture or acid in the system, and (3) after a compressor burnout."},{id:"a2l_173",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 un filtro-drier bloqueado debe CORTARSE del sistema en lugar de soldarse para removerse?",opciones:["Es m\xE1s r\xE1pido cortar","Aplicar calor al filtro-drier bloqueado puede liberar la humedad atrapada de vuelta al sistema. Cortarlo evita este problema","Por razones de seguridad del soldador","Solo si es de cobre"],respuesta_correcta:1,explicacion:"Un filtro-drier bloqueado contiene humedad y \xE1cidos atrapados. Aplicar calor de soldadura libera esta humedad de vuelta al sistema, contamin\xE1ndolo nuevamente. Siempre CORTAR el drier bloqueado para removerlo.",question:"Why must a blocked filter-drier be CUT from the system instead of unsoldered?",options:["It is faster to cut","Applying heat to a blocked filter-drier can release trapped moisture back into the system. Cutting it avoids this problem","For welder safety reasons","Only if it is copper"],explanation:"A blocked filter-drier contains trapped moisture and acids. Applying brazing heat releases this moisture back into the system, recontaminating it. Always CUT the blocked drier to remove it."},{id:"a2l_174",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 tipo de filtro-drier requieren los sistemas de bomba de calor?",opciones:["El mismo que sistemas de A/C de una sola direcci\xF3n","Bi-flow (flujo bidireccional) \u2014 porque el refrigerante fluye en ambas direcciones dependiendo del modo calefacci\xF3n/enfriamiento","Ninguno \u2014 las bombas de calor no necesitan drier","Solo uno de mayor capacidad"],respuesta_correcta:1,explicacion:"Los sistemas de bomba de calor requieren filtros-drier BI-FLOW que permiten el flujo de refrigerante en AMBAS DIRECCIONES. En modo enfriamiento el refrigerante fluye en un sentido; en modo calefacci\xF3n, en sentido contrario.",question:"What type of filter-drier do heat pump systems require?",options:["The same as one-directional A/C systems","Bi-flow (bidirectional flow) \u2014 because refrigerant flows in both directions depending on heating/cooling mode","None \u2014 heat pumps don't need driers","Only a larger capacity one"],explanation:"Heat pump systems require BI-FLOW filter-driers that allow refrigerant flow in BOTH DIRECTIONS. In cooling mode, refrigerant flows one way; in heating mode, it flows the opposite direction."},{id:"a2l_175",categoria:"A2L_CAMPO",pregunta:"\xBFC\xF3mo verifica el t\xE9cnico si un filtro-drier est\xE1 bloqueado?",opciones:["Visualmente \u2014 si se ve sucio est\xE1 bloqueado","Midiendo la temperatura o presi\xF3n en ambos lados del drier \u2014 si hay ca\xEDda de temperatura/presi\xF3n, est\xE1 bloqueado","Solo si el sistema no enfr\xEDa","El drier nunca se bloquea"],respuesta_correcta:1,explicacion:"Para verificar si el drier est\xE1 bloqueado: medir temperatura en ambos lados (entrada y salida). Si la temperatura de salida es significativamente MENOR (ca\xEDda de presi\xF3n en el drier), est\xE1 bloqueado. Tambi\xE9n se puede medir la diferencia de presi\xF3n con el manifold.",question:"How does the technician verify if a filter-drier is blocked?",options:["Visually \u2014 if it looks dirty it's blocked","By measuring temperature or pressure on both sides of the drier \u2014 if there is a temperature/pressure drop, it is blocked","Only if the system doesn't cool","The drier never blocks"],explanation:"To check if the drier is blocked: measure the temperature on both sides (inlet and outlet). If the outlet temperature is significantly LOWER (pressure drop across the drier), it is blocked. Pressure differential can also be measured with the manifold."},{id:"a2l_176",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es la funci\xF3n del acumulador en la l\xEDnea de succi\xF3n?",opciones:["Regular la presi\xF3n de alta","Prevenir que refrigerante l\xEDquido entre al compresor en la l\xEDnea de succi\xF3n, protegiendo contra liquid floodback","Almacenar refrigerante adicional","Filtrar el aceite del sistema"],respuesta_correcta:1,explicacion:"El acumulador est\xE1 en la l\xEDnea de succi\xF3n justo antes del compresor. Su funci\xF3n es proporcionar espacio para que cualquier l\xEDquido residual en la l\xEDnea de succi\xF3n se vaporice ANTES de llegar al compresor. Protege contra liquid floodback.",question:"What is the function of the accumulator in the suction line?",options:["Regulate high-side pressure","Prevent liquid refrigerant from entering the compressor in the suction line, protecting against liquid floodback","Store additional refrigerant","Filter system oil"],explanation:"The accumulator sits in the suction line just before the compressor. Its function is to provide space for any residual liquid in the suction line to vaporize BEFORE reaching the compressor. It protects against liquid floodback."},{id:"a2l_177",categoria:"A2L_CAMPO",pregunta:"\xBFPara qu\xE9 se usa el receptor (liquid receiver) en sistemas de refrigeraci\xF3n?",opciones:["Para almacenar aceite de compresor","Para almacenar l\xEDquido subcooled despu\xE9s del condensador, permitiendo pump-down y acomodando variaciones de carga","Para filtrar el refrigerante","Para medir la cantidad de refrigerante"],respuesta_correcta:1,explicacion:"El receiver se ubica despu\xE9s del condensador y almacena refrigerante l\xEDquido subcooled. Permite: (1) pump-down para servicio (almacena toda la carga del sistema), y (2) acomodar variaciones en la carga del sistema sin afectar la alimentaci\xF3n de refrigerante a la v\xE1lvula de expansi\xF3n.",question:"What is the liquid receiver used for in refrigeration systems?",options:["To store compressor oil","To store subcooled liquid after the condenser, allowing pump-down and accommodating charge variations","To filter the refrigerant","To measure refrigerant quantity"],explanation:"The receiver sits after the condenser and stores subcooled liquid refrigerant. It allows: (1) pump-down for service (stores the entire system charge), and (2) accommodating charge variations without affecting refrigerant supply to the expansion valve."},{id:"a2l_178",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 tipo de v\xE1lvula de expansi\xF3n tiene un orificio FIJO que no se ajusta?",opciones:["TXV (v\xE1lvula termost\xE1tica de expansi\xF3n)","Pist\xF3n (piston) o tubo capilar (cap tube) \u2014 dispositivos de metering fijo","AXV (v\xE1lvula autom\xE1tica de expansi\xF3n)","EEV (v\xE1lvula electr\xF3nica de expansi\xF3n)"],respuesta_correcta:1,explicacion:"Los dispositivos de metering FIJO son el pist\xF3n y el tubo capilar \u2014 tienen un orificio de tama\xF1o fijo. Las v\xE1lvulas ajustables son: TXV (termost\xE1tica), AXV (autom\xE1tica), y EEV (electr\xF3nica), todas con apertura variable que responde a condiciones del sistema.",question:"What type of expansion valve has a FIXED orifice that does not adjust?",options:["TXV (thermostatic expansion valve)","Piston or capillary tube (cap tube) \u2014 fixed metering devices","AXV (automatic expansion valve)","EEV (electronic expansion valve)"],explanation:"Fixed metering devices are the piston and capillary tube \u2014 they have a fixed-size orifice. Adjustable valves are: TXV (thermostatic), AXV (automatic), and EEV (electronic), all with variable openings that respond to system conditions."},{id:"a2l_179",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 la TXV mantiene un superheat de evaporador m\xE1s constante que un pist\xF3n?",opciones:["No hay diferencia entre TXV y pist\xF3n","La TXV regula activamente la apertura seg\xFAn el superheat medido por su bulbo sensor \u2014 m\xE1s refrigerante cuando hace m\xE1s calor, menos cuando hace menos","El pist\xF3n es m\xE1s eficiente que la TXV","La TXV solo funciona bien en sistemas A2L"],respuesta_correcta:1,explicacion:"La TXV tiene un bulbo sensor en la l\xEDnea de succi\xF3n que mide el superheat y ajusta continuamente la apertura de la v\xE1lvula. Cuando la carga aumenta (m\xE1s calor), abre m\xE1s para alimentar m\xE1s refrigerante. Esto mantiene el superheat en el rango objetivo independientemente de las condiciones.",question:"Why does the TXV maintain a more constant evaporator superheat than a piston?",options:["There is no difference between TXV and piston","The TXV actively regulates the opening based on superheat measured by its sensing bulb \u2014 more refrigerant when hotter, less when cooler","The piston is more efficient than the TXV","The TXV only works well in A2L systems"],explanation:"The TXV has a sensing bulb on the suction line that measures superheat and continuously adjusts the valve opening. When the load increases (more heat), it opens more to feed more refrigerant. This maintains superheat in the target range regardless of conditions."},{id:"a2l_180",categoria:"A2L_CAMPO",pregunta:"\xBFD\xF3nde debe instalarse el filtro-drier de l\xEDnea l\xEDquida para mayor vida \xFAtil?",opciones:["Cerca del condensador para mayor conveniencia","Preferiblemente en interiores cerca del dispositivo de metering \u2014 se expone a menor calor, extending su vida \xFAtil","No importa la ubicaci\xF3n","Solo cerca del compresor"],respuesta_correcta:1,explicacion:"El filtro-drier de l\xEDnea l\xEDquida dura m\xE1s instalado EN INTERIORES cerca del dispositivo de metering (TXV/pist\xF3n). Instalado cerca del condensador exterior se expone a mayor calor y temperatura c\xEDclica que puede degradar el desecante m\xE1s r\xE1pidamente.",question:"Where should the liquid line filter-drier be installed for maximum life?",options:["Near the condenser for convenience","Preferably indoors near the metering device \u2014 exposed to less heat, extending its lifespan","Location doesn't matter","Only near the compressor"],explanation:"The liquid line filter-drier lasts longer installed INDOORS near the metering device (TXV/piston). Installed near the outdoor condenser, it is exposed to more heat and temperature cycling that can degrade the desiccant more rapidly."},{id:"a2l_181",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 la l\xEDnea de succi\xF3n debe tener la pendiente correcta hacia el compresor?",opciones:["Para evitar fugas de refrigerante","Para facilitar el retorno de aceite al compresor \u2014 el aceite circula con el refrigerante y debe poder regresar","Solo por est\xE9tica","Solo en instalaciones comerciales"],respuesta_correcta:1,explicacion:"La l\xEDnea de succi\xF3n debe facilitar el RETORNO DE ACEITE al compresor. El aceite circula mezclado con el vapor de refrigerante. Si la l\xEDnea de succi\xF3n no tiene la pendiente/velocidad correcta, el aceite puede acumularse en la l\xEDnea y drenar el compresor de lubricaci\xF3n.",question:"Why must the suction line have the correct pitch toward the compressor?",options:["To prevent refrigerant leaks","To facilitate oil return to the compressor \u2014 oil circulates with the refrigerant and must be able to return","Only for aesthetics","Only in commercial installations"],explanation:"The suction line must facilitate OIL RETURN to the compressor. Oil circulates mixed with refrigerant vapor. If the suction line doesn't have the correct pitch/velocity, oil can accumulate in the line and drain the compressor of lubrication."},{id:"a2l_182",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 es un 'oil trap' (trampa de aceite) y cu\xE1ndo se instala en una l\xEDnea de succi\xF3n?",opciones:["Un filtro para el aceite","Un sif\xF3n en la l\xEDnea de succi\xF3n en subidas verticales largas \u2014 facilita el retorno de aceite hacia arriba contra la gravedad","Una v\xE1lvula de retenci\xF3n para aceite","Solo para sistemas industriales"],respuesta_correcta:1,explicacion:"Un oil trap es un sif\xF3n en forma de U en la parte inferior de subidas verticales largas en la l\xEDnea de succi\xF3n. Permite que el aceite se acumule y sea arrastrado por el vapor de refrigerante subiendo. Sin ellos, el aceite puede no retornar al compresor en instalaciones con l\xEDneas verticales largas.",question:"What is an 'oil trap' and when is it installed in a suction line?",options:["An oil filter","A trap in the suction line on long vertical rises \u2014 facilitates oil return upward against gravity","An oil check valve","Only for industrial systems"],explanation:"An oil trap is a U-shaped siphon at the bottom of long vertical rises in the suction line. It allows oil to accumulate and be carried by refrigerant vapor going up. Without them, oil may not return to the compressor in installations with long vertical lines."},{id:"a2l_183",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es el prop\xF3sito de la l\xEDnea de nitr\xF3geno de purga durante el proceso de brazado?",opciones:["Para presurizar el sistema y detectar fugas","Para desplazar el ox\xEDgeno dentro de las tuber\xEDas durante el brazado, previniendo oxidaci\xF3n y formaci\xF3n de escama interna (scale) que da\xF1ar\xEDa v\xE1lvulas y compresores","Para enfriar las tuber\xEDas r\xE1pidamente","Para verificar que las uniones est\xE9n bien selladas"],respuesta_correcta:1,explicacion:"La purga de nitr\xF3geno durante el brazado desplaza el ox\xEDgeno del interior de las tuber\xEDas. Sin esta purga, el calor del brazado oxida el cobre internamente, formando escama (scale) que puede tapar la TXV, contaminar el compresor y causar fallas prematuras.",question:"What is the purpose of the nitrogen purge line during the brazing process?",options:["To pressurize the system and detect leaks","To displace oxygen inside the tubing during brazing, preventing oxidation and internal scale formation that would damage valves and compressors","To cool the tubing quickly","To verify joints are properly sealed"],explanation:"Nitrogen purge during brazing displaces oxygen from inside the tubing. Without this purge, the brazing heat oxidizes the copper internally, forming scale that can clog the TXV, contaminate the compressor, and cause premature failures."},{id:"a2l_184",categoria:"A2L_CAMPO",pregunta:"\xBFA qu\xE9 presi\xF3n se realiza la purga de nitr\xF3geno durante el brazado?",opciones:["Alta presi\xF3n \u2014 100 PSI o m\xE1s","Baja presi\xF3n \u2014 \xBD a 2 PSI para simplemente desplazar el ox\xEDgeno sin crear peligro","Solo se hace antes de soldar, no durante","No hay especificaci\xF3n de presi\xF3n"],respuesta_correcta:1,explicacion:"La purga de nitr\xF3geno durante el brazado se hace a BAJA PRESI\xD3N: \xBD a 2 PSI. Esta presi\xF3n es suficiente para desplazar el ox\xEDgeno del interior pero no crea peligro de proyecci\xF3n de metal fundido ni problemas de seguridad.",question:"At what pressure is the nitrogen purge performed during brazing?",options:["High pressure \u2014 100 PSI or more","Low pressure \u2014 1/2 to 2 PSI to simply displace oxygen without creating danger","Only done before brazing, not during","No pressure specification"],explanation:"Nitrogen purge during brazing is done at LOW PRESSURE: 1/2 to 2 PSI. This pressure is sufficient to displace oxygen from inside but doesn't create danger of molten metal projection or safety problems."},{id:"a2l_185",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 tipo de brazado se usa para unir cobre a cobre en la mayor\xEDa de instalaciones HVAC?",opciones:["Soldadura de plomero (solder) con esta\xF1o y plomo","Brazado con varillas de relleno de aleaci\xF3n de plata (5-56% de plata) sin flux para cobre-cobre","Soldadura MIG","Solo pegamento especial para cobre"],respuesta_correcta:1,explicacion:"Para cobre a cobre en HVAC se usa brazado con varillas de relleno de aleaci\xF3n de PLATA (5-56% silver) que NO requieren flux. Para metales disimilares (cobre-aluminio, cobre-acero) s\xED se requiere flux apropiado.",question:"What type of brazing is used to join copper to copper in most HVAC installations?",options:["Plumber solder with tin and lead","Brazing with silver alloy filler rods (5-56% silver) without flux for copper-to-copper","MIG welding","Only special copper adhesive"],explanation:"For copper to copper in HVAC, brazing with SILVER alloy filler rods (5-56% silver) is used, which does NOT require flux. For dissimilar metals (copper-aluminum, copper-steel) appropriate flux IS required."},{id:"a2l_186",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es la diferencia entre brazado (brazing) y soldadura fuerte o welding?",opciones:["Son exactamente lo mismo","Brazado une los metales por capilaridad con metal de relleno de menor punto de fusi\xF3n que los metales base \u2014 NO funde los metales base. La soldadura (welding) S\xCD funde los metales base","El brazado es para pl\xE1stico, el welding para metal","No hay diferencia significativa"],respuesta_correcta:1,explicacion:"Brazado = el metal de relleno (plata/cobre) se derrite por debajo del punto de fusi\xF3n de los metales base y penetra por capilaridad. Los metales base NO se derriten. Welding = los metales base S\xCD se funden. Para instalaciones HVAC siempre se usa brazado, no welding.",question:"What is the difference between brazing and welding?",options:["They are exactly the same","Brazing joins metals by capillarity with filler metal of lower melting point than the base metals \u2014 does NOT melt the base metals. Welding DOES melt the base metals","Brazing is for plastic, welding for metal","There is no significant difference"],explanation:"Brazing = the filler metal (silver/copper) melts below the melting point of the base metals and penetrates by capillarity. The base metals do NOT melt. Welding = the base metals DO melt. For HVAC installations, brazing is always used, not welding."},{id:"a2l_187",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es la diferencia pr\xE1ctica entre un soplete de air-acetylene y uno de oxyacetylene?",opciones:["No hay diferencia pr\xE1ctica","Air-acetylene usa ox\xEDgeno del ambiente (llama m\xE1s ancha, ~3,000\xB0F). Oxyacetylene usa cilindro separado de O2 (llama m\xE1s concentrada, ~5,400\xB0F). El air-acetylene es m\xE1s com\xFAn para HVAC","El air-acetylene es solo para plomer\xEDa","El oxyacetylene es m\xE1s seguro para A2L"],respuesta_correcta:1,explicacion:"Air-acetylene: usa ox\xEDgeno del ambiente, produce llama m\xE1s ancha y temperatura menor (~3,000\xB0F). M\xE1s common para trabajo HVAC/R. Oxyacetylene: usa cilindro separado de O2, llama m\xE1s concentrada y hotter (~5,400\xB0F). Para trabajo de mayor precisi\xF3n o metales m\xE1s gruesos.",question:"What is the practical difference between an air-acetylene and an oxyacetylene torch?",options:["No practical difference","Air-acetylene uses ambient oxygen (wider flame, ~3,000\xB0F). Oxyacetylene uses separate O2 cylinder (more focused flame, ~5,400\xB0F). Air-acetylene is more common for HVAC","Air-acetylene is only for plumbing","Oxyacetylene is safer for A2L"],explanation:"Air-acetylene: uses ambient oxygen, produces wider flame and lower temperature (~3,000\xB0F). More common for HVAC/R work. Oxyacetylene: uses separate O2 cylinder, more focused and hotter flame (~5,400\xB0F). For more precise work or thicker metals."},{id:"a2l_188",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 NUNCA se debe usar presi\xF3n de ox\xEDgeno para verificar fugas en un sistema de refrigeraci\xF3n?",opciones:["Solo porque es caro","El ox\xEDgeno mezclado con aceite de compresor u otros materiales bajo presi\xF3n puede causar una EXPLOSI\xD3N \u2014 use solo nitr\xF3geno seco","Solo porque no es preciso","Solo para sistemas A2L"],respuesta_correcta:1,explicacion:"NUNCA ox\xEDgeno para leak check. El ox\xEDgeno a alta presi\xF3n mezclado con aceite de compresor u otros materiales org\xE1nicos puede auto-encenderse causando EXPLOSI\xD3N. Solo nitr\xF3geno seco es seguro para presurizar sistemas HVAC.",question:"Why should oxygen NEVER be used to pressurize a refrigeration system for leak testing?",options:["Only because it is expensive","Oxygen mixed with compressor oil or other materials under pressure can cause an EXPLOSION \u2014 use only dry nitrogen","Only because it is not precise","Only for A2L systems"],explanation:"NEVER oxygen for leak check. Oxygen at high pressure mixed with compressor oil or other organic materials can self-ignite causing an EXPLOSION. Only dry nitrogen is safe for pressurizing HVAC systems."},{id:"a2l_189",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 debe hacer el t\xE9cnico si la presi\xF3n de prueba con nitr\xF3geno CAE durante los 60 minutos?",opciones:["Es normal una ligera ca\xEDda \u2014 continuar","Hay una fuga \u2014 encontrarla con detector/agua jabonosa/UV, repararla, y repetir la prueba completa desde el inicio","Solo a\xF1adir m\xE1s nitr\xF3geno","La prueba se considera pasada si la ca\xEDda es menor al 10%"],respuesta_correcta:1,explicacion:"Cualquier ca\xEDda de presi\xF3n durante los 60 minutos de prueba indica FUGA. Procedimiento: localizar la fuga (detector electr\xF3nico, agua jabonosa, o UV), reparar, y repetir la prueba COMPLETA desde el inicio para verificar que no hay m\xE1s fugas.",question:"What must the technician do if the nitrogen test pressure DROPS during the 60 minutes?",options:["A slight drop is normal \u2014 continue","There is a leak \u2014 find it with detector/soapy water/UV, repair it, and repeat the complete test from the beginning","Only add more nitrogen","The test is considered passed if the drop is less than 10%"],explanation:"Any pressure drop during the 60-minute test indicates a LEAK. Procedure: locate the leak (electronic detector, soapy water, or UV), repair, and repeat the COMPLETE test from the beginning to verify no additional leaks."},{id:"a2l_190",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es la temperatura m\xE1xima para el lubricante de roscas (thread sealant) cuando se usa en tuber\xEDas de refrigeraci\xF3n?",opciones:["No importa la temperatura","Usar solo sealants espec\xEDficamente compatibles con refrigerantes y que puedan tolerar las temperaturas del sistema (cryogenic a muy alta presi\xF3n)","Solo PTFE tape est\xE1ndar de plomer\xEDa","Cualquier sealant de ferreter\xEDa"],respuesta_correcta:1,explicacion:"Para tuber\xEDas de refrigeraci\xF3n usar SOLO sealants (PTFE tape o compuesto) espec\xEDficamente compatibles con refrigerantes a las temperaturas del sistema. Algunos sealants de plomer\xEDa general no son compatibles con refrigerantes o no toleran las temperaturas extremas.",question:"What is the maximum temperature rating for thread sealant when used on refrigeration tubing?",options:["Temperature doesn't matter","Use only sealants specifically compatible with refrigerants that can tolerate system temperatures (cryogenic to very high pressure)","Only standard plumbing PTFE tape","Any hardware store sealant"],explanation:"For refrigeration tubing use ONLY sealants (PTFE tape or compound) specifically compatible with refrigerants at system temperatures. Some general plumbing sealants are not compatible with refrigerants or don't tolerate extreme temperatures."},{id:"a2l_191",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es el componente m\xE1s costoso y cr\xEDtico de un sistema de refrigeraci\xF3n?",opciones:["El condensador","El compresor \u2014 su falla generalmente requiere reemplazo del sistema o reparaci\xF3n mayor","La v\xE1lvula de expansi\xF3n","El filtro-drier"],respuesta_correcta:1,explicacion:"El compresor es el coraz\xF3n del sistema y el componente m\xE1s costoso. Su falla puede deberse a: l\xEDquido floodback, falta de aceite, sobrecarga el\xE9ctrica, contaminaci\xF3n del sistema, o exceso de temperatura. Proteger el compresor es prioritario.",question:"What is the most costly and critical component of a refrigeration system?",options:["The condenser","The compressor \u2014 its failure generally requires system replacement or major repair","The expansion valve","The filter-drier"],explanation:"The compressor is the heart of the system and the most expensive component. Its failure can be due to: liquid floodback, lack of oil, electrical overload, system contamination, or excess temperature. Protecting the compressor is the priority."},{id:"a2l_192",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 causa el 'liquid slugging' en un compresor y por qu\xE9 es destructivo?",opciones:["El compresor recibe demasiado vapor superheated","El compresor recibe refrigerante l\xEDquido que no puede comprimirse \u2014 causa golpe hidr\xE1ulico que puede romper v\xE1lvulas o bielas","El compresor trabaja con poco aceite","El compresor tiene voltaje incorrecto"],respuesta_correcta:1,explicacion:"Liquid slugging = refrigerante l\xEDquido entra al compresor (que es una bomba de vapor). El l\xEDquido no puede comprimirse como el vapor \u2014 causa un golpe hidr\xE1ulico que puede romper v\xE1lvulas de descarga, anillos del pist\xF3n, o connecting rods. Es una de las fallas m\xE1s destructivas.",question:"What causes 'liquid slugging' in a compressor and why is it destructive?",options:["The compressor receives too much superheated vapor","The compressor receives liquid refrigerant that cannot be compressed \u2014 causes hydraulic hammer that can break valves or connecting rods","The compressor operates with low oil","The compressor has incorrect voltage"],explanation:"Liquid slugging = liquid refrigerant enters the compressor (which is a vapor pump). The liquid cannot be compressed like vapor \u2014 it causes a hydraulic hammer that can break discharge valves, piston rings, or connecting rods. It is one of the most destructive failures."},{id:"a2l_193",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 es un 'compressor burnout' y qu\xE9 s\xEDntomas se observan?",opciones:["El compresor trabaja a m\xE1xima eficiencia","El motor del compresor se quema el\xE9ctricamente \u2014 el refrigerante y aceite presentan \xE1cidos, color oscuro, y olor a quemado. Las lecturas el\xE9ctricas muestran resistencia a tierra o entre fases incorrecta","El compresor enfr\xEDa demasiado","Solo ocurre en sistemas antiguos"],respuesta_correcta:1,explicacion:"Compressor burnout = falla el\xE9ctrica del motor del compresor. S\xEDntomas: olor a quemado al abrir el sistema, aceite oscuro/contaminado, presencia de \xE1cidos (prueba con acid test kit), y lecturas el\xE9ctricas incorrectas (resistencia a tierra, desequilibrio entre fases).",question:"What is a 'compressor burnout' and what symptoms are observed?",options:["The compressor operates at maximum efficiency","The compressor motor burns out electrically \u2014 the refrigerant and oil show acids, dark color, and burned smell. Electrical readings show ground resistance or incorrect phase-to-phase values","The compressor overcools","Only occurs in old systems"],explanation:"Compressor burnout = electrical failure of the compressor motor. Symptoms: burning smell when opening the system, dark/contaminated oil, presence of acids (acid test kit), and incorrect electrical readings (ground resistance, phase imbalance)."},{id:"a2l_194",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 procedimiento se debe seguir despu\xE9s de un compressor burnout?",opciones:["Solo reemplazar el compresor y listo","Recuperar refrigerante en tanque separado, reemplazar compresor, instalar suction line drier, flush del sistema, instalar nuevos driers, a\xF1adir aceite limpio y refrigerante nuevo","Solo cambiar el aceite","Solo limpiar el sistema externamente"],respuesta_correcta:1,explicacion:"Despu\xE9s de un burnout: (1) recuperar refrigerante en cilindro SEPARADO (contaminado), (2) reemplazar compresor, (3) instalar suction line drier temporal, (4) flush del sistema, (5) instalar nuevos filtros-drier, (6) aceite POE limpio, (7) refrigerante nuevo. Verificar el sistema completo.",question:"What procedure should be followed after a compressor burnout?",options:["Only replace the compressor and done","Recover refrigerant in separate tank, replace compressor, install suction line drier, system flush, install new driers, add clean oil and new refrigerant","Only change the oil","Only clean the system externally"],explanation:"After a burnout: (1) recover refrigerant in a SEPARATE tank (contaminated), (2) replace compressor, (3) install suction line drier, (4) system flush, (5) install new filter-driers, (6) clean POE oil, (7) new refrigerant. Verify the complete system."},{id:"a2l_195",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 el suction line drier (drier de l\xEDnea de succi\xF3n) es temporal y debe removerse?",opciones:["Porque es muy costoso dejarlo permanente","El suction line drier est\xE1 dise\xF1ado solo para limpiar el sistema despu\xE9s de contaminaci\xF3n \u2014 debe removerse cuando se bloquee, ya que una restricci\xF3n en la succi\xF3n puede da\xF1ar el compresor por baja presi\xF3n","No es necesario removerlo","Solo se usa en sistemas A2L"],respuesta_correcta:1,explicacion:"El suction line drier NO es permanente \u2014 solo para cleanup post-burnout. Si se bloquea (lo cual se indica por ca\xEDda de presi\xF3n medida con gauges en sus puertos), causa restricci\xF3n en la succi\xF3n que puede da\xF1ar el compresor. Removerlo cuando se bloquee o despu\xE9s de que el sistema se ha limpiado.",question:"Why is the suction line drier temporary and must be removed?",options:["Because it is too costly to leave permanently","The suction line drier is designed only for post-contamination system cleanup \u2014 it must be removed when blocked, as a restriction in the suction can damage the compressor from low pressure","It is not necessary to remove it","Only used in A2L systems"],explanation:"The suction line drier is NOT permanent \u2014 only for post-burnout cleanup. If it blocks (indicated by pressure drop measured with gauges at its ports), it causes suction restriction that can damage the compressor from low pressure. Remove when blocked or after system is clean."},{id:"a2l_196",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 indica que un compresor tiene falla de v\xE1lvulas internas?",opciones:["Ruido normal de operaci\xF3n","Presi\xF3n de baja alta Y presi\xF3n de alta baja simult\xE1neamente \u2014 el compresor no puede crear la diferencia de presi\xF3n normal","Solo presi\xF3n de baja alta","Solo presi\xF3n de alta baja"],respuesta_correcta:1,explicacion:"Falla de v\xE1lvulas del compresor: presi\xF3n de baja ALTA y presi\xF3n de alta BAJA al mismo tiempo. El compresor no puede mantener la diferencia de presi\xF3n. Diferente a un compresor que no arranca o que tiene problema el\xE9ctrico.",question:"What indicates that a compressor has internal valve failure?",options:["Normal operating noise","Low-side pressure high AND high-side pressure low simultaneously \u2014 the compressor cannot create the normal pressure differential","Only high low-side pressure","Only low high-side pressure"],explanation:"Compressor valve failure: low-side pressure HIGH and high-side pressure LOW at the same time. The compressor cannot maintain the pressure differential. Different from a compressor that won't start or has an electrical problem."},{id:"a2l_197",categoria:"A2L_CAMPO",pregunta:"\xBFPor qu\xE9 los sistemas A2L requieren espec\xEDficamente compresores certificados para A2L?",opciones:["Solo por requisito de garant\xEDa","Los compresores para A2L tienen materiales y sellados compatibles con los nuevos refrigerantes y aceites, adem\xE1s de componentes el\xE9ctricos internos dise\xF1ados para no encender el A2L","Solo por presiones diferentes","No hay diferencia \u2014 cualquier compresor compatible por presi\xF3n funciona"],respuesta_correcta:1,explicacion:"Los compresores A2L certificados tienen: (1) materiales internos compatibles con HFC/HFO y POE, (2) sellados dise\xF1ados para las nuevas mezclas, y (3) componentes el\xE9ctricos internos (IS) dise\xF1ados para no generar chispa que encienda el A2L.",question:"Why do A2L systems specifically require compressors certified for A2L?",options:["Only for warranty requirement","A2L compressors have materials and seals compatible with the new refrigerants and oils, plus internal electrical components designed not to ignite the A2L","Only due to different pressures","No difference \u2014 any pressure-compatible compressor works"],explanation:"A2L certified compressors have: (1) internal materials compatible with HFC/HFO and POE, (2) seals designed for the new blends, and (3) internal electrical components (IS) designed not to generate sparks that ignite the A2L."},{id:"a2l_198",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 es el 'acid test' y cu\xE1ndo se realiza?",opciones:["Una prueba de limpieza del sistema","Una prueba que mide la acidez del aceite del sistema \u2014 se hace cuando se sospecha contaminaci\xF3n por burnout, humedad, o en inspecciones de mantenimiento preventivo","Solo para sistemas comerciales","Solo despu\xE9s de un burnout"],respuesta_correcta:1,explicacion:"El acid test mide la acidez del aceite del sistema usando un kit especial. Se realiza: (1) despu\xE9s de un burnout, (2) cuando se sospecha contaminaci\xF3n por humedad, (3) en mantenimiento preventivo en sistemas comerciales. Acidez alta indica necesidad de flush del sistema.",question:"What is the 'acid test' and when is it performed?",options:["A system cleaning test","A test that measures acidity of the system oil \u2014 done when contamination from burnout or moisture is suspected, or in preventive maintenance inspections","Only for commercial systems","Only after a burnout"],explanation:"The acid test measures the acidity of system oil using a special kit. It is performed: (1) after a burnout, (2) when moisture contamination is suspected, (3) in preventive maintenance on commercial systems. High acidity indicates the need for system flush."},{id:"a2l_199",categoria:"A2L_CAMPO",pregunta:"\xBFQu\xE9 verificaci\xF3n el\xE9ctrica b\xE1sica se hace a un compresor antes de reemplazarlo?",opciones:["Solo verificar que tiene voltaje","Medir resistencia de cada devanado (ohmmeter), resistencia a tierra (megohmmeter), y amperaje de operaci\xF3n vs FLA en placa","Solo verificar el capacitor","Solo medir voltaje de suministro"],respuesta_correcta:1,explicacion:"Verificaciones el\xE9ctricas del compresor: (1) resistencia de cada devanado (ohmmeter) \u2014 verificar que los valores son correctos y equilibrados, (2) resistencia a tierra (megohmmeter) \u2014 debe ser muy alta (Mohms), (3) amperaje de operaci\xF3n vs FLA indicado en placa.",question:"What basic electrical verification is done on a compressor before replacing it?",options:["Only verify it has voltage","Measure resistance of each winding (ohmmeter), ground resistance (megohmmeter), and operating amperage vs FLA on the nameplate","Only verify the capacitor","Only measure supply voltage"],explanation:"Compressor electrical verifications: (1) resistance of each winding (ohmmeter) \u2014 verify values are correct and balanced, (2) ground resistance (megohmmeter) \u2014 should be very high (MOhms), (3) operating amperage vs FLA indicated on the nameplate."},{id:"a2l_200",categoria:"A2L_CAMPO",pregunta:"\xBFCu\xE1l es la diferencia entre un compresor scroll y un compresor reciprocating (pist\xF3n)?",opciones:["No hay diferencia pr\xE1ctica","Scroll: espirales orbitales, m\xE1s silencioso y eficiente, muy com\xFAn en residencial moderno. Reciprocating: pistones, m\xE1s resistente a liquid floodback, m\xE1s com\xFAn en aplicaciones industriales","El scroll es solo para A2L","El reciprocating es m\xE1s nuevo"],respuesta_correcta:1,explicacion:"Scroll: dos espirales que rotan para comprimir \u2014 m\xE1s silencioso, m\xE1s eficiente, dominante en sistemas residenciales modernos, pero vulnerable a liquid floodback. Reciprocating (pist\xF3n): m\xE1s robusto ante liquid floodback, m\xE1s simple mec\xE1nicamente, com\xFAn en sistemas comerciales e industriales.",question:"What is the difference between a scroll compressor and a reciprocating (piston) compressor?",options:["No practical difference","Scroll: orbiting spirals, quieter and more efficient, very common in modern residential. Reciprocating: pistons, more resistant to liquid floodback, more common in industrial applications","Scroll is only for A2L","Reciprocating is newer"],explanation:"Scroll: two orbiting spirals that compress \u2014 quieter, more efficient, dominant in modern residential systems, but vulnerable to liquid floodback. Reciprocating (piston): more robust against liquid floodback, mechanically simpler, common in commercial and industrial systems."},{id:"a2l_201",categoria:"A2L_AVANZADO",pregunta:"Un sistema R-454B tiene temperatura de salida normal pero la presi\xF3n de baja est\xE1 ligeramente elevada. El airflow es correcto. \xBFQu\xE9 verificar?",opciones:["Cambiar el compresor inmediatamente","Verificar: TXV atascada abierta, sobrecarga de refrigerante, o temperatura de evaporador m\xE1s alta que lo normal por carga de calor elevada","A\xF1adir refrigerante","Solo verificar el filtro"],respuesta_correcta:1,explicacion:"Presi\xF3n de baja ligeramente alta con airflow correcto puede indicar: TXV atascada en posici\xF3n abierta (alimentando m\xE1s refrigerante), sobrecarga de refrigerante, o simplemente una carga de calor mayor que lo normal (clima m\xE1s caliente, espacio m\xE1s ocupado).",question:"An R-454B system has normal supply air temperature but the low-side pressure is slightly elevated. Airflow is correct. What to check?",options:["Replace the compressor immediately","Check: TXV stuck open, refrigerant overcharge, or evaporator temperature higher than normal due to elevated heat load","Add refrigerant","Only check the filter"],explanation:"Slightly high low-side pressure with correct airflow can indicate: TXV stuck in the open position (feeding more refrigerant), refrigerant overcharge, or simply a higher than normal heat load (hotter weather, more occupied space)."},{id:"a2l_202",categoria:"A2L_AVANZADO",pregunta:"Al llegar a un sistema R-32 con 'no cooling', encuentras presi\xF3n de baja y alta iguales con el compresor corriendo. \xBFCu\xE1l es el diagn\xF3stico m\xE1s probable?",opciones:["El sistema necesita refrigerante","Compresor no est\xE1 comprimiendo \u2014 v\xE1lvulas rotas o falla mec\xE1nica interna","El condensador est\xE1 bloqueado","El TXV est\xE1 atascado"],respuesta_correcta:1,explicacion:"Presiones iguales en alta y baja con el compresor funcionando = el compresor NO EST\xC1 COMPRIMIENDO. El compresor funciona el\xE9ctrica/mec\xE1nicamente (enciende) pero sus v\xE1lvulas internas est\xE1n defectuosas o hay p\xE9rdida severa de compresi\xF3n interna.",question:"Upon arriving at an R-32 system with 'no cooling,' you find low-side and high-side pressure equal with the compressor running. What is the most likely diagnosis?",options:["The system needs refrigerant","Compressor is not compressing \u2014 broken valves or internal mechanical failure","The condenser is blocked","The TXV is stuck"],explanation:"Equal pressures on high and low sides with the compressor running = the compressor IS NOT COMPRESSING. The compressor works electrically/mechanically (starts) but its internal valves are defective or there is severe internal compression loss."},{id:"a2l_203",categoria:"A2L_AVANZADO",pregunta:"Un sistema R-454B tiene condensador muy caliente al tacto pero la presi\xF3n de alta es normal. \xBFQu\xE9 puede indicar?",opciones:["Situaci\xF3n normal","El condensador puede tener restricci\xF3n de airflow \u2014 el refrigerante est\xE1 condensando pero transfiriendo menos calor, causando temperatura superficial alta con presi\xF3n aparentemente normal por un tiempo","El compresor est\xE1 fallando","Falta refrigerante"],respuesta_correcta:1,explicacion:"Un condensador muy caliente con presi\xF3n aparentemente normal puede indicar restricci\xF3n parcial de airflow \u2014 el condensador est\xE1 sobrecalentado y eventualmente la presi\xF3n de alta comenzar\xE1 a subir. Limpiar el condensador y verificar el ventilador.",question:"An R-454B system has a very hot condenser to the touch but the high-side pressure is normal. What could this indicate?",options:["Normal situation","The condenser may have airflow restriction \u2014 refrigerant is condensing but transferring less heat, causing high surface temperature with apparently normal pressure temporarily","The compressor is failing","Low on refrigerant"],explanation:"A very hot condenser with apparently normal pressure may indicate partial airflow restriction \u2014 the condenser is overheated and eventually high-side pressure will begin to rise. Clean the condenser and verify the fan."},{id:"a2l_204",categoria:"A2L_AVANZADO",pregunta:"\xBFC\xF3mo diferencias entre un sistema R-32 bajo en refrigerante vs un sistema con restricci\xF3n en la l\xEDnea l\xEDquida?",opciones:["No se puede diferenciar","Baja carga: presi\xF3n de baja baja + superheat alto + subcooling bajo. Restricci\xF3n en l\xEDnea l\xEDquida: presi\xF3n de baja baja + superheat alto + subcooling ALTO (el refrigerante se acumula antes de la restricci\xF3n)","Son id\xE9nticos \u2014 se resuelven igual","Solo midiendo el peso del refrigerante"],respuesta_correcta:1,explicacion:"La diferencia clave est\xE1 en el SUBCOOLING: baja carga de refrigerante muestra subcooling BAJO. Una restricci\xF3n en la l\xEDnea l\xEDquida muestra subcooling ALTO (el refrigerante se acumula antes de la restricci\xF3n, el sistema 'cree' que tiene suficiente pero no llega correctamente).",question:"How do you differentiate between an R-32 system low on refrigerant vs a system with a liquid line restriction?",options:["Cannot differentiate","Low charge: low suction pressure + high superheat + low subcooling. Liquid line restriction: low suction pressure + high superheat + HIGH subcooling (refrigerant accumulates before the restriction)","They are identical \u2014 resolved the same way","Only by weighing the refrigerant"],explanation:"The key difference is in SUBCOOLING: low refrigerant charge shows LOW subcooling. A liquid line restriction shows HIGH subcooling (refrigerant accumulates before the restriction, the system 'thinks' it has enough but it's not arriving correctly)."},{id:"a2l_205",categoria:"A2L_AVANZADO",pregunta:"Un cliente reporta que el sistema R-454B enfr\xEDa bien en la ma\xF1ana pero no en las tardes calientes. \xBFCu\xE1l es la causa m\xE1s probable?",opciones:["El sistema est\xE1 en buenas condiciones","El sistema est\xE1 dise\xF1ado o cargado para condiciones normales pero en pico de calor (temperatura alta exterior) no tiene capacidad suficiente \u2014 posible subdimensionamiento o condensador sucio","El termostato est\xE1 roto","Falta refrigerante"],respuesta_correcta:1,explicacion:"Sistema que enfr\xEDa bien en condiciones normales pero no en pico de calor puede indicar: sistema subdimensionado para la carga m\xE1xima, condensador parcialmente sucio (funciona bien con temperatura ambiente baja pero falla en calor extremo), o carga de refrigerante marginalmente baja.",question:"A customer reports the R-454B system cools well in the morning but not during hot afternoons. What is the most likely cause?",options:["The system is in good condition","The system is designed or charged for normal conditions but at peak heat (high outdoor temperature) does not have sufficient capacity \u2014 possible undersizing or dirty condenser","The thermostat is broken","Low on refrigerant"],explanation:"A system that cools well under normal conditions but not at peak heat can indicate: system undersized for maximum load, partially dirty condenser (works fine with low ambient but fails in extreme heat), or marginally low refrigerant charge."},{id:"a2l_206",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es el diagn\xF3stico cuando la presi\xF3n de baja es normal pero el amperaje del compresor R-32 est\xE1 muy elevado?",opciones:["El compresor est\xE1 perfecto","Posibles causas: condensador bloqueado (presi\xF3n de alta elevada que eleva amperaje), voltaje bajo, problema mec\xE1nico interno del compresor, o capacitor deficiente","El sistema necesita refrigerante","El filtro-drier est\xE1 bloqueado"],respuesta_correcta:1,explicacion:"Alto amperaje con presi\xF3n de baja normal puede indicar: (1) presi\xF3n de alta elevada por condensador bloqueado aumentando la carga del compresor, (2) voltaje bajo que causa sobreintensidad, (3) problema mec\xE1nico interno (rodamientos) del compresor, (4) capacitor deficiente en monof\xE1sico.",question:"What is the diagnosis when the low-side pressure is normal but the R-32 compressor amperage is very elevated?",options:["The compressor is perfect","Possible causes: blocked condenser (elevated high-side pressure increasing amperage), low voltage, internal mechanical compressor problem, or deficient capacitor","The system needs refrigerant","The filter-drier is blocked"],explanation:"High amperage with normal low-side pressure can indicate: (1) elevated high-side pressure from blocked condenser increasing compressor load, (2) low supply voltage causing overcurrent, (3) internal mechanical problem (bearings) in the compressor, (4) deficient capacitor in single-phase."},{id:"a2l_207",categoria:"A2L_AVANZADO",pregunta:"Un t\xE9cnico encuentra un sistema R-454B que fue instalado hace 3 meses y ya perdi\xF3 el 25% de su carga. \xBFCu\xE1l es el primer paso?",opciones:["Recargar el 25% perdido","ENCONTRAR Y REPARAR la fuga antes de a\xF1adir refrigerante \u2014 recargar sin reparar viola regulaciones y es in\xFAtil a largo plazo","Solo a\xF1adir la mitad y ver qu\xE9 pasa","Cambiar el sistema completo"],respuesta_correcta:1,explicacion:"SIEMPRE localizar y reparar la fuga ANTES de recargar. Las regulaciones EPA requieren reparar fugas. Recargar sin reparar es desperdiciar refrigerante, dinero, y potencialmente violar regulaciones de fuga si el sistema supera el umbral anual.",question:"A technician finds an R-454B system installed 3 months ago that has already lost 25% of its charge. What is the first step?",options:["Recharge the 25% lost","FIND AND REPAIR the leak before adding refrigerant \u2014 recharging without repairing violates regulations and is useless long-term","Only add half and see what happens","Replace the entire system"],explanation:"ALWAYS locate and repair the leak BEFORE recharging. EPA regulations require leak repair. Recharging without repair is wasting refrigerant, money, and potentially violating leak regulations if the system exceeds the annual threshold."},{id:"a2l_208",categoria:"A2L_AVANZADO",pregunta:"Un cliente reporta que el sistema hace un ruido de 'burbujeo' en la l\xEDnea l\xEDquida. \xBFQu\xE9 indica?",opciones:["Operaci\xF3n normal","Hay vapor (burbujas) en la l\xEDnea l\xEDquida \u2014 indicativo de bajo subcooling, posiblemente por baja carga de refrigerante o refrigerante evapor\xE1ndose por ca\xEDda de presi\xF3n antes de la TXV","El compresor est\xE1 haciendo ruido","El condensador tiene problemas"],respuesta_correcta:1,explicacion:"Ruido de burbujeo en la l\xEDnea l\xEDquida = vapor en la l\xEDnea l\xEDquida = bajo subcooling. Las burbujas de vapor bloquean la alimentaci\xF3n correcta de la TXV reduciendo la capacidad del sistema. Puede ser por: baja carga de refrigerante, subcooling insuficiente del condensador, o restricci\xF3n en la l\xEDnea l\xEDquida.",question:"A customer reports the system makes a 'gurgling' noise in the liquid line. What does this indicate?",options:["Normal operation","There is vapor (bubbles) in the liquid line \u2014 indicative of low subcooling, possibly from low refrigerant charge or refrigerant flashing before the TXV","The compressor is making noise","The condenser has problems"],explanation:"Gurgling noise in the liquid line = vapor in the liquid line = low subcooling. Vapor bubbles block proper TXV feeding, reducing system capacity. Can be from: low refrigerant charge, insufficient condenser subcooling, or liquid line restriction."},{id:"a2l_209",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 diagn\xF3stico se hace cuando un sistema R-32 tiene ICE form\xE1ndose en la l\xEDnea de succi\xF3n afuera del evaporador?",opciones:["El sistema funciona perfectamente \u2014 el hielo es normal","Bajo superheat \u2014 refrigerante l\xEDquido est\xE1 saliendo del evaporador y llegando a la l\xEDnea de succi\xF3n donde se congela el condensado. Posible: TXV atascada abierta, sobrecarga de refrigerante, o bajo airflow del evaporador","El sistema tiene fuga","El condensador est\xE1 sucio"],respuesta_correcta:1,explicacion:"Hielo en la l\xEDnea de succi\xF3n FUERA del evaporador indica superheat muy bajo \u2014 el refrigerante no termin\xF3 de evaporarse en el evaporador y sale como l\xEDquido. Causas: TXV sobredimensionada/atascada abierta, refrigerante en exceso, o bajo airflow en el evaporador.",question:"What is the diagnosis when an R-32 system has ICE forming on the suction line outside the evaporator?",options:["The system is working perfectly","Low superheat \u2014 liquid refrigerant is exiting the evaporator and reaching the suction line where condensate freezes. Possible: TXV stuck open, refrigerant overcharge, or low evaporator airflow","The system has a leak","The condenser is dirty"],explanation:"Ice on the suction line OUTSIDE the evaporator indicates very low superheat \u2014 the refrigerant didn't finish evaporating in the evaporator and exits as liquid. Causes: oversized/stuck-open TXV, excess refrigerant, or low evaporator airflow."},{id:"a2l_210",categoria:"A2L_AVANZADO",pregunta:"\xBFC\xF3mo distingues entre ICE en el evaporador por bajo airflow vs por bajo superheat (baja carga)?",opciones:["No se puede distinguir","Bajo airflow: hielo empieza desde la entrada del evaporador donde el aire es m\xE1s fr\xEDo. Bajo superheat/baja carga: hielo tiende a formarse m\xE1s uniformemente o desde el centro/salida del evaporador","Son id\xE9nticos","Solo midiendo la carga del sistema"],respuesta_correcta:1,explicacion:"El patr\xF3n de hielo puede ayudar a distinguir: bajo airflow causa hielo que comienza desde la entrada del evaporador (donde el aire fr\xEDo se estanca). Bajo superheat/baja carga causa formaci\xF3n de hielo m\xE1s uniforme. Sin embargo, medir superheat y verificar airflow es m\xE1s confiable.",question:"How do you distinguish between ICE on the evaporator from low airflow vs from low superheat (low charge)?",options:["Cannot distinguish","Low airflow: ice starts from the evaporator inlet where air is coldest. Low superheat/low charge: ice tends to form more uniformly or from the center/outlet of the evaporator","They are identical","Only by measuring system charge"],explanation:"The ice pattern can help distinguish: low airflow causes ice starting from the evaporator inlet (where cold air stagnates). Low superheat/low charge causes more uniform ice formation. However, measuring superheat and checking airflow is more reliable."},{id:"a2l_211",categoria:"A2L_AVANZADO",pregunta:"Un sistema R-454B nuevo fue instalado hace 1 semana y el t\xE9cnico reporta que la presi\xF3n de alta sube progresivamente durante la operaci\xF3n. \xBFQu\xE9 puede indicar?",opciones:["Funcionamiento normal en sistema nuevo","Posible presencia de no-condensables (aire) en el sistema \u2014 los gases no-condensables se acumulan en el condensador elevando la presi\xF3n de alta progresivamente","El condensador est\xE1 sucio","El compresor est\xE1 fallando"],respuesta_correcta:1,explicacion:"Presi\xF3n de alta que sube PROGRESIVAMENTE puede indicar no-condensables (generalmente aire) en el sistema \u2014 se acumulan en el condensador con el tiempo. Verificar: comparar presi\xF3n de saturaci\xF3n de la tabla P/T con la presi\xF3n actual del sistema cuando est\xE9 APAGADO y estabilizado.",question:"A new R-454B system installed 1 week ago has high-side pressure that rises progressively during operation. What could this indicate?",options:["Normal operation in a new system","Possible presence of non-condensables (air) in the system \u2014 non-condensable gases accumulate in the condenser raising high-side pressure progressively","The condenser is dirty","The compressor is failing"],explanation:"High-side pressure that rises PROGRESSIVELY can indicate non-condensables (usually air) in the system \u2014 they accumulate in the condenser over time. Verify: compare the P/T chart saturation pressure with the actual system pressure when OFF and stabilized."},{id:"a2l_212",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 indica una lectura de 'ground fault' (falla a tierra) en el motor del compresor?",opciones:["El compresor est\xE1 en perfectas condiciones","El barniz aislante del motor se ha deteriorado \u2014 hay contacto el\xE9ctrico entre los devanados y la carcasa del compresor. Generalmente indica falla o falla inminente del compresor","Solo problemas de instalaci\xF3n el\xE9ctrica","El capacitor est\xE1 defectuoso"],respuesta_correcta:1,explicacion:"Ground fault (falla a tierra) en el compresor = el barniz aislante del motor se ha deteriorado, permitiendo contacto el\xE9ctrico entre devanados y carcasa. Puede indicar: quemado del motor (burnout), contaminaci\xF3n severa del aceite, o degradaci\xF3n por sobrecalentamiento. El compresor generalmente necesita reemplazo.",question:"What does a 'ground fault' reading on the compressor motor indicate?",options:["The compressor is in perfect condition","The motor's insulation varnish has deteriorated \u2014 there is electrical contact between the windings and the compressor shell. Generally indicates failure or imminent failure","Only electrical installation problems","The capacitor is defective"],explanation:"Ground fault in the compressor = motor insulation varnish has deteriorated, allowing electrical contact between windings and shell. Can indicate: motor burnout, severe oil contamination, or degradation from overheating. The compressor generally needs replacement."},{id:"a2l_213",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 pueden indicar lecturas de resistencia el\xE9ctricas DESEQUILIBRADAS entre los 3 devanados (R, S, C) de un compresor trif\xE1sico?",opciones:["Funcionamiento normal","Devanado(s) con resistencia diferente pueden indicar: devanado quemado parcialmente, cortocircuito interno, o compresor con burnout incipiente","Solo diferencia de calibraci\xF3n del instrumento","Solo indica que el compresor necesita aceite"],respuesta_correcta:1,explicacion:"En compresores trif\xE1sicos, las resistencias entre R-C, S-C, y T-C deben ser similares. Desequilibrio significativo puede indicar devanado quemado parcialmente o cortocircuito interno. Siempre comparar con las especificaciones del fabricante del compresor.",question:"What can UNBALANCED resistance readings between the 3 windings (R, S, C) of a three-phase compressor indicate?",options:["Normal operation","Winding(s) with different resistance may indicate: partially burned winding, internal short circuit, or compressor with incipient burnout","Only instrument calibration difference","Only indicates the compressor needs oil"],explanation:"In three-phase compressors, resistances between R-C, S-C, and T-C should be similar. Significant imbalance can indicate partially burned winding or internal short circuit. Always compare with the compressor manufacturer's specifications."},{id:"a2l_214",categoria:"A2L_AVANZADO",pregunta:"Un sistema R-32 de bomba de calor no calienta eficientemente en invierno aunque enfr\xEDa bien en verano. \xBFCu\xE1l es la revisi\xF3n prioritaria?",opciones:["El sistema necesita refrigerante","La v\xE1lvula de 4 v\xEDas puede no estar cambiando completamente de modo enfriamiento a calefacci\xF3n \u2014 permite bypass de refrigerante","El compresor est\xE1 fallando","El condensador est\xE1 sucio"],respuesta_correcta:1,explicacion:"Una v\xE1lvula de 4 v\xEDas que no cambia completamente puede hacer que parte del refrigerante tome el camino de enfriamiento incluso en modo calefacci\xF3n, reduciendo la capacidad de calefacci\xF3n. S\xEDntoma cl\xE1sico: enfr\xEDa bien pero no calienta bien (o viceversa).",question:"An R-32 heat pump system does not heat efficiently in winter although it cools well in summer. What is the priority check?",options:["The system needs refrigerant","The 4-way valve may not be fully switching from cooling to heating mode \u2014 allows refrigerant bypass","The compressor is failing","The condenser is dirty"],explanation:"A 4-way valve that doesn't fully switch can allow some refrigerant to take the cooling path even in heating mode, reducing heating capacity. Classic symptom: cools well but doesn't heat well (or vice versa)."},{id:"a2l_215",categoria:"A2L_AVANZADO",pregunta:"\xBFC\xF3mo se verifica una v\xE1lvula de 4 v\xEDas defectuosa en una bomba de calor?",opciones:["Solo visualmente","Medir temperaturas en las 4 conexiones de la v\xE1lvula \u2014 un bypass interno se detectar\xE1 por temperatura incorrecta (la l\xEDnea fr\xEDa en modo calefacci\xF3n deber\xEDa ser caliente si la v\xE1lvula est\xE1 bien","Solo midiendo el amperaje del compresor","Solo verificando la presi\xF3n"],respuesta_correcta:1,explicacion:"Para verificar una v\xE1lvula de 4 v\xEDas: en modo calefacci\xF3n medir temperaturas en las 4 puertos. Una v\xE1lvula con bypass muestra temperatura incorrecta \u2014 por ejemplo, en modo calefacci\xF3n la l\xEDnea de succi\xF3n deber\xEDa ser de la temperatura de retorno (caliente del espacio), no de la l\xEDnea de descarga.",question:"How is a defective 4-way valve verified in a heat pump?",options:["Only visually","Measure temperatures at all 4 connections of the valve \u2014 an internal bypass will be detected by incorrect temperature (the cold line in heating mode should be hot if the valve is working properly)","Only by measuring compressor amperage","Only by checking pressure"],explanation:"To verify a 4-way valve: in heating mode measure temperatures at all 4 ports. A valve with bypass shows incorrect temperature \u2014 for example, in heating mode the suction line should be at the return temperature (warm from the space), not from the discharge line."},{id:"a2l_216",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 indica cuando un sistema R-454B tiene amperaje BAJO en el compresor?",opciones:["Excelente eficiencia","Posibles causas: baja carga de refrigerante (el compresor tiene poca resistencia al comprimir gas poco denso), voltaje alto, o compresor desgastado con anillos en mal estado","El compresor est\xE1 en perfectas condiciones","El filtro est\xE1 limpio"],respuesta_correcta:1,explicacion:"Amperaje bajo en el compresor puede indicar: (1) baja carga de refrigerante (poco refrigerante = baja densidad del gas = menor trabajo para comprimir), (2) voltaje de l\xEDnea elevado, (3) compresor con desgaste interno (anillos deficientes que no comprimen efectivamente).",question:"What does it indicate when an R-454B system has LOW compressor amperage?",options:["Excellent efficiency","Possible causes: low refrigerant charge (compressor has little resistance compressing low-density gas), high voltage, or worn compressor with bad rings","The compressor is in perfect condition","The filter is clean"],explanation:"Low compressor amperage can indicate: (1) low refrigerant charge (less refrigerant = lower gas density = less work to compress), (2) elevated line voltage, (3) compressor with internal wear (deficient rings not compressing effectively)."},{id:"a2l_217",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 busca el t\xE9cnico cuando verifica 'superheat de sistema' vs 'superheat de evaporador'?",opciones:["Son exactamente lo mismo","Superheat de evaporador = en la salida del evaporador (indica la carga de la TXV). Superheat de sistema = en la entrada del compresor (indica el estado de la l\xEDnea de succi\xF3n y posible calentamiento adicional)","El superheat de sistema no se usa","Solo se mide uno de los dos"],respuesta_correcta:1,explicacion:"Superheat de evaporador = temperatura de succi\xF3n en la salida del evaporador menos temperatura de saturaci\xF3n. Indica si la TXV est\xE1 trabajando correctamente. Superheat de sistema = temperatura de succi\xF3n en la entrada del compresor. Diferencia entre los dos indica cu\xE1nto se calienta el vapor en la l\xEDnea de succi\xF3n.",question:"What is the technician looking for when checking 'system superheat' vs 'evaporator superheat'?",options:["They are exactly the same","Evaporator superheat = at the evaporator outlet (indicates TXV loading). System superheat = at the compressor inlet (indicates suction line condition and possible additional heating)","System superheat is not used","Only one of the two is measured"],explanation:"Evaporator superheat = suction temperature at the evaporator outlet minus saturation temperature. Indicates if the TXV is working correctly. System superheat = suction temperature at the compressor inlet. Difference between the two indicates how much the vapor heats up in the suction line."},{id:"a2l_218",categoria:"A2L_AVANZADO",pregunta:"Un sistema R-32 comercial tiene presi\xF3n de alta que FLUCT\xDAA constantemente en lugar de ser estable. \xBFQu\xE9 puede indicar?",opciones:["Funcionamiento normal","Posibles causas: TXV 'hunting' (oscilando), ventilador del condensador c\xEDclico, o fluctuaciones de carga de calor \u2014 verificar primero si el ventilador del condensador est\xE1 funcionando correctamente","Solo ruido el\xE9ctrico en el man\xF3metro","El compresor est\xE1 fallando"],respuesta_correcta:1,explicacion:"Fluctuaci\xF3n de presi\xF3n de alta puede indicar: ventilador del condensador que cicla (on/off) irregularmente, TXV hunting que crea fluctuaciones de presi\xF3n en toda la alta, o variaciones significativas en la carga del condensador.",question:"An R-32 commercial system has high-side pressure that FLUCTUATES constantly instead of being stable. What could this indicate?",options:["Normal operation","Possible causes: TXV 'hunting' (oscillating), cycling condenser fan, or heat load fluctuations \u2014 first check if the condenser fan is working correctly","Only electrical noise in the gauge","The compressor is failing"],explanation:"High-side pressure fluctuation can indicate: condenser fan cycling (on/off) irregularly, TXV hunting creating pressure fluctuations throughout the high side, or significant variations in condenser load."},{id:"a2l_219",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'thermal expansion valve hunting' y c\xF3mo se identifica?",opciones:["Cuando la TXV est\xE1 atascada cerrada","Cuando la TXV oscila continuamente abriendo y cerrando \u2014 se identifica por fluctuaciones continuas de superheat y presi\xF3n de baja sin llegar a estabilizarse","Cuando la TXV tiene fuga interna","Solo ocurre en sistemas A2L"],respuesta_correcta:1,explicacion:"TXV hunting = la v\xE1lvula no puede encontrar un punto de equilibrio y oscila continuamente. Se identifica por: superheat y presi\xF3n de baja que suben y bajan continuamente sin estabilizarse. Causas: TXV sobredimensionada, bulbo mal posicionado, o ajuste incorrecto del superheat de la TXV.",question:"What is 'thermal expansion valve hunting' and how is it identified?",options:["When the TXV is stuck closed","When the TXV continuously oscillates opening and closing \u2014 identified by continuous fluctuations of superheat and low-side pressure without stabilizing","When the TXV has an internal leak","Only occurs in A2L systems"],explanation:"TXV hunting = the valve cannot find an equilibrium point and oscillates continuously. Identified by: superheat and low-side pressure that continuously rise and fall without stabilizing. Causes: oversized TXV, mispositioned bulb, or incorrect TXV superheat adjustment."},{id:"a2l_220",categoria:"A2L_AVANZADO",pregunta:"Un sistema R-454B de split residencial hace ruido de 'chasquido' (clicking) al arrancar. \xBFQu\xE9 verificar primero en el sistema el\xE9ctrico?",opciones:["Nada \u2014 es normal","Verificar el capacitor de arranque y de funcionamiento \u2014 el clicking puede indicar que el compresor intenta arrancar pero el capacitor no tiene suficiente energ\xEDa para iniciar la rotaci\xF3n","Verificar el termostato","Verificar el voltaje del sistema"],respuesta_correcta:1,explicacion:"El chasquido de arranque seguido de apagado puede indicar un CAPACITOR deficiente. El motor del compresor intenta iniciar la rotaci\xF3n pero el capacitor no provee suficiente torque de arranque. El capacitor con alta tensi\xF3n de descarga (capacitores para A2L) es especialmente importante verificar con medidor de capacitancia.",question:"An R-454B residential split system makes a 'clicking' noise at startup. What to check first in the electrical system?",options:["Nothing \u2014 it is normal","Check the start and run capacitor \u2014 the clicking may indicate the compressor is trying to start but the capacitor does not have enough energy to initiate rotation","Check the thermostat","Check system voltage"],explanation:"Startup clicking followed by shutdown can indicate a DEFICIENT CAPACITOR. The compressor motor tries to start rotation but the capacitor doesn't provide enough startup torque. The capacitor with high discharge voltage (capacitors for A2L) is especially important to verify with a capacitance meter."},{id:"a2l_221",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la prueba el\xE9ctrica m\xE1s importante ANTES de comenzar trabajo en un sistema A2L de-energizado?",opciones:["Medir el voltaje de l\xEDnea","Verificar con mult\xEDmetro que hay cero voltaje presente DESPU\xC9S del lockout/tagout \u2014 no asumir que el sistema est\xE1 de-energizado","Solo apagar el breaker","Solo desconectar el termostato"],respuesta_correcta:1,explicacion:"PRIMERO: aplicar LOTO (lockout/tagout) COMPLETO, luego VERIFICAR con mult\xEDmetro que hay cero voltaje. Nunca asumir que el sistema est\xE1 de-energizado solo porque el breaker est\xE1 apagado. El t\xE9cnico que realiza el trabajo debe tener la \xFAnica llave del candado.",question:"What is the most important electrical test BEFORE beginning work on a de-energized A2L system?",options:["Measure line voltage","Verify with multimeter that there is zero voltage present AFTER lockout/tagout \u2014 do not assume the system is de-energized","Only turn off the breaker","Only disconnect the thermostat"],explanation:"FIRST: apply COMPLETE LOTO (lockout/tagout), then VERIFY with multimeter that there is zero voltage. Never assume the system is de-energized just because the breaker is off. The technician performing the work must have the only padlock key."},{id:"a2l_222",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'locked rotor amperage' (LR",opciones:["y por qu\xE9 importa?A) El amperaje normal de operaci\xF3n","El amperaje m\xE1ximo que el motor del compresor toma en el instante de arranque cuando el rotor est\xE1 'atascado' antes de comenzar a girar \u2014 puede ser 5-8 veces el FLA","El amperaje de fallo del motor","El amperaje m\xEDnimo de operaci\xF3n"],respuesta_correcta:1,explicacion:"LRA = amperaje m\xE1ximo al arranque (antes de que el motor comience a girar). Puede ser 5-8 veces el FLA (Full Load Amperage) normal. Importante para: dimensionar los conductores, breakers y capacitores correctamente. Un capacitor deficiente hace que el LRA dure m\xE1s tiempo del normal.",question:"What is 'locked rotor amperage' (LRA) and why does it matter?",options:["The normal operating amperage","The maximum amperage the compressor motor draws at the instant of startup when the rotor is 'locked' before starting to spin \u2014 can be 5-8 times the FLA","The motor failure amperage","The minimum operating amperage"],explanation:"LRA = maximum amperage at startup (before the motor begins to spin). Can be 5-8 times the normal FLA (Full Load Amperage). Important for: correctly sizing conductors, breakers, and capacitors. A deficient capacitor causes the LRA to last longer than normal."},{id:"a2l_223",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 los sistemas A2L requieren componentes el\xE9ctricos 'intrinsically safe' (IS)?",opciones:["Por el mayor consumo de energ\xEDa","Para prevenir que una falla el\xE9ctrica genere suficiente energ\xEDa para encender el A2L \u2014 los contactores y capacitores IS est\xE1n dise\xF1ados para contener chispas dentro del enclosure herm\xE9tico","Solo por reducci\xF3n de consumo","Solo es un requisito de garant\xEDa"],respuesta_correcta:1,explicacion:"Los componentes IS en sistemas A2L tienen enclosures herm\xE9ticos que contienen cualquier chispa o arco interno, previniendo que se exponga al ambiente donde podr\xEDa haber vapores de A2L. Si un componente IS falla, la chispa queda DENTRO del enclosure.",question:"Why do A2L systems require 'intrinsically safe' (IS) electrical components?",options:["Due to higher energy consumption","To prevent an electrical failure from generating enough energy to ignite the A2L \u2014 IS contactors and capacitors are designed to contain sparks within the sealed enclosure","Only for consumption reduction","Only a warranty requirement"],explanation:"IS components in A2L systems have sealed enclosures that contain any internal spark or arc, preventing exposure to the environment where A2L vapors may be present. If an IS component fails, the spark stays INSIDE the enclosure."},{id:"a2l_224",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 indica una lectura de resistencia a tierra de 0 ohms en el motor del compresor?",opciones:["El motor est\xE1 en perfectas condiciones","Falla completa a tierra \u2014 el barniz aislante est\xE1 completamente deteriorado. El compresor necesita reemplazo","Solo indica que est\xE1 bien aterrizado","Solo un problema de calibraci\xF3n del instrumento"],respuesta_correcta:1,explicacion:"Resistencia a tierra de 0 ohms (o cualquier valor bajo) = SHORT COMPLETO A TIERRA. El barniz aislante del motor est\xE1 completamente deteriorado, creando contacto directo entre devanados y carcasa met\xE1lica. El compresor NECESITA reemplazo \u2014 no es reparable en campo.",question:"What does a ground resistance reading of 0 ohms on the compressor motor indicate?",options:["The motor is in perfect condition","Complete ground fault \u2014 the insulation varnish is completely deteriorated. The compressor needs replacement","Only indicates it is well grounded","Only an instrument calibration problem"],explanation:"Ground resistance of 0 ohms (or any low value) = COMPLETE SHORT TO GROUND. The motor insulation varnish is completely deteriorated, creating direct contact between windings and the metal shell. The compressor NEEDS replacement \u2014 not field-repairable."},{id:"a2l_225",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'desequilibrio de voltaje' y c\xF3mo afecta compresores trif\xE1sicos?",opciones:["Una variaci\xF3n aceptable en sistemas trif\xE1sicos","Un desequilibrio de m\xE1s de 2% entre las tres fases puede causar sobrecalentamiento severo del motor del compresor \u2014 cada 1% de desequilibrio causa aumento desproporcionado en el calor del motor","Solo afecta a sistemas grandes","No afecta a compresores modernos"],respuesta_correcta:1,explicacion:"Desequilibrio de voltaje > 2% entre las 3 fases causa corrientes desequilibradas en el motor. Un desequilibrio de 3.5% puede causar aumento de temperatura del 25% en el motor. Los compresores trif\xE1sicos son muy sensibles al desequilibrio \u2014 verificar y corregir en la fuente de alimentaci\xF3n.",question:"What is 'voltage imbalance' and how does it affect three-phase compressors?",options:["An acceptable variation in three-phase systems","An imbalance of more than 2% between the three phases can cause severe motor overheating \u2014 each 1% of imbalance causes disproportionate increase in motor heat","Only affects large systems","Does not affect modern compressors"],explanation:"Voltage imbalance > 2% between the 3 phases causes unbalanced currents in the motor. A 3.5% imbalance can cause a 25% temperature increase in the motor. Three-phase compressors are very sensitive to imbalance \u2014 verify and correct at the power source."},{id:"a2l_226",categoria:"A2L_AVANZADO",pregunta:"\xBFC\xF3mo se mide correctamente el amperaje de un compresor monof\xE1sico?",opciones:["Solo en la l\xEDnea de entrada al equipo","Con la pinza amperim\xE9trica en el conductor de la l\xEDnea caliente (hot wire) al compresor espec\xEDficamente \u2014 no en el conductor neutral ni en el wire completo del equipo","En el conductor neutral","Con el equipo apagado"],respuesta_correcta:1,explicacion:"Para medir amperaje del compresor: colocar la pinza en el HOT WIRE que va espec\xEDficamente al compresor. El conductor neutral en sistemas monof\xE1sicos lleva el mismo amperaje pero en direcci\xF3n opuesta \u2014 medir el hot wire es la pr\xE1ctica est\xE1ndar para comparar con el FLA de la placa.",question:"How is the amperage of a single-phase compressor correctly measured?",options:["Only at the equipment input line","With the clamp ammeter on the hot wire conductor to the compressor specifically \u2014 not on the neutral conductor or on the complete equipment wire","On the neutral conductor","With the equipment off"],explanation:"To measure compressor amperage: place the clamp on the HOT WIRE going specifically to the compressor. The neutral conductor in single-phase systems carries the same amperage but in opposite direction \u2014 measuring the hot wire is standard practice for comparing with the nameplate FLA."},{id:"a2l_227",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la funci\xF3n del capacitor de arranque (start capacitor) vs el capacitor de funcionamiento (run capacitor)?",opciones:["Son exactamente lo mismo","Start: alta capacitancia solo durante el arranque para proveer torque inicial, se desconecta r\xE1pidamente. Run: menor capacitancia, permanece en circuito durante toda la operaci\xF3n para mejorar eficiencia","El start cap es para motores grandes, el run cap para peque\xF1os","Solo los sistemas A2L usan run capacitors"],respuesta_correcta:1,explicacion:"Start capacitor: alta capacitancia (100-600 \xB5F) que provee torque adicional SOLO durante el arranque \u2014 se desconecta por el starting relay en 1-3 segundos. Run capacitor: menor capacitancia (5-60 \xB5F) que permanece en circuito DURANTE toda la operaci\xF3n para desplazamiento de fase y eficiencia.",question:"What is the function of the start capacitor vs the run capacitor?",options:["They are exactly the same","Start: high capacitance only during startup to provide initial torque, disconnects quickly. Run: lower capacitance, remains in circuit during all operation to improve efficiency","Start cap is for large motors, run cap for small","Only A2L systems use run capacitors"],explanation:"Start capacitor: high capacitance (100-600 \xB5F) providing additional torque ONLY during startup \u2014 disconnected by the starting relay in 1-3 seconds. Run capacitor: lower capacitance (5-60 \xB5F) remaining in the circuit DURING all operation for phase displacement and efficiency."},{id:"a2l_228",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 indica un capacitor 'swollen' (hinchado)?",opciones:["Que est\xE1 completamente funcional","Que el capacitor ha fallado o est\xE1 pr\xF3ximo a fallar \u2014 el gas interno se ha expandido por sobrecalentamiento o falla del diel\xE9ctrico. Debe reemplazarse","Solo que es un capacitor de alta capacidad","Que el sistema tiene exceso de voltaje"],respuesta_correcta:1,explicacion:"Un capacitor hinchado (swollen) indica falla interna \u2014 el diel\xE9ctrico se ha degradado generando gas que expande la carcasa. Nunca usar un capacitor hinchado \u2014 puede explotar o causar falla el\xE9ctrica que da\xF1e otros componentes. Reemplazar inmediatamente.",question:"What does a 'swollen' capacitor indicate?",options:["That it is fully functional","That the capacitor has failed or is about to fail \u2014 internal gas has expanded from overheating or dielectric failure. Must be replaced","Only that it is a high-capacity capacitor","That the system has excess voltage"],explanation:"A swollen capacitor indicates internal failure \u2014 the dielectric has degraded generating gas that expands the housing. Never use a swollen capacitor \u2014 it can explode or cause electrical failure damaging other components. Replace immediately."},{id:"a2l_229",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 causa el 'thermal overload' de un compresor y c\xF3mo se resetea?",opciones:["Una falla del compresor que requiere reemplazo","El overload protector interno del compresor abre el circuito por sobrecalentamiento \u2014 generalmente se resetea autom\xE1ticamente cuando el compresor se enfr\xEDa. La causa subyacente debe investigarse","Solo requiere resetear el breaker","Solo ocurre en sistemas viejos"],respuesta_correcta:1,explicacion:"El thermal overload (sobrecarga t\xE9rmica) abre el circuito del compresor cuando detecta temperatura o amperaje excesivo. Se resetea autom\xE1ticamente cuando el compresor se enfr\xEDa. La causa (voltaje bajo, presiones incorrectas, poca ventilaci\xF3n del compresor) DEBE identificarse y corregirse.",question:"What causes 'thermal overload' of a compressor and how is it reset?",options:["A compressor failure requiring replacement","The compressor's internal overload protector opens the circuit due to overheating \u2014 generally resets automatically when the compressor cools. The underlying cause must be investigated","Only requires resetting the breaker","Only occurs in old systems"],explanation:"The thermal overload (thermal overload) opens the compressor circuit when it detects excessive temperature or amperage. It resets automatically when the compressor cools. The cause (low voltage, incorrect pressures, poor compressor ventilation) MUST be identified and corrected."},{id:"a2l_230",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 mide la 'resistencia de aislamiento' con un megohmmeter en el motor del compresor?",opciones:["La resistencia de los devanados del motor","La calidad del barniz aislante entre los devanados y la carcasa \u2014 un valor alto (Mohms) indica buen aislamiento, un valor bajo indica degradaci\xF3n del aislante","El amperaje m\xE1ximo del motor","La capacitancia del capacitor"],respuesta_correcta:1,explicacion:"El megohmmeter mide la resistencia de AISLAMIENTO entre los devanados del motor y la carcasa met\xE1lica. Valor alto (>10 MOhms) = buen aislamiento. Valor bajo = barniz deteriorado = riesgo de falla a tierra. Se realiza en compresores con sospecha de burnout o como mantenimiento preventivo.",question:"What does 'insulation resistance' measured with a megohmmeter on the compressor motor measure?",options:["The resistance of the motor windings","The quality of the insulation varnish between the windings and the shell \u2014 a high value (Mohms) indicates good insulation, a low value indicates insulation degradation","The motor's maximum amperage","The capacitor capacitance"],explanation:"The megohmmeter measures INSULATION resistance between motor windings and the metal shell. High value (>10 MOhms) = good insulation. Low value = deteriorated varnish = ground fault risk. Performed on compressors suspected of burnout or as preventive maintenance."},{id:"a2l_231",categoria:"A2L_AVANZADO",pregunta:"\xBFC\xF3mo se ajusta el superheat de una TXV con bulbo externo?",opciones:["No se puede ajustar en campo","Girando el tornillo de ajuste en la base de la v\xE1lvula \u2014 sentido horario AUMENTA el superheat (cierra m\xE1s la v\xE1lvula), sentido antihorario DISMINUYE el superheat","Solo se ajusta en f\xE1brica","Solo cambiando el bulbo"],respuesta_correcta:1,explicacion:"La TXV se ajusta girando el tornillo de ajuste: HORARIO = aumenta la tensi\xF3n del resorte = aumenta el superheat (cierra m\xE1s la v\xE1lvula). ANTIHORARIO = disminuye la tensi\xF3n = disminuye el superheat. Hacer ajustes peque\xF1os (1/4 a 1/2 vuelta) y esperar 15-20 minutos para evaluar el efecto.",question:"How is the superheat of a TXV with an external bulb adjusted?",options:["Cannot be adjusted in the field","By turning the adjustment screw at the base of the valve \u2014 clockwise INCREASES superheat (closes the valve more), counterclockwise DECREASES superheat","Only adjustable at the factory","Only by changing the bulb"],explanation:"The TXV is adjusted by turning the adjustment screw: CLOCKWISE = increases spring tension = increases superheat (closes the valve more). COUNTERCLOCKWISE = decreases tension = decreases superheat. Make small adjustments (1/4 to 1/2 turn) and wait 15-20 minutes to evaluate the effect."},{id:"a2l_232",categoria:"A2L_AVANZADO",pregunta:"\xBFD\xF3nde se instala correctamente el bulbo de la TXV?",opciones:["Junto al compresor","En la l\xEDnea de succi\xF3n, cercano a la salida del evaporador, en posici\xF3n de las 4 a las 8 del reloj para buen contacto t\xE9rmico, aislado del ambiente exterior","En el condesador","En la l\xEDnea l\xEDquida"],respuesta_correcta:1,explicacion:"El bulbo de la TXV va en la l\xEDnea de SUCCI\xD3N, cerca de la SALIDA del evaporador (donde mide el superheat). Debe estar en posici\xF3n entre las 4 y las 8 del reloj para buen contacto con el refrigerante en la tuber\xEDa. Debe estar bien aislado del ambiente exterior para que solo mida la temperatura del refrigerante.",question:"Where is the TXV sensing bulb correctly installed?",options:["Next to the compressor","On the suction line, close to the evaporator outlet, in the 4 to 8 o'clock position for good thermal contact, insulated from the outside environment","On the condenser","On the liquid line"],explanation:"The TXV sensing bulb goes on the SUCTION line, close to the evaporator OUTLET (where it measures superheat). It should be positioned between 4 and 8 o'clock for good contact with the refrigerant in the pipe. It must be well insulated from the outside environment so it only measures refrigerant temperature."},{id:"a2l_233",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'flash gas' y d\xF3nde ocurre en el sistema?",opciones:["Gas de escape del sistema","Una peque\xF1a porci\xF3n del refrigerante l\xEDquido que se vaporiza instant\xE1neamente al pasar por el dispositivo de metering \u2014 esta vaporizaci\xF3n enfr\xEDa el refrigerante restante","Gas en el tanque de recuperaci\xF3n","Solo en sistemas A3"],respuesta_correcta:1,explicacion:"Flash gas = peque\xF1a porci\xF3n del refrigerante l\xEDquido que se vaporiza inmediatamente al pasar por la v\xE1lvula de expansi\xF3n (ca\xEDda de presi\xF3n s\xFAbita). Este proceso de vaporizaci\xF3n absorbe calor latente, enfriando el refrigerante restante a la temperatura de evaporaci\xF3n correcta.",question:"What is 'flash gas' and where does it occur in the system?",options:["System exhaust gas","A small portion of liquid refrigerant that vaporizes instantly when passing through the metering device \u2014 this vaporization cools the remaining refrigerant","Gas in the recovery tank","Only in A3 systems"],explanation:"Flash gas = a small portion of liquid refrigerant that vaporizes immediately when passing through the expansion valve (sudden pressure drop). This vaporization process absorbs latent heat, cooling the remaining refrigerant to the correct evaporating temperature."},{id:"a2l_234",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 el refrigerante que llega a la TXV debe llegar como L\xCDQUIDO puro (100%) y no con vapor?",opciones:["No importa el estado \u2014 la TXV maneja ambos","La TXV est\xE1 dise\xF1ada para medrar L\xCDQUIDO. Si llega vapor (burbujas), la capacidad real de la v\xE1lvula se reduce significativamente porque el vapor ocupa mucho m\xE1s volumen que el l\xEDquido","Solo importa para A2L","Solo para TXV termost\xE1ticas, no electr\xF3nicas"],respuesta_correcta:1,explicacion:"La TXV mide el VOLUMEN de refrigerante, no la masa. El vapor ocupa ~20 veces m\xE1s volumen que el l\xEDquido a la misma presi\xF3n. Si hay vapor mezclado con el l\xEDquido, la TXV 'cree' que est\xE1 pasando m\xE1s refrigerante del que realmente est\xE1 pasando en masa, reduciendo la capacidad real del sistema.",question:"Why must the refrigerant arriving at the TXV arrive as pure (100%) LIQUID and not with vapor?",options:["State doesn't matter \u2014 the TXV handles both","The TXV is designed to meter LIQUID. If vapor (bubbles) arrives, the actual capacity of the valve is significantly reduced because vapor occupies much more volume than liquid","Only matters for A2L","Only for thermostatic TXVs, not electronic"],explanation:"The TXV is designed to meter VOLUME of refrigerant, not mass. Vapor occupies ~20 times more volume than liquid at the same pressure. If vapor is mixed with the liquid, the TXV 'thinks' more refrigerant is passing than actually is in mass, reducing actual system capacity."},{id:"a2l_235",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la se\xF1al de que una TXV tiene el bulbo 'perdido su carga' (perdi\xF3 el refrigerante interno del bulbo)?",opciones:["La TXV nunca falla de esta manera","La TXV se cierra completamente porque no hay presi\xF3n en el bulbo para abrirla \u2014 el sistema tendr\xE1 presi\xF3n de baja muy baja o en vac\xEDo","La TXV se abre completamente","No tiene efecto visible"],respuesta_correcta:1,explicacion:"Si el bulbo de la TXV pierde su carga (refrigerante interno), la presi\xF3n del bulbo cae a cero. Sin presi\xF3n del bulbo, solo act\xFAa el resorte que mantiene la v\xE1lvula CERRADA. El sistema tendr\xE1 presi\xF3n de baja extremadamente baja (o vac\xEDo) y el evaporador no estar\xE1 fr\xEDo.",question:"What is the sign that a TXV has 'lost its charge' (lost the internal refrigerant from the bulb)?",options:["The TXV never fails this way","The TXV closes completely because there is no bulb pressure to open it \u2014 the system will have very low or vacuum low-side pressure","The TXV opens completely","No visible effect"],explanation:"If the TXV sensing bulb loses its charge (internal refrigerant), the bulb pressure drops to zero. Without bulb pressure, only the spring acts to keep the valve CLOSED. The system will have extremely low (or vacuum) low-side pressure and the evaporator will not be cold."},{id:"a2l_236",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'MOP' (Maximum Operating Pressure) en TXVs con limitaci\xF3n?",opciones:["La presi\xF3n m\xE1xima de la l\xEDnea de alta","Un mecanismo en algunas TXV que previene que la v\xE1lvula abra completamente cuando la presi\xF3n de baja excede un valor preestablecido \u2014 protege el compresor de arrancar en condiciones de alta presi\xF3n","La presi\xF3n m\xE1xima del bulbo","Solo para sistemas industriales"],respuesta_correcta:1,explicacion:"MOP (Maximum Operating Pressure) = caracter\xEDstica de algunas TXV que limita la apertura m\xE1xima cuando la presi\xF3n de evaporador excede un valor establecido. Esto previene que el compresor arranque con carga excesiva (alta presi\xF3n de baja) despu\xE9s de un apagado largo en ambiente caliente.",question:"What is 'MOP' (Maximum Operating Pressure) in limited TXVs?",options:["The maximum high-side line pressure","A mechanism in some TXVs that prevents the valve from opening fully when the low-side pressure exceeds a preset value \u2014 protects the compressor from starting under high pressure conditions","The maximum bulb pressure","Only for industrial systems"],explanation:"MOP (Maximum Operating Pressure) = a feature of some TXVs that limits maximum opening when evaporator pressure exceeds a set value. This prevents the compressor from starting with excessive load (high low-side pressure) after a long shutdown in hot environment."},{id:"a2l_237",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1les son las se\xF1ales de una TXV atascada en posici\xF3n CERRADA?",opciones:["Presiones de alta elevadas","Presi\xF3n de baja extremadamente baja o en vac\xEDo, superheat muy alto, l\xEDnea de succi\xF3n caliente y seca \u2014 el evaporador 'muere de hambre' sin refrigerante","Presi\xF3n de baja normal","Solo un ruido inusual"],respuesta_correcta:1,explicacion:"TXV atascada cerrada: el evaporador recibe poco o nada de refrigerante. S\xEDntomas: presi\xF3n de baja MUY baja o vac\xEDo, superheat extremadamente alto (l\xEDnea de succi\xF3n muy caliente y seca), sin enfriamiento, y posible formaci\xF3n de hielo solo en el inicio del evaporador.",question:"What are the signs of a TXV stuck in the CLOSED position?",options:["Elevated high-side pressures","Extremely low or vacuum low-side pressure, very high superheat, hot and dry suction line \u2014 the evaporator 'starves' without refrigerant","Normal low-side pressure","Only an unusual noise"],explanation:"TXV stuck closed: the evaporator receives little or no refrigerant. Symptoms: VERY low or vacuum low-side pressure, extremely high superheat (very hot and dry suction line), no cooling, and possible ice formation only at the evaporator inlet."},{id:"a2l_238",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la ventaja de una EEV (electronic expansion valve) sobre una TXV termost\xE1tica?",opciones:["La EEV es m\xE1s barata","La EEV puede ajustarse electr\xF3nicamente por el controlador del sistema con mucha mayor precisi\xF3n y velocidad, respondiendo a condiciones cambiantes de manera m\xE1s eficiente que la TXV mec\xE1nica","La TXV es siempre mejor","No hay diferencia pr\xE1ctica"],respuesta_correcta:1,explicacion:"La EEV se controla electr\xF3nicamente (pasos de motor stepper), permitiendo ajuste mucho m\xE1s preciso y r\xE1pido que la TXV mec\xE1nica. Los sistemas modernos A2L con controladores inteligentes usan EEV para optimizar la eficiencia bajo cualquier condici\xF3n de carga.",question:"What is the advantage of an EEV (electronic expansion valve) over a thermostatic TXV?",options:["The EEV is cheaper","The EEV can be electronically adjusted by the system controller with much greater precision and speed, responding to changing conditions more efficiently than the mechanical TXV","The TXV is always better","No practical difference"],explanation:"The EEV is electronically controlled (stepper motor steps), allowing much more precise and fast adjustment than the mechanical TXV. Modern A2L systems with smart controllers use EEV to optimize efficiency under any load condition."},{id:"a2l_239",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 la TXV necesita un diferencial de presi\xF3n m\xEDnimo para funcionar correctamente?",opciones:["No necesita diferencial espec\xEDfico","La TXV require que el lado de alta sea significativamente mayor que el lado de baja para funcionar \u2014 si el diferencial es muy peque\xF1o, no puede controlar el flujo correctamente","Solo para TXVs antiguas","Solo en climas fr\xEDos"],respuesta_correcta:1,explicacion:"La TXV necesita un diferencial de presi\xF3n adecuado entre alta y baja para funcionar correctamente (generalmente al menos 100 PSI de diferencial en sistemas de alta presi\xF3n). Diferencial muy bajo hace que la v\xE1lvula sea inestable o no pueda regular el flujo apropiadamente.",question:"Why does the TXV need a minimum pressure differential to function correctly?",options:["It does not need a specific differential","The TXV requires the high side to be significantly greater than the low side to function \u2014 if the differential is too small, it cannot control flow correctly","Only for old TXVs","Only in cold climates"],explanation:"The TXV needs an adequate pressure differential between high and low sides to function correctly (generally at least 100 PSI differential in high-pressure systems). Very low differential makes the valve unstable or unable to regulate flow appropriately."},{id:"a2l_240",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 causa que una TXV quede atascada en posici\xF3n ABIERTA?",opciones:["El bulbo pierde su carga","Contaminaci\xF3n en el orificio de la v\xE1lvula, resorte roto, o da\xF1o del diafragma \u2014 la v\xE1lvula no puede cerrarse correctamente causando inundaci\xF3n del evaporador","La TXV siempre se ataca cerrada","Solo ocurre en sistemas A2L"],respuesta_correcta:1,explicacion:"TXV atascada abierta: contaminaci\xF3n en el orificio de la v\xE1lvula, resorte roto o debilitado, o da\xF1o del diafragma de control. S\xEDntomas: superheat muy bajo o negativo (refrigerante l\xEDquido al compresor), presi\xF3n de baja alta, y potencial liquid floodback al compresor.",question:"What causes a TXV to get stuck in the OPEN position?",options:["The bulb loses its charge","Contamination in the valve orifice, broken spring, or diaphragm damage \u2014 the valve cannot close properly causing evaporator flooding","The TXV always gets stuck closed","Only occurs in A2L systems"],explanation:"TXV stuck open: contamination in the valve orifice, broken or weakened spring, or control diaphragm damage. Symptoms: very low or negative superheat (liquid refrigerant to compressor), high low-side pressure, and potential liquid floodback to the compressor."},{id:"a2l_241",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la temperatura de condensaci\xF3n \xF3ptima para un sistema de A/C residencial con R-454B?",opciones:["Igual que la temperatura del aire exterior","La temperatura de condensaci\xF3n debe ser aproximadamente 20-30\xB0F MAYOR que la temperatura del aire exterior para que haya transferencia de calor adecuada","Igual que la temperatura interior","No hay temperatura \xF3ptima"],respuesta_correcta:1,explicacion:"La temperatura de condensaci\xF3n debe ser t\xEDpicamente 20-30\xB0F m\xE1s alta que la temperatura del aire exterior (approach temperature). Si la temperatura exterior es 95\xB0F, la temperatura de condensaci\xF3n deber\xEDa ser ~115-125\xB0F. Mayor diferencia = mayor transferencia de calor.",question:"What is the optimal condensing temperature for a residential A/C system with R-454B?",options:["Same as outdoor air temperature","The condensing temperature should be approximately 20-30\xB0F HIGHER than the outdoor air temperature for adequate heat transfer","Same as indoor temperature","No optimal temperature"],explanation:"Condensing temperature should typically be 20-30\xB0F higher than the outdoor air temperature (approach temperature). If outdoor temperature is 95\xB0F, condensing temperature should be ~115-125\xB0F. Greater difference = greater heat transfer."},{id:"a2l_242",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 causa que el condensador se 'sub-enfr\xEDe' excesivamente?",opciones:["La temperatura exterior es baja","Exceso de refrigerante en el sistema \u2014 el refrigerante extra se acumula en el condensador causando subcooling mayor al dise\xF1ado","El ventilador del condensador est\xE1 demasiado r\xE1pido","El compresor es demasiado eficiente"],respuesta_correcta:1,explicacion:"Subcooling excesivo generalmente indica EXCESO DE REFRIGERANTE en el sistema. El refrigerante extra se acumula en el condensador, aumentando el subcooling pero tambi\xE9n reduciendo la superficie disponible para condensaci\xF3n (elevando la presi\xF3n de alta).",question:"What causes the condenser to 'subcool' excessively?",options:["Outdoor temperature is low","Excess refrigerant in the system \u2014 the extra refrigerant accumulates in the condenser causing higher subcooling than designed","The condenser fan is too fast","The compressor is too efficient"],explanation:"Excessive subcooling generally indicates EXCESS REFRIGERANT in the system. The extra refrigerant accumulates in the condenser, increasing subcooling but also reducing the surface available for condensation (raising high-side pressure)."},{id:"a2l_243",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 ocurre con el sistema cuando el ventilador del condensador falla completamente?",opciones:["El sistema sigue funcionando sin problemas","La presi\xF3n de alta sube r\xE1pidamente hasta disparar el presostato de alta o el thermal overload del compresor \u2014 el sistema se apaga por protecci\xF3n","Solo reduce la eficiencia un poco","Solo aumenta el ruido"],respuesta_correcta:1,explicacion:"Sin ventilador del condensador: el calor no puede disiparse al exterior, la presi\xF3n de alta sube r\xE1pidamente. El presostato de alta presi\xF3n (high pressure cutout) abre el circuito del compresor por protecci\xF3n. El sistema cicla on/off o se apaga completamente.",question:"What happens to the system when the condenser fan fails completely?",options:["The system continues working without problems","The high-side pressure rises rapidly until tripping the high pressure cutout or the compressor thermal overload \u2014 the system shuts down for protection","Only reduces efficiency slightly","Only increases noise"],explanation:"Without a condenser fan: heat cannot dissipate to the outdoors, high-side pressure rises rapidly. The high pressure cutout opens the compressor circuit for protection. The system cycles on/off or shuts down completely."},{id:"a2l_244",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 se usa agua jabonosa para detectar fugas en la bobina del condensador despu\xE9s de una limpieza qu\xEDmica?",opciones:["La espuma del jab\xF3n hace m\xE1s f\xE1cil ver la suciedad","Si la bobina tiene grietas microsc\xF3picas o uniones debilitadas por la limpieza qu\xEDmica, la agua jabonosa formar\xE1 burbujas en los puntos de fuga al estar el sistema bajo presi\xF3n de nitr\xF3geno","El agua jabonosa limpia mejor","Solo por tradici\xF3n"],respuesta_correcta:1,explicacion:"Despu\xE9s de limpiar un condensador con qu\xEDmicos \xE1cidos, es recomendable hacer leak check con agua jabonosa bajo presi\xF3n de nitr\xF3geno. Los qu\xEDmicos de limpieza pueden debilitar uniones o revelar grietas microsc\xF3picas existentes que el sistema presurizado resaltar\xE1 con burbujas.",question:"Why is soapy water used to detect leaks in the condenser coil after chemical cleaning?",options:["Foam makes dirt easier to see","If the coil has microscopic cracks or joints weakened by chemical cleaning, soapy water will form bubbles at leak points when the system is under nitrogen pressure","Soapy water cleans better","Only by tradition"],explanation:"After cleaning a condenser with acid chemicals, it is recommended to leak check with soapy water under nitrogen pressure. The cleaning chemicals can weaken joints or reveal existing microscopic cracks that the pressurized system will highlight with bubbles."},{id:"a2l_245",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'approach temperature' del condensador y qu\xE9 indica?",opciones:["La temperatura del refrigerante entrando al condensador","La diferencia entre la temperatura de condensaci\xF3n (saturaci\xF3n) y la temperatura del aire exterior entrando al condensador \u2014 indica la eficiencia de transferencia de calor del condensador","La temperatura del aire saliendo del condensador","Solo se mide en sistemas comerciales"],respuesta_correcta:1,explicacion:"Approach temperature = temperatura de saturaci\xF3n del condensador - temperatura del aire de entrada al condensador. Un approach bajo (bueno) indica que el condensador est\xE1 transfiriendo calor eficientemente. Un approach alto puede indicar condensador sucio, airflow insuficiente, o sistema sobredimensionado.",question:"What is the condenser 'approach temperature' and what does it indicate?",options:["The temperature of refrigerant entering the condenser","The difference between the condensing (saturation) temperature and the outdoor air temperature entering the condenser \u2014 indicates the heat transfer efficiency of the condenser","The air temperature leaving the condenser","Only measured in commercial systems"],explanation:"Approach temperature = condenser saturation temperature - incoming air temperature to the condenser. Low approach (good) indicates the condenser is transferring heat efficiently. High approach may indicate dirty condenser, insufficient airflow, or oversized system."},{id:"a2l_246",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la temperatura de saturaci\xF3n \xF3ptima del evaporador en un sistema de confort de A/C?",opciones:["Igual que la temperatura del cuarto","T\xEDpicamente 35-45\xB0F para balance entre capacidad de enfriamiento y extracci\xF3n de humedad del aire \u2014 debajo de 32\xB0F el evaporador se congelar\xEDa","0\xB0F (temperatura de congelamiento)","70\xB0F (temperatura del cuarto)"],respuesta_correcta:1,explicacion:"La temperatura de saturaci\xF3n del evaporador en A/C de confort t\xEDpicamente es 35-45\xB0F. Esto: (1) permite enfriamiento eficiente, (2) permite condensaci\xF3n de humedad (dehumidification) en la bobina, y (3) est\xE1 sobre 32\xB0F para prevenir congelamiento en condiciones normales de operaci\xF3n.",question:"What is the optimal evaporator saturation temperature in a comfort A/C system?",options:["Same as room temperature","Typically 35-45\xB0F to balance cooling capacity and air moisture extraction \u2014 below 32\xB0F the evaporator would freeze","0\xB0F (freezing temperature)","70\xB0F (room temperature)"],explanation:"Evaporator saturation temperature in comfort A/C is typically 35-45\xB0F. This: (1) allows efficient cooling, (2) allows moisture condensation (dehumidification) on the coil, and (3) is above 32\xB0F to prevent freezing under normal operating conditions."},{id:"a2l_247",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 el evaporador puede congelarse aun cuando el sistema tiene carga de refrigerante correcta?",opciones:["El evaporador no puede congelarse con carga correcta","El bajo airflow (filtro tapado, ventilador deficiente, bobina sucia) reduce la carga de calor al evaporador, haciendo que la temperatura de saturaci\xF3n baje por debajo de 32\xB0F \u2014 el evaporador se congela incluso con la carga correcta","Solo se congela por exceso de refrigerante","Solo en climas muy fr\xEDos"],respuesta_correcta:1,explicacion:"El evaporador se congela cuando la temperatura de saturaci\xF3n baja de 32\xB0F. Causas: (1) bajo airflow (m\xE1s com\xFAn \u2014 el menos calor que llega, m\xE1s baja la temperatura), (2) baja carga de refrigerante (superheat bajo en evaporador), o (3) temperatura exterior muy baja en ciertos sistemas.",question:"Why can the evaporator freeze even when the system has the correct refrigerant charge?",options:["The evaporator cannot freeze with correct charge","Low airflow (clogged filter, deficient fan, dirty coil) reduces heat load to the evaporator, causing saturation temperature to drop below 32\xB0F \u2014 the evaporator freezes even with correct charge","Only freezes from excess refrigerant","Only in very cold climates"],explanation:"The evaporator freezes when saturation temperature drops below 32\xB0F. Causes: (1) low airflow (most common \u2014 less heat arriving, lower the temperature), (2) low refrigerant charge (low superheat in evaporator), or (3) very low outdoor temperature in certain systems."},{id:"a2l_248",categoria:"A2L_AVANZADO",pregunta:"\xBFC\xF3mo se descongela correctamente un evaporador congelado antes de diagnosticar el sistema?",opciones:["Con soplete de propano directamente en el hielo","Apagando el compresor y dejando el ventilador del evaporador corriendo (modo 'fan only') hasta que el hielo se derrita naturalmente","Con agua caliente directamente","Simplemente esperar con el sistema apagado completamente"],respuesta_correcta:1,explicacion:"Para descongelar un evaporador: (1) APAGAR el compresor, (2) mantener el ventilador del evaporador funcionando en modo 'fan only' \u2014 esto hace circular el aire templado del cuarto sobre la bobina congelada, descongel\xE1ndola m\xE1s r\xE1pido que apagado completamente. NUNCA usar soplete ni calor directo en la bobina.",question:"How is a frozen evaporator correctly defrosted before diagnosing the system?",options:["With a propane torch directly on the ice","By turning off the compressor and leaving the evaporator fan running (fan only mode) until the ice melts naturally","With hot water directly","Simply wait with the system completely off"],explanation:"To defrost an evaporator: (1) TURN OFF the compressor, (2) keep the evaporator fan running in 'fan only' mode \u2014 this circulates warm room air over the frozen coil, defrosting it faster than being completely off. NEVER use a torch or direct heat on the coil."},{id:"a2l_249",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'temperature split' y cu\xE1l es el rango normal para A/C residencial?",opciones:["La diferencia entre interior y exterior","La diferencia de temperatura entre el aire que ENTRA y el aire que SALE del evaporador \u2014 rango normal: 16-22\xB0F dependiendo de la humedad relativa y la eficiencia del sistema","Solo se mide en sistemas comerciales","No tiene valor de referencia"],respuesta_correcta:1,explicacion:"Temperature split = temperatura de retorno (entrada al evaporador) - temperatura de suministro (salida). Normal: 16-22\xB0F en sistemas residenciales correctamente cargados y con airflow adecuado. Menor a 16\xB0F puede indicar airflow alto, baja carga, o problema de refrigerante. Mayor a 22\xB0F puede indicar airflow bajo.",question:"What is the 'temperature split' and what is the normal range for residential A/C?",options:["The difference between indoor and outdoor","The temperature difference between the air ENTERING and the air LEAVING the evaporator \u2014 normal range: 16-22\xB0F depending on relative humidity and system efficiency","Only measured in commercial systems","No reference value"],explanation:"Temperature split = return air temperature (entering evaporator) - supply air temperature (leaving). Normal: 16-22\xB0F in properly charged residential systems with adequate airflow. Less than 16\xB0F may indicate high airflow, low charge, or refrigerant problem. More than 22\xB0F may indicate low airflow."},{id:"a2l_250",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 la DEHUMIDIFICATION (extracci\xF3n de humedad) del evaporador es afectada por el airflow?",opciones:["El airflow no afecta la deshumidificaci\xF3n","Mayor airflow = menos tiempo de contacto entre el aire h\xFAmedo y la bobina fr\xEDa = menos condensaci\xF3n de humedad. Menor airflow (325-350 CFM/ton) = m\xE1s tiempo de contacto = m\xE1s deshumidificaci\xF3n","La deshumidificaci\xF3n no depende del airflow","Solo en climas tropicales"],respuesta_correcta:1,explicacion:"Para mayor deshumidificaci\xF3n: reducir el airflow (325-350 CFM/ton) para aumentar el tiempo de contacto entre el aire y la bobina fr\xEDa, permitiendo m\xE1s condensaci\xF3n de humedad. Para condiciones de alta carga sensible (calor seco): aumentar el airflow (425-450 CFM/ton) para mayor enfriamiento y menos deshumidificaci\xF3n.",question:"Why is the DEHUMIDIFICATION (moisture removal) of the evaporator affected by airflow?",options:["Airflow does not affect dehumidification","Higher airflow = less contact time between humid air and cold coil = less moisture condensation. Lower airflow (325-350 CFM/ton) = more contact time = more dehumidification","Dehumidification does not depend on airflow","Only in tropical climates"],explanation:"For greater dehumidification: reduce airflow (325-350 CFM/ton) to increase contact time between air and the cold coil, allowing more moisture condensation. For high sensible load (dry heat): increase airflow (425-450 CFM/ton) for more cooling and less dehumidification."},{id:"a2l_251",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1les son los 4 componentes principales del ciclo b\xE1sico de refrigeraci\xF3n por compresi\xF3n de vapor?",opciones:["Compresor, bomba, condensador, evaporador","Compresor, condensador, dispositivo de expansi\xF3n (metering device), evaporador","Compresor, filtro, condensador, v\xE1lvula","Compresor, capacitor, condensador, TXV"],respuesta_correcta:1,explicacion:"Los 4 componentes b\xE1sicos del ciclo de vapor comprimido son: (1) COMPRESOR \u2014 comprime el vapor, (2) CONDENSADOR \u2014 libera calor al exterior, (3) DISPOSITIVO DE EXPANSI\xD3N \u2014 reduce presi\xF3n/temperatura, (4) EVAPORADOR \u2014 absorbe calor del espacio.",question:"What are the 4 main components of the basic vapor compression refrigeration cycle?",options:["Compressor, pump, condenser, evaporator","Compressor, condenser, expansion device (metering device), evaporator","Compressor, filter, condenser, valve","Compressor, capacitor, condenser, TXV"],explanation:"The 4 basic components of the vapor compression cycle are: (1) COMPRESSOR \u2014 compresses vapor, (2) CONDENSER \u2014 releases heat to outdoors, (3) EXPANSION DEVICE \u2014 reduces pressure/temperature, (4) EVAPORATOR \u2014 absorbs heat from the space."},{id:"a2l_252",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la diferencia entre un sistema split y un sistema packaged?",opciones:["Son exactamente lo mismo","Split: unidades separadas interior (evaporador) y exterior (condensador+compresor). Packaged: todos los componentes en una sola unidad (generalmente en el techo o junto al edificio)","El split es siempre m\xE1s eficiente","El packaged solo se usa en industrial"],respuesta_correcta:1,explicacion:"Split: dos unidades separadas conectadas por l\xEDneas de refrigerante \u2014 unidad interior (evaporador + ventilador interior) y unidad exterior (condensador + compresor + ventilador exterior). Packaged: todos los componentes HVAC en un solo gabinete, generalmente rooftop (techo) en sistemas comerciales.",question:"What is the difference between a split system and a packaged system?",options:["They are exactly the same","Split: separate indoor (evaporator) and outdoor (condenser+compressor) units. Packaged: all components in a single unit (generally on the roof or next to the building)","Split is always more efficient","Packaged is only used in industrial"],explanation:"Split: two separate units connected by refrigerant lines \u2014 indoor unit (evaporator + indoor fan) and outdoor unit (condenser + compressor + outdoor fan). Packaged: all HVAC components in a single cabinet, generally rooftop in commercial systems."},{id:"a2l_253",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la diferencia funcional entre una bomba de calor y un sistema de solo enfriamiento?",opciones:["No hay diferencia","Una bomba de calor puede invertir el ciclo de refrigeraci\xF3n con una v\xE1lvula de 4 v\xEDas \u2014 el condensador y el evaporador intercambian funciones para proveer tanto enfriamiento como calefacci\xF3n","La bomba de calor usa diferente refrigerante","La bomba de calor no puede enfriar"],respuesta_correcta:1,explicacion:"Una bomba de calor tiene una v\xE1lvula de 4 v\xEDas que invierte la direcci\xF3n del flujo de refrigerante. En modo enfriamiento: el interior act\xFAa como evaporador (absorbe calor). En modo calefacci\xF3n: el exterior act\xFAa como evaporador (extrae calor del exterior) y el interior como condensador (libera calor al interior).",question:"What is the functional difference between a heat pump and a cooling-only system?",options:["There is no difference","A heat pump can reverse the refrigeration cycle with a 4-way valve \u2014 the condenser and evaporator swap functions to provide both cooling and heating","The heat pump uses a different refrigerant","The heat pump cannot cool"],explanation:"A heat pump has a 4-way valve that reverses refrigerant flow direction. In cooling mode: the indoor unit acts as evaporator (absorbs heat). In heating mode: the outdoor unit acts as evaporator (extracts heat from outdoors) and the indoor unit as condenser (releases heat indoors)."},{id:"a2l_254",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es un sistema VRF (Variable Refrigerant Flow)?",opciones:["Un sistema de caudal variable de aire","Un sistema donde el compresor de velocidad variable y las v\xE1lvulas electr\xF3nicas controlan la cantidad de refrigerante que va a cada unidad interior, permitiendo control individual de m\xFAltiples zonas","Solo para sistemas industriales","Un sistema de alta presi\xF3n especial"],respuesta_correcta:1,explicacion:"VRF = Variable Refrigerant Flow. El compresor de velocidad variable modula su capacidad seg\xFAn la demanda. Las EEV en cada unidad interior controlan el flujo individualmente. Permite que m\xFAltiples unidades interiores operen independientemente con diferentes temperaturas en un edificio.",question:"What is a VRF (Variable Refrigerant Flow) system?",options:["A variable airflow system","A system where the variable-speed compressor and electronic valves control the amount of refrigerant going to each indoor unit, allowing individual control of multiple zones","Only for industrial systems","A special high-pressure system"],explanation:"VRF = Variable Refrigerant Flow. The variable-speed compressor modulates its capacity based on demand. EEVs at each indoor unit control flow individually. Allows multiple indoor units to operate independently with different temperatures in a building."},{id:"a2l_255",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1les son las ventajas del VRF sobre sistemas tradicionales?",opciones:["El VRF es m\xE1s simple","Mayor eficiencia energ\xE9tica (inverter/variable speed), control individual por zona, sin ductos en la mayor\xEDa de instalaciones, y capacidad de recuperaci\xF3n de calor (algunos modelos pueden enfriar y calentar simult\xE1neamente zonas diferentes)","El VRF solo enfr\xEDa, no calienta","El VRF es m\xE1s barato que cualquier alternativa"],respuesta_correcta:1,explicacion:"Ventajas del VRF: (1) eficiencia superior con compresor inverter de velocidad variable, (2) control individual de m\xFAltiples zonas simult\xE1neamente, (3) sin ductos en instalaciones de expansi\xF3n directa, (4) algunos modelos calefaccionan algunas zonas mientras enfr\xEDan otras simult\xE1neamente (recuperaci\xF3n de calor).",question:"What are the advantages of VRF over traditional systems?",options:["VRF is simpler","Greater energy efficiency (inverter/variable speed), individual zone control, no ductwork in most installations, and heat recovery capability (some models can simultaneously cool and heat different zones)","VRF only cools, doesn't heat","VRF is cheaper than any alternative"],explanation:"VRF advantages: (1) superior efficiency with inverter variable-speed compressor, (2) individual control of multiple zones simultaneously, (3) no ductwork in direct expansion installations, (4) some models heat some zones while cooling others simultaneously (heat recovery)."},{id:"a2l_256",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la diferencia entre un sistema de expansi\xF3n directa (DX) y un sistema de agua helada (chilled water)?",opciones:["No hay diferencia","DX: el refrigerante circula directamente hasta los espacios a acondicionar. Agua helada: el refrigerante solo circula en el chiller central, enfr\xEDa agua que luego circula a las unidades terminales","El DX siempre es m\xE1s eficiente","El agua helada solo se usa en residencial"],respuesta_correcta:1,explicacion:"DX (Direct Expansion): el refrigerante circula directamente a los serpentines de enfriamiento en los espacios. Agua helada: el refrigerante se usa solo en el chiller central para enfriar agua; el agua helada circula a las unidades terminales (fan coil units) en el edificio. Los chillers son sistemas de baja presi\xF3n con grandes capacidades.",question:"What is the difference between a direct expansion (DX) system and a chilled water system?",options:["No difference","DX: refrigerant circulates directly to the spaces to be conditioned. Chilled water: refrigerant only circulates in the central chiller, cools water that then circulates to terminal units","DX is always more efficient","Chilled water is only used in residential"],explanation:"DX (Direct Expansion): refrigerant circulates directly to cooling coils in the spaces. Chilled water: refrigerant is used only in the central chiller to cool water; chilled water circulates to terminal units (fan coil units) in the building. Chillers are low-pressure systems with large capacities."},{id:"a2l_257",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1ndo se usa el proceso de 'pump down' en un sistema de refrigeraci\xF3n?",opciones:["Para a\xF1adir refrigerante","Para transferir el refrigerante del sistema al receptor para almacenamiento, permitiendo trabajo en ciertas partes del sistema sin recuperar todo el refrigerante","Para limpiar el sistema","Solo en sistemas grandes"],respuesta_correcta:1,explicacion:"Pump down = proceso de bombear el refrigerante del evaporador y l\xEDneas de baja hacia el receptor o condensador para almacenamiento temporal. Permite trabajar en el lado de baja del sistema (cambiar TXV, filtro, etc.) sin necesitar recuperar todo el refrigerante del sistema.",question:"When is the 'pump down' process used in a refrigeration system?",options:["To add refrigerant","To transfer refrigerant from the system to the receiver for storage, allowing work on certain parts of the system without recovering all the refrigerant","To clean the system","Only in large systems"],explanation:"Pump down = process of pumping refrigerant from the evaporator and low-side lines to the receiver or condenser for temporary storage. Allows work on the low side (changing TXV, filter, etc.) without needing to recover all the system's refrigerant."},{id:"a2l_258",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es el 'balance point' en una bomba de calor y por qu\xE9 importa?",opciones:["El punto donde las presiones alta y baja se igualan","La temperatura exterior a la que la bomba de calor ya no puede satisfacer la demanda de calefacci\xF3n sin asistencia el\xE9ctrica adicional","El punto de m\xE1xima eficiencia","Solo para sistemas comerciales"],respuesta_correcta:1,explicacion:"Balance point = temperatura exterior por debajo de la cual la bomba de calor no puede proveer suficiente calor para mantener la temperatura interior deseada sin calefacci\xF3n auxiliar (resistencias el\xE9ctricas). Generalmente 30-40\xB0F para la mayor\xEDa de climas templados. Abajo del balance point, la calefacci\xF3n auxiliar activa.",question:"What is the 'balance point' in a heat pump and why does it matter?",options:["The point where high and low pressures equalize","The outdoor temperature at which the heat pump can no longer satisfy the heating demand without additional electric auxiliary heat","The point of maximum efficiency","Only for commercial systems"],explanation:"Balance point = outdoor temperature below which the heat pump cannot provide sufficient heating to maintain the desired indoor temperature without auxiliary heating (electric resistance). Generally 30-40\xB0F for most temperate climates. Below balance point, auxiliary heating activates."},{id:"a2l_259",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 el ciclo de refrigeraci\xF3n b\xE1sico NO cambia cuando se usa un refrigerante A2L como R-32?",opciones:["S\xED cambia completamente","El ciclo termodin\xE1mico es el mismo: compresi\xF3n, condensaci\xF3n, expansi\xF3n, evaporaci\xF3n. Lo que cambia son las presiones/temperaturas espec\xEDficas del refrigerante y los requisitos de seguridad adicionales por la inflamabilidad","El A2L requiere un ciclo diferente","Solo los componentes cambian"],respuesta_correcta:1,explicacion:"El ciclo de compresi\xF3n de vapor b\xE1sico es el mismo independientemente del refrigerante: comprimir vapor, condensar a l\xEDquido liberando calor, expandir reduciendo temperatura, evaporar absorbiendo calor. Lo que cambia son las presiones/temperaturas de operaci\xF3n del refrigerante y los requisitos de seguridad adicionales.",question:"Why does the basic refrigeration cycle NOT change when using an A2L refrigerant like R-32?",options:["Yes it does change completely","The thermodynamic cycle is the same: compression, condensation, expansion, evaporation. What changes are the specific pressures/temperatures of the refrigerant and additional safety requirements due to flammability","A2L requires a different cycle","Only the components change"],explanation:"The basic vapor compression cycle is the same regardless of refrigerant: compress vapor, condense to liquid releasing heat, expand reducing temperature, evaporate absorbing heat. What changes are the operating pressures/temperatures of the refrigerant and additional safety requirements."},{id:"a2l_260",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 verificaci\xF3n debe hacer el t\xE9cnico en el airflow ANTES de diagnosticar un problema de refrigerante?",opciones:["El airflow no necesita verificarse","Verificar: filter limpio, ventilador funcional a velocidad correcta, bobina limpia, y que los CFM/ton coincidan con los requisitos del fabricante. Un airflow incorrecto simula problemas de carga de refrigerante","Solo verificar el filtro","Solo medir la temperatura de suministro"],respuesta_correcta:1,explicacion:"SIEMPRE verificar el airflow antes de diagnosticar refrigerante. El airflow afecta directamente el superheat, subcooling, y temperature split. Un filtro tapado o ventilador deficiente puede crear s\xEDntomas id\xE9nticos a una carga de refrigerante incorrecta, llevando a diagn\xF3sticos y 'soluciones' equivocadas.",question:"What airflow verification must the technician perform BEFORE diagnosing a refrigerant problem?",options:["Airflow does not need to be checked","Check: clean filter, functional fan at correct speed, clean coil, and CFM/ton matching manufacturer requirements. Incorrect airflow simulates refrigerant charge problems","Only check the filter","Only measure supply temperature"],explanation:"ALWAYS verify airflow before diagnosing refrigerant. Airflow directly affects superheat, subcooling, and temperature split. A clogged filter or deficient fan can create symptoms identical to incorrect refrigerant charge, leading to wrong diagnoses and 'solutions'."},{id:"a2l_261",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 establece ASHRAE Standard 15 sobre cuartos de m\xE1quinas con sistemas A2L?",opciones:["No aplica a cuartos de m\xE1quinas","Regula el dise\xF1o, ventilaci\xF3n, sensores de seguridad y l\xEDmites de concentraci\xF3n de refrigerante permitidos en cuartos de m\xE1quinas con equipos HVAC incluyendo los que usan A2L","Solo para instalaciones residenciales","Solo para sistemas con m\xE1s de 1,000 lb de refrigerante"],respuesta_correcta:1,explicacion:"ASHRAE 15 establece requisitos para cuartos de m\xE1quinas: ventilaci\xF3n m\xEDnima requerida, sensores de refrigerante (activos para A2L), l\xEDmites de concentraci\xF3n, alarmas, y procedimientos de emergencia. Para sistemas con A2L, los requisitos son m\xE1s estrictos que para A1.",question:"What does ASHRAE Standard 15 establish about mechanical rooms with A2L systems?",options:["Does not apply to mechanical rooms","Regulates the design, ventilation, safety sensors, and allowable refrigerant concentration limits in mechanical rooms with HVAC equipment including A2L","Only for residential installations","Only for systems with more than 1,000 lb of refrigerant"],explanation:"ASHRAE 15 establishes requirements for mechanical rooms: minimum required ventilation, refrigerant sensors (active for A2L), concentration limits, alarms, and emergency procedures. For A2L systems, requirements are stricter than for A1."},{id:"a2l_262",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 restricci\xF3n adicional aplica a sistemas A2L instalados en espacios debajo del nivel del suelo (basements)?",opciones:["No hay restricciones adicionales","Los refrigerantes m\xE1s pesados que el aire (incluyendo A2L) tienden a acumularse en espacios bajos como s\xF3tanos \u2014 se requieren consideraciones adicionales de ventilaci\xF3n y sensores para prevenir acumulaci\xF3n de concentraciones inflamables","Solo requieren un extinguidor extra","No se permite A2L en s\xF3tanos"],respuesta_correcta:1,explicacion:"Los A2L son m\xE1s pesados que el aire y se acumulan en puntos bajos como s\xF3tanos. Para instalaciones en basement u otros espacios bajos, se deben considerar: sensores activos en los puntos de posible acumulaci\xF3n (nivel del piso), ventilaci\xF3n mec\xE1nica hacia arriba o al exterior, y posiblemente restricciones de carga m\xE1xima.",question:"What additional restriction applies to A2L systems installed in spaces below ground level (basements)?",options:["No additional restrictions","Refrigerants heavier than air (including A2L) tend to accumulate in low spaces like basements \u2014 additional ventilation and sensor considerations are required to prevent accumulation of flammable concentrations","Only requires an extra extinguisher","A2L is not permitted in basements"],explanation:"A2L refrigerants are heavier than air and accumulate at low points like basements. For installations in basements or other low spaces, considerations include: active sensors at potential accumulation points (floor level), mechanical ventilation upward or to outdoors, and possibly maximum charge restrictions."},{id:"a2l_263",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 requiere ASHRAE 15.2 antes de instalar un sistema A2L en una ubicaci\xF3n residencial espec\xEDfica?",opciones:["Solo verificar que el equipo sea A2L certificado","Evaluar la ubicaci\xF3n para: volumen de espacio (dispersal volume), clasificaci\xF3n de ocupaci\xF3n, fuentes potenciales de ignici\xF3n, y que cumpla los requisitos de carga m\xE1xima (m1 o m2) para esa ubicaci\xF3n espec\xEDfica","Solo obtener el permiso de construcci\xF3n","Solo verificar que el espacio tiene toma de corriente"],respuesta_correcta:1,explicacion:"ASHRAE 15.2 requiere evaluar la ubicaci\xF3n espec\xEDfica para: (1) volumen del espacio (dispersal volume suficiente para la carga del sistema), (2) clasificaci\xF3n de ocupaci\xF3n residencial, (3) fuentes potenciales de ignici\xF3n cercanas, y (4) verificar que la carga del sistema no exceda los l\xEDmites m1 o m2 para esa ubicaci\xF3n.",question:"What does ASHRAE 15.2 require before installing an A2L system at a specific residential location?",options:["Only verify the equipment is A2L certified","Evaluate the location for: space volume (dispersal volume), occupancy classification, potential ignition sources, and that it meets the maximum charge requirements (m1 or m2) for that specific location","Only obtain the building permit","Only verify the space has an outlet"],explanation:"ASHRAE 15.2 requires evaluating the specific location for: (1) space volume (sufficient dispersal volume for the system charge), (2) residential occupancy classification, (3) nearby potential ignition sources, and (4) verifying the system charge does not exceed m1 or m2 limits for that location."},{id:"a2l_264",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la consecuencia de instalar un sistema A2L sin verificar el dispersal volume requerido?",opciones:["No hay consecuencias legales","Una fuga total del sistema podr\xEDa crear concentraciones de refrigerante por encima del LFL en el espacio, representando riesgo de ignici\xF3n. Tambi\xE9n viola los c\xF3digos de instalaci\xF3n","Solo reduce la eficiencia","Solo afecta la garant\xEDa"],respuesta_correcta:1,explicacion:"Si el dispersal volume es insuficiente: una fuga total del sistema podr\xEDa crear una concentraci\xF3n de refrigerante por ENCIMA del LFL en el espacio, representando riesgo de ignici\xF3n. La instalaci\xF3n tambi\xE9n viola c\xF3digos ASHRAE 15.2, exponiendo al instalador a responsabilidad legal.",question:"What is the consequence of installing an A2L system without verifying the required dispersal volume?",options:["No legal consequences","A total system leak could create refrigerant concentrations above the LFL in the space, representing ignition risk. It also violates installation codes","Only reduces efficiency","Only affects the warranty"],explanation:"If dispersal volume is insufficient: a total system leak could create a refrigerant concentration ABOVE the LFL in the space, representing ignition risk. The installation also violates ASHRAE 15.2 codes, exposing the installer to legal liability."},{id:"a2l_265",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 es una 'control area' en el contexto de almacenamiento de refrigerantes inflamables?",opciones:["El \xE1rea de trabajo del t\xE9cnico","Una secci\xF3n de un edificio con l\xEDmites definidos (paredes, pisos, techos resistentes al fuego) que se usa para calcular la cantidad m\xE1xima de materiales peligrosos permitidos en esa secci\xF3n","El \xE1rea alrededor del equipo para mantenimiento","Solo para edificios comerciales"],respuesta_correcta:1,explicacion:"Control area = secci\xF3n de un edificio con l\xEDmites definidos (paredes, pisos, techos con cierta resistencia al fuego) que determina cu\xE1nta cantidad de material peligroso (incluyendo refrigerante inflamable) puede almacenarse en esa secci\xF3n. Las regulaciones de almacenamiento limitan la cantidad por control area.",question:"What is a 'control area' in the context of flammable refrigerant storage?",options:["The technician's work area","A section of a building with defined boundaries (fire-resistant walls, floors, ceilings) used to calculate the maximum amount of hazardous materials allowed in that section","The area around the equipment for maintenance","Only for commercial buildings"],explanation:"Control area = section of a building with defined boundaries (walls, floors, ceilings with certain fire resistance) that determines how much hazardous material (including flammable refrigerant) can be stored in that section. Storage regulations limit the amount per control area."},{id:"a2l_266",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 est\xE1ndar UL espec\xEDficamente cubre los equipos de refrigeraci\xF3n comercial split con A2L (sistemas con unidades condensadoras remotas)?",opciones:["UL 60335-2-40","UL 60335-2-89 \u2014 cubre dise\xF1o y especificaciones para refrigeraci\xF3n comercial split-type","UL 508","UL 1004"],respuesta_correcta:1,explicacion:"UL 60335-2-89 ('2-89') cubre el dise\xF1o y especificaciones de prueba para sistemas de refrigeraci\xF3n comercial SPLIT-TYPE \u2014 equipos con unidades condensadoras remotas (walk-in coolers, refrigeraci\xF3n de supermercados) que pueden usar A2L.",question:"What UL standard specifically covers commercial split refrigeration equipment with A2L (systems with remote condensing units)?",options:["UL 60335-2-40","UL 60335-2-89 \u2014 covers design and specifications for split-type commercial refrigeration","UL 508","UL 1004"],explanation:"UL 60335-2-89 ('2-89') covers the design and test specifications for SPLIT-TYPE commercial refrigeration systems \u2014 equipment with remote condensing units (walk-in coolers, supermarket refrigeration) that may use A2L."},{id:"a2l_267",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 debe verificar el t\xE9cnico sobre el permiso antes de instalar un sistema A2L en una instalaci\xF3n comercial?",opciones:["No se requieren permisos para A2L","Verificar que se obtuvo el permiso de construcci\xF3n/mec\xE1nico apropiado de la jurisdicci\xF3n local, y que la instalaci\xF3n cumple tanto con los c\xF3digos del permiso como con ASHRAE 15 y los requerimientos del fabricante","Solo verificar el permiso de electricidad","Solo el permiso el\xE9ctrico es necesario para A2L"],respuesta_correcta:1,explicacion:"Para instalaciones comerciales A2L: (1) verificar que se obtuvo el permiso mec\xE1nico/de construcci\xF3n apropiado, (2) la instalaci\xF3n debe cumplir los c\xF3digos del permiso, ASHRAE 15 (comercial), los requisitos de UL del equipo, y los requerimientos del fabricante. El inspector puede requerir verificaciones espec\xEDficas para A2L.",question:"What must the technician verify regarding permits before installing an A2L system in a commercial facility?",options:["No permits are required for A2L","Verify that the appropriate building/mechanical permit was obtained from the local jurisdiction, and that the installation complies with both permit codes and ASHRAE 15 and manufacturer requirements","Only verify the electrical permit","Only the electrical permit is needed for A2L"],explanation:"For commercial A2L installations: (1) verify that the appropriate mechanical/building permit was obtained, (2) the installation must comply with permit codes, ASHRAE 15 (commercial), UL requirements for the equipment, and manufacturer requirements. The inspector may require specific A2L verifications."},{id:"a2l_268",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1ndo se considera que el patr\xF3n de recargas de un sistema A2L es prueba de fuga que requiere acci\xF3n?",opciones:["Cuando se recarga m\xE1s de 5 lb a la vez","Cuando el sistema ha necesitado ser recargado al menos una vez dentro de un per\xEDodo de 3 a\xF1os \u2014 se debe identificar y reparar la fuga","Solo si el propietario se queja","Solo para sistemas con m\xE1s de 50 lb"],respuesta_correcta:1,explicacion:"El patr\xF3n de recarga al menos una vez en 3 a\xF1os se considera PRUEBA de fuga. La fuga DEBE identificarse, repararse, y el sistema verificarse antes de recargar. Documentar la reparaci\xF3n en la etiqueta del sistema.",question:"When is the pattern of recharges for an A2L system considered proof of a leak requiring action?",options:["When more than 5 lb is recharged at once","When the system has needed to be recharged at least once within a 3-year period \u2014 the leak must be identified and repaired","Only if the owner complains","Only for systems with more than 50 lb"],explanation:"The recharge pattern of at least once in 3 years is considered PROOF of a leak. The leak MUST be identified, repaired, and the system verified before recharging. Document the repair on the system label."},{id:"a2l_269",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 documenta el t\xE9cnico en la etiqueta del sistema cada vez que hace servicio en un sistema A2L?",opciones:["Solo la fecha de servicio","Fecha del servicio Y cantidad de refrigerante a\xF1adido (si se a\xF1adi\xF3 alguno) \u2014 esto sirve como registro de servicio y evidencia de patr\xF3n de fuga si es necesario","Solo el nombre del t\xE9cnico","No se requiere documentaci\xF3n de service en la etiqueta"],respuesta_correcta:1,explicacion:"La etiqueta permanente en sistemas A2L sirve tambi\xE9n como registro de servicio. En cada servicio donde se a\xF1ada refrigerante: documentar la fecha y la cantidad a\xF1adida. Este registro permite identificar patrones de fuga con el tiempo.",question:"What does the technician document on the system label each time service is performed on an A2L system?",options:["Only the service date","Date of service AND amount of refrigerant added (if any was added) \u2014 this serves as a service record and evidence of leak pattern if needed","Only the technician's name","No service documentation required on the label"],explanation:"The permanent label on A2L systems also serves as a service record. At each service where refrigerant is added: document the date and amount added. This record allows identifying leak patterns over time."},{id:"a2l_270",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 establece OSHA sobre la clasificaci\xF3n de ambientes inflamables y las herramientas que se usan?",opciones:["OSHA no regula el tipo de herramientas","Los ambientes con gases inflamables se clasifican como Clase I Divisi\xF3n 2 seg\xFAn NFPA 70 / NEC \u2014 se requieren herramientas y equipos sin chispa, sin arco en estas \xE1reas","Solo se requieren guantes especiales","Solo aplica a industrias petroqu\xEDmicas"],respuesta_correcta:1,explicacion:"OSHA junto con NFPA 70 (NEC) clasifica los ambientes con gases inflamables como Clase I Divisi\xF3n 2. En estas \xE1reas se requieren herramientas y equipos espec\xEDficamente certificados para ambientes inflamables (sin chispa, sin arco el\xE9ctrico). Aplica cuando se trabaja con A2L, A2, y A3 refrigerantes.",question:"What does OSHA establish about flammable atmosphere classification and the tools used?",options:["OSHA does not regulate tool types","Environments with flammable gases are classified as Class I Division 2 per NFPA 70 / NEC \u2014 spark-free, arc-free tools and equipment are required in these areas","Only special gloves are required","Only applies to petrochemical industries"],explanation:"OSHA together with NFPA 70 (NEC) classifies environments with flammable gases as Class I Division 2. In these areas, tools and equipment specifically certified for flammable environments (spark-free, arc-free) are required. Applies when working with A2L, A2, and A3 refrigerants."},{id:"a2l_271",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es el principal desaf\xEDo de instalar un sistema VRF con R-32 en un edificio de m\xFAltiples pisos?",opciones:["El R-32 no puede usarse en VRF","Calcular y verificar los l\xEDmites de carga por piso/zona (dispersal volume y clasificaci\xF3n de ocupaci\xF3n), y asegurar que la distribuci\xF3n de carga total del sistema no exceda los l\xEDmites de seguridad para ninguna zona individual","Solo el peso del equipo","Solo la instalaci\xF3n el\xE9ctrica"],respuesta_correcta:1,explicacion:"El principal desaf\xEDo en VRF con A2L en m\xFAltiples pisos es calcular y gestionar los l\xEDmites de carga por zona: cada espacio atendido debe tener suficiente dispersal volume para la porci\xF3n de carga que recibe, considerando la clasificaci\xF3n de ocupaci\xF3n de cada piso/zona individual.",question:"What is the main challenge of installing a VRF system with R-32 in a multi-story building?",options:["R-32 cannot be used in VRF","Calculate and verify charge limits per floor/zone (dispersal volume and occupancy classification), and ensure the total system charge distribution does not exceed safety limits for any individual zone","Only equipment weight","Only electrical installation"],explanation:"The main challenge in VRF with A2L in multiple stories is calculating and managing charge limits per zone: each served space must have sufficient dispersal volume for the portion of charge it receives, considering the occupancy classification of each individual floor/zone."},{id:"a2l_272",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 precauci\xF3n especial aplica cuando se hace servicio en un sistema VRF A2L en un edificio ocupado?",opciones:["No hay precauciones adicionales para edificios ocupados","Establecer un per\xEDmetro de seguridad, verificar que el \xE1rea de trabajo est\xE1 bien ventilada, tener extinguidor disponible, y coordinar con los ocupantes para evacuar las \xE1reas adyacentes si hay riesgo de fuga durante el servicio","Solo avisar al propietario","Solo necesitas guantes adicionales"],respuesta_correcta:1,explicacion:"Trabajar en sistemas A2L en edificios ocupados requiere: (1) establecer per\xEDmetro de seguridad, (2) verificar ventilaci\xF3n del \xE1rea de trabajo, (3) coordinar evacuaci\xF3n de \xE1reas adyacentes si hay riesgo de fuga durante el servicio, (4) tener extinguidor y detector de refrigerante disponibles.",question:"What special precaution applies when servicing a VRF A2L system in an occupied building?",options:["No additional precautions for occupied buildings","Establish a safety perimeter, verify the work area is well ventilated, have extinguisher available, and coordinate with occupants to evacuate adjacent areas if there is leak risk during service","Only notify the owner","Only need additional gloves"],explanation:"Working on A2L systems in occupied buildings requires: (1) establishing a safety perimeter, (2) verifying work area ventilation, (3) coordinating evacuation of adjacent areas if there is leak risk during service, (4) having fire extinguisher and refrigerant detector available."},{id:"a2l_273",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 diferencia el servicio de sistemas VRF de sistemas split convencionales en t\xE9rminos de recuperaci\xF3n A2L?",opciones:["No hay diferencia","Los sistemas VRF tienen m\xE1s refrigerante total distribuido en m\xFAltiples unidades y largas l\xEDneas \u2014 la recuperaci\xF3n es m\xE1s compleja y puede requerir equipos de mayor capacidad. Adem\xE1s, recuperar desde m\xFAltiples unidades independientes requiere planificaci\xF3n cuidadosa","Los sistemas VRF no requieren recuperaci\xF3n","Solo la cantidad de refrigerante es diferente"],respuesta_correcta:1,explicacion:"Los sistemas VRF tienen caracter\xEDsticas que complican la recuperaci\xF3n: (1) gran cantidad total de refrigerante (pueden tener cientos de libras), (2) refrigerante distribuido en m\xFAltiples unidades interiores y largas l\xEDneas, (3) m\xFAltiples circuitos separados que deben recuperarse. Planificar la recuperaci\xF3n con cuidado, verificar que se recupera de todos los circuitos.",question:"What differentiates servicing VRF systems from conventional split systems in terms of A2L recovery?",options:["No difference","VRF systems have more total refrigerant distributed across multiple units and long lines \u2014 recovery is more complex and may require higher capacity equipment. Additionally, recovering from multiple independent units requires careful planning","VRF systems don't require recovery","Only the amount of refrigerant is different"],explanation:"VRF systems have characteristics that complicate recovery: (1) large total refrigerant amount (can have hundreds of pounds), (2) refrigerant distributed across multiple indoor units and long lines, (3) multiple separate circuits that must be recovered. Plan recovery carefully, verify recovery from all circuits."},{id:"a2l_274",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 significa 'heat recovery VRF' y qu\xE9 lo diferencia del VRF est\xE1ndar?",opciones:["El VRF que solo recupera calor del exterior","Un sistema VRF que puede SIMULT\xC1NEAMENTE enfriar algunas zonas y calentar otras \u2014 el calor 'recuperado' de las zonas que se enfr\xEDan se transfiere a las zonas que necesitan calefacci\xF3n","Un VRF con recuperador de calor externo","Solo para climas fr\xEDos"],respuesta_correcta:1,explicacion:"Heat Recovery VRF: un sistema de 3 tubos (tuber\xEDa de alta, baja, y una tercera para transferencia de calor) que permite enfriar y calentar simult\xE1neamente zonas diferentes del mismo edificio. El calor extra\xEDdo de las zonas en modo enfriamiento se transfiere a las zonas que necesitan calefacci\xF3n \u2014 alta eficiencia energ\xE9tica.",question:"What does 'heat recovery VRF' mean and what differentiates it from standard VRF?",options:["VRF that only recovers heat from outdoors","A VRF system that can SIMULTANEOUSLY cool some zones and heat others \u2014 the heat 'recovered' from zones being cooled is transferred to zones needing heating","A VRF with external heat exchanger","Only for cold climates"],explanation:"Heat Recovery VRF: a 3-pipe system (high pipe, low pipe, and a third for heat transfer) that allows simultaneously cooling and heating different zones of the same building. Heat extracted from zones in cooling mode is transferred to zones needing heating \u2014 high energy efficiency."},{id:"a2l_275",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1les son los desaf\xEDos espec\xEDficos de trabajar con R-32 en sistemas multi-split vs R-410A?",opciones:["No hay diferencias","Los sistemas R-32 requieren: (1) herramientas y manifolds rated para A2L, (2) carga precisa en l\xEDquido si es R-454B (R-32 puro puede ser gas o l\xEDquido), (3) nitrogen sweep despu\xE9s de recuperaci\xF3n, (4) verificar label matching de todos los componentes, (5) etiqueta UL post-instalaci\xF3n","El R-32 es m\xE1s f\xE1cil de manejar","Solo la diferencia de presi\xF3n importa"],respuesta_correcta:1,explicacion:"Trabajar con R-32 vs R-410A requiere consideraciones adicionales: (1) herramientas y manifolds certificados A2L, (2) label matching de componentes, (3) nitrogen sweep despu\xE9s de recuperaci\xF3n antes de soldar, (4) etiqueta UL permanente post-instalaci\xF3n, (5) evaluaci\xF3n del sitio para requisitos A2L, y (6) lockout/tagout con mult\xEDmetro para verificar de-energizaci\xF3n.",question:"What are the specific challenges of working with R-32 in multi-split systems vs R-410A?",options:["No differences","R-32 systems require: (1) A2L-rated tools and manifolds, (2) liquid charging for R-454B (R-32 pure can be gas or liquid), (3) nitrogen sweep after recovery, (4) label matching of all components, (5) UL label post-installation","R-32 is easier to handle","Only the pressure difference matters"],explanation:"Working with R-32 vs R-410A requires additional considerations: (1) A2L-certified tools and manifolds, (2) label matching of components, (3) nitrogen sweep after recovery before brazing, (4) permanent UL label post-installation, (5) site evaluation for A2L requirements, and (6) lockout/tagout with multimeter to verify de-energization."},{id:"a2l_276",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 el R-32 tiene presiones ligeramente MAYORES que el R-410A a la misma temperatura?",opciones:["Por error de fabricaci\xF3n \u2014 deber\xEDan ser iguales","El R-32 tiene una curva de presi\xF3n de saturaci\xF3n diferente a la del R-410A \u2014 aunque similar, el R-32 puro genera presiones un poco m\xE1s altas porque es un componente individual sin el 'efecto de mezcla' del R-125 en el R-410A","Por diferencia de tama\xF1o molecular","No hay diferencia real de presi\xF3n"],respuesta_correcta:1,explicacion:"El R-32 es un refrigerante puro con su propia curva P-T \xFAnica. El R-410A es mezcla de R-32 y R-125. La adici\xF3n de R-125 modifica las propiedades de la mezcla. El R-32 puro opera a presiones ligeramente m\xE1s altas que el R-410A a la misma temperatura de saturaci\xF3n.",question:"Why does R-32 have slightly HIGHER pressures than R-410A at the same temperature?",options:["Manufacturing error \u2014 they should be identical","R-32 has a different saturation pressure curve than R-410A \u2014 although similar, pure R-32 generates slightly higher pressures because it is an individual component without the 'blending effect' of R-125 in R-410A","Due to molecular size difference","There is no real pressure difference"],explanation:"R-32 is a pure refrigerant with its own unique P-T curve. R-410A is a blend of R-32 and R-125. The addition of R-125 modifies the blend properties. Pure R-32 operates at slightly higher pressures than R-410A at the same saturation temperature."},{id:"a2l_277",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 el R-454B y el R-410A tienen presiones de operaci\xF3n muy similares?",opciones:["Por coincidencia","El R-454B fue dise\xF1ado espec\xEDficamente para tener presiones de operaci\xF3n similares al R-410A, facilitando la transici\xF3n \u2014 los fabricantes pueden dise\xF1ar sistemas R-454B con dimensiones de componentes similares a los sistemas R-410A existentes","Todos los HFCs tienen las mismas presiones","No tienen presiones similares"],respuesta_correcta:1,explicacion:"R-454B fue dise\xF1ado como SUCESOR COMPATIBLE del R-410A. Mantener presiones similares es una decisi\xF3n de dise\xF1o intencional para: (1) facilitar la transici\xF3n para fabricantes que ya dise\xF1an para R-410A, (2) permitir sistemas con componentes de dimensiones similares, (3) minimizar cambios en los procesos de manufactura.",question:"Why do R-454B and R-410A have very similar operating pressures?",options:["By coincidence","R-454B was specifically designed to have operating pressures similar to R-410A, facilitating the transition \u2014 manufacturers can design R-454B systems with component dimensions similar to existing R-410A systems","All HFCs have the same pressures","They don't have similar pressures"],explanation:"R-454B was designed as a COMPATIBLE SUCCESSOR to R-410A. Maintaining similar pressures is an intentional design decision to: (1) facilitate the transition for manufacturers already designing for R-410A, (2) allow systems with similar component dimensions, (3) minimize changes in manufacturing processes."},{id:"a2l_278",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 significa que el R-32 es un 'refrigerante de composici\xF3n constante'?",opciones:["Que nunca cambia de estado","Que es un refrigerante puro de un solo componente \u2014 su composici\xF3n no cambia bajo ninguna circunstancia, incluyendo fugas. No fracciona","Que solo funciona a temperatura constante","Solo aplica a almacenamiento"],respuesta_correcta:1,explicacion:"'Composici\xF3n constante' = refrigerante puro de un solo componente que NO FRACCIONA bajo ninguna condici\xF3n. Si un sistema R-32 pierde refrigerante por fuga, el refrigerante restante en el sistema tiene EXACTAMENTE la misma composici\xF3n que antes. Esto facilita el topped off y el diagn\xF3stico.",question:"What does it mean that R-32 is a 'constant composition' refrigerant?",options:["That it never changes state","That it is a pure single-component refrigerant \u2014 its composition does not change under any circumstances, including leaks. It does not fractionate","That it only works at constant temperature","Only applies to storage"],explanation:"'Constant composition' = pure single-component refrigerant that does NOT FRACTIONATE under any condition. If an R-32 system loses refrigerant through a leak, the remaining refrigerant in the system has EXACTLY the same composition as before. This facilitates topped-off and diagnosis."},{id:"a2l_279",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 implica el 'fractionation' del R-454B en una fuga lenta?",opciones:["No hay implicaciones pr\xE1cticas","En una fuga lenta, el R-32 (m\xE1s vol\xE1til, mayor presi\xF3n de vapor) puede escapar a mayor velocidad que el R-1234yf, cambiando gradualmente la composici\xF3n del refrigerante restante y las propiedades del sistema","Solo afecta al GWP","Solo ocurre en fugas grandes"],respuesta_correcta:1,explicacion:"En fugas lentas de R-454B, el fraccionamiento puede causar que el R-32 (componente m\xE1s vol\xE1til) escape preferencialmente, alterando gradualmente la composici\xF3n de la mezcla restante. Esto cambia la relaci\xF3n P-T, el GWP efectivo, y puede afectar el desempe\xF1o del sistema. Por esto, las fugas de R-454B deben repararse y el sistema recargarse completamente.",question:"What does 'fractionation' of R-454B imply in a slow leak?",options:["No practical implications","In a slow leak, the more volatile R-32 (higher vapor pressure) can escape at a faster rate than R-1234yf, gradually changing the composition of the remaining refrigerant and system properties","Only affects GWP","Only occurs in large leaks"],explanation:"In slow R-454B leaks, fractionation can cause R-32 (the more volatile component) to escape preferentially, gradually altering the remaining blend composition. This changes the P-T relationship, effective GWP, and can affect system performance. This is why R-454B leaks must be repaired and the system fully recharged."},{id:"a2l_280",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es el significado de 'HFC/HFO blend' en el nombre de R-454B?",opciones:["Solo una descripci\xF3n t\xE9cnica sin significado pr\xE1ctico","Indica que la mezcla contiene tanto un componente HFC (R-32) como un componente HFO (R-1234yf) \u2014 esta combinaci\xF3n permite lograr bajo GWP (del HFO) con propiedades operativas manejables (del HF","C) Solo aplica a sistemas automotrices","Significa que tiene dos aceites diferentes"],respuesta_correcta:2,explicacion:"HFC/HFO blend indica que R-454B combina: R-32 (HFC) + R-1234yf (HFO). El HFC (R-32) aporta presiones y caracter\xEDsticas operativas conocidas y manejables. El HFO (R-1234yf) aporta el GWP muy bajo. La mezcla logra: presiones similares a R-410A, GWP=466, y clasificaci\xF3n A2L.",question:"What is the meaning of 'HFC/HFO blend' in the name R-454B?",options:["Only a technical description with no practical meaning","Indicates the blend contains both an HFC component (R-32) and an HFO component (R-1234yf) \u2014 this combination achieves low GWP (from HFO) with manageable operating properties (from HFC)","Only applies to automotive systems","Means it has two different oils"],explanation:"HFC/HFO blend indicates that R-454B combines: R-32 (HFC) + R-1234yf (HFO). The HFC (R-32) provides known and manageable operating pressures and characteristics. The HFO (R-1234yf) provides very low GWP. The blend achieves: pressures similar to R-410A, GWP=466, and A2L classification."},{id:"a2l_281",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 algunos t\xE9cnicos describen al R-32 como 'medio componente' del R-410A?",opciones:["Por error \u2014 R-32 no tiene relaci\xF3n con R-410A","R-410A es una mezcla de R-32 (50%) + R-125 (50%). El R-32 es literalmente UNO DE LOS DOS COMPONENTES del R-410A \u2014 la diferencia es que el R-410A tiene R-125 adicional que modifica sus propiedades","El R-32 solo se usa como componente","Solo es una descripci\xF3n informal sin base t\xE9cnica"],respuesta_correcta:1,explicacion:"R-410A = R-32 (50%) + R-125 (50%). El R-32 es literalmente la mitad del R-410A. Al eliminar el R-125 (que tiene GWP=3,500), el R-32 solo tiene GWP=675 vs R-410A GWP=2,088. Esta relaci\xF3n explica por qu\xE9 el R-32 tiene presiones similares al R-410A pero es A2L porque sin el R-125 la mezcla es levemente inflamable.",question:"Why do some technicians describe R-32 as 'half the component' of R-410A?",options:["By error \u2014 R-32 has no relation to R-410A","R-410A is a blend of R-32 (50%) + R-125 (50%). R-32 is literally ONE OF THE TWO COMPONENTS of R-410A \u2014 the difference is that R-410A has additional R-125 that modifies its properties","R-32 is only used as a component","Only an informal description without technical basis"],explanation:"R-410A = R-32 (50%) + R-125 (50%). R-32 is literally half of R-410A. By eliminating R-125 (which has GWP=3,500), R-32 alone has GWP=675 vs R-410A GWP=2,088. This relationship explains why R-32 has pressures similar to R-410A but is A2L because without R-125 the blend is mildly flammable."},{id:"a2l_282",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 el R-125 se a\xF1adi\xF3 al R-32 para crear el R-410A originalmente?",opciones:["Para mejorar el GWP","Para hacer la mezcla no inflamable (A1) \u2014 el R-32 solo es A2L, pero la adici\xF3n de R-125 en proporci\xF3n adecuada crea una mezcla A1. El precio pagado fue un GWP m\xE1s alto","Para reducir el costo","Para aumentar la capacidad de enfriamiento"],respuesta_correcta:1,explicacion:"El R-125 (no inflamable, A1) se a\xF1adi\xF3 al R-32 (levemente inflamable, A2L) para crear R-410A A1 (no inflamable). Esto fue importante cuando los A2L no estaban bien aceptados por la industria. El costo fue aumentar el GWP (R-125 tiene GWP=3,500, mucho mayor que R-32=675).",question:"Why was R-125 added to R-32 to create R-410A originally?",options:["To improve GWP","To make the blend non-flammable (A1) \u2014 R-32 alone is A2L, but adding R-125 in the right proportion creates an A1 blend. The price paid was higher GWP","To reduce cost","To increase cooling capacity"],explanation:"R-125 (non-flammable, A1) was added to R-32 (mildly flammable, A2L) to create R-410A A1 (non-flammable). This was important when A2L refrigerants were not well accepted by the industry. The cost was increasing GWP (R-125 has GWP=3,500, much higher than R-32=675)."},{id:"a2l_283",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es el principal uso del R-1234yf en la actualidad?",opciones:["Reemplazar R-410A en sistemas residenciales","A/C automotriz \u2014 reemplaza el R-134a (GWP=1,430) con GWP<1, cumpliendo regulaciones europeas y norteamericanas de bajas emisiones de GHG para veh\xEDculos nuevos","Solo como componente de mezclas","Solo en aplicaciones industriales"],respuesta_correcta:1,explicacion:"R-1234yf es el refrigerante DOMINANTE en A/C automotriz nuevo, reemplazando al R-134a. Con GWP<1 cumple las regulaciones de la UE (Mac Directive 2006/40/EC) y norteamericanas que requieren GWP<150 para sistemas de A/C de veh\xEDculos nuevos.",question:"What is the primary use of R-1234yf currently?",options:["To replace R-410A in residential systems","Automotive A/C \u2014 replaces R-134a (GWP=1,430) with GWP<1, meeting European and North American low-GHG emission regulations for new vehicles","Only as a blend component","Only in industrial applications"],explanation:"R-1234yf is the DOMINANT refrigerant in new automotive A/C, replacing R-134a. With GWP<1 it meets EU regulations (MAC Directive 2006/40/EC) and North American regulations requiring GWP<150 for new vehicle A/C systems."},{id:"a2l_284",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 la R-1234yf es muy dif\xEDcil de encender a pesar de ser A2L?",opciones:["No es dif\xEDcil de encender \u2014 es el m\xE1s peligroso de los A2L","Su MIE extremadamente alto (5,000-10,000 mJ) lo hace el m\xE1s dif\xEDcil de encender entre los A2L. Para comparar, el propano tiene MIE=0.25 mJ y una buj\xEDa produce 20-30 mJ \u2014 muy por debajo del umbral del R-1234yf","Su LFL alto lo hace seguro","Solo por el color del cilindro"],respuesta_correcta:1,explicacion:"R-1234yf tiene MIE=5,000-10,000 mJ \u2014 extraordinariamente dif\xEDcil de encender. Una buj\xEDa de alto voltaje produce solo 20-30 mJ. Esto significa que pr\xE1cticamente ning\xFAn dispositivo el\xE9ctrico dom\xE9stico normal puede encender R-1234yf, haci\xE9ndolo muy seguro en la pr\xE1ctica a pesar de su clasificaci\xF3n t\xE9cnica A2L.",question:"Why is R-1234yf very difficult to ignite despite being A2L?",options:["It is not hard to ignite \u2014 it is the most dangerous A2L","Its extremely high MIE (5,000-10,000 mJ) makes it the most difficult to ignite among A2L. For comparison, propane has MIE=0.25 mJ and a spark plug produces 20-30 mJ \u2014 well below the R-1234yf threshold","Its high LFL makes it safe","Only because of the cylinder color"],explanation:"R-1234yf has MIE=5,000-10,000 mJ \u2014 extraordinarily difficult to ignite. A high-voltage spark plug produces only 20-30 mJ. This means practically no normal domestic electrical device can ignite R-1234yf, making it very safe in practice despite its technical A2L classification."},{id:"a2l_285",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es el impacto del R-466A en la transici\xF3n a bajos GWP comparado con R-454B?",opciones:["R-466A siempre es mejor que R-454B","R-466A ofrece GWP=733 con clasificaci\xF3n A1 (no inflamable) \u2014 ventaja: sin complejidades de seguridad A2L. Desventaja: GWP mayor que R-454B (466). La elecci\xF3n depende de si el instalador prefiere eliminar complejidades A2L vs lograr el GWP m\xE1s bajo posible","R-454B es siempre mejor","No hay diferencia pr\xE1ctica entre ellos"],respuesta_correcta:1,explicacion:"R-466A vs R-454B es un balance entre seguridad y GWP: R-466A (GWP=733, A1 \u2014 no inflamable) elimina las complejidades de seguridad A2L pero tiene GWP m\xE1s alto. R-454B (GWP=466, A2L) logra mayor reducci\xF3n de GWP pero requiere todas las precauciones de seguridad A2L. La elecci\xF3n depende de los requisitos del cliente y del instalador.",question:"What is the impact of R-466A on the low-GWP transition compared to R-454B?",options:["R-466A is always better than R-454B","R-466A offers GWP=733 with A1 classification (non-flammable) \u2014 advantage: no A2L safety complexities. Disadvantage: higher GWP than R-454B (466). Choice depends on whether the installer prefers eliminating A2L complexities vs achieving the lowest possible GWP","R-454B is always better","No practical difference between them"],explanation:"R-466A vs R-454B is a balance between safety and GWP: R-466A (GWP=733, A1 \u2014 non-flammable) eliminates A2L safety complexities but has higher GWP. R-454B (GWP=466, A2L) achieves greater GWP reduction but requires all A2L safety precautions. The choice depends on the client's and installer's requirements."},{id:"a2l_286",categoria:"A2L_AVANZADO",pregunta:"\xBFPor qu\xE9 la industria HVAC est\xE1 en transici\xF3n hacia refrigerantes A2L si los A1 son m\xE1s seguros?",opciones:["Por capricho del mercado","Los A1 disponibles (R-410A, R-404A) tienen GWP muy alto. Los nuevos A2L ofrecen reducci\xF3n significativa de GWP mientras mantienen eficiencia operativa similar \u2014 el beneficio ambiental justifica las precauciones de seguridad adicionales","Los A2L son m\xE1s baratos","Solo por regulaci\xF3n sin raz\xF3n t\xE9cnica"],respuesta_correcta:1,explicacion:"La transici\xF3n a A2L es impulsada por regulaciones ambientales (Montreal Protocol Kigali Amendment, EPA SNAP) que requieren reducir GWP de refrigerantes. Los nuevos A2L (R-32, R-454B) ofrecen reducci\xF3n de GWP del 68-78% vs R-410A mientras mantienen eficiencia similar. El impacto ambiental reducido justifica las precauciones adicionales de seguridad.",question:"Why is the HVAC industry transitioning to A2L refrigerants if A1s are safer?",options:["Market whim","Available A1s (R-410A, R-404A) have very high GWP. New A2L offer significant GWP reduction while maintaining similar operational efficiency \u2014 the environmental benefit justifies the additional safety precautions","A2L are cheaper","Only regulation with no technical reason"],explanation:"The transition to A2L is driven by environmental regulations (Montreal Protocol Kigali Amendment, EPA SNAP) requiring reduced refrigerant GWP. New A2L refrigerants (R-32, R-454B) offer 68-78% GWP reduction vs R-410A while maintaining similar efficiency. The reduced environmental impact justifies additional safety precautions."},{id:"a2l_287",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1ndo se espera que la mayor\xEDa de fabricantes de equipos residenciales en USA hayan completado la transici\xF3n a A2L?",opciones:["Ya completaron en 2020","2025-2026 es el per\xEDodo principal de transici\xF3n \u2014 los equipos de mayor eficiencia (SEER2 m\xEDnimo) aprobados por la EPA ya son principalmente A2L","No hay fecha espec\xEDfica \u2014 es voluntario","2030 o despu\xE9s"],respuesta_correcta:1,explicacion:"La transici\xF3n principal a A2L en residencial USA ocurre en 2025-2026. Los nuevos requisitos de eficiencia (SEER2) combinados con las aprobaciones de EPA SNAP 23 impulsaron a los principales fabricantes a lanzar sus l\xEDneas A2L (principalmente R-454B) para cumplir simult\xE1neamente con eficiencia y GWP reducido.",question:"When is the majority of residential equipment manufacturers in the USA expected to complete the transition to A2L?",options:["Already completed in 2020","2025-2026 is the primary transition period \u2014 the higher efficiency equipment (minimum SEER2) approved by EPA are primarily A2L","No specific date \u2014 it is voluntary","2030 or later"],explanation:"The main A2L transition in US residential occurs in 2025-2026. New efficiency requirements (SEER2) combined with EPA SNAP 23 approvals drove major manufacturers to launch their A2L lines (primarily R-454B) to simultaneously meet efficiency and reduced GWP requirements."},{id:"a2l_288",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 implica para los t\xE9cnicos en servicio el per\xEDodo de transici\xF3n A2L cuando hay tanto R-410A como R-454B en el mercado?",opciones:["No hay implicaciones \u2014 los sistemas son intercambiables","Los t\xE9cnicos deben: (1) verificar SIEMPRE el refrigerante en la placa de datos, (2) tener equipo compatible con ambos refrigerantes, (3) nunca mezclar R-410A y R-454B, (4) conocer los procedimientos A2L adicionales para sistemas R-454B","Solo se necesita un manifold diferente","Solo necesitan nueva capacitaci\xF3n una vez"],respuesta_correcta:1,explicacion:"Durante la transici\xF3n, los t\xE9cnicos pueden encontrar AMBOS refrigerantes en el campo. Esto requiere: (1) verificar SIEMPRE la placa de datos antes de comenzar, (2) tener herramientas compatibles con A2L, (3) nunca mezclar refrigerantes, (4) aplicar procedimientos A2L adicionales cuando corresponda, y (5) mantener cilindros de recuperaci\xF3n separados.",question:"What does the A2L transition period mean for service technicians when both R-410A and R-454B are on the market?",options:["No implications \u2014 systems are interchangeable","Technicians must: (1) ALWAYS verify refrigerant on the data plate, (2) have equipment compatible with both refrigerants, (3) never mix R-410A and R-454B, (4) know the additional A2L procedures for R-454B systems","Only need a different manifold","Only need new training once"],explanation:"During the transition, technicians may encounter BOTH refrigerants in the field. This requires: (1) ALWAYS verify the data plate before starting, (2) have A2L-compatible tools, (3) never mix refrigerants, (4) apply additional A2L procedures when applicable, and (5) maintain separate recovery cylinders."},{id:"a2l_289",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la diferencia en precio t\xEDpica entre el R-454B y el R-410A y por qu\xE9?",opciones:["Son exactamente del mismo precio","R-454B generalmente cuesta m\xE1s que R-410A \u2014 contiene R-1234yf (HFO) que es m\xE1s costoso de producir que los HFC tradicionales. Los costos deben bajar con mayor escala de producci\xF3n","El R-454B siempre es m\xE1s barato","El costo no importa para el t\xE9cnico"],respuesta_correcta:1,explicacion:"R-454B t\xEDpicamente cuesta m\xE1s que R-410A porque contiene R-1234yf (HFO), cuya s\xEDntesis es m\xE1s compleja y costosa que los HFC tradicionales. Con la mayor escala de producci\xF3n y la reducci\xF3n del R-410A, se espera que los precios de los A2L se normalicen con el tiempo.",question:"What is the typical price difference between R-454B and R-410A and why?",options:["They are exactly the same price","R-454B generally costs more than R-410A \u2014 it contains R-1234yf (HFO) which is more expensive to produce than traditional HFCs. Costs should decrease with greater production scale","R-454B is always cheaper","Cost doesn't matter to the technician"],explanation:"R-454B typically costs more than R-410A because it contains R-1234yf (HFO), whose synthesis is more complex and costly than traditional HFCs. With greater production scale and reduction of R-410A, A2L prices are expected to normalize over time."},{id:"a2l_290",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 habilidades adicionales necesita un t\xE9cnico para estar preparado para la era A2L?",opciones:["Solo aprender el nombre de los nuevos refrigerantes","Capacitaci\xF3n en seguridad A2L (label matching, nitrogen sweep, herramientas spark-free, nitrogen decay test), manejo de tablas P/T de nuevos refrigerantes, familiarizaci\xF3n con sensores activos, y actualizaci\xF3n en c\xF3digos ASHRAE 15/15.2","Solo una certificaci\xF3n adicional","No se necesitan habilidades nuevas"],respuesta_correcta:1,explicacion:"Para la era A2L los t\xE9cnicos necesitan: (1) capacitaci\xF3n en seguridad espec\xEDfica A2L, (2) conocer las tablas P/T de R-32, R-454B, R-452B, (3) procedimientos de instalaci\xF3n adicionales (label matching, prueba de presi\xF3n 60 min, nitrogen sweep, decay test), (4) conocer y cumplir ASHRAE 15.2, y (5) familiarizarse con sensores activos y requisitos de documentaci\xF3n UL.",question:"What additional skills does a technician need to be prepared for the A2L era?",options:["Only learn the names of new refrigerants","A2L safety training (label matching, nitrogen sweep, spark-free tools, nitrogen decay test), handling P/T charts for new refrigerants, familiarization with active sensors, and updates on ASHRAE 15/15.2 codes","Only one additional certification","No new skills needed"],explanation:"For the A2L era, technicians need: (1) specific A2L safety training, (2) knowledge of P/T charts for R-32, R-454B, R-452B, (3) additional installation procedures (label matching, 60-min pressure test, nitrogen sweep, decay test), (4) knowledge of and compliance with ASHRAE 15.2, and (5) familiarity with active sensors and UL documentation requirements."},{id:"a2l_291",categoria:"A2L_AVANZADO",pregunta:"Un t\xE9cnico de otro estado llega a dar servicio a un equipo R-454B nuevo. Al abrir el manifold dice que las presiones son iguales que el R-410A as\xED que no necesita la tabla P/T de R-454B. \xBFEst\xE1 en lo correcto?",opciones:["S\xED \u2014 son casi id\xE9nticas as\xED que es correcto","No \u2014 aunque las presiones son similares, existen diferencias importantes especialmente en las columnas Liquid/Vapor del R-454B (mezcla zeotr\xF3pica). Siempre usar la tabla P/T correcta para el refrigerante espec\xEDfico","S\xED pero solo para diagn\xF3stico b\xE1sico","No importa la tabla \u2014 las presiones hablan solas"],respuesta_correcta:1,explicacion:"INCORRECTO. Aunque R-454B tiene presiones similares a R-410A, existen diferencias: (1) R-454B es zeotr\xF3pico con dos columnas (Liquid/Vapor), (2) los valores espec\xEDficos difieren, (3) usar la tabla incorrecta lleva a c\xE1lculos de superheat y subcooling err\xF3neos y posiblemente a carga incorrecta del sistema.",question:"A technician from another state arrives to service a new R-454B unit. When opening the manifold, he says the pressures are the same as R-410A so he doesn't need the R-454B P/T chart. Is he correct?",options:["Yes \u2014 they are nearly identical so it is correct","No \u2014 although pressures are similar, important differences exist especially in the Liquid/Vapor columns of R-454B (zeotropic blend). Always use the correct P/T chart for the specific refrigerant","Yes but only for basic diagnosis","The chart doesn't matter \u2014 pressures speak for themselves"],explanation:"INCORRECT. Although R-454B has pressures similar to R-410A, differences exist: (1) R-454B is zeotropic with two columns (Liquid/Vapor), (2) the specific values differ, (3) using the wrong chart leads to incorrect superheat and subcooling calculations and possibly incorrect system charging."},{id:"a2l_292",categoria:"A2L_AVANZADO",pregunta:"Al revisar un minisplit nuevo R-32, el t\xE9cnico nota que el sistema enfr\xEDa pero la unidad interior chorrea agua excesivamente. \xBFCu\xE1l es la causa m\xE1s probable?",opciones:["El sistema necesita m\xE1s refrigerante","El drenaje del condensado est\xE1 obstruido o incorrecto \u2014 el agua que el evaporador extrae de la humedad del aire no puede drenar y desborda","El compresor est\xE1 fallando","El sistema tiene exceso de refrigerante"],respuesta_correcta:1,explicacion:"El desbordamiento de agua de la unidad interior casi siempre es un PROBLEMA DE DRENAJE: l\xEDnea de drenaje obstruida (algas, suciedad), pendiente incorrecta del drenaje, o bandeja de condensado llena. El sistema puede estar extrayendo la cantidad correcta de humedad pero el agua no puede salir.",question:"When checking a new R-32 minisplit, the technician notices the indoor unit leaks water excessively. What is the most likely cause?",options:["The system needs more refrigerant","The condensate drain is obstructed or incorrect \u2014 the water the evaporator extracts from air humidity cannot drain and overflows","The compressor is failing","The system has excess refrigerant"],explanation:"Water overflow from the indoor unit is almost always a DRAINAGE PROBLEM: clogged drain line (algae, dirt), incorrect drain slope, or full condensate pan. The system may be extracting the correct amount of moisture but the water cannot exit."},{id:"a2l_293",categoria:"A2L_AVANZADO",pregunta:"Un instalador joven conecta R-454B nuevo a un sistema que anteriormente ten\xEDa R-410A sin cambiar el aceite. \xBFQu\xE9 problema puede surgir?",opciones:["Ninguno \u2014 los aceites son compatibles","El aceite POE en el sistema puede estar contaminado con residuos de operaciones previas. M\xE1s importante: si el sistema anterior usaba aceite mineral (en caso de retrofit desde R-22), eso es incompatible con el R-454B","Solo reduce la eficiencia","Solo afecta la garant\xEDa"],respuesta_correcta:1,explicacion:"Si el sistema anterior tambi\xE9n ten\xEDa R-410A (y por tanto POE), la contaminaci\xF3n cruzada del aceite POE generalmente es aceptable. PERO si hubo alg\xFAn sistema anterior con aceite mineral y no se limpi\xF3 completamente, el aceite mineral residual ser\xE1 incompatible con el R-454B/POE. Siempre verificar el historial del sistema.",question:"A young installer connects new R-454B to a system that previously had R-410A without changing the oil. What problem could arise?",options:["None \u2014 oils are compatible","The POE oil in the system may be contaminated with residue from previous operations. More importantly: if the previous system used mineral oil (in case of retrofit from R-22), that is incompatible with R-454B","Only reduces efficiency","Only affects the warranty"],explanation:"If the previous system also had R-410A (and therefore POE), cross-contamination of POE oil is generally acceptable. BUT if there was a previous system with mineral oil that wasn't completely cleaned, the residual mineral oil will be incompatible with R-454B/POE. Always verify the system history."},{id:"a2l_294",categoria:"A2L_AVANZADO",pregunta:"Un t\xE9cnico recibe una llamada de emergencia: el cliente reporta que el sistema de A/C hizo un 'pop' fuerte y dej\xF3 de funcionar. Al llegar, el t\xE9cnico huele algo inusual. \xBFCu\xE1l es el protocolo?",opciones:["Conectar el manifold inmediatamente para revisar presiones","NO entrar hasta verificar con detector de gases que el \xE1rea es segura. Si es un sistema A2L y hay fuga, hay riesgo de ignici\xF3n. Ventilar el \xE1rea, verificar con detector, asegurar que no hay fuentes de ignici\xF3n antes de entrar a dar servicio","Solo abrir ventanas y entrar","Llamar a los bomberos inmediatamente sin verificar"],respuesta_correcta:1,explicacion:"Protocolo correcto: (1) NO entrar hasta verificar con detector, (2) si hay olor inusual y es sistema A2L, sospechar fuga, (3) ventilar el \xE1rea desde el exterior si es posible, (4) verificar con detector de gases antes de entrar, (5) eliminar fuentes de ignici\xF3n, (6) solo entonces proceder a diagnosticar. El 'pop' puede indicar ruptura de componente con liberaci\xF3n de refrigerante.",question:"A technician receives an emergency call: the customer reports the A/C system made a loud 'pop' and stopped working. Upon arrival, the technician smells something unusual. What is the protocol?",options:["Connect the manifold immediately to check pressures","DO NOT enter until verifying with gas detector that the area is safe. If it is an A2L system and there is a leak, there is ignition risk. Ventilate the area, verify with detector, ensure no ignition sources before entering","Only open windows and enter","Call the fire department immediately without checking"],explanation:"Correct protocol: (1) DO NOT enter until verified with detector, (2) if there is an unusual smell and it's an A2L system, suspect a leak, (3) ventilate the area from outside if possible, (4) verify with gas detector before entering, (5) eliminate ignition sources, (6) only then proceed to diagnose. The 'pop' may indicate component rupture with refrigerant release."},{id:"a2l_295",categoria:"A2L_AVANZADO",pregunta:"Un t\xE9cnico tiene que hacer una reparaci\xF3n de soldadura en un sistema R-32 que est\xE1 instalado en un peque\xF1o cuarto de servidores con poca ventilaci\xF3n. \xBFCu\xE1les son las consideraciones de seguridad especiales?",opciones:["Ninguna especial \u2014 soldar es soldar","ANTES de soldar: (1) recuperar el R-32, (2) nitrogen sweep completo, (3) verificar con detector que no hay vapores, (4) establecer ventilaci\xF3n mec\xE1nica adicional para el trabajo con soplete, (5) tener extinguidor disponible, (6) minimizar el tiempo de trabajo en el espacio confinado","Solo abrir la puerta del cuarto","Solo apagar el R-32 y soldar normalmente"],respuesta_correcta:1,explicacion:"Cuarto peque\xF1o + R-32 + soldadura = riesgo alto. Protocolo: (1) recuperar R-32 completamente, (2) nitrogen sweep, (3) verificar con detector que no hay vapores residuales, (4) establecer ventilaci\xF3n mec\xE1nica para durante el trabajo con soplete (el soplete consume ox\xEDgeno y puede liberar gases de combusti\xF3n), (5) extinguidor a mano, (6) trabajar r\xE1pido y verificar el \xE1rea frecuentemente.",question:"A technician must perform a brazing repair on an R-32 system installed in a small server room with poor ventilation. What are the special safety considerations?",options:["None special \u2014 brazing is brazing","BEFORE brazing: (1) recover the R-32, (2) complete nitrogen sweep, (3) verify with detector that no vapors remain, (4) establish additional mechanical ventilation for torch work, (5) have extinguisher available, (6) minimize working time in the confined space","Only open the room door","Only turn off the R-32 and braze normally"],explanation:"Small room + R-32 + brazing = high risk. Protocol: (1) completely recover R-32, (2) nitrogen sweep, (3) verify with detector that no residual vapors remain, (4) establish mechanical ventilation for during torch work (the torch consumes oxygen and can release combustion gases), (5) extinguisher at hand, (6) work quickly and frequently check the area."},{id:"a2l_296",categoria:"A2L_AVANZADO",pregunta:"Un propietario pregunta si puede instalar m\xE1s refrigerante R-454B del que especifica el fabricante para mejorar el enfriamiento. \xBFCu\xE1l es la respuesta correcta?",opciones:["S\xED \u2014 m\xE1s refrigerante siempre mejora el enfriamiento","NO. La carga m\xE1xima est\xE1 determinada por el dispersal volume del espacio y los l\xEDmites de seguridad A2L. Exceder la carga del fabricante puede: violar los l\xEDmites de seguridad, reducir la eficiencia, y anular la garant\xEDa","Depende del espacio disponible","Solo est\xE1 limitado por el tama\xF1o del sistema"],respuesta_correcta:1,explicacion:"NO. La carga de R-454B est\xE1 determinada por: (1) las especificaciones del fabricante (que ya optimizaron la carga para m\xE1xima eficiencia), (2) el dispersal volume del espacio (l\xEDmite de seguridad A2L), y (3) los l\xEDmites m1/m2 de los c\xF3digos de instalaci\xF3n. Exceder la carga NO mejora el enfriamiento \u2014 reduce la eficiencia y puede crear condiciones inseguras.",question:"A property owner asks if more R-454B can be installed than the manufacturer specifies to improve cooling. What is the correct answer?",options:["Yes \u2014 more refrigerant always improves cooling","NO. The maximum charge is determined by the dispersal volume of the space and A2L safety limits. Exceeding the manufacturer's charge can: violate safety limits, reduce efficiency, and void the warranty","Depends on available space","Only limited by system size"],explanation:"NO. R-454B charge is determined by: (1) manufacturer specifications (which already optimized the charge for maximum efficiency), (2) the space's dispersal volume (A2L safety limit), and (3) m1/m2 limits from installation codes. Exceeding the charge does NOT improve cooling \u2014 it reduces efficiency and can create unsafe conditions."},{id:"a2l_297",categoria:"A2L_AVANZADO",pregunta:"\xBFQu\xE9 debe hacer un t\xE9cnico que descubre que se us\xF3 el aceite incorrecto (mineral en lugar de POE) en un sistema R-32 nuevo?",opciones:["Nada \u2014 el sistema funcionar\xE1 igual","Recuperar el R-32 en cilindro separado, drenar el aceite mineral incorrecto, hacer nitrogen sweep, instalar nuevos filtros-drier, a\xF1adir la cantidad correcta de POE especificada por el fabricante, recargar con el R-32 recuperado si est\xE1 en buen estado","Solo a\xF1adir POE encima del aceite mineral","Solo cambiar el filtro-drier"],respuesta_correcta:1,explicacion:"Procedimiento obligatorio cuando hay aceite incorrecto: (1) recuperar el R-32 en cilindro separado para reutilizar si no est\xE1 contaminado, (2) drenar el aceite mineral incorrecto completamente, (3) nitrogen sweep para limpiar residuos, (4) instalar nuevos filtros-drier, (5) a\xF1adir la cantidad exacta de POE especificado por el fabricante, (6) recargar con el R-32 recuperado.",question:"What should a technician do upon discovering that the wrong oil (mineral instead of POE) was used in a new R-32 system?",options:["Nothing \u2014 the system will work the same","Recover the R-32 in a separate cylinder, drain the incorrect mineral oil, nitrogen sweep, install new filter-driers, add the correct amount of POE specified by the manufacturer, recharge with the recovered R-32 if in good condition","Only add POE on top of the mineral oil","Only change the filter-drier"],explanation:"Mandatory procedure with wrong oil: (1) recover R-32 in a separate cylinder for reuse if not contaminated, (2) completely drain the incorrect mineral oil, (3) nitrogen sweep to clean residue, (4) install new filter-driers, (5) add exact amount of POE specified by manufacturer, (6) recharge with recovered R-32."},{id:"a2l_298",categoria:"A2L_AVANZADO",pregunta:"Durante una instalaci\xF3n de sistema R-454B, el t\xE9cnico nota que uno de los componentes (el filtro-drier) tiene etiqueta que dice 'Compatible with HFCs including R-410A' pero NO menciona A2L ni R-454B. \xBFPuede instalarse?",opciones:["S\xED \u2014 todos los HFCs son iguales para el drier","NO \u2014 label matching requiere que CADA componente est\xE9 espec\xEDficamente certificado para A2L. Un drier certificado solo para R-410A/HFCs A1 puede no tener los materiales internos correctos para A2L. La instalaci\xF3n NO puede proceder","S\xED si es del mismo fabricante","Solo si es de alta calidad"],respuesta_correcta:1,explicacion:"NO PUEDE INSTALARSE. El principio de label matching es ABSOLUTO: cada componente debe estar certificado espec\xEDficamente para A2L y para el refrigerante espec\xEDfico. Un drier certificado para R-410A puede no tener materiales compatibles con R-454B o no estar dise\xF1ado para ambiente inflamable. Reemplazar con drier certificado A2L.",question:"During an R-454B system installation, the technician notices one component (the filter-drier) has a label saying 'Compatible with HFCs including R-410A' but does NOT mention A2L or R-454B. Can it be installed?",options:["Yes \u2014 all HFCs are the same for the drier","NO \u2014 label matching requires that EACH component be specifically certified for A2L. A drier certified only for R-410A/A1 HFCs may not have the correct internal materials for A2L. Installation CANNOT proceed","Yes if from the same manufacturer","Only if it is high quality"],explanation:"CANNOT BE INSTALLED. The label matching principle is ABSOLUTE: each component must be specifically certified for A2L and for the specific refrigerant. A drier certified for R-410A may not have materials compatible with R-454B or may not be designed for a flammable environment. Replace with an A2L-certified drier."},{id:"a2l_299",categoria:"A2L_AVANZADO",pregunta:"Un cliente llama diciendo que su sistema R-32 nuevo tiene un olor extra\xF1o que sali\xF3 de una vez y ya no se repite. \xBFCu\xE1l es la respuesta correcta del t\xE9cnico?",opciones:["Decirle que es normal \u2014 los sistemas nuevos tienen olores","Investigar la situaci\xF3n: verificar si hubo fuga de R-32 (el R-32 tiene ligero olor perceptible en altas concentraciones), verificar que el sistema est\xE1 funcionando correctamente y que no hay fuga activa. Si hubo fuga, verificar que el \xE1rea fue bien ventilada y que no hay fuentes de ignici\xF3n","Solo decirle que ya pas\xF3","Solo cambiar el filtro de aire"],respuesta_correcta:1,explicacion:"Un olor inusual en sistema con A2L debe tomarse en serio: (1) puede haber habido una fuga de R-32 (perceptible en altas concentraciones), (2) verificar el sistema para confirmar operaci\xF3n correcta y ausencia de fuga activa, (3) verificar que el \xE1rea fue bien ventilada, (4) documentar el incidente. Si hay fuga activa, seguir el protocolo de evacuaci\xF3n/ventilaci\xF3n.",question:"A customer calls saying their new R-32 system had a strange odor that came once and did not repeat. What is the correct technician response?",options:["Tell the customer not to worry \u2014 it's nothing","GO IMMEDIATELY to inspect: a single odor event from an R-32 system could indicate a minor refrigerant leak that briefly contacted a hot surface (producing hydrogen fluoride). Verify system integrity, check for leaks, and ensure safety","Wait to see if it happens again","Only tell them to open windows"],explanation:"GO IMMEDIATELY to inspect: a single odor event from an R-32 system could indicate a minor refrigerant leak that briefly contacted a hot surface (forming hydrogen fluoride). Verify system integrity, perform a complete leak check, and ensure safety before leaving."},{id:"a2l_300",categoria:"A2L_AVANZADO",pregunta:"\xBFCu\xE1l es la responsabilidad del t\xE9cnico si instala un sistema A2L sin seguir el procedimiento de label matching y posteriormente hay un incidente de ignici\xF3n?",opciones:["Ninguna \u2014 es responsabilidad del fabricante","El t\xE9cnico tiene responsabilidad legal significativa \u2014 no seguir los procedimientos de instalaci\xF3n requeridos (label matching, c\xF3digos de instalaci\xF3n) puede resultar en: responsabilidad civil por da\xF1os, p\xE9rdida de licencia, y potencialmente procesamiento criminal si hay lesiones","Solo pierde la garant\xEDa del fabricante","Solo si firm\xF3 algo espec\xEDfico"],respuesta_correcta:1,explicacion:"El t\xE9cnico que instala sin seguir los procedimientos requeridos (label matching, c\xF3digos ASHRAE, UL, etc.) asume responsabilidad legal significativa en caso de incidente. Esto incluye: responsabilidad civil por da\xF1os a propiedad y personas, posible p\xE9rdida de licencia/certificaci\xF3n, y en casos de negligencia grave con lesiones, potencial responsabilidad criminal.ARRAY JAVASCRIPT \u2014 PEGA EN questions.js (ESTUDIO A2L)export const A2L_STUDY_QUESTIONS = [ // Nivel 1 (n:1-100), Nivel 2 (n:101-200), Nivel 3 (n:201-300) // categorias: A2L_N1, A2L_N2, A2L_N3 { id:&quot;a2l_study_1&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 significa la 'L' en la clasificaci\xF3n A2L de ASHRAE?&quot;, opciones:[&quot;Liquid (l\xEDquido)&quot;,&quot;Lower flammability (inflamabilidad menor) \u2014 velocidad de llama \u226410 cm/s&quot;,&quot;Large (grande)&quot;,&quot;Low pressure (baja presi\xF3n)&quot;], respuesta_correcta:1, explicacion:&quot;La 'L' en A2L indica Lower flammability \u2014 inflamabilidad menor con velocidad de llama de 10 cm/s o menos. Diferente a A2 que tiene velocidad de llama entre 10-46 cm/s.&quot; }, { id:&quot;a2l_study_2&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-22?&quot;, opciones:[&quot;A2L&quot;,&quot;A2&quot;,&quot;A1&quot;,&quot;B1&quot;], respuesta_correcta:2, explicacion:&quot;R-22 es A1 \u2014 baja toxicidad y sin inflamabilidad. Por eso fue tan ampliamente usado durante d\xE9cadas. Aunque tiene ODP=0.055 y GWP=1,810.&quot; }, { id:&quot;a2l_study_3&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-290 (propano)?&quot;, opciones:[&quot;A2L&quot;,&quot;A2&quot;,&quot;A1&quot;,&quot;A3&quot;], respuesta_correcta:3, explicacion:&quot;R-290 (propano) es A3 \u2014 altamente inflamable. Velocidad de llama 46 cm/s, MIE de solo 0.25 mJ. Por eso est\xE1 limitado a cargas muy peque\xF1as en equipos herm\xE9ticamente sellados.&quot; }, { id:&quot;a2l_study_4&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-410A?&quot;, opciones:[&quot;A2L&quot;,&quot;A2&quot;,&quot;A1&quot;,&quot;B1&quot;], respuesta_correcta:2, explicacion:&quot;R-410A es A1 \u2014 baja toxicidad, sin inflamabilidad. A pesar de ser A1, tiene GWP=2,088 lo cual lo hace ambientalmente problem\xE1tico aunque seguro desde punto de vista de inflamabilidad.&quot; }, { id:&quot;a2l_study_5&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la clasificaci\xF3n ASHRAE del R-717 (amoniaco)?&quot;, opciones:[&quot;A2L&quot;,&quot;B2L&quot;,&quot;A1&quot;,&quot;B3&quot;], respuesta_correcta:1, explicacion:&quot;R-717 (amoniaco) es B2L \u2014 mayor toxicidad (B) y levemente inflamable (2L). Es altamente eficiente pero su toxicidad limita su uso a instalaciones industriales con personal capacitado.&quot; }, { id:&quot;a2l_study_6&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 indica la letra 'B' en clasificaciones ASHRAE como B1, B2L?&quot;, opciones:[&quot;Baja toxicidad&quot;,&quot;Mayor nivel de toxicidad para humanos&quot;,&quot;Baja presi\xF3n de operaci\xF3n&quot;,&quot;Blends (mezclas)&quot;], respuesta_correcta:1, explicacion:&quot;La letra B en clasificaciones ASHRAE indica MAYOR toxicidad para humanos. A = baja toxicidad. B = mayor toxicidad. Los refrigerantes B requieren m\xE1s precauciones de ventilaci\xF3n y protecci\xF3n personal.&quot; }, { id:&quot;a2l_study_7&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1ntas clases de inflamabilidad existen en el sistema ASHRAE?&quot;, opciones:[&quot;2 clases: 1 y 2&quot;,&quot;3 clases: 1, 2, 3&quot;,&quot;4 clases: 1, 2L, 2, 3&quot;,&quot;5 clases&quot;], respuesta_correcta:2, explicacion:&quot;Existen 4 clases de inflamabilidad ASHRAE: 1 (sin propagaci\xF3n de llama), 2L (levemente inflamable, \u226410 cm/s), 2 (baja inflamabilidad), y 3 (alta inflamabilidad). La 2L fue agregada espec\xEDficamente para los nuevos A2L.&quot; }, { id:&quot;a2l_study_8&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 prueba est\xE1ndar usa ASHRAE para determinar la inflamabilidad de un refrigerante?&quot;, opciones:[&quot;ASTM E-681 modificado por ASHRAE&quot;,&quot;UL 508 est\xE1ndar de equipos&quot;,&quot;NFPA 70 c\xF3digo el\xE9ctrico&quot;,&quot;ISO 9001 calidad&quot;], respuesta_correcta:0, explicacion:&quot;La inflamabilidad de los refrigerantes se determina con la prueba ASTM E-681 modificada por ASHRAE. La llama debe ser continua extendida en arco de 90\xB0 para que el refrigerante sea clasificado como inflamable.&quot; }, { id:&quot;a2l_study_9&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 refrigerante A2L tiene clasificaci\xF3n ASHRAE A1 aunque tenga bajo GWP?&quot;, opciones:[&quot;R-32&quot;,&quot;R-1234yf&quot;,&quot;R-466A&quot;,&quot;R-454B&quot;], respuesta_correcta:2, explicacion:&quot;R-466A es el \xFAnico entre los nuevos refrigerantes de bajo GWP que logra clasificaci\xF3n A1 (no inflamable). GWP=733, significativamente menor que R-410A (2,088) pero sin las complicaciones de seguridad de los A2L.&quot; }, { id:&quot;a2l_study_10&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el n\xFAmero de serie de la norma ASHRAE que asigna clasificaciones de seguridad a refrigerantes?&quot;, opciones:[&quot;ASHRAE 15&quot;,&quot;ASHRAE 34&quot;,&quot;ASHRAE 62.1&quot;,&quot;ASHRAE 90.1&quot;], respuesta_correcta:1, explicacion:&quot;ASHRAE Standard 34 asigna designaciones y clasificaciones de seguridad a todos los refrigerantes (toxicidad e inflamabilidad). Tambi\xE9n establece los Refrigerant Concentration Limits (RCL).&quot; }, { id:&quot;a2l_study_11&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el GWP del R-32?&quot;, opciones:[&quot;2,088&quot;,&quot;1,430&quot;,&quot;675&quot;,&quot;466&quot;], respuesta_correcta:2, explicacion:&quot;R-32 tiene GWP=675. Comparado con R-410A (2,088), es una reducci\xF3n del 68%. R-32 es el principal competidor de R-454B para reemplazar R-410A en sistemas residenciales.&quot; }, { id:&quot;a2l_study_12&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el GWP del R-454B?&quot;, opciones:[&quot;675&quot;,&quot;466&quot;,&quot;2,088&quot;,&quot;733&quot;], respuesta_correcta:1, explicacion:&quot;R-454B tiene GWP=466, la reducci\xF3n m\xE1s dram\xE1tica entre los sucesores del R-410A \u2014 una mejora del 78%. Por eso es el refrigerante aprobado por los principales fabricantes en USA para equipos nuevos desde 2025.&quot; }, { id:&quot;a2l_study_13&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFDe qu\xE9 componentes est\xE1 formado el R-454B?&quot;, opciones:[&quot;R-32 + R-125&quot;,&quot;R-32 + R-1234yf&quot;,&quot;R-32 + R-134a&quot;,&quot;R-125 + R-1234yf&quot;], respuesta_correcta:1, explicacion:&quot;R-454B = R-32 (31.6%) + R-1234yf (68.4%). La combinaci\xF3n de HFC + HFO logra: GWP bajo (466), presiones similares a R-410A, y clasificaci\xF3n A2L.&quot; }, { id:&quot;a2l_study_14&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFDe qu\xE9 componentes est\xE1 formado el R-452B?&quot;, opciones:[&quot;R-32 + R-1234yf (2 componentes)&quot;,&quot;R-32 + R-125 + R-1234yf (3 componentes)&quot;,&quot;R-32 + R-134a + R-125&quot;,&quot;R-410A + R-1234yf&quot;], respuesta_correcta:1, explicacion:&quot;R-452B = R-32 + R-125 + R-1234yf (mezcla ternaria de tres componentes). GWP=676, muy similar al R-32 puro pero con la ventaja de permitir topped off en caso de fugas peque\xF1as.&quot; }, { id:&quot;a2l_study_15&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 es un refrigerante HFO?&quot;, opciones:[&quot;Hydrofluorocarbon \u2014 contiene H, F y C con solo enlaces simples&quot;,&quot;Hydrofluoroolefin \u2014 contiene H, F y C con al menos un doble enlace de carbono&quot;,&quot;Hydrocarbon fluoride \u2014 derivado del propano&quot;,&quot;High Frequency Oil \u2014 aceite especial para A2L&quot;], respuesta_correcta:1, explicacion:&quot;HFO (Hydrofluoroolefin) = contiene H, F y C con al menos un DOBLE ENLACE de carbono. Este doble enlace es lo que les da bajo GWP (se degradan r\xE1pido en la atm\xF3sfera) y tambi\xE9n los hace levemente inflamables.&quot; }, { id:&quot;a2l_study_16&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la diferencia qu\xEDmica entre HFC y HFO?&quot;, opciones:[&quot;Solo el n\xFAmero de \xE1tomos de fl\xFAor&quot;,&quot;Los HFO tienen al menos un doble enlace de carbono (olefin), los HFC solo tienen enlaces simples&quot;,&quot;Los HFC son m\xE1s pesados&quot;,&quot;No hay diferencia qu\xEDmica, solo comercial&quot;], respuesta_correcta:1, explicacion:&quot;HFC = solo enlaces simples entre carbonos (saturado). HFO = al menos un doble enlace de carbono (insaturado/olefin). Esta diferencia estructural hace que los HFO se degraden mucho m\xE1s r\xE1pido en la atm\xF3sfera, resultando en GWP muy bajo.&quot; }, { id:&quot;a2l_study_17&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 refrigerante A2L es el principal usado en A/C automotriz nuevo?&quot;, opciones:[&quot;R-32&quot;,&quot;R-454B&quot;,&quot;R-1234yf&quot;,&quot;R-452B&quot;], respuesta_correcta:2, explicacion:&quot;R-1234yf es el refrigerante A2L usado en A/C automotriz, reemplazando al R-134a (GWP=1,430). R-1234yf tiene GWP<1 y aunque es levemente inflamable (A2L), su MIE extremadamente alto (5,000-10,000 mJ) lo hace muy dif\xEDcil de encender.&quot; }, { id:&quot;a2l_study_18&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la presi\xF3n de succi\xF3n del R-32 a 45\xB0F de temperatura de evaporaci\xF3n?&quot;, opciones:[&quot;68-75 PSI (igual que R-22)&quot;,&quot;118-125 PSI (igual que R-410A)&quot;,&quot;133 PSI (ligeramente mayor que R-410A)&quot;,&quot;50 PSI (menor que R-22)&quot;], respuesta_correcta:2, explicacion:&quot;R-32 a 45\xB0F de saturaci\xF3n: aproximadamente 133 PSI. Es ligeramente MAYOR que R-410A (130 PSI) a la misma temperatura. Las herramientas y manifolds deben estar rated para estas presiones.&quot; }, { id:&quot;a2l_study_19&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la presi\xF3n de alta (descarga) del R-454B a 120\xB0F de temperatura de condensaci\xF3n?&quot;, opciones:[&quot;250-260 PSI (igual que R-22)&quot;,&quot;400-420 PSI (igual que R-410A)&quot;,&quot;~397 PSI (liquid) / ~386 PSI (vapor)&quot;,&quot;500+ PSI&quot;], respuesta_correcta:2, explicacion:&quot;R-454B a 120\xB0F: Liquid pressure ~397 PSI, Vapor pressure ~386 PSI. Muy similar al R-410A, por eso la transici\xF3n no requiere cambios dr\xE1sticos en dise\xF1o de sistemas aunque s\xED componentes certificados A2L.&quot; }, { id:&quot;a2l_study_20&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el aceite lubricante correcto para sistemas con R-32 o R-454B?&quot;, opciones:[&quot;Aceite mineral (MO)&quot;,&quot;Aceite alquilbenceno (AB)&quot;,&quot;Aceite POE (Polyolester)&quot;,&quot;Aceite PAG&quot;], respuesta_correcta:2, explicacion:&quot;Los refrigerantes HFC y HFO (R-32, R-454B, R-452B, R-1234yf) requieren aceite POE (Polyolester). El aceite mineral NO es miscible con HFCs \u2014 se acumula en el evaporador causando problemas de transferencia de calor.&quot; }, { id:&quot;a2l_study_21&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el LFL (Lower Flammability Limit) del R-32?&quot;, opciones:[&quot;6.2%&quot;,&quot;14.4%&quot;,&quot;3.9%&quot;,&quot;2.1%&quot;], respuesta_correcta:1, explicacion:&quot;R-32 tiene LFL=14.4%. Para comparar: propano (A3)=2.1%, R-1234yf=6.2%, amoniaco=15%. El LFL alto del R-32 significa que necesita alta concentraci\xF3n para encenderse, haci\xE9ndolo m\xE1s seguro que los A3.&quot; }, { id:&quot;a2l_study_22&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el LFL del R-454B?&quot;, opciones:[&quot;14.4%&quot;,&quot;11.8%&quot;,&quot;6.2%&quot;,&quot;2.1%&quot;], respuesta_correcta:1, explicacion:&quot;R-454B tiene LFL=11.8%, ligeramente menor que R-32 (14.4%) pero mucho mayor que propano (2.1%). A\xFAn as\xED, requiere concentraci\xF3n significativa antes de volverse inflamable.&quot; }, { id:&quot;a2l_study_23&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el LFL del R-1234yf?&quot;, opciones:[&quot;14.4%&quot;,&quot;11.8%&quot;,&quot;6.2%&quot;,&quot;2.1%&quot;], respuesta_correcta:2, explicacion:&quot;R-1234yf tiene LFL=6.2%. Aunque es m\xE1s bajo que R-32 (14.4%), su MIE extremadamente alto (5,000-10,000 mJ) lo hace de los m\xE1s dif\xEDciles de encender entre los A2L.&quot; }, { id:&quot;a2l_study_24&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 es el MIE (Minimum Ignition Energy)?&quot;, opciones:[&quot;La presi\xF3n m\xEDnima para operar el sistema&quot;,&quot;La energ\xEDa el\xE9ctrica m\xEDnima en milijoules para encender la mezcla refrigerante-aire&quot;,&quot;La temperatura m\xEDnima de almacenamiento&quot;,&quot;El voltaje m\xEDnimo del equipo el\xE9ctrico&quot;], respuesta_correcta:1, explicacion:&quot;MIE = Minimum Ignition Energy = energ\xEDa m\xEDnima de chispa (mJ) necesaria para encender una mezcla refrigerante-aire. MIE alto = m\xE1s dif\xEDcil de encender. R-1234yf: 5,000-10,000 mJ (muy dif\xEDcil). R-290 propano: 0.25 mJ (muy f\xE1cil).&quot; }, { id:&quot;a2l_study_25&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el MIE del R-32?&quot;, opciones:[&quot;0.25 mJ (igual que propano)&quot;,&quot;5,000-10,000 mJ (igual que R-1234yf)&quot;,&quot;30-100 mJ&quot;,&quot;0.38 mJ&quot;], respuesta_correcta:2, explicacion:&quot;R-32 tiene MIE=30-100 mJ. Para comparar: propano (A3)=0.25 mJ, R-1234yf=5,000-10,000 mJ. Una buj\xEDa de alto voltaje produce 20-30 mJ \u2014 en el l\xEDmite inferior del rango de R-32.&quot; }, { id:&quot;a2l_study_26&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la temperatura de auto-ignici\xF3n del R-32?&quot;, opciones:[&quot;200\xB0C (392\xB0F)&quot;,&quot;405\xB0C (761\xB0F)&quot;,&quot;648\xB0C (1,198\xB0F)&quot;,&quot;100\xB0C (212\xB0F)&quot;], respuesta_correcta:2, explicacion:&quot;R-32 tiene temperatura de auto-ignici\xF3n de 648\xB0C (1,198\xB0F). Esta temperatura extremadamente alta significa que superficies calientes de equipos HVAC normales (generalmente <200\xB0C) no pueden encenderlo.&quot; }, { id:&quot;a2l_study_27&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la velocidad de llama del R-32?&quot;, opciones:[&quot;46 cm/s (igual que propano)&quot;,&quot;6.7 cm/s (\u226410 cm/s \u2014 A2L)&quot;,&quot;23 cm/s (A2)&quot;,&quot;0 cm/s (A1)&quot;], respuesta_correcta:1, explicacion:&quot;R-32 tiene velocidad de llama de 6.7 cm/s, dentro del l\xEDmite A2L (\u226410 cm/s). Comparado: propano (A3)=46 cm/s. Esta baja velocidad hace que el fuego de R-32 se propague lentamente y sea menos probable que se extienda.&quot; }, { id:&quot;a2l_study_28&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el calor de combusti\xF3n del R-32 vs R-290 propano?&quot;, opciones:[&quot;Son iguales&quot;,&quot;R-32: ~3,869 BTU/lb. Propano: ~19,905 BTU/lb&quot;,&quot;R-32 libera m\xE1s energ\xEDa que propano&quot;,&quot;El calor de combusti\xF3n no aplica a refrigerantes&quot;], respuesta_correcta:1, explicacion:&quot;R-32 libera ~3,869 BTU/lb si se quema. El propano libera ~19,905 BTU/lb \u2014 m\xE1s de 5 veces m\xE1s energ\xEDa. Esto significa que un incendio de R-32 tiene MUCHO menor probabilidad de propagarse a materiales cercanos.&quot; }, { id:&quot;a2l_study_29&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el RCL (Refrigerant Concentration Limit) del R-32 en PPM?&quot;, opciones:[&quot;140,000 PPM&quot;,&quot;50,000 PPM&quot;,&quot;36,000 PPM&quot;,&quot;5,300 PPM&quot;], respuesta_correcta:2, explicacion:&quot;R-32 tiene RCL=36,000 PPM. Comparado: R-410A (A1)=140,000 PPM, R-290 propano (A3)=5,300 PPM. El A2L tiene RCL intermedio entre los extremos de A1 y A3.&quot; }, { id:&quot;a2l_study_30&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el RCL del R-454B?&quot;, opciones:[&quot;36,000 PPM&quot;,&quot;19,000 PPM&quot;,&quot;50,000 PPM&quot;,&quot;140,000 PPM&quot;], respuesta_correcta:1, explicacion:&quot;R-454B tiene RCL=19,000 PPM, m\xE1s restrictivo que R-32 (36,000 PPM). Esto refleja su LFL m\xE1s bajo (11.8% vs 14.4%). El RCL es el l\xEDmite m\xE1s restrictivo entre toxicidad, asfixia e inflamabilidad.&quot; }, { id:&quot;a2l_study_31&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 protocolo internacional regula la eliminaci\xF3n de refrigerantes que agotan el ozono?&quot;, opciones:[&quot;Protocolo de Kioto (1997)&quot;,&quot;Protocolo de Montreal (1987)&quot;,&quot;Acuerdo de Par\xEDs (2015)&quot;,&quot;Enmienda de Kigali (2016)&quot;], respuesta_correcta:1, explicacion:&quot;El Protocolo de Montreal (1987) fue el primer acuerdo internacional para eliminar CFCs y HCFCs. La Enmienda de Kigali (2016) lo extendi\xF3 para incluir la reducci\xF3n gradual de HFCs de alto GWP.&quot; }, { id:&quot;a2l_study_32&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 enmienda al Protocolo de Montreal incluy\xF3 la reducci\xF3n de HFCs?&quot;, opciones:[&quot;Enmienda de Londres (1990)&quot;,&quot;Enmienda de Copenhague (1992)&quot;,&quot;Enmienda de Kigali (2016)&quot;,&quot;Enmienda de Pek\xEDn (1999)&quot;], respuesta_correcta:2, explicacion:&quot;La Enmienda de Kigali (2016) fue espec\xEDficamente dise\xF1ada para reducir gradualmente la producci\xF3n y uso de HFCs, que aunque no afectan el ozono, tienen alto GWP. Los A2L como R-32 y R-454B son alternativas con menor GWP.&quot; }, { id:&quot;a2l_study_33&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el ODP del R-32?&quot;, opciones:[&quot;0.055 (igual que R-22)&quot;,&quot;0&quot;,&quot;1.0&quot;,&quot;0.01&quot;], respuesta_correcta:1, explicacion:&quot;R-32 tiene ODP=0 \u2014 no da\xF1a la capa de ozono porque es un HFC (no contiene cloro). Esto lo diferencia fundamentalmente de R-22 (HCFC, ODP=0.055) que ten\xEDa efecto destructivo en el ozono.&quot; }, { id:&quot;a2l_study_34&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPor qu\xE9 los HFO tienen GWP tan bajo (menor a 1)?&quot;, opciones:[&quot;Porque son m\xE1s pesados que el aire&quot;,&quot;Su doble enlace de carbono hace que se degraden muy r\xE1pidamente en la trop\xF3sfera (d\xEDas vs a\xF1os)&quot;,&quot;Porque no contienen carbono&quot;,&quot;Porque son naturales&quot;], respuesta_correcta:1, explicacion:&quot;Los HFO se degradan en la trop\xF3sfera en d\xEDas o semanas gracias a su doble enlace de carbono (reacciona con el radical OH). Comparado: los HFC tardan a\xF1os o d\xE9cadas en degradarse, por eso tienen GWP alto.&quot; }, { id:&quot;a2l_study_35&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFEn qu\xE9 a\xF1o se prohibi\xF3 la producci\xF3n e importaci\xF3n de R-22 en USA?&quot;, opciones:[&quot;2010&quot;,&quot;2015&quot;,&quot;2020&quot;,&quot;2025&quot;], respuesta_correcta:2, explicacion:&quot;El 1 de enero de 2020 se prohibi\xF3 la producci\xF3n e importaci\xF3n de R-22 en USA. Desde 2010 ya no se pod\xEDa usar en equipos NUEVOS. El R-22 recuperado puede seguir us\xE1ndose para servicio de equipos existentes.&quot; }, { id:&quot;a2l_study_36&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el GWP base de referencia contra el que se comparan todos los refrigerantes?&quot;, opciones:[&quot;R-11 con GWP=1&quot;,&quot;CO2 (R-744) con GWP=1&quot;,&quot;R-22 con GWP=1&quot;,&quot;Metano con GWP=1&quot;], respuesta_correcta:1, explicacion:&quot;El CO2 (R-744) tiene GWP=1 y es la referencia base. Todo los dem\xE1s se miden comparando cu\xE1nto calentamiento produce 1 kg del refrigerante vs 1 kg de CO2 en un per\xEDodo de 100 a\xF1os.&quot; }, { id:&quot;a2l_study_37&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPor qu\xE9 el R-410A se considera un 'super contaminante' clim\xE1tico?&quot;, opciones:[&quot;Porque da\xF1a el ozono&quot;,&quot;Porque tiene GWP=2,088 \u2014 2,088 veces m\xE1s potente que el CO2 como gas de efecto invernadero&quot;,&quot;Porque es t\xF3xico para humanos&quot;,&quot;Porque es m\xE1s pesado que el aire&quot;], respuesta_correcta:1, explicacion:&quot;R-410A tiene GWP=2,088. Esto significa que 1 kg de R-410A liberado a la atm\xF3sfera tiene el mismo efecto de calentamiento que 2,088 kg de CO2. Por eso la EPA lo est\xE1 eliminando y reemplazando con A2L de menor GWP.&quot; }, { id:&quot;a2l_study_38&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el GWP del R-404A y por qu\xE9 se est\xE1 eliminando agresivamente?&quot;, opciones:[&quot;GWP=675 (igual que R-32)&quot;,&quot;GWP=2,088 (igual que R-410A)&quot;,&quot;GWP=3,920 \u2014 uno de los m\xE1s altos entre refrigerantes comunes&quot;,&quot;GWP<1 (igual que R-1234yf)&quot;], respuesta_correcta:2, explicacion:&quot;R-404A tiene GWP=3,920, uno de los m\xE1s altos entre los refrigerantes comunes. Se usa en refrigeraci\xF3n comercial (supermercados) y est\xE1 siendo reemplazado agresivamente por R-448A, R-449A y R-449B.&quot; }, { id:&quot;a2l_study_39&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 programa de la EPA eval\xFAa y aprueba sustitutos para refrigerantes que agotan el ozono?&quot;, opciones:[&quot;Secci\xF3n 608 \u2014 recuperaci\xF3n de refrigerantes&quot;,&quot;SNAP (Significant New Alternatives Policy) \u2014 Secci\xF3n 612&quot;,&quot;SNAP 23 \u2014 lista de aprobados 2023&quot;,&quot;Programa ARI 700&quot;], respuesta_correcta:1, explicacion:&quot;SNAP (Significant New Alternatives Policy) bajo la Secci\xF3n 612 de la Clean Air Act eval\xFAa sustitutos para sustancias que agotan el ozono y genera listas de sustitutos aceptables e inaceptables por sector industrial.&quot; }, { id:&quot;a2l_study_40&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1les refrigerantes aprob\xF3 EPA SNAP 23 para A/C residencial y comercial ligero?&quot;, opciones:[&quot;Solo R-32&quot;,&quot;R-452B, R-454A, R-454B, R-454C, R-457A y R-32 (todos sujetos a condiciones)&quot;,&quot;Cualquier A2L sin restricciones&quot;,&quot;Solo R-1234yf&quot;], respuesta_correcta:1, explicacion:&quot;SNAP 23 aprob\xF3 para A/C residencial/comercial ligero: R-452B, R-454A, R-454B, R-454C, R-457A, y R-32. Todos sujetos a condiciones de uso espec\xEDficas incluyendo requisitos de instalaci\xF3n A2L.&quot; }, { id:&quot;a2l_study_41&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el extinguidor correcto para trabajar con refrigerantes A2L?&quot;, opciones:[&quot;Clase A \u2014 combustibles s\xF3lidos&quot;,&quot;Clase B (polvo seco) o ABC&quot;,&quot;Clase C \u2014 equipos el\xE9ctricos&quot;,&quot;Clase D \u2014 metales combustibles&quot;], respuesta_correcta:1, explicacion:&quot;Clase B (polvo seco, Dry Powder) o ABC. La Clase B cubre gases y l\xEDquidos inflamables. Siempre tenerlo disponible y SABER USARLO antes de comenzar cualquier trabajo con refrigerante inflamable.&quot; }, { id:&quot;a2l_study_42&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPor qu\xE9 los refrigerantes son peligrosos en espacios confinados aunque no sean inflamables?&quot;, opciones:[&quot;Solo son peligrosos si son inflamables&quot;,&quot;Desplazan el ox\xEDgeno del aire, pudiendo causar asfixia por falta de ox\xEDgeno&quot;,&quot;Solo son peligrosos si son t\xF3xicos&quot;,&quot;No son peligrosos en espacios confinados&quot;], respuesta_correcta:1, explicacion:&quot;TODOS los refrigerantes (A1, A2L, A3) pueden causar asfixia en espacios confinados al desplazar el ox\xEDgeno del aire. La mayor\xEDa de accidentes mortales con refrigerantes son por ASFIXIA, no por toxicidad directa.&quot; }, { id:&quot;a2l_study_43&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 equipo de protecci\xF3n personal b\xE1sico se usa al trabajar con refrigerantes?&quot;, opciones:[&quot;Solo guantes de hule&quot;,&quot;Gafas de seguridad y guantes como m\xEDnimo&quot;,&quot;Solo mascarilla N95&quot;,&quot;No se requiere PPE especial para refrigerantes&quot;], respuesta_correcta:1, explicacion:&quot;El PPE m\xEDnimo para trabajo con refrigerantes incluye gafas de seguridad (protecci\xF3n contra salpicaduras de refrigerante l\xEDquido que puede causar quemaduras/congelaci\xF3n) y guantes. Para A2L a\xF1adir protecci\xF3n adicional seg\xFAn SDS del refrigerante espec\xEDfico.&quot; }, { id:&quot;a2l_study_44&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 puede causar el refrigerante l\xEDquido al contacto con la piel o los ojos?&quot;, opciones:[&quot;Nada \u2014 los refrigerantes son seguros en piel&quot;,&quot;Quemaduras por fr\xEDo (congelaci\xF3n) en piel y posiblemente ceguera en ojos&quot;,&quot;Solo irritaci\xF3n leve temporal&quot;,&quot;Solo problemas si es t\xF3xico&quot;], respuesta_correcta:1, explicacion:&quot;El refrigerante l\xEDquido al vaporizar r\xE1pidamente en la piel causa QUEMADURAS POR FR\xCDO (frostbite). En los ojos puede causar da\xF1o serio o ceguera. Siempre usar gafas de seguridad y guantes al manipular refrigerante l\xEDquido.&quot; }, { id:&quot;a2l_study_45&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFA qu\xE9 temperatura m\xE1xima deben almacenarse los cilindros de refrigerante?&quot;, opciones:[&quot;50\xB0F (10\xB0C)&quot;,&quot;100\xB0F (38\xB0C)&quot;,&quot;125\xB0F (52\xB0C)&quot;,&quot;150\xB0F (66\xB0C)&quot;], respuesta_correcta:2, explicacion:&quot;Los cilindros de refrigerante deben almacenarse a menos de 125\xB0F (52\xB0C). A temperaturas mayores la presi\xF3n interna puede aumentar dr\xE1sticamente y causar ruptura del cilindro.&quot; }, { id:&quot;a2l_study_46&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFHasta qu\xE9 porcentaje de su capacidad m\xE1xima se puede llenar un tanque de recuperaci\xF3n?&quot;, opciones:[&quot;60%&quot;,&quot;70%&quot;,&quot;80%&quot;,&quot;100%&quot;], respuesta_correcta:2, explicacion:&quot;Los tanques de recuperaci\xF3n NO deben llenarse m\xE1s del 80% de su capacidad. El 20% restante permite la expansi\xF3n del refrigerante sin que el tanque alcance presiones peligrosas.&quot; }, { id:&quot;a2l_study_47&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 indica la f\xF3rmula (WC \xD7 0.80) + TW en el contexto de cilindros de recuperaci\xF3n?&quot;, opciones:[&quot;La presi\xF3n m\xE1xima de trabajo del cilindro&quot;,&quot;El peso m\xE1ximo permitido de refrigerante en el cilindro incluyendo el peso del cilindro vac\xEDo&quot;,&quot;El volumen de agua que cabe en el cilindro&quot;,&quot;La fecha de pr\xF3xima recertificaci\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;WC (Water Capacity) \xD7 0.80 + TW (Tare Weight) = peso m\xE1ximo total del cilindro lleno al 80%. WC est\xE1 estampado en el collar del cilindro. Esta f\xF3rmula determina cu\xE1ndo DEJAR DE recuperar antes de llenar demasiado.&quot; }, { id:&quot;a2l_study_48&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCada cu\xE1ntos a\xF1os deben someterse a prueba hidrost\xE1tica los cilindros de recuperaci\xF3n DOT?&quot;, opciones:[&quot;2 a\xF1os&quot;,&quot;3 a\xF1os&quot;,&quot;5 a\xF1os&quot;,&quot;10 a\xF1os&quot;], respuesta_correcta:2, explicacion:&quot;Los cilindros de recuperaci\xF3n DOT deben someterse a prueba hidrost\xE1tica cada 5 a\xF1os. La fecha de fabricaci\xF3n y la fecha de retest est\xE1n estampadas en el collar del cilindro. Un cilindro vencido no puede usarse legalmente.&quot; }, { id:&quot;a2l_study_49&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 color tienen los cilindros de recuperaci\xF3n DOT est\xE1ndar?&quot;, opciones:[&quot;Azul y blanco&quot;,&quot;Gris y amarillo&quot;,&quot;Verde y rojo&quot;,&quot;Negro y naranja&quot;], respuesta_correcta:1, explicacion:&quot;Los cilindros de recuperaci\xF3n DOT son color gris (cuerpo) y amarillo (tapa/collar). Los A2L a\xF1aden una banda roja para identificarlos como inflamables. NUNCA usar cilindros de color diferente a los aprobados DOT.&quot; }, { id:&quot;a2l_study_50&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 es una 'SDS' y cu\xE1ndo debes consultarla?&quot;, opciones:[&quot;System Data Sheet \u2014 especificaciones del sistema&quot;,&quot;Safety Data Sheet \u2014 antes de trabajar con cualquier refrigerante o qu\xEDmico nuevo&quot;,&quot;Standard Design Specification \u2014 para instalaciones&quot;,&quot;Service Data Sheet \u2014 manual de servicio del equipo&quot;], respuesta_correcta:1, explicacion:&quot;SDS (Safety Data Sheet, antes MSDS) contiene: toxicidad, inflamabilidad, primeros auxilios, manejo seguro, incompatibilidades, y procedimientos de emergencia. SIEMPRE consultarla antes de trabajar con un refrigerante o qu\xEDmico nuevo.&quot; }, { id:&quot;a2l_study_51&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 herramientas deben usarse cuando se trabaja con refrigerantes A2L, A2 o A3?&quot;, opciones:[&quot;Cualquier herramienta certificada UL&quot;,&quot;Solo herramientas certificadas spark-free (sin chispa, sin arco) para ambiente inflamable&quot;,&quot;Solo herramientas manuales, sin el\xE9ctricas&quot;,&quot;Cualquier herramienta disponible en el cami\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;Con refrigerantes A2L/A2/A3: SOLO herramientas certificadas para ambiente inflamable (spark-free) seg\xFAn NFPA 70 y NEC. Las herramientas comunes pueden generar chispas que enciendan el refrigerante.&quot; }, { id:&quot;a2l_study_52&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 herramienta mide el nivel de evacuaci\xF3n con precisi\xF3n en micrones?&quot;, opciones:[&quot;Man\xF3metro del manifold (en pulgadas Hg)&quot;,&quot;Medidor digital de micrones (digital micron gauge)&quot;,&quot;Term\xF3metro digital&quot;,&quot;Amper\xEDmetro&quot;], respuesta_correcta:1, explicacion:&quot;El medidor digital de micrones (micron gauge) es la \xFAnica herramienta que puede medir con precisi\xF3n niveles de vac\xEDo profundo. Los manifolds anal\xF3gicos miden en pulgadas Hg \u2014 demasiado imprecisos para vac\xEDos profundos.&quot; }, { id:&quot;a2l_study_53&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFD\xF3nde debe colocarse el medidor de micrones durante la evacuaci\xF3n?&quot;, opciones:[&quot;Junto a la bomba de vac\xEDo&quot;,&quot;Tan cerca del sistema como sea posible (no en la bomba)&quot;,&quot;No importa el lugar&quot;,&quot;Solo al final de la evacuaci\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;El micr\xF3metro debe estar tan cerca del SISTEMA como sea posible (idealmente en el puerto del core removal tool). Colocarlo en la bomba solo mide que la bomba funciona, no el nivel real del sistema.&quot; }, { id:&quot;a2l_study_54&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 hoses (mangueras) son las m\xE1s eficientes para evacuaci\xF3n?&quot;, opciones:[&quot;1/4 pulgada \u2014 las m\xE1s comunes en manifolds&quot;,&quot;3/8 pulgada o 1/2 pulgada vacuum-rated con cores removidos&quot;,&quot;Cualquier manguera del manifold existente&quot;,&quot;Solo mangueras especiales de evacuaci\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;Para evacuaci\xF3n eficiente: mangueras 3/8&quot; o 1/2&quot; vacuum-rated con cores Schrader removidos. Una manguera 1/4&quot; con cores provee ~0.2 CFM a la bomba. Con 2 mangueras 1/2&quot; sin cores puedes llegar a 6 CFM.&quot; }, { id:&quot;a2l_study_55&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPara qu\xE9 se usa el core removal tool durante el servicio?&quot;, opciones:[&quot;Para cambiar el refrigerante del sistema&quot;,&quot;Para remover los cores Schrader de las v\xE1lvulas de servicio, permitiendo mayor flujo&quot;,&quot;Para medir la presi\xF3n del sistema&quot;,&quot;Para agregar aceite al compresor&quot;], respuesta_correcta:1, explicacion:&quot;El core removal tool permite remover los cores Schrader de las v\xE1lvulas de servicio sin liberar refrigerante. Sin cores, el flujo para evacuaci\xF3n y recuperaci\xF3n aumenta dr\xE1sticamente (de 0.2 CFM a varios CFM).&quot; }, { id:&quot;a2l_study_56&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 tipo de manifold se requiere para trabajar con sistemas A2L?&quot;, opciones:[&quot;Cualquier manifold existente \u2014 son universales&quot;,&quot;Manifold specifically rated para refrigerantes inflamables y para las presiones del A2L espec\xEDfico&quot;,&quot;Solo manifolds digitales&quot;,&quot;Solo manifolds de 4 v\xE1lvulas&quot;], respuesta_correcta:1, explicacion:&quot;Los manifolds para A2L deben estar: (1) rated para refrigerantes inflamables (materiales y sellados apropiados), y (2) rated para las presiones del refrigerante espec\xEDfico. El R-32 opera a presiones mayores que R-22.&quot; }, { id:&quot;a2l_study_57&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 tipo de aceite debe usarse en la bomba de vac\xEDo para mejores resultados?&quot;, opciones:[&quot;Cualquier aceite disponible \u2014 10W30 funciona&quot;,&quot;Aceite de alta calidad espec\xEDfico para bomba de vac\xEDo, cambiado antes de cada trabajo&quot;,&quot;Aceite sint\xE9tico de motor&quot;,&quot;No se requiere aceite \u2014 las bombas modernas son sin aceite&quot;], respuesta_correcta:1, explicacion:&quot;Usar aceite de ALTA CALIDAD espec\xEDfico para bomba de vac\xEDo y cambiarlo ANTES de cada trabajo de evacuaci\xF3n. El aceite contaminado o degradado reduce la capacidad de vac\xEDo. El color del aceite indica si debe cambiarse.&quot; }, { id:&quot;a2l_study_58&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1ndo debe cambiarse el aceite de la bomba de vac\xEDo?&quot;, opciones:[&quot;Solo cuando se ve muy oscuro&quot;,&quot;Antes de cada evacuaci\xF3n y cuando se contamina con humedad durante el trabajo&quot;,&quot;Solo una vez al a\xF1o&quot;,&quot;Solo cuando la bomba no llega al vac\xEDo requerido&quot;], respuesta_correcta:1, explicacion:&quot;El aceite de bomba de vac\xEDo debe cambiarse: ANTES de cada evacuaci\xF3n importante (para asegurar m\xE1xima eficiencia) y DURANTE el trabajo si se contamina con humedad (el aceite se ver\xE1 turbio o muy oscuro).&quot; }, { id:&quot;a2l_study_59&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 es un 'gas ballast' en una bomba de vac\xEDo?&quot;, opciones:[&quot;Un cilindro de nitr\xF3geno conectado a la bomba&quot;,&quot;Una v\xE1lvula que permite entrada de aire durante evacuaci\xF3n para prevenir condensaci\xF3n de vapores de agua en el aceite&quot;,&quot;Un filtro especial para A2L&quot;,&quot;El tanque de recuperaci\xF3n de la bomba&quot;], respuesta_correcta:1, explicacion:&quot;El gas ballast es una v\xE1lvula que permite entrada de aire a la bomba durante evacuaci\xF3n. Esto previene que el vapor de agua se condense en el aceite de la bomba. La v\xE1lvula DEBE cerrarse para alcanzar el nivel final de vac\xEDo profundo.&quot; }, { id:&quot;a2l_study_60&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 es la escala de 'micrones' y c\xF3mo se relaciona con pulgadas Hg?&quot;, opciones:[&quot;Es una medida de temperatura&quot;,&quot;Una unidad de presi\xF3n muy peque\xF1a: presi\xF3n atmosf\xE9rica = 760,000 micrones. A 29.98 inHg = ~500 micrones&quot;,&quot;Es una medida de di\xE1metro de tuber\xEDa&quot;,&quot;No se relaciona con pulgadas Hg&quot;], respuesta_correcta:1, explicacion:&quot;Micrones = unidad de presi\xF3n muy peque\xF1a. Presi\xF3n atmosf\xE9rica = 760,000 micrones = 0 inHg. El objetivo de evacuaci\xF3n (500 micrones) equivale aproximadamente a 29.98 inHg. Los manifolds anal\xF3gicos no pueden medir esta diferencia \u2014 necesitas micr\xF3metro digital.&quot; }, { id:&quot;a2l_study_61&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 es la 'recuperaci\xF3n' (recovery) de refrigerante?&quot;, opciones:[&quot;Ventilar el refrigerante al exterior de forma controlada&quot;,&quot;Transferir el refrigerante de un sistema sellado a un cilindro de recuperaci\xF3n aprobado DOT&quot;,&quot;Reciclar el refrigerante dentro del mismo sistema&quot;,&quot;Enviar el refrigerante al fabricante para reciclaje&quot;], respuesta_correcta:1, explicacion:&quot;Recovery = transferir el refrigerante desde el sistema sellado a un cilindro de recuperaci\xF3n aprobado DOT. NO es ventilarlo ni tirarlo. El proceso minimiza la liberaci\xF3n de refrigerante al ambiente.&quot; }, { id:&quot;a2l_study_62&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la diferencia entre 'recycling' y 'reclamation'?&quot;, opciones:[&quot;Son lo mismo con diferente nombre&quot;,&quot;Recycling = limpieza b\xE1sica en campo para reusar en el mismo sistema. Reclamation = purificaci\xF3n a est\xE1ndar ARI 700 en instalaci\xF3n certificada para vender como nuevo&quot;,&quot;Recycling es legal, reclamation no&quot;,&quot;Reclamation es m\xE1s barato&quot;], respuesta_correcta:1, explicacion:&quot;Recycling = pasar por filtro-drier en campo para reducir contaminantes \u2014 puede reutilizarse en el mismo sistema o del mismo propietario. Reclamation = proceso industrial que purifica el refrigerante al est\xE1ndar ARI 700 (como nuevo) para reventa.&quot; }, { id:&quot;a2l_study_63&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1les refrigerantes est\xE1n EXENTOS del mandato de recuperaci\xF3n de la EPA bajo Secci\xF3n 608?&quot;, opciones:[&quot;Todos los A2L est\xE1n exentos&quot;,&quot;R-290 (propano) y R-600a (isobutano) \u2014 hidrocarburos naturales&quot;,&quot;Solo R-32 est\xE1 exento&quot;,&quot;Ninguno \u2014 todos deben recuperarse&quot;], respuesta_correcta:1, explicacion:&quot;R-290 (propano) y R-600a (isobutano) son hidrocarburos naturales EXENTOS del mandato de recuperaci\xF3n de la EPA. Para m\xE1s informaci\xF3n sobre sustitutos exentos: epa.gov/snap.&quot; }, { id:&quot;a2l_study_64&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 nivel de evacuaci\xF3n se requiere para recuperaci\xF3n de sistemas de ALTA presi\xF3n post-1993 con MENOS de 200 lb?&quot;, opciones:[&quot;4 pulgadas Hg&quot;,&quot;10 pulgadas Hg&quot;,&quot;15 pulgadas Hg&quot;,&quot;0 PSI&quot;], respuesta_correcta:1, explicacion:&quot;Para sistemas de alta presi\xF3n post-Nov 1993 con menos de 200 lb de refrigerante: se requiere evacuar a 10 pulgadas Hg. Si la carga es 200 lb o m\xE1s: 15 pulgadas Hg. Equipos pre-1993: solo 4 pulgadas Hg.&quot; }, { id:&quot;a2l_study_65&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPor qu\xE9 se recomienda recuperar el refrigerante en estado VAPOR en lugar de l\xEDquido cuando es posible?&quot;, opciones:[&quot;La recuperaci\xF3n en vapor es m\xE1s r\xE1pida&quot;,&quot;La recuperaci\xF3n en vapor minimiza la p\xE9rdida de aceite del sistema, aunque es m\xE1s lenta&quot;,&quot;La recuperaci\xF3n en l\xEDquido est\xE1 prohibida&quot;,&quot;No hay diferencia entre vapor y l\xEDquido&quot;], respuesta_correcta:1, explicacion:&quot;Recuperaci\xF3n en vapor es M\xC1S LENTA pero minimiza la p\xE9rdida de aceite del sistema. La recuperaci\xF3n en l\xEDquido es m\xE1s r\xE1pida pero arrastra aceite del compresor hacia el cilindro de recuperaci\xF3n.&quot; }, { id:&quot;a2l_study_66&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 debe hacer el t\xE9cnico con el cilindro de A2L recuperado antes de iniciar reparaciones?&quot;, opciones:[&quot;Dejarlo junto al equipo para referencia&quot;,&quot;Moverlo a una distancia segura del \xE1rea de trabajo antes de cualquier trabajo con fuego o chispa&quot;,&quot;Vaciarlo completamente primero&quot;,&quot;Guardarlo en un cuarto cerrado&quot;], respuesta_correcta:1, explicacion:&quot;Despu\xE9s de recuperar A2L: mover el cilindro a DISTANCIA SEGURA del \xE1rea de trabajo ANTES de usar soplete o cualquier herramienta que genere chispa. El cilindro con refrigerante inflamable es una fuente de peligro si hay fuego.&quot; }, { id:&quot;a2l_study_67&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPor qu\xE9 se recomienda el 'nitrogen sweep' despu\xE9s de recuperar A2L y antes de soldar?&quot;, opciones:[&quot;Para verificar que el sistema est\xE1 vac\xEDo&quot;,&quot;El aceite del sistema puede retener vapores de refrigerante inflamable \u2014 el nitr\xF3geno los desplaza&quot;,&quot;Para lubricar las tuber\xEDas antes de soldar&quot;,&quot;Solo es necesario en sistemas grandes&quot;], respuesta_correcta:1, explicacion:&quot;Despu\xE9s de recuperar A2L, el aceite POE del sistema puede retener vapores de refrigerante inflamable. El nitrogen sweep (purga con nitr\xF3geno seco a baja presi\xF3n) desplaza estos vapores, haciendo seguro el uso de soplete.&quot; }, { id:&quot;a2l_study_68&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1les son los componentes b\xE1sicos de un setup de recuperaci\xF3n?&quot;, opciones:[&quot;Solo la m\xE1quina de recuperaci\xF3n&quot;,&quot;M\xE1quina de recuperaci\xF3n + cilindro DOT + mangueras + pre-filtro drier + escala&quot;,&quot;Solo la m\xE1quina y el cilindro&quot;,&quot;Solo manifold y mangueras&quot;], respuesta_correcta:1, explicacion:&quot;Setup b\xE1sico de recuperaci\xF3n: (1) m\xE1quina de recuperaci\xF3n, (2) cilindro DOT aprobado, (3) mangueras 1/4&quot; o 3/8&quot;, (4) pre-filtro drier (filtra part\xEDculas), (5) escala de refrigerante para monitorear cu\xE1nto se recuper\xF3.&quot; }, { id:&quot;a2l_study_69&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPor qu\xE9 se deben purgar las mangueras de servicio antes de comenzar la recuperaci\xF3n?&quot;, opciones:[&quot;Para verificar que no hay fugas&quot;,&quot;Para eliminar el aire atrapado en las mangueras que contaminar\xEDa el refrigerante y aumentar\xEDa la presi\xF3n en el cilindro&quot;,&quot;Solo para manifolds viejos&quot;,&quot;No es necesario purgar mangueras&quot;], respuesta_correcta:1, explicacion:&quot;SIEMPRE purgar el aire de las mangueras antes de recuperar. El aire en las mangueras entra al cilindro de recuperaci\xF3n como no-condensable, aumenta la presi\xF3n y contamina el refrigerante haci\xE9ndolo m\xE1s dif\xEDcil de reclamar.&quot; }, { id:&quot;a2l_study_70&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 pasa con el refrigerante recuperado si la presi\xF3n del cilindro sube despu\xE9s de aislar el sistema de la m\xE1quina?&quot;, opciones:[&quot;Es normal \u2014 el proceso est\xE1 completo&quot;,&quot;Puede indicar que hay refrigerante adicional atrapado en el aceite del sistema vaporiz\xE1ndose \u2014 puede ser necesario reiniciar la m\xE1quina&quot;,&quot;Solo indica que el cilindro est\xE1 lleno&quot;,&quot;El cilindro debe reemplazarse&quot;], respuesta_correcta:1, explicacion:&quot;Si la presi\xF3n sube despu\xE9s de aislar: el refrigerante atrapado en el aceite del sistema se est\xE1 vaporizando. Puede necesitarse reiniciar la m\xE1quina de recuperaci\xF3n para recuperar este refrigerante adicional hasta estabilizar la presi\xF3n.&quot; }, { id:&quot;a2l_study_71&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 es 'label matching' en instalaci\xF3n de sistemas A2L?&quot;, opciones:[&quot;Verificar que la etiqueta del cilindro coincida con el manifold&quot;,&quot;Verificar que TODOS los componentes est\xE9n dise\xF1ados y certificados para A2L antes de proceder&quot;,&quot;Hacer que las etiquetas coincidan visualmente&quot;,&quot;Verificar n\xFAmero de modelo con el manual&quot;], respuesta_correcta:1, explicacion:&quot;Label matching = verificar que CADA componente (evaporador, condensador, compresor, TXV, v\xE1lvulas, drier, etc.) est\xE9 certificado A2L. Si cualquier componente NO est\xE1 rated para A2L, la instalaci\xF3n NO puede proceder.&quot; }, { id:&quot;a2l_study_72&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el orden correcto de operaciones al instalar un sistema A2L nuevo?&quot;, opciones:[&quot;Cargar refrigerante \u2192 prueba de fugas \u2192 evacuar&quot;,&quot;Evaluar sitio \u2192 label matching \u2192 instalar \u2192 prueba N2 \u2192 evacuar \u2192 decay test \u2192 cargar \u2192 etiqueta UL&quot;,&quot;Instalar \u2192 evacuar \u2192 cargar \u2192 verificar&quot;,&quot;Solo instalar y encender&quot;], respuesta_correcta:1, explicacion:&quot;Orden correcto: (1) Evaluar sitio para A2L, (2) label matching, (3) instalar con purga N2 durante brazado, (4) prueba presi\xF3n N2 (60 min, cero ca\xEDda), (5) evacuaci\xF3n a 500 micrones, (6) decay test, (7) cargar refrigerante, (8) etiqueta UL.&quot; }, { id:&quot;a2l_study_73&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 presi\xF3n y tiempo m\xEDnimo se requieren para la prueba de presi\xF3n de una nueva instalaci\xF3n A2L?&quot;, opciones:[&quot;100 PSI por 30 minutos&quot;,&quot;Presi\xF3n de datos de la placa por m\xEDnimo 60 minutos \u2014 sin ca\xEDda de presi\xF3n&quot;,&quot;150 PSI por 15 minutos&quot;,&quot;10 PSI por 10 minutos&quot;], respuesta_correcta:1, explicacion:&quot;Prueba de presi\xF3n A2L: presurizar con nitr\xF3geno seco a la presi\xF3n m\xE1s baja de las placas de datos de los componentes, por m\xEDnimo 60 minutos. CERO ca\xEDda de presi\xF3n durante la prueba para considerar que pas\xF3.&quot; }, { id:&quot;a2l_study_74&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 criterio debe cumplir el vacuum decay test en una instalaci\xF3n A2L?&quot;, opciones:[&quot;La presi\xF3n no debe subir en absoluto&quot;,&quot;La presi\xF3n no debe subir m\xE1s de 1,500 micrones en 10 minutos despu\xE9s de aislar de la bomba&quot;,&quot;Solo alcanzar 500 micrones es suficiente&quot;,&quot;La presi\xF3n puede subir hasta 5,000 micrones&quot;], respuesta_correcta:1, explicacion:&quot;Vacuum decay test: despu\xE9s de 500 micrones, aislar el sistema de la bomba. La presi\xF3n NO debe subir m\xE1s de 1,500 micrones en 10 minutos. Si sube m\xE1s: hay fuga o humedad \u2014 investigar antes de cargar refrigerante.&quot; }, { id:&quot;a2l_study_75&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 informaci\xF3n m\xEDnima requiere la etiqueta permanente UL en sistemas A2L?&quot;, opciones:[&quot;Solo el tipo de refrigerante&quot;,&quot;Nombre del contratista, nivel de vac\xEDo, presi\xF3n de prueba, fecha, tipo de refrigerante, y carga total (lb y oz)&quot;,&quot;Solo la fecha de instalaci\xF3n&quot;,&quot;Solo el n\xFAmero de certificaci\xF3n del t\xE9cnico&quot;], respuesta_correcta:1, explicacion:&quot;La etiqueta permanente UL requerida en sistemas A2L debe incluir: nombre del contratista/t\xE9cnico, nivel de vac\xEDo alcanzado, presi\xF3n de prueba, fecha de prueba y evacuaci\xF3n, tipo de refrigerante, y carga total (libras y onzas).&quot; }, { id:&quot;a2l_study_76&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 protecci\xF3n requieren las tuber\xEDas A2L instaladas dentro de paredes o pisos?&quot;, opciones:[&quot;Ninguna especial&quot;,&quot;Strike plates u otros escudos para prevenir perforaciones accidentales&quot;,&quot;Solo aislamiento t\xE9rmico&quot;,&quot;Solo deben estar bien soldadas&quot;], respuesta_correcta:1, explicacion:&quot;Tuber\xEDas A2L dentro de paredes/pisos deben estar protegidas con STRIKE PLATES (planchas met\xE1licas) u otros escudos para prevenir perforaciones accidentales que causar\xEDan fugas de refrigerante inflamable.&quot; }, { id:&quot;a2l_study_77&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFC\xF3mo se carga el R-454B correctamente?&quot;, opciones:[&quot;En estado gaseoso igual que refrigerante puro&quot;,&quot;En estado L\xCDQUIDO del cilindro \u2014 es mezcla zeotr\xF3pica que fracciona si se carga en gas&quot;,&quot;En cualquier estado&quot;,&quot;Solo con equipo especializado&quot;], respuesta_correcta:1, explicacion:&quot;R-454B SIEMPRE debe cargarse en estado L\xCDQUIDO del cilindro. Como mezcla zeotr\xF3pica, si se carga en gas el R-32 m\xE1s vol\xE1til sale primero, cambiando la composici\xF3n de la mezcla y afectando el desempe\xF1o del sistema.&quot; }, { id:&quot;a2l_study_78&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPuede el R-32 cargarse en estado gaseoso?&quot;, opciones:[&quot;No \u2014 igual que R-454B debe ser siempre l\xEDquido&quot;,&quot;S\xED \u2014 es refrigerante puro que no fracciona, puede cargarse como gas o l\xEDquido&quot;,&quot;Solo en emergencias&quot;,&quot;Solo con cilindros especiales&quot;], respuesta_correcta:1, explicacion:&quot;R-32 ES refrigerante puro (un solo componente) \u2014 NO fracciona. Puede cargarse como gas o como l\xEDquido sin cambiar su composici\xF3n. Esta es una ventaja operacional sobre mezclas como R-454B.&quot; }, { id:&quot;a2l_study_79&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 debe incluirse en el cargo final de la etiqueta permanente cuando se completa una instalaci\xF3n A2L?&quot;, opciones:[&quot;Solo el tipo de refrigerante&quot;,&quot;El tipo de refrigerante Y el peso total en libras y onzas que qued\xF3 en el sistema&quot;,&quot;Solo el n\xFAmero de cilindros usados&quot;,&quot;Solo el costo del refrigerante usado&quot;], respuesta_correcta:1, explicacion:&quot;La etiqueta permanente debe registrar el tipo de refrigerante Y el peso total (en libras y onzas) cargado en el sistema al finalizar la instalaci\xF3n. Cualquier recarga futura tambi\xE9n debe documentarse en esa etiqueta.&quot; }, { id:&quot;a2l_study_80&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 documentaci\xF3n debe entregarse al propietario al finalizar una instalaci\xF3n A2L?&quot;, opciones:[&quot;Solo la factura&quot;,&quot;Los manuales de instalaci\xF3n y servicio del fabricante, revisando con el propietario&quot;,&quot;Solo la garant\xEDa&quot;,&quot;Solo el n\xFAmero de serie&quot;], respuesta_correcta:1, explicacion:&quot;Al finalizar instalaci\xF3n A2L: los manuales de instalaci\xF3n y servicio DEBEN entregarse al propietario (o quedar con el equipo). El t\xE9cnico debe tomarse tiempo para revisar la documentaci\xF3n con el propietario.&quot; }, { id:&quot;a2l_study_81&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 cubre espec\xEDficamente la Secci\xF3n 608 de la Clean Air Act?&quot;, opciones:[&quot;Calidad del aire en ciudades&quot;,&quot;Manejo de refrigerantes \u2014 proh\xEDbe ventilar, requiere recuperaci\xF3n, certifica t\xE9cnicos y equipos&quot;,&quot;Emisiones de veh\xEDculos&quot;,&quot;Producci\xF3n de sustancias qu\xEDmicas&quot;], respuesta_correcta:1, explicacion:&quot;Secci\xF3n 608 de la CAA regula el manejo de refrigerantes: proh\xEDbe la ventilaci\xF3n intencional, requiere recuperaci\xF3n antes de trabajar en sistemas, y exige certificaci\xF3n a t\xE9cnicos que manejan refrigerantes regulados.&quot; }, { id:&quot;a2l_study_82&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 cubre la Secci\xF3n 612 de la Clean Air Act?&quot;, opciones:[&quot;Certificaci\xF3n de t\xE9cnicos EPA 608&quot;,&quot;Evaluaci\xF3n y aprobaci\xF3n de sustitutos para sustancias que agotan el ozono (programa SNAP)&quot;,&quot;Regulaci\xF3n de emisiones industriales&quot;,&quot;Manejo de residuos qu\xEDmicos&quot;], respuesta_correcta:1, explicacion:&quot;Secci\xF3n 612 = programa SNAP. Requiere que la EPA eval\xFAe alternativas para refrigerantes que agotan el ozono y genere listas de sustitutos aceptables e inaceptables. De aqu\xED salen las aprobaciones de nuevos A2L.&quot; }, { id:&quot;a2l_study_83&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1les refrigerantes est\xE1n regulados bajo la Secci\xF3n 608?&quot;, opciones:[&quot;Solo CFCs y HCFCs&quot;,&quot;CFCs, HCFCs, HFCs y HFOs \u2014 todos deben recuperarse&quot;,&quot;Solo los que da\xF1an el ozono&quot;,&quot;Solo los que tienen GWP>1,000&quot;], respuesta_correcta:1, explicacion:&quot;La Secci\xF3n 608 regula CFCs, HCFCs, HFCs y HFOs \u2014 todos deben recuperarse antes de hacer servicio. No est\xE1 permitido ventilar intencionalmente ninguno de estos refrigerantes bajo ninguna circunstancia.&quot; }, { id:&quot;a2l_study_84&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 cubre ASHRAE Standard 15?&quot;, opciones:[&quot;Clasificaciones de seguridad de refrigerantes&quot;,&quot;Dise\xF1o, construcci\xF3n, instalaci\xF3n y operaci\xF3n de equipos HVAC comerciales \u2014 incluye restricciones A2L&quot;,&quot;Procedimientos de recuperaci\xF3n&quot;,&quot;Certificaci\xF3n de t\xE9cnicos&quot;], respuesta_correcta:1, explicacion:&quot;ASHRAE Standard 15 cubre dise\xF1o, construcci\xF3n, instalaci\xF3n y operaci\xF3n de equipos HVAC comerciales y cuartos de m\xE1quinas. Fue actualizado para incluir restricciones espec\xEDficas para A2L.&quot; }, { id:&quot;a2l_study_85&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el prop\xF3sito espec\xEDfico de ASHRAE Standard 15.2?&quot;, opciones:[&quot;Es id\xE9ntico al 15&quot;,&quot;Standard NUEVO espec\xEDficamente para aplicaciones residenciales A2L&quot;,&quot;Cubre solo aplicaciones industriales&quot;,&quot;Cubre solo automotriz&quot;], respuesta_correcta:1, explicacion:&quot;ASHRAE Standard 15.2 fue creado espec\xEDficamente para aplicaciones residenciales de A2L. Es el companion residencial del ASHRAE 15 (comercial). Contiene restricciones para instalaci\xF3n, servicio y disposici\xF3n de A2L en viviendas.&quot; }, { id:&quot;a2l_study_86&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 establece ASHRAE Standard 34?&quot;, opciones:[&quot;Los procedimientos de instalaci\xF3n HVAC&quot;,&quot;Las designaciones y clasificaciones de seguridad (toxicidad e inflamabilidad) de refrigerantes y RCLs&quot;,&quot;Los procedimientos de recuperaci\xF3n&quot;,&quot;Los est\xE1ndares de certificaci\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;ASHRAE Standard 34 establece: designaciones num\xE9ricas de refrigerantes (ej: R-32), clasificaciones de seguridad ASHRAE (A1, A2L, A2, A3, B1, B2L, etc.), y los Refrigerant Concentration Limits (RCL) para cada refrigerante.&quot; }, { id:&quot;a2l_study_87&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 cubre UL Standard 60335-2-40 (3a edici\xF3n)?&quot;, opciones:[&quot;Equipos industriales solamente&quot;,&quot;A/C, bombas de calor y deshumidificadores \u2014 la 3a edici\xF3n (2019) agreg\xF3 especificaciones para A2L&quot;,&quot;Solo motores el\xE9ctricos&quot;,&quot;Solo equipos de refrigeraci\xF3n comercial&quot;], respuesta_correcta:1, explicacion:&quot;UL 60335-2-40, 3a edici\xF3n (2019), cubre dise\xF1o y especificaciones de prueba para A/C, bombas de calor y deshumidificadores. La 3a edici\xF3n espec\xEDficamente agreg\xF3 requerimientos para equipos con refrigerantes A2L.&quot; }, { id:&quot;a2l_study_88&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 cubre el Code of Federal Regulations T\xEDtulo 49?&quot;, opciones:[&quot;Solo transporte a\xE9reo&quot;,&quot;Transporte de materiales peligrosos incluyendo gases inflamables en TODOS los medios de transporte&quot;,&quot;Solo producci\xF3n de refrigerantes&quot;,&quot;Solo almacenamiento de qu\xEDmicos&quot;], respuesta_correcta:1, explicacion:&quot;CFR T\xEDtulo 49 (DOT) regula el transporte de HAZMAT en todos los medios \u2014 carretera, ferrocarril, aire, agua. Incluye clasificaci\xF3n, embalaje, marcado, documentaci\xF3n y capacitaci\xF3n para materiales peligrosos incluyendo gases inflamables.&quot; }, { id:&quot;a2l_study_89&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1ntos a\xF1os de vigencia tiene la certificaci\xF3n EPA 608?&quot;, opciones:[&quot;2 a\xF1os&quot;,&quot;5 a\xF1os&quot;,&quot;10 a\xF1os&quot;,&quot;Es permanente \u2014 no expira&quot;], respuesta_correcta:3, explicacion:&quot;La certificaci\xF3n EPA 608 es PERMANENTE \u2014 nunca expira. Una vez obtenida es v\xE1lida de por vida. Diferente a OSHA-10 (expira en 5 a\xF1os) o NATE (requiere renovaci\xF3n cada 2 a\xF1os).&quot; }, { id:&quot;a2l_study_90&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es la penalidad m\xE1xima por ventilar intencionalmente refrigerante?&quot;, opciones:[&quot;$500 por incidente&quot;,&quot;$5,000 por d\xEDa&quot;,&quot;$44,539 por violaci\xF3n&quot;,&quot;$10,000 por libra&quot;], respuesta_correcta:2, explicacion:&quot;La EPA puede imponer multas de hasta $44,539 por d\xEDa por cada violaci\xF3n de las regulaciones de refrigerantes de la Secci\xF3n 608. Las violaciones tambi\xE9n pueden resultar en procesamiento criminal.&quot; }, { id:&quot;a2l_study_91&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFEn qu\xE9 posici\xF3n deben almacenarse los cilindros A2L?&quot;, opciones:[&quot;Horizontal para ahorrar espacio&quot;,&quot;Vertical (upright) para que el dispositivo de alivio est\xE9 en contacto con el espacio de vapor&quot;,&quot;Cualquier posici\xF3n&quot;,&quot;Solo con cadenas de seguridad&quot;], respuesta_correcta:1, explicacion:&quot;Cilindros A2L DEBEN almacenarse VERTICALES. Esto asegura que el dispositivo de alivio de presi\xF3n est\xE9 en contacto con el espacio de vapor (no l\xEDquido). Si el dispositivo se activa sobre l\xEDquido, liberar\xEDa m\xE1s refrigerante.&quot; }, { id:&quot;a2l_study_92&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 proh\xEDbe OSHA para almacenamiento de cilindros de refrigerante inflamable?&quot;, opciones:[&quot;Almacenamiento en racks al aire libre&quot;,&quot;Almacenamiento en lockers cerrados, contenedores o espacios confinados sin ventilaci\xF3n&quot;,&quot;Almacenamiento en cuartos ventilados&quot;,&quot;Almacenamiento en el cami\xF3n de servicio&quot;], respuesta_correcta:1, explicacion:&quot;OSHA proh\xEDbe almacenar cilindros de refrigerante inflamable en lockers cerrados, contenedores o espacios confinados sin ventilaci\xF3n. Si se usa un enclosure, DEBE ser seguro y ventilado.&quot; }, { id:&quot;a2l_study_93&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 requisitos de ventilaci\xF3n aplican al almacenamiento de A2L?&quot;, opciones:[&quot;No se requiere ventilaci\xF3n especial&quot;,&quot;El \xE1rea de almacenamiento debe tener ventilaci\xF3n adecuada para prevenir acumulaci\xF3n de vapores inflamables&quot;,&quot;Solo en grandes almacenes&quot;,&quot;Solo si se almacenan m\xE1s de 100 lb&quot;], respuesta_correcta:1, explicacion:&quot;El almacenamiento de refrigerantes inflamables requiere ventilaci\xF3n adecuada para prevenir que una posible fuga cree concentraciones inflamables. La ventilaci\xF3n puede ser natural o mec\xE1nica seg\xFAn los requisitos locales.&quot; }, { id:&quot;a2l_study_94&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 placard NFPA identifica los peligros en instalaciones de almacenamiento de refrigerantes A2L?&quot;, opciones:[&quot;NFPA 10 \u2014 extinguidores&quot;,&quot;NFPA 704 \u2014 identificaci\xF3n de peligros (diamante de colores)&quot;,&quot;NFPA 13 \u2014 sprinklers&quot;,&quot;NFPA 70 \u2014 c\xF3digo el\xE9ctrico&quot;], respuesta_correcta:1, explicacion:&quot;NFPA 704 = diamante de cuatro colores: azul (health), rojo (flammability), amarillo (reactivity), blanco (special). Requerido en instalaciones de almacenamiento para identificar peligros de los materiales almacenados.&quot; }, { id:&quot;a2l_study_95&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 registros debe tener una instalaci\xF3n que almacena refrigerantes A2L?&quot;, opciones:[&quot;Solo un inventario de cantidad&quot;,&quot;Plan de Manejo de Materiales Peligrosos (HMMP), inventario HMIS, y SDS de cada refrigerante&quot;,&quot;Solo las facturas de compra&quot;,&quot;No se requieren registros especiales&quot;], respuesta_correcta:1, explicacion:&quot;Para almacenamiento de A2L se requiere: Plan de Manejo de Materiales Peligrosos (HMMP), Hazardous Materials Inventory Statement (HMIS) onsite, y hojas SDS actualizadas para cada tipo de refrigerante almacenado.&quot; }, { id:&quot;a2l_study_96&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFCu\xE1l es el extinguidor requerido en veh\xEDculos que transportan A2L seg\xFAn DOT?&quot;, opciones:[&quot;Clase A (combustibles s\xF3lidos)&quot;,&quot;Clase B (polvo seco \u2014 Dry Powder)&quot;,&quot;Clase C (el\xE9ctrico)&quot;,&quot;Cualquier extinguidor disponible&quot;], respuesta_correcta:1, explicacion:&quot;DOT requiere que los veh\xEDculos que transportan gases inflamables (incluyendo A2L) lleven extinguidor Clase B (Dry Powder). Este tipo espec\xEDfico es efectivo para gases y l\xEDquidos inflamables.&quot; }, { id:&quot;a2l_study_97&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFA qu\xE9 distancia m\xEDnima est\xE1 prohibido fumar al transportar gases inflamables seg\xFAn DOT?&quot;, opciones:[&quot;10 pies&quot;,&quot;25 pies&quot;,&quot;50 pies&quot;,&quot;100 pies&quot;], respuesta_correcta:1, explicacion:&quot;DOT proh\xEDbe fumar dentro de 25 pies de gases inflamables durante el transporte. Tambi\xE9n requiere: inventario escrito de los gases, SDS para cada refrigerante, y medidas de seguridad contra acceso no autorizado.&quot; }, { id:&quot;a2l_study_98&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFEn qu\xE9 posici\xF3n pueden transportarse los cilindros A2L en veh\xEDculos de servicio?&quot;, opciones:[&quot;Solo vertical&quot;,&quot;Solo horizontal con valva hacia arriba&quot;,&quot;Pueden transportarse horizontalmente \u2014 la v\xE1lvula de alivio debe estar en posici\xF3n 12 en punto&quot;,&quot;En cualquier posici\xF3n&quot;], respuesta_correcta:2, explicacion:&quot;Los cilindros A2L PUEDEN transportarse horizontalmente (caben en los racks est\xE1ndar de los camiones de servicio). La mejor pr\xE1ctica es asegurarse de que la v\xE1lvula de alivio est\xE9 en posici\xF3n de 12 en punto (hacia arriba).&quot; }, { id:&quot;a2l_study_99&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFPor qu\xE9 los cilindros A2L requieren v\xE1lvula de alivio en lugar de disco de ruptura?&quot;, opciones:[&quot;Solo por regulaci\xF3n cosm\xE9tica&quot;,&quot;La v\xE1lvula abre y CIERRA \u2014 previene liberaci\xF3n total del contenido. El disco se destruye permanentemente liberando todo el contenido&quot;,&quot;Son m\xE1s baratas de fabricar&quot;,&quot;No hay diferencia pr\xE1ctica&quot;], respuesta_correcta:1, explicacion:&quot;V\xE1lvula de alivio: ABRE cuando la presi\xF3n excede el l\xEDmite y CIERRA cuando baja \u2014 previene liberaci\xF3n total. Disco de ruptura: se destruye permanentemente al activarse liberando todo el contenido. Para A2L inflamables, la v\xE1lvula es mucho m\xE1s segura.&quot; }, { id:&quot;a2l_study_100&quot;, categoria:&quot;A2L_N1&quot;, nivel:1, pregunta:&quot;\xBFQu\xE9 regulaciones adem\xE1s del DOT pueden aplicar al transporte de A2L en algunos estados?&quot;, opciones:[&quot;Solo el DOT aplica \u2014 los estados no pueden regular m\xE1s&quot;,&quot;Algunos estados requieren placards en el veh\xEDculo y ventilaci\xF3n adicional dependiendo del volumen transportado&quot;,&quot;Los estados no pueden regular el transporte de refrigerantes&quot;,&quot;Solo aplica en California&quot;], respuesta_correcta:1, explicacion:&quot;Adem\xE1s del DOT federal, ALGUNOS ESTADOS pueden requerir placards adicionales en el veh\xEDculo y/o ventilaci\xF3n dependiendo del volumen de gas inflamable transportado. SIEMPRE verificar regulaciones estatales y locales adem\xE1s del DOT.&quot; }, { id:&quot;a2l_study_101&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un t\xE9cnico llega a servicio de un minisplit que usa R-32. \xBFCu\xE1l es el PRIMER paso antes de abrir el sistema?&quot;, opciones:[&quot;Conectar el manifold inmediatamente&quot;,&quot;Evaluar el \xE1rea para fuentes de ignici\xF3n, ventilar el espacio, y tener el extinguidor listo antes de comenzar&quot;,&quot;Solo apagar el equipo&quot;,&quot;Solo revisar el termostato&quot;], respuesta_correcta:1, explicacion:&quot;PRIMERO: evaluar el \xE1rea para fuentes de ignici\xF3n (chispas, llamas, superficies calientes), asegurar ventilaci\xF3n adecuada, y tener el extinguidor Clase B disponible. Solo entonces comenzar el trabajo con el sistema A2L.&quot; }, { id:&quot;a2l_study_102&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo determinas si un sistema residencial nuevo usa R-454B o R-410A?&quot;, opciones:[&quot;Por el color del equipo&quot;,&quot;Por la placa de datos (nameplate) del equipo \u2014 siempre indica el tipo de refrigerante&quot;,&quot;Por el color de las mangueras del manifold&quot;,&quot;Por el a\xF1o de fabricaci\xF3n solamente&quot;], respuesta_correcta:1, explicacion:&quot;La placa de datos (nameplate) del equipo SIEMPRE indica el tipo de refrigerante, la carga en oz/lb, y otras especificaciones. Es la fuente definitiva \u2014 nunca asumir el refrigerante sin verificar la placa.&quot; }, { id:&quot;a2l_study_103&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un sistema R-454B tiene presi\xF3n de succi\xF3n de 112 PSI. La l\xEDnea de succi\xF3n mide 55\xB0F. \xBFCu\xE1l es el superheat?&quot;, opciones:[&quot;No se puede calcular con A2L&quot;,&quot;Superheat = 55\xB0F - 45\xB0F = 10\xB0F (usando la tabla P/T vapor del R-454B)&quot;,&quot;Superheat = 55\xB0F - 40\xB0F = 15\xB0F&quot;,&quot;Los A2L no tienen superheat&quot;], respuesta_correcta:1, explicacion:&quot;Para mezclas zeotr\xF3picas como R-454B: usar la columna VAPOR (dew point) de la tabla P/T para calcular superheat. A 112 PSI vapor \u2248 45\xB0F de saturaci\xF3n. Superheat = 55\xB0F - 45\xB0F = 10\xB0F.&quot; }, { id:&quot;a2l_study_104&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Al cargar R-454B, \xBFen qu\xE9 posici\xF3n debe estar el cilindro y en qu\xE9 estado debe estar el refrigerante?&quot;, opciones:[&quot;Cilindro vertical, cargar en gas&quot;,&quot;Cilindro invertido, cargar en L\xCDQUIDO para prevenir fraccionamiento&quot;,&quot;Cilindro en cualquier posici\xF3n, gas o l\xEDquido igual&quot;,&quot;Cilindro horizontal, cargar en gas&quot;], respuesta_correcta:1, explicacion:&quot;R-454B debe cargarse en L\xCDQUIDO para prevenir fraccionamiento. Para obtener l\xEDquido del cilindro: invertirlo (si es cilindro sin dip tube) o usar el dip tube si lo tiene. Luego controlar el flujo con la v\xE1lvula del manifold.&quot; }, { id:&quot;a2l_study_105&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un sistema R-32 tiene superheat de evaporador de 5\xB0F. \xBFQu\xE9 indica esto?&quot;, opciones:[&quot;El sistema est\xE1 perfectamente cargado&quot;,&quot;El superheat est\xE1 demasiado BAJO \u2014 riesgo de que refrigerante l\xEDquido llegue al compresor&quot;,&quot;El sistema necesita m\xE1s refrigerante&quot;,&quot;El condensador est\xE1 sucio&quot;], respuesta_correcta:1, explicacion:&quot;Superheat de 5\xB0F es DEMASIADO BAJO. El sistema necesita suficiente superheat (t\xEDpicamente 8-15\xB0F para sistemas residenciales) para asegurar que solo vapor seco llega al compresor. L\xEDquido al compresor puede causar falla catastr\xF3fica.&quot; }, { id:&quot;a2l_study_106&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 puede indicar burbujas en la mirilla (sight glass) de un sistema R-454B en operaci\xF3n normal?&quot;, opciones:[&quot;El sistema funciona perfectamente&quot;,&quot;Refrigerante insuficiente (bajo subcooling o baja carga)&quot;,&quot;El sistema tiene exceso de refrigerante&quot;,&quot;Las burbujas son normales en A2L&quot;], respuesta_correcta:1, explicacion:&quot;Burbujas en la mirilla indican que el refrigerante llega en mezcla gas-l\xEDquido a la v\xE1lvula de expansi\xF3n \u2014 generalmente por BAJA CARGA de refrigerante o subcooling insuficiente. Investigar causa antes de a\xF1adir refrigerante.&quot; }, { id:&quot;a2l_study_107&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es el indicador visual de que un cilindro A2L tiene refrigerante inflamable?&quot;, opciones:[&quot;Color azul del cilindro&quot;,&quot;Banda roja en la parte superior del cilindro&quot;,&quot;Etiqueta amarilla&quot;,&quot;No hay indicador visual est\xE1ndar&quot;], respuesta_correcta:1, explicacion:&quot;Los cilindros con refrigerante inflamable DEBEN tener una BANDA ROJA en la parte superior. AHRI Guideline N establece que todos los cilindros deben ser color gris/verde claro, pero los inflamables a\xF1aden la banda roja.&quot; }, { id:&quot;a2l_study_108&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un t\xE9cnico descubre que un sistema nuevo R-454B tiene una presi\xF3n de baja de 80 PSI y la temperatura de saturaci\xF3n correspondiente es 30\xB0F. La l\xEDnea de succi\xF3n mide 45\xB0F. \xBFCu\xE1l es el superheat?&quot;, opciones:[&quot;15\xB0F&quot;,&quot;25\xB0F&quot;,&quot;30\xB0F&quot;,&quot;45\xB0F&quot;], respuesta_correcta:0, explicacion:&quot;Superheat = temperatura de l\xEDnea de succi\xF3n - temperatura de saturaci\xF3n = 45\xB0F - 30\xB0F = 15\xB0F. Este valor (15\xB0F) est\xE1 dentro del rango normal t\xEDpico para sistemas residenciales (8-20\xB0F depending on system).&quot; }, { id:&quot;a2l_study_109&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Al revisar un sistema R-32, la presi\xF3n de alta es 350 PSI y la temperatura de la l\xEDnea l\xEDquida es 95\xB0F. La temperatura de saturaci\xF3n a 350 PSI es 110\xB0F. \xBFCu\xE1l es el subcooling?&quot;, opciones:[&quot;15\xB0F&quot;,&quot;25\xB0F&quot;,&quot;5\xB0F&quot;,&quot;110\xB0F&quot;], respuesta_correcta:0, explicacion:&quot;Subcooling = temperatura de saturaci\xF3n - temperatura de l\xEDnea l\xEDquida = 110\xB0F - 95\xB0F = 15\xB0F. Un subcooling de 15\xB0F es t\xEDpicamente bueno para sistemas residenciales, indicando que hay suficiente l\xEDquido subenfriado llegando a la v\xE1lvula de expansi\xF3n.&quot; }, { id:&quot;a2l_study_110&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 precauci\xF3n especial aplica cuando uses soplete para soldar en un sistema que previamente ten\xEDa R-32?&quot;, opciones:[&quot;Ninguna \u2014 solo soldar normalmente&quot;,&quot;Recuperar el R-32, hacer nitrogen sweep, verificar con detector de gases que el \xE1rea est\xE9 libre de vapores antes de usar soplete&quot;,&quot;Solo apagar el sistema&quot;,&quot;Solo asegurarse de que no haya fugas&quot;], respuesta_correcta:1, explicacion:&quot;Antes de soldar en sistema previo con R-32: (1) recuperar completamente, (2) nitrogen sweep para desplazar vapores en el aceite, (3) verificar con detector que el \xE1rea est\xE9 libre de vapores inflamables. El aceite POE puede retener R-32 que se libera con el calor.&quot; }, { id:&quot;a2l_study_111&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo calculas el peso m\xE1ximo que puedes poner en un cilindro de recuperaci\xF3n?&quot;, opciones:[&quot;El cilindro puede llenarse completamente&quot;,&quot;(Water Capacity \xD7 0.80) + Tare Weight = peso m\xE1ximo total del cilindro&quot;,&quot;Solo pesar el refrigerante recuperado&quot;,&quot;No es necesario calcular \u2014 la m\xE1quina para autom\xE1ticamente&quot;], respuesta_correcta:1, explicacion:&quot;F\xF3rmula: (WC \xD7 0.80) + TW = peso m\xE1ximo permitido. WC (Water Capacity) y TW (Tare Weight) est\xE1n estampados en el collar del cilindro. El 80% asegura espacio para expansi\xF3n del refrigerante.&quot; }, { id:&quot;a2l_study_112&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 indican las letras 'WC' y 'TW' en el collar de un cilindro DOT?&quot;, opciones:[&quot;Working Capacity y Total Weight&quot;,&quot;Water Capacity (capacidad de agua en lbs) y Tare Weight (peso del cilindro vac\xEDo)&quot;,&quot;Work Condition y Transfer Weight&quot;,&quot;Weight Certified y Tank Weight&quot;], respuesta_correcta:1, explicacion:&quot;WC = Water Capacity (capacidad de agua en lbs) \u2014 indica el volumen del cilindro. TW = Tare Weight (peso del cilindro vac\xEDo en lbs). Estos dos valores se usan para calcular cu\xE1nto refrigerante puede caber.&quot; }, { id:&quot;a2l_study_113&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 debe hacer el t\xE9cnico si el sistema de A2L tiene fuga activa al llegar al trabajo?&quot;, opciones:[&quot;Comenzar el trabajo con cuidado extra&quot;,&quot;EVACUAR el \xE1rea, VENTILAR, verificar que est\xE9 libre de fuentes de ignici\xF3n y vapores inflamables antes de regresar a dar servicio&quot;,&quot;Solo abrir ventanas y continuar&quot;,&quot;Solo apagar el equipo&quot;], respuesta_correcta:1, explicacion:&quot;Con fuga activa de A2L: EVACUAR inmediatamente, VENTILAR el \xE1rea, y verificar con detector de gases que el \xE1rea est\xE9 libre de vapores inflamables Y fuentes de ignici\xF3n antes de regresar. No asumir que la concentraci\xF3n es segura.&quot; }, { id:&quot;a2l_study_114&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo verificas con un detector electr\xF3nico que el \xE1rea est\xE1 libre de vapores A2L antes de usar soplete?&quot;, opciones:[&quot;No es posible verificar con detector \u2014 solo confiar en el olfato&quot;,&quot;Usar el detector en modo refrigerante, revisar m\xFAltiples puntos bajos del \xE1rea (los vapores se acumulan en puntos bajos)&quot;,&quot;Solo verificar cerca del equipo&quot;,&quot;Los detectores no funcionan para A2L&quot;], respuesta_correcta:1, explicacion:&quot;Los vapores de A2L son m\xE1s pesados que el aire y se acumulan en PUNTOS BAJOS. Verificar con detector en los puntos m\xE1s bajos del \xE1rea (pisos, rincones, s\xF3tanos) antes de usar soplete o cualquier fuente de ignici\xF3n.&quot; }, { id:&quot;a2l_study_115&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 herramienta usa el t\xE9cnico para verificar que el sistema A2L tiene voltaje CERO antes de trabajar?&quot;, opciones:[&quot;Solo el interruptor del panel&quot;,&quot;Mult\xEDmetro para verificar ausencia de voltaje \u2014 despu\xE9s del lockout/tagout&quot;,&quot;El term\xF3metro digital&quot;,&quot;El medidor de presi\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;OBLIGATORIO: despu\xE9s de aplicar lockout/tagout (LOTO), verificar con MULT\xCDMETRO que NO hay voltaje presente. El t\xE9cnico debe tener la \xFAnica llave del candado LOTO. Nunca asumir que el sistema est\xE1 de-energizado solo porque el switch est\xE1 apagado.&quot; }, { id:&quot;a2l_study_116&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un t\xE9cnico nota que un sistema R-454B nuevo del a\xF1o pasado ya necesita recarga por segunda vez. \xBFQu\xE9 debe hacer?&quot;, opciones:[&quot;Recargar \u2014 es normal en sistemas nuevos&quot;,&quot;Encontrar y reparar la fuga ANTES de recargar \u2014 recargar sin reparar viola regulaciones de fuga&quot;,&quot;Solo a\xF1adir la cantidad perdida&quot;,&quot;Reemplazar el compresor&quot;], respuesta_correcta:1, explicacion:&quot;Recargar sin reparar la fuga viola las regulaciones EPA. PRIMERO localizar y reparar la fuga, LUEGO recargar. Un sistema que necesita recarga frecuente es evidencia de fuga \u2014 legalmente debe repararse.&quot; }, { id:&quot;a2l_study_117&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 s\xEDmbolo ISO debe aparecer en la placa del equipo cuando usa refrigerante inflamable?&quot;, opciones:[&quot;ISO 9001 \u2014 calidad&quot;,&quot;ISO 7010-W021 \u2014 s\xEDmbolo de llama (tri\xE1ngulo amarillo con llama)&quot;,&quot;ISO 14001 \u2014 ambiental&quot;,&quot;No se requiere s\xEDmbolo especial&quot;], respuesta_correcta:1, explicacion:&quot;El s\xEDmbolo ISO 7010-W021 (tri\xE1ngulo amarillo con llama negra) DEBE estar en la placa de datos de equipos con refrigerante inflamable, cerca de donde se indica el tipo y cantidad de refrigerante.&quot; }, { id:&quot;a2l_study_118&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 debe escribir el t\xE9cnico en la etiqueta del equipo cuando va a desechar un sistema A2L?&quot;, opciones:[&quot;Nada \u2014 no se requiere documentaci\xF3n para desecho&quot;,&quot;Que el equipo fue descomisionado y el refrigerante fue recuperado, con fecha y firma del t\xE9cnico&quot;,&quot;Solo el n\xFAmero de serie&quot;,&quot;Solo la fecha&quot;], respuesta_correcta:1, explicacion:&quot;Al descomisionar equipo A2L: la etiqueta DEBE indicar que fue descomisionado y el refrigerante fue recuperado. Debe estar fechada y firmada por el t\xE9cnico. Esta documentaci\xF3n es legalmente requerida.&quot; }, { id:&quot;a2l_study_119&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 deben incluir los componentes de reemplazo para un sistema A2L en campo?&quot;, opciones:[&quot;Cualquier componente del mismo tama\xF1o f\xEDsico&quot;,&quot;Solo partes OEM especificadas por el fabricante \u2014 certificadas para operar en ambiente A2L inflamable&quot;,&quot;Cualquier componente certificado UL&quot;,&quot;Solo verificar que el voltaje sea correcto&quot;], respuesta_correcta:1, explicacion:&quot;SOLO partes OEM del fabricante. Partes de terceros no certificadas para A2L pueden no estar dise\xF1adas para operar seguramente en ambiente inflamable y podr\xEDan convertirse en fuente de ignici\xF3n si fallan.&quot; }, { id:&quot;a2l_study_120&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo debe descargarse un capacitor en un sistema A2L para evitar riesgo de ignici\xF3n?&quot;, opciones:[&quot;Con destornillador directamente en los terminales \u2014 m\xE1s r\xE1pido&quot;,&quot;Con resistor o herramienta de descarga que no genere chispa&quot;,&quot;No es necesario descargarlo&quot;,&quot;Solo esperar que se descargue solo con tiempo&quot;], respuesta_correcta:1, explicacion:&quot;En sistemas A2L, el cortocircuito directo del capacitor con destornillador est\xE1 PROHIBIDO \u2014 genera chispa que puede encender el refrigerante. Usar un resistor o descargador especial que disipe la energ\xEDa sin chispa.&quot; }, { id:&quot;a2l_study_121&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un sistema R-32 tiene presi\xF3n de baja muy alta y presi\xF3n de alta baja. \xBFQu\xE9 componente es sospechoso?&quot;, opciones:[&quot;Compresor en perfectas condiciones&quot;,&quot;V\xE1lvulas del compresor defectuosas o compresor con p\xE9rdida de compresi\xF3n&quot;,&quot;TXV atascada cerrada&quot;,&quot;Condensador sucio&quot;], respuesta_correcta:1, explicacion:&quot;Presiones de baja alta Y alta baja simult\xE1neamente indica que el compresor no est\xE1 comprimiendo efectivamente \u2014 v\xE1lvulas del compresor defectuosas o p\xE9rdida de compresi\xF3n interna. El compresor no puede crear la diferencia de presi\xF3n necesaria.&quot; }, { id:&quot;a2l_study_122&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un sistema R-454B tiene presiones normales pero la temperatura de salida de aire es m\xE1s alta de lo normal. \xBFQu\xE9 verificar primero?&quot;, opciones:[&quot;Agregar refrigerante inmediatamente&quot;,&quot;Verificar el airflow (flujo de aire) \u2014 puede estar restringido por filtro sucio, bobina congelada, o ventilador defectuoso&quot;,&quot;Reemplazar el compresor&quot;,&quot;Verificar el termostato&quot;], respuesta_correcta:1, explicacion:&quot;Si las presiones son normales pero el enfriamiento es insuficiente, el problema m\xE1s probable es AIRFLOW restringido: filtro sucio, bobina congelada, ventilador que no gira correctamente, o ductos obstruidos. Verificar airflow antes de asumir problemas de refrigerante.&quot; }, { id:&quot;a2l_study_123&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 indica una temperatura de suction line muy caliente (alto superheat de sistema) en un sistema R-32?&quot;, opciones:[&quot;El sistema tiene exceso de refrigerante&quot;,&quot;El sistema est\xE1 bajo en refrigerante \u2014 la l\xEDnea de succi\xF3n se calienta porque el refrigerante se vaporiz\xF3 antes del final del evaporador&quot;,&quot;El condensador est\xE1 trabajando bien&quot;,&quot;El compresor est\xE1 en buen estado&quot;], respuesta_correcta:1, explicacion:&quot;Alto superheat de sistema generalmente indica BAJA CARGA de refrigerante. El refrigerante se evapora antes de llegar al final del evaporador, y el vapor restante se sigue calentando (superheating) en el evaporador y la l\xEDnea de succi\xF3n.&quot; }, { id:&quot;a2l_study_124&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 causa presi\xF3n de alta excesivamente elevada en un sistema R-454B funcionando?&quot;, opciones:[&quot;Baja carga de refrigerante&quot;,&quot;Condensador sucio/bloqueado, exceso de refrigerante, o presencia de no-condensables (aire)&quot;,&quot;Compresor defectuoso&quot;,&quot;TXV mal calibrada&quot;], respuesta_correcta:1, explicacion:&quot;Presi\xF3n de alta excesiva puede ser por: condensador sucio/bloqueado (m\xE1s com\xFAn), exceso de carga de refrigerante, presencia de no-condensables (aire en el sistema), o temperatura ambiente extremadamente alta.&quot; }, { id:&quot;a2l_study_125&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo distingues una fuga de A2L de una fuga de A1 durante diagn\xF3stico?&quot;, opciones:[&quot;No hay diferencia \u2014 mismo proceso&quot;,&quot;Mismos m\xE9todos de detecci\xF3n, pero debes usar detector espec\xEDfico para el refrigerante del sistema Y tomar precauciones extra de seguridad antes de iniciar&quot;,&quot;Los A2L no se pueden detectar con detector electr\xF3nico&quot;,&quot;Los A2L son indetectables&quot;], respuesta_correcta:1, explicacion:&quot;Los m\xE9todos de detecci\xF3n son similares (detector electr\xF3nico, agua jabonosa, UV), pero: (1) usar detector certificado para el refrigerante espec\xEDfico, (2) verificar el \xE1rea para fuentes de ignici\xF3n ANTES de iniciar la b\xFAsqueda de fugas, (3) los vapores A2L se acumulan en puntos bajos.&quot; }, { id:&quot;a2l_study_126&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 indica una presi\xF3n de baja negativamente baja (vac\xEDo) en un sistema en funcionamiento?&quot;, opciones:[&quot;El sistema funciona perfectamente&quot;,&quot;Posibles causas: refrigerante muy bajo, TXV atascada cerrada, o filtro drier muy restringido&quot;,&quot;El compresor est\xE1 fallando&quot;,&quot;El condensador est\xE1 sucio&quot;], respuesta_correcta:1, explicacion:&quot;Presi\xF3n de baja bajo lo normal o negativa indica restricci\xF3n severa en el lado de baja: filtro drier bloqueado, TXV atascada cerrada, refrigerante extremadamente bajo, o l\xEDnea de l\xEDquido restringida. Diagnosticar y eliminar cada posibilidad.&quot; }, { id:&quot;a2l_study_127&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 es el 'hunting' de una TXV y c\xF3mo se manifiesta en las presiones?&quot;, opciones:[&quot;Cuando el t\xE9cnico no puede encontrar la v\xE1lvula&quot;,&quot;Cuando la TXV oscila constantemente abriendo y cerrando \u2014 las presiones fluct\xFAan continuamente sin estabilizarse&quot;,&quot;Solo ocurre en sistemas A2L&quot;,&quot;Una v\xE1lvula que est\xE1 atascada cerrada&quot;], respuesta_correcta:1, explicacion:&quot;TXV 'hunting' = la v\xE1lvula oscila (abre/cierra) continuamente sin estabilizarse, causando fluctuaciones constantes en las presiones del sistema. Puede indicar: TXV sobredimensionada, bulbo de la TXV mal posicionado, o superheat incorrectamente ajustado.&quot; }, { id:&quot;a2l_study_128&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo verificas si hay no-condensables (aire) en un sistema de A2L?&quot;, opciones:[&quot;No se puede verificar en campo&quot;,&quot;Comparar la presi\xF3n del sistema APAGADO y estabilizado con la presi\xF3n de saturaci\xF3n de la tabla P/T a la temperatura ambiente \u2014 si la presi\xF3n es mayor, hay no-condensables&quot;,&quot;Solo enviar el refrigerante al laboratorio&quot;,&quot;Los no-condensables no afectan los A2L&quot;], respuesta_correcta:1, explicacion:&quot;Con el sistema APAGADO y estabilizado (presi\xF3n igual en alta y baja): verificar la presi\xF3n de saturaci\xF3n de la tabla P/T a la temperatura ambiente actual. Si la presi\xF3n del sistema es MAYOR que la de saturaci\xF3n, hay no-condensables (aire) en el sistema.&quot; }, { id:&quot;a2l_study_129&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Un sistema R-32 tiene subcooling de 2\xB0F. \xBFQu\xE9 problema puede indicar?&quot;, opciones:[&quot;Subcooling excelente&quot;,&quot;Subcooling demasiado bajo \u2014 puede indicar baja carga de refrigerante o problema en el condensador&quot;,&quot;Subcooling demasiado alto&quot;,&quot;No hay problema con 2\xB0F&quot;], respuesta_correcta:1, explicacion:&quot;Subcooling de 2\xB0F es DEMASIADO BAJO. El subcooling insuficiente indica que el refrigerante no est\xE1 completamente subenfriado como l\xEDquido \u2014 puede haber burbujas de vapor en la l\xEDnea l\xEDquida causando ineficiencia y posible da\xF1o a la TXV.&quot; }, { id:&quot;a2l_study_130&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 indica un compresor que cicla frecuentemente (on/off) en un sistema R-454B?&quot;, opciones:[&quot;Funcionamiento normal&quot;,&quot;Posibles causas: sistema sobredimensionado, refrigerante incorrecto, presostato defectuoso, o problema de carga de calor insuficiente&quot;,&quot;El compresor est\xE1 en perfectas condiciones&quot;,&quot;Solo indica cambios de temperatura ambiente&quot;], respuesta_correcta:1, explicacion:&quot;Ciclado frecuente puede indicar: sistema sobredimensionado para el espacio, refrigerante incorrecto en el sistema, presostato o termostato defectuoso, o carga de calor insuficiente para el tama\xF1o del sistema.&quot; }, { id:&quot;a2l_study_131&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1les son los tres m\xE9todos principales para cargar un sistema de refrigeraci\xF3n?&quot;, opciones:[&quot;Solo por peso con escala&quot;,&quot;Carga cr\xEDtica por peso (escala), por superheat, y por subcooling&quot;,&quot;Solo por superheat&quot;,&quot;Solo leer las presiones del manifold&quot;], respuesta_correcta:1, explicacion:&quot;Los tres m\xE9todos principales son: (1) Carga cr\xEDtica por peso \u2014 m\xE1s precisa, especialmente para sistemas nuevos, (2) Por superheat \u2014 usa tabla de superheat del fabricante, (3) Por subcooling \u2014 usa tabla de subcooling del fabricante. El fabricante especifica cu\xE1l usar para su sistema.&quot; }, { id:&quot;a2l_study_132&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPara qu\xE9 tipo de sistema es m\xE1s apropiado el m\xE9todo de carga por SUPERHEAT?&quot;, opciones:[&quot;Sistemas con TXV&quot;,&quot;Sistemas con dispositivos de metering fijos (pist\xF3n/cap tube) en condiciones est\xE1ndar&quot;,&quot;Sistemas comerciales grandes&quot;,&quot;Sistemas A2L \xFAnicamente&quot;], respuesta_correcta:1, explicacion:&quot;El m\xE9todo de carga por superheat es m\xE1s apropiado para sistemas con dispositivos de metering FIJO (pist\xF3n o cap tube), donde la carga correcta se refleja en el superheat de evaporador. Los sistemas con TXV generalmente se cargan por subcooling.&quot; }, { id:&quot;a2l_study_133&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 el m\xE9todo de carga por peso es especialmente importante en sistemas nuevos A2L?&quot;, opciones:[&quot;Solo porque es m\xE1s r\xE1pido&quot;,&quot;Los A2L tienen restricciones de carga m\xE1xima \u2014 la carga exacta del fabricante asegura no exceder l\xEDmites de seguridad y garant\xEDa&quot;,&quot;El peso no importa para A2L&quot;,&quot;Solo para sistema de 3 toneladas o m\xE1s&quot;], respuesta_correcta:1, explicacion:&quot;Los sistemas A2L tienen restricciones de carga m\xE1xima (m1 o m2) basadas en el volumen del espacio. La carga exacta del fabricante (por peso) asegura: (1) m\xE1xima eficiencia, (2) no exceder l\xEDmites de seguridad de A2L, y (3) mantener la garant\xEDa del fabricante.&quot; }, { id:&quot;a2l_study_134&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 verifica el t\xE9cnico ANTES de cargar un sistema A2L para asegurar que el airflow es correcto?&quot;, opciones:[&quot;Nada \u2014 cargar directamente&quot;,&quot;Verificar el airflow seg\xFAn los requisitos del fabricante antes de cargar&quot;,&quot;Solo verificar que el filtro est\xE9 limpio&quot;,&quot;Solo medir la temperatura de salida de aire&quot;], respuesta_correcta:1, explicacion:&quot;ANTES de cargar: verificar que el airflow del sistema coincide con los requisitos del fabricante. Un airflow incorrecto afectar\xE1 tanto el superheat como el subcooling, dando lecturas falsas que llevar\xEDan a una carga incorrecta.&quot; }, { id:&quot;a2l_study_135&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 es el 'critical charge' y cu\xE1ndo se usa?&quot;, opciones:[&quot;La carga m\xE1xima permitida por EPA&quot;,&quot;Cargar el sistema por peso exactamente seg\xFAn especificaciones del fabricante \u2014 especialmente importante en sistemas con l\xEDneas de longitud espec\xEDfica&quot;,&quot;La carga de emergencia cuando el sistema pierde todo el refrigerante&quot;,&quot;Solo para sistemas de muy alta presi\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;Critical charge = cargar por peso exactamente la cantidad especificada por el fabricante. Es el m\xE9todo m\xE1s preciso y especialmente importante para: sistemas nuevos A2L, sistemas con longitud espec\xEDfica de l\xEDneas de tuber\xEDa, o sistemas donde el fabricante lo especifique.&quot; }, { id:&quot;a2l_study_136&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1ndo se recomienda a\xF1adir refrigerante con el cilindro en ICE (hielo) durante recuperaci\xF3n?&quot;, opciones:[&quot;Siempre \u2014 el hielo es mejor&quot;,&quot;Para acelerar la recuperaci\xF3n poniendo el cilindro en hielo, bajando su presi\xF3n interna y creando mayor diferencia de presi\xF3n para transferencia&quot;,&quot;Solo para sistemas muy grandes&quot;,&quot;Solo cuando hace calor extremo&quot;], respuesta_correcta:1, explicacion:&quot;Colocar el cilindro de recuperaci\xF3n en hielo durante la recuperaci\xF3n baja su temperatura y presi\xF3n interna. Esto crea mayor diferencia de presi\xF3n entre el sistema y el cilindro, acelerando el proceso de recuperaci\xF3n.&quot; }, { id:&quot;a2l_study_137&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es la diferencia entre 'subcooling de condensador' y 'subcooling de sistema'?&quot;, opciones:[&quot;Son exactamente lo mismo&quot;,&quot;Subcooling de condensador = medido en la salida del condensador. Subcooling de sistema = puede diferir por p\xE9rdidas de presi\xF3n en la l\xEDnea l\xEDquida&quot;,&quot;El de sistema siempre es mayor&quot;,&quot;Solo aplica a sistemas A1&quot;], respuesta_correcta:1, explicacion:&quot;Subcooling de condensador = temperatura de saturaci\xF3n (alta) - temperatura de l\xEDnea l\xEDquida en la SALIDA del condensador. Subcooling de sistema puede ser diferente si se mide en otro punto de la l\xEDnea l\xEDquida donde la presi\xF3n ya cay\xF3.&quot; }, { id:&quot;a2l_study_138&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 le indica al t\xE9cnico una lectura de SUBCOOLING alta en un sistema R-32?&quot;, opciones:[&quot;El sistema est\xE1 perfectamente cargado&quot;,&quot;Posible sobrecarga de refrigerante o condensador muy eficiente (temperatura ambiente baja)&quot;,&quot;El sistema necesita m\xE1s refrigerante&quot;,&quot;El compresor est\xE1 fallando&quot;], respuesta_correcta:1, explicacion:&quot;Subcooling alto puede indicar: sobrecarga de refrigerante (a\xF1adir m\xE1s refrigerante del especificado), temperatura ambiente muy baja (condensaci\xF3n m\xE1s eficiente), o condensador sobredimensionado para las condiciones actuales.&quot; }, { id:&quot;a2l_study_139&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Al a\xF1adir R-32 a un sistema que perdi\xF3 refrigerante por fuga reparada, \xBFc\xF3mo cargas correctamente?&quot;, opciones:[&quot;A\xF1adir hasta que las presiones parezcan normales&quot;,&quot;Primero reparar la fuga, luego cargar por peso la diferencia (cantidad especificada por fabricante menos lo que qued\xF3)&quot;,&quot;A\xF1adir un poco y ver c\xF3mo funciona&quot;,&quot;Solo cargar hasta que desaparezcan las burbujas en la mirilla&quot;], respuesta_correcta:1, explicacion:&quot;Proceso correcto: (1) PRIMERO reparar y verificar la fuga, (2) medir cu\xE1nto refrigerante queda si es posible, (3) cargar la diferencia para alcanzar la carga total especificada por el fabricante. Si no se puede medir el residual, recuperar todo y recargar completamente.&quot; }, { id:&quot;a2l_study_140&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 el airflow incorrecto hace que el diagn\xF3stico de carga de refrigerante sea dif\xEDcil?&quot;, opciones:[&quot;No tiene efecto en el diagn\xF3stico&quot;,&quot;El airflow inadecuado cambia el superheat y subcooling de manera similar a una carga incorrecta, pudiendo llevar a diagn\xF3stico err\xF3neo&quot;,&quot;Solo afecta el confort, no el diagn\xF3stico&quot;,&quot;Solo en sistemas A2L&quot;], respuesta_correcta:1, explicacion:&quot;Airflow bajo causa superheat alto (similar a baja carga) y airflow alto causa superheat bajo (similar a sobrecarga). Siempre verificar airflow ANTES de diagnosticar la carga de refrigerante para evitar a\xF1adir o quitar refrigerante innecesariamente.&quot; }, { id:&quot;a2l_study_141&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es el objetivo de la evacuaci\xF3n (pulling vacuum) antes de cargar refrigerante?&quot;, opciones:[&quot;Solo verificar que no hay fugas&quot;,&quot;Remover aire, humedad y otros no-condensables del sistema que da\xF1ar\xEDan el refrigerante y los componentes&quot;,&quot;Solo verificar que el sistema est\xE1 bien instalado&quot;,&quot;Reducir la presi\xF3n para cargar m\xE1s refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;La evacuaci\xF3n remueve: (1) aire y no-condensables (que elevan artificialmente la presi\xF3n de alta), (2) humedad (que reacciona con el refrigerante y aceite formando \xE1cidos corrosivos). El \xFAnico objeto en el sistema debe ser refrigerante y aceite.&quot; }, { id:&quot;a2l_study_142&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 son los 'no-condensables' en el contexto de sistemas HVAC?&quot;, opciones:[&quot;Aceites que no se condensan&quot;,&quot;Gases (principalmente aire y nitr\xF3geno) que no se condensan a vapor en el ciclo de refrigeraci\xF3n \u2014 causan presiones altas artificialmente&quot;,&quot;Refrigerante en estado vapor&quot;,&quot;Contaminantes s\xF3lidos&quot;], respuesta_correcta:1, explicacion:&quot;No-condensables = gases que no se condensan en el ciclo de refrigeraci\xF3n (principalmente aire y nitr\xF3geno). Si est\xE1n en el sistema, se acumulan en el condensador elevando artificialmente la presi\xF3n de alta, reduciendo eficiencia y potencialmente da\xF1ando el compresor.&quot; }, { id:&quot;a2l_study_143&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 fen\xF3meno ocurre con el agua durante una evacuaci\xF3n profunda?&quot;, opciones:[&quot;El agua se congela y queda en el sistema&quot;,&quot;La presi\xF3n reducida baja el punto de ebullici\xF3n del agua a temperatura ambiente, permitiendo que se evapore y sea removida por la bomba de vac\xEDo&quot;,&quot;El agua no puede removerse por vac\xEDo&quot;,&quot;El agua solo se remueve con calor&quot;], respuesta_correcta:1, explicacion:&quot;En un vac\xEDo profundo, el punto de ebullici\xF3n del agua baja dr\xE1sticamente (el agua hierve a temperatura ambiente bajo 500 micrones). Esto permite que la humedad se evapore y sea removida por la bomba de vac\xEDo \u2014 el proceso de DEHYDRATION.&quot; }, { id:&quot;a2l_study_144&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1les son las dos etapas de la evacuaci\xF3n?&quot;, opciones:[&quot;Solo una etapa: vac\xEDo profundo&quot;,&quot;Degassing (remoci\xF3n de aire y no-condensables) primero, luego Dehydration (remoci\xF3n de humedad)&quot;,&quot;Dehydration primero, luego Degassing&quot;,&quot;Solo la etapa final de 500 micrones&quot;], respuesta_correcta:1, explicacion:&quot;Evacuaci\xF3n en dos etapas: (1) DEGASSING \u2014 remoci\xF3n de aire y no-condensables mientras la presi\xF3n baja hasta ~5,000 micrones, (2) DEHYDRATION \u2014 remoci\xF3n de humedad a medida que el vac\xEDo se profundiza por debajo de 5,000 micrones hacia 500 micrones.&quot; }, { id:&quot;a2l_study_145&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 NO se puede evaluar la evacuaci\xF3n por el sonido de la bomba o tiempo?&quot;, opciones:[&quot;S\xED se puede \u2014 una bomba ruidosa indica mal vac\xEDo&quot;,&quot;El nivel real de vac\xEDo solo se determina con un micr\xF3metro digital \u2014 el sonido y el tiempo no son indicadores confiables del nivel de vac\xEDo alcanzado&quot;,&quot;Solo para sistemas grandes&quot;,&quot;Solo si la bomba es nueva&quot;], respuesta_correcta:1, explicacion:&quot;El sonido de la bomba y el tiempo no correlacionan confiablemente con el nivel de vac\xEDo. Una bomba puede sonar 'bien' pero no alcanzar el vac\xEDo requerido por aceite contaminado. SIEMPRE medir con micr\xF3metro digital.&quot; }, { id:&quot;a2l_study_146&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 indica si la presi\xF3n sube r\xE1pidamente despu\xE9s de aislar el sistema de la bomba de vac\xEDo?&quot;, opciones:[&quot;El sistema complet\xF3 la evacuaci\xF3n correctamente&quot;,&quot;Hay una FUGA en el sistema \u2014 el sistema no puede mantener el vac\xEDo&quot;,&quot;El sistema tiene humedad&quot;,&quot;La bomba es demasiado peque\xF1a&quot;], respuesta_correcta:1, explicacion:&quot;Si la presi\xF3n sube R\xC1PIDO y continuamente despu\xE9s de aislar: hay una FUGA en el sistema. Si la presi\xF3n sube LENTAMENTE y se estabiliza: hay humedad (la humedad se evapora hasta equilibrio). Si no sube o sube muy poco: evacuaci\xF3n exitosa.&quot; }, { id:&quot;a2l_study_147&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1ndo se debe cambiar el aceite de la bomba de vac\xEDo durante una evacuaci\xF3n larga?&quot;, opciones:[&quot;Solo al final de la evacuaci\xF3n&quot;,&quot;Cuando el aceite se ve turbio u oscuro durante la evacuaci\xF3n \u2014 los contaminantes del sistema degradan el aceite&quot;,&quot;Solo una vez al a\xF1o&quot;,&quot;Nunca durante una evacuaci\xF3n \u2014 solo antes&quot;], respuesta_correcta:1, explicacion:&quot;Durante evacuaciones largas o en sistemas muy h\xFAmedos/contaminados, el aceite puede degradarse y aparecer turbio. Cuando el aceite se contamina DURANTE la evacuaci\xF3n, cambiarlo inmediatamente y continuar para lograr el vac\xEDo requerido.&quot; }, { id:&quot;a2l_study_148&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 es la 'triple evacuaci\xF3n' y cu\xE1ndo la requieren algunos fabricantes A2L?&quot;, opciones:[&quot;Evacuar tres veces el mismo sistema sin nitr\xF3geno&quot;,&quot;Evacuar \u2192 romper el vac\xEDo con nitr\xF3geno (hasta 0 PSI) \u2192 repetir 3 veces. Remueve humedad y contaminantes m\xE1s efectivamente&quot;,&quot;Solo es necesaria en sistemas de alta humedad&quot;,&quot;Solo para sistemas de m\xE1s de 5 toneladas&quot;], respuesta_correcta:1, explicacion:&quot;Triple evacuaci\xF3n: (1) evacuar a ~1,000-2,000 micrones, (2) romper vac\xEDo con nitr\xF3geno seco hasta presi\xF3n atmosf\xE9rica, (3) repetir el proceso 2 veces m\xE1s. Remueve humedad y no-condensables m\xE1s efectivamente que una sola evacuaci\xF3n. Algunos fabricantes A2L la requieren.&quot; }, { id:&quot;a2l_study_149&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo saber si los residuos de aceite A1 previo en las l\xEDneas afectar\xE1n el sistema A2L nuevo?&quot;, opciones:[&quot;No afecta \u2014 todos los aceites son iguales&quot;,&quot;Si quedan residuos significativos de aceite mineral en un sistema que se convertir\xE1 a A2L, pueden contaminar el aceite POE y causar problemas \u2014 algunos fabricantes requieren flush con N2&quot;,&quot;Solo es problema en sistemas peque\xF1os&quot;,&quot;Solo si el sistema ten\xEDa R-22&quot;], respuesta_correcta:1, explicacion:&quot;El aceite mineral previo puede contaminar el aceite POE del nuevo sistema A2L. Si el sistema tuvo R-22 (aceite mineral) y se convierte a R-454B (POE), algunos fabricantes requieren nitrogen sweep o flush para remover residuos de aceite mineral de las l\xEDneas.&quot; }, { id:&quot;a2l_study_150&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 es importante cerrar el gas ballast de la bomba de vac\xEDo para el vaciado final?&quot;, opciones:[&quot;El gas ballast no importa&quot;,&quot;El gas ballast abierto permite entrada de aire que previene alcanzar el vac\xEDo profundo final \u2014 debe cerrarse para la etapa final&quot;,&quot;El gas ballast siempre debe estar cerrado&quot;,&quot;El gas ballast solo aplica a sistemas grandes&quot;], respuesta_correcta:1, explicacion:&quot;El gas ballast permite entrada de aire durante la evacuaci\xF3n para prevenir condensaci\xF3n en el aceite. Sin embargo, con el ballast abierto NO se puede alcanzar el vac\xEDo profundo final. Cerrar el ballast para la etapa final (por debajo de 5,000 micrones) para alcanzar 500 micrones.&quot; }, { id:&quot;a2l_study_151&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1ndo es obligatorio el nitrogen sweep despu\xE9s de recuperar A2L?&quot;, opciones:[&quot;Solo si vas a usar soplete&quot;,&quot;Siempre despu\xE9s de recuperar A2L si vas a abrir el sistema con cualquier herramienta o trabajo que pueda generar chispa o calor&quot;,&quot;Solo en sistemas grandes&quot;,&quot;Solo si el sistema ten\xEDa fuga grande&quot;], respuesta_correcta:1, explicacion:&quot;El nitrogen sweep es obligatorio SIEMPRE que se vaya a hacer trabajo que pueda generar chispa, arco el\xE9ctrico, o calor \u2014 no solo al soldar. Esto incluye: soldadura, cambio de componentes el\xE9ctricos, y cualquier trabajo donde se abra el sistema en un \xE1rea con posible acumulaci\xF3n de vapores.&quot; }, { id:&quot;a2l_study_152&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 indica la NFPA 704 diamante rojo n\xFAmero 3 para un refrigerante?&quot;, opciones:[&quot;Sin riesgo de inflamabilidad&quot;,&quot;Inflamabilidad alta \u2014 el material puede encenderse bajo la mayor\xEDa de condiciones de temperatura ambiente&quot;,&quot;Solo levemente inflamable&quot;,&quot;Inflamabilidad moderada solo a temperaturas elevadas&quot;], respuesta_correcta:1, explicacion:&quot;NFPA 704 diamante rojo: 0=no inflamable, 1=requiere calentamiento significativo para encenderse, 2=requiere calentamiento moderado, 3=puede encenderse bajo la mayor\xEDa de condiciones de temperatura ambiente, 4=vaporizar\xE1 y quemar\xE1 r\xE1pidamente. Los A2L generalmente clasifican como 1-2.&quot; }, { id:&quot;a2l_study_153&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 significa que un sistema A2L requiere 'active mitigation' para exceder la carga m1?&quot;, opciones:[&quot;Solo instalar un extinguidor adicional&quot;,&quot;Instalar sensores activos de refrigerante, ventilaci\xF3n mec\xE1nica activa, y/o sistemas de pump down autom\xE1tico antes de poder instalar la carga m2 mayor&quot;,&quot;Solo agregar m\xE1s R-32 al sistema&quot;,&quot;No tiene implicaciones especiales&quot;], respuesta_correcta:1, explicacion:&quot;Para exceder la carga m1 (carga sin mitigaci\xF3n), se deben instalar estrategias de mitigaci\xF3n activa antes de colocar la carga m2 mayor. Estas incluyen: sensores activos de refrigerante, ventilaci\xF3n mec\xE1nica activa, pump down autom\xE1tico, o combinaciones de estas medidas.&quot; }, { id:&quot;a2l_study_154&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 restricciones aplican al almacenamiento de A2L en un cuarto de m\xE1quinas sin sistema de sprinklers?&quot;, opciones:[&quot;No hay restricciones especiales&quot;,&quot;Hay un l\xEDmite de peso m\xE1ximo de refrigerante inflamable que se puede almacenar por \xE1rea de control \u2014 instalar sprinklers permite aumentar ese l\xEDmite&quot;,&quot;Solo se requiere ventilaci\xF3n&quot;,&quot;Solo para almacenamiento de m\xE1s de 500 lb&quot;], respuesta_correcta:1, explicacion:&quot;Los c\xF3digos (OSHA, DOT, locales) limitan el peso de refrigerante inflamable almacenado por \xE1rea de control SIN sprinklers. Con sistema de sprinklers activo instalado, ese l\xEDmite puede incrementarse. La cantidad exacta depende del refrigerante y el c\xF3digo local aplicable.&quot; }, { id:&quot;a2l_study_155&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1ndo se activa el vent del purgador en un sistema que usa A2L?&quot;, opciones:[&quot;Nunca \u2014 los A2L no tienen purgadores&quot;,&quot;Los purgadores NO se usan en sistemas A2L de alta presi\xF3n. Solo en sistemas de baja presi\xF3n (Tipo III). Para A2L, los no-condensables se previenen con buena evacuaci\xF3n&quot;,&quot;Solo en sistemas grandes&quot;,&quot;Solo en invierno&quot;], respuesta_correcta:1, explicacion:&quot;Los purgadores son espec\xEDficos de sistemas de BAJA PRESI\xD3N (Tipo III/chillers), donde el sistema opera al vac\xEDo y el aire entra por fugas. Los sistemas A2L de alta presi\xF3n (R-32, R-454B) NO usan purgadores \u2014 previenen no-condensables con buena evacuaci\xF3n.&quot; }, { id:&quot;a2l_study_156&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 verificaci\xF3n debe hacer el t\xE9cnico al reutilizar tuber\xEDas existentes para un nuevo sistema A2L?&quot;, opciones:[&quot;No es necesaria ninguna verificaci\xF3n&quot;,&quot;Verificar que las tuber\xEDas cumplen est\xE1ndares, son el tama\xF1o correcto para el nuevo sistema, est\xE1n limpias, y pasan prueba de presi\xF3n con nitr\xF3geno&quot;,&quot;Solo verificar el di\xE1metro&quot;,&quot;Solo verificar que no tienen fugas visibles&quot;], respuesta_correcta:1, explicacion:&quot;Para reutilizar tuber\xEDas: (1) verificar que cumplen los est\xE1ndares aplicables, (2) son el tama\xF1o y longitud correctos para el nuevo sistema, (3) est\xE1n limpias (sin contaminaci\xF3n, sin aceite mineral excesivo si era R-22), (4) pasan prueba de presi\xF3n con nitr\xF3geno.&quot; }, { id:&quot;a2l_study_157&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es el l\xEDmite de trace gas A2L para detecci\xF3n de fugas seg\xFAn ASHRAE 34?&quot;, opciones:[&quot;Sin l\xEDmite \u2014 solo unos pocos oz&quot;,&quot;No debe exceder 25% del LFL del refrigerante espec\xEDfico&quot;,&quot;Solo 1 oz m\xE1ximo&quot;,&quot;No se permite trace gas A2L&quot;], respuesta_correcta:1, explicacion:&quot;Al usar A2L como trace gas para detecci\xF3n de fugas: la cantidad NO debe exceder el 25% del LFL del refrigerante. Por ejemplo, si el LFL del R-32 es 14.4% del volumen del aire, el trace gas no debe crear concentraci\xF3n mayor al 3.6% en el \xE1rea.&quot; }, { id:&quot;a2l_study_158&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 se\xF1alizaci\xF3n debe tener un equipo A2L en el exterior de la unidad?&quot;, opciones:[&quot;Solo la placa de datos normal&quot;,&quot;Advertencia: 'Risk of Fire or Explosion. Flammable Refrigerant Used. To Be Repaired Only by Trained Service Personnel. Do Not Puncture Refrigerant Tubing'&quot;,&quot;Solo el s\xEDmbolo ISO&quot;,&quot;Solo el n\xFAmero de modelo&quot;], respuesta_correcta:1, explicacion:&quot;Los equipos con refrigerante inflamable deben tener etiqueta de advertencia que incluya: 'Warning \u2014 Risk of Fire or Explosion. Flammable Refrigerant Used. To Be Repaired Only by Trained Service Personnel. Do Not Puncture Refrigerant Tubing.'&quot; }, { id:&quot;a2l_study_159&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 los sistemas A2L requieren componentes el\xE9ctricos 'intrinsically safe' (IS)?&quot;, opciones:[&quot;Solo por est\xE9tica&quot;,&quot;Para prevenir que una falla el\xE9ctrica genere suficiente energ\xEDa para encender el refrigerante A2L \u2014 los contactores y capacitores son dise\xF1ados para contener cualquier chispa&quot;,&quot;Solo para reducir el consumo de electricidad&quot;,&quot;Solo es requerimiento est\xE9tico&quot;], respuesta_correcta:1, explicacion:&quot;Los componentes IS (intrinsically safe) est\xE1n dise\xF1ados para que NO puedan liberar suficiente energ\xEDa el\xE9ctrica o t\xE9rmica para encender una mezcla de A2L-aire. Los contactores y capacitores est\xE1n sellados para contener cualquier chispa dentro del enclosure.&quot; }, { id:&quot;a2l_study_160&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1les son los 4 factores que hacen a los A2L significativamente m\xE1s seguros que los A3?&quot;, opciones:[&quot;Son m\xE1s baratos y f\xE1ciles de conseguir&quot;,&quot;MIE m\xE1s alto, LFL m\xE1s alto, menor calor de combusti\xF3n, y menor velocidad de llama&quot;,&quot;Solo son m\xE1s seguros porque la EPA los aprob\xF3&quot;,&quot;Solo por su menor GWP&quot;], respuesta_correcta:1, explicacion:&quot;Los 4 factores de seguridad A2L vs A3: (1) MIE m\xE1s ALTO = m\xE1s dif\xEDciles de encender, (2) LFL m\xE1s ALTO = requieren mayor concentraci\xF3n para inflamarse, (3) Calor de combusti\xF3n m\xE1s BAJO = menos energ\xEDa si se queman, (4) Velocidad de llama m\xE1s BAJA = fuego se propaga m\xE1s lentamente.&quot; }, { id:&quot;a2l_study_161&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 el aceite mineral NO puede usarse con refrigerantes A2L como R-32 o R-454B?&quot;, opciones:[&quot;Solo por costo \u2014 el POE es m\xE1s barato&quot;,&quot;El aceite mineral no es miscible con HFCs/HFOs \u2014 no se mezcla con el refrigerante y puede acumularse en el evaporador causando mala transferencia de calor y falla del compresor&quot;,&quot;Solo por razones de garant\xEDa&quot;,&quot;El aceite mineral funciona igual que POE para A2L&quot;], respuesta_correcta:1, explicacion:&quot;Los HFCs y HFOs requieren aceite POE porque: el aceite mineral NO es miscible con estos refrigerantes. Si se usa mineral, el aceite se separa del refrigerante y se acumula en el evaporador, reduciendo la transferencia de calor y eventualmente drenando el compresor de lubricaci\xF3n.&quot; }, { id:&quot;a2l_study_162&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 el aceite POE debe manejarse con cuidado y no exponerse al aire libre?&quot;, opciones:[&quot;Solo porque es costoso&quot;,&quot;El POE es MUY higrosc\xF3pico \u2014 absorbe humedad del aire r\xE1pidamente. Una vez saturado de humedad puede formar \xE1cidos que da\xF1an el sistema&quot;,&quot;Por razones est\xE9ticas&quot;,&quot;Solo en climas h\xFAmedos&quot;], respuesta_correcta:1, explicacion:&quot;El POE es extremadamente higrosc\xF3pico \u2014 absorbe humedad del aire incluso a trav\xE9s de recipientes pl\xE1sticos. La exposici\xF3n recomendada al aire libre es de m\xE1ximo 15 minutos. Humedad en el POE puede causar hidr\xF3lisis, formando \xE1cidos y sludge que tapan componentes del sistema.&quot; }, { id:&quot;a2l_study_163&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 es la 'hidr\xF3lisis' del aceite POE y cu\xE1ndo ocurre?&quot;, opciones:[&quot;Una limpieza especial del aceite&quot;,&quot;La descomposici\xF3n del POE por presencia de agua, formando \xE1cidos org\xE1nicos y alcohol \u2014 puede causar obstrucciones en v\xE1lvulas y filtros&quot;,&quot;Una propiedad de lubricaci\xF3n&quot;,&quot;Solo en sistemas de alta presi\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;Hidr\xF3lisis = descomposici\xF3n del POE en presencia de agua, produciendo \xE1cidos org\xE1nicos, esters, y alcohol. Los \xE1cidos pueden corroer metales, da\xF1ar el barniz del motor del compresor, y tapar orificios de v\xE1lvulas y filtros.&quot; }, { id:&quot;a2l_study_164&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 aceite se usa principalmente en sistemas de A/C automotriz con R-1234yf?&quot;, opciones:[&quot;Aceite mineral&quot;,&quot;Aceite POE&quot;,&quot;Aceite PAG (Polyalkylene Glycol)&quot;,&quot;Aceite alquilbenceno (AB)&quot;], respuesta_correcta:2, explicacion:&quot;R-1234yf en automotriz usa aceite PAG (Polyalkylene Glycol), igual que usaba con R-134a. El PAG es extremadamente higrosc\xF3pico y NO es miscible con refrigerantes que contengan cloro. Se usa espec\xEDficamente en sistemas automotrices.&quot; }, { id:&quot;a2l_study_165&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1nto tiempo m\xE1ximo se recomienda exposici\xF3n del aceite POE al aire libre?&quot;, opciones:[&quot;1 hora&quot;,&quot;15 minutos m\xE1ximo&quot;,&quot;No importa el tiempo&quot;,&quot;Solo 5 minutos&quot;], respuesta_correcta:1, explicacion:&quot;El aceite POE solo debe exponerse al aire libre por un m\xE1ximo de 15 minutos. Despu\xE9s de este tiempo, la absorci\xF3n de humedad puede ser significativa. Siempre cerrar el recipiente inmediatamente y almacenar en contenedor sellado de metal o vidrio.&quot; }, { id:&quot;a2l_study_166&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 debe hacer el t\xE9cnico si sospecha que el aceite POE del sistema est\xE1 contaminado con humedad?&quot;, opciones:[&quot;Continuar operando \u2014 se limpiar\xE1 solo&quot;,&quot;Recuperar el refrigerante en tanque separado, drenar el aceite contaminado, limpiar el sistema, instalar nuevos filtros-drier, y a\xF1adir aceite POE nuevo y refrigerante&quot;,&quot;Solo cambiar el filtro-drier&quot;,&quot;Solo a\xF1adir m\xE1s aceite nuevo&quot;], respuesta_correcta:1, explicacion:&quot;Si el aceite POE est\xE1 contaminado con humedad o \xE1cidos: (1) recuperar refrigerante en tanque separado (no mezclar), (2) drenar aceite contaminado, (3) flush del sistema, (4) instalar nuevos filtros-drier (succi\xF3n y l\xEDquido), (5) a\xF1adir aceite POE nuevo limpio, (6) recargar refrigerante.&quot; }, { id:&quot;a2l_study_167&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 los aceites de refrigeraci\xF3n NO deben mezclarse entre s\xED?&quot;, opciones:[&quot;Solo por costo&quot;,&quot;La mezcla de aceites puede no lubriar correctamente el compresor o no ser miscible con el refrigerante del sistema&quot;,&quot;Solo si son de diferente marca&quot;,&quot;Los aceites pueden mezclarse sin problema&quot;], respuesta_correcta:1, explicacion:&quot;Los aceites de refrigeraci\xF3n tienen diferentes propiedades de viscosidad, miscibilidad con refrigerantes, y compatibilidad con materiales. Mezclarlos puede resultar en lubricaci\xF3n deficiente y/o incompatibilidad con el refrigerante, causando problemas de retorno de aceite al compresor.&quot; }, { id:&quot;a2l_study_168&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 aceite lubricante es compatible con R-22 (HCFC)?&quot;, opciones:[&quot;Solo POE&quot;,&quot;Aceite mineral (MO) o Alquilbenceno (AB) son compatibles con HCFCs como R-22&quot;,&quot;Solo PAG&quot;,&quot;Cualquier aceite sirve para R-22&quot;], respuesta_correcta:1, explicacion:&quot;R-22 (HCFC) es compatible con aceite mineral (MO) y aceite alquilbenceno (AB). El aceite mineral es el m\xE1s tradicional con R-22. El AB tiene mejor miscibilidad en aplicaciones de baja temperatura.&quot; }, { id:&quot;a2l_study_169&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;Al cambiar de R-22 (con aceite mineral) a R-454B (con POE), \xBFqu\xE9 se debe hacer con el aceite?&quot;, opciones:[&quot;Se puede dejar el aceite mineral \u2014 no hay problema&quot;,&quot;El aceite mineral debe ser removido. Algunos fabricantes requieren nitrogen sweep o flush de l\xEDneas para eliminar residuos de mineral antes de instalar el sistema R-454B&quot;,&quot;Solo a\xF1adir POE encima del mineral&quot;,&quot;El R-454B funciona bien con aceite mineral&quot;], respuesta_correcta:1, explicacion:&quot;La conversi\xF3n de R-22 a R-454B requiere remover el aceite mineral. Residuos de aceite mineral son incompatibles con el POE del nuevo sistema y con el R-454B. Verificar las instrucciones del fabricante del nuevo sistema para los pasos espec\xEDficos de limpieza de l\xEDneas.&quot; }, { id:&quot;a2l_study_170&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFEn qu\xE9 contenedores debe almacenarse el aceite POE?&quot;, opciones:[&quot;Cualquier contenedor \u2014 incluyendo pl\xE1stico&quot;,&quot;Contenedores de metal o vidrio herm\xE9ticamente sellados \u2014 el POE puede absorber humedad incluso a trav\xE9s de pl\xE1stico&quot;,&quot;Solo en latas de aluminio&quot;,&quot;Solo en los contenedores originales del fabricante&quot;], respuesta_correcta:1, explicacion:&quot;El aceite POE debe almacenarse en contenedores de METAL o VIDRIO herm\xE9ticamente sellados. El POE es tan higrosc\xF3pico que puede absorber humedad incluso a trav\xE9s de contenedores pl\xE1sticos con el tiempo. Nunca usar contenedores pl\xE1sticos para almacenamiento a largo plazo.&quot; }, { id:&quot;a2l_study_171&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es la funci\xF3n principal del filtro-drier (filter-drier) en un sistema de refrigeraci\xF3n?&quot;, opciones:[&quot;Filtrar solo part\xEDculas s\xF3lidas&quot;,&quot;Filtrar part\xEDculas Y absorber humedad del refrigerante en el sistema sellado&quot;,&quot;Solo filtrar el aceite&quot;,&quot;Regular el flujo de refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;El filtro-drier tiene dos funciones: (1) FILTRAR part\xEDculas s\xF3lidas (metales, suciedad) a trav\xE9s de screens y material filtrante, y (2) ABSORBER humedad (y \xE1cidos) a trav\xE9s del core desecante. Protege al compresor y a la v\xE1lvula de expansi\xF3n.&quot; }, { id:&quot;a2l_study_172&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1ndo DEBE reemplazarse el filtro-drier en un sistema?&quot;, opciones:[&quot;Solo cuando se bloquea completamente&quot;,&quot;Siempre que el sistema se abre para reparaci\xF3n, Y cuando hay evidencia de contaminaci\xF3n de humedad o \xE1cidos&quot;,&quot;Solo una vez al a\xF1o&quot;,&quot;Solo despu\xE9s de cambio de compresor&quot;], respuesta_correcta:1, explicacion:&quot;El filtro-drier DEBE reemplazarse: (1) SIEMPRE que el sistema se abra para reparaci\xF3n (ya que se expone al aire y absorbe humedad), (2) cuando hay evidencia de humedad o \xE1cidos en el sistema, y (3) despu\xE9s de un burnout de compresor.&quot; }, { id:&quot;a2l_study_173&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 un filtro-drier bloqueado debe CORTARSE del sistema en lugar de soldarse para removerse?&quot;, opciones:[&quot;Es m\xE1s r\xE1pido cortar&quot;,&quot;Aplicar calor al filtro-drier bloqueado puede liberar la humedad atrapada de vuelta al sistema. Cortarlo evita este problema&quot;,&quot;Por razones de seguridad del soldador&quot;,&quot;Solo si es de cobre&quot;], respuesta_correcta:1, explicacion:&quot;Un filtro-drier bloqueado contiene humedad y \xE1cidos atrapados. Aplicar calor de soldadura libera esta humedad de vuelta al sistema, contamin\xE1ndolo nuevamente. Siempre CORTAR el drier bloqueado para removerlo.&quot; }, { id:&quot;a2l_study_174&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 tipo de filtro-drier requieren los sistemas de bomba de calor?&quot;, opciones:[&quot;El mismo que sistemas de A/C de una sola direcci\xF3n&quot;,&quot;Bi-flow (flujo bidireccional) \u2014 porque el refrigerante fluye en ambas direcciones dependiendo del modo calefacci\xF3n/enfriamiento&quot;,&quot;Ninguno \u2014 las bombas de calor no necesitan drier&quot;,&quot;Solo uno de mayor capacidad&quot;], respuesta_correcta:1, explicacion:&quot;Los sistemas de bomba de calor requieren filtros-drier BI-FLOW que permiten el flujo de refrigerante en AMBAS DIRECCIONES. En modo enfriamiento el refrigerante fluye en un sentido; en modo calefacci\xF3n, en sentido contrario.&quot; }, { id:&quot;a2l_study_175&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFC\xF3mo verifica el t\xE9cnico si un filtro-drier est\xE1 bloqueado?&quot;, opciones:[&quot;Visualmente \u2014 si se ve sucio est\xE1 bloqueado&quot;,&quot;Midiendo la temperatura o presi\xF3n en ambos lados del drier \u2014 si hay ca\xEDda de temperatura/presi\xF3n, est\xE1 bloqueado&quot;,&quot;Solo si el sistema no enfr\xEDa&quot;,&quot;El drier nunca se bloquea&quot;], respuesta_correcta:1, explicacion:&quot;Para verificar si el drier est\xE1 bloqueado: medir temperatura en ambos lados (entrada y salida). Si la temperatura de salida es significativamente MENOR (ca\xEDda de presi\xF3n en el drier), est\xE1 bloqueado. Tambi\xE9n se puede medir la diferencia de presi\xF3n con el manifold.&quot; }, { id:&quot;a2l_study_176&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es la funci\xF3n del acumulador en la l\xEDnea de succi\xF3n?&quot;, opciones:[&quot;Regular la presi\xF3n de alta&quot;,&quot;Prevenir que refrigerante l\xEDquido entre al compresor en la l\xEDnea de succi\xF3n, protegiendo contra liquid floodback&quot;,&quot;Almacenar refrigerante adicional&quot;,&quot;Filtrar el aceite del sistema&quot;], respuesta_correcta:1, explicacion:&quot;El acumulador est\xE1 en la l\xEDnea de succi\xF3n justo antes del compresor. Su funci\xF3n es proporcionar espacio para que cualquier l\xEDquido residual en la l\xEDnea de succi\xF3n se vaporice ANTES de llegar al compresor. Protege contra liquid floodback.&quot; }, { id:&quot;a2l_study_177&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPara qu\xE9 se usa el receptor (liquid receiver) en sistemas de refrigeraci\xF3n?&quot;, opciones:[&quot;Para almacenar aceite de compresor&quot;,&quot;Para almacenar l\xEDquido subcooled despu\xE9s del condensador, permitiendo pump-down y acomodando variaciones de carga&quot;,&quot;Para filtrar el refrigerante&quot;,&quot;Para medir la cantidad de refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;El receiver se ubica despu\xE9s del condensador y almacena refrigerante l\xEDquido subcooled. Permite: (1) pump-down para servicio (almacena toda la carga del sistema), y (2) acomodar variaciones en la carga del sistema sin afectar la alimentaci\xF3n de refrigerante a la v\xE1lvula de expansi\xF3n.&quot; }, { id:&quot;a2l_study_178&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 tipo de v\xE1lvula de expansi\xF3n tiene un orificio FIJO que no se ajusta?&quot;, opciones:[&quot;TXV (v\xE1lvula termost\xE1tica de expansi\xF3n)&quot;,&quot;Pist\xF3n (piston) o tubo capilar (cap tube) \u2014 dispositivos de metering fijo&quot;,&quot;AXV (v\xE1lvula autom\xE1tica de expansi\xF3n)&quot;,&quot;EEV (v\xE1lvula electr\xF3nica de expansi\xF3n)&quot;], respuesta_correcta:1, explicacion:&quot;Los dispositivos de metering FIJO son el pist\xF3n y el tubo capilar \u2014 tienen un orificio de tama\xF1o fijo. Las v\xE1lvulas ajustables son: TXV (termost\xE1tica), AXV (autom\xE1tica), y EEV (electr\xF3nica), todas con apertura variable que responde a condiciones del sistema.&quot; }, { id:&quot;a2l_study_179&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 la TXV mantiene un superheat de evaporador m\xE1s constante que un pist\xF3n?&quot;, opciones:[&quot;No hay diferencia entre TXV y pist\xF3n&quot;,&quot;La TXV regula activamente la apertura seg\xFAn el superheat medido por su bulbo sensor \u2014 m\xE1s refrigerante cuando hace m\xE1s calor, menos cuando hace menos&quot;,&quot;El pist\xF3n es m\xE1s eficiente que la TXV&quot;,&quot;La TXV solo funciona bien en sistemas A2L&quot;], respuesta_correcta:1, explicacion:&quot;La TXV tiene un bulbo sensor en la l\xEDnea de succi\xF3n que mide el superheat y ajusta continuamente la apertura de la v\xE1lvula. Cuando la carga aumenta (m\xE1s calor), abre m\xE1s para alimentar m\xE1s refrigerante. Esto mantiene el superheat en el rango objetivo independientemente de las condiciones.&quot; }, { id:&quot;a2l_study_180&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFD\xF3nde debe instalarse el filtro-drier de l\xEDnea l\xEDquida para mayor vida \xFAtil?&quot;, opciones:[&quot;Cerca del condensador para mayor conveniencia&quot;,&quot;Preferiblemente en interiores cerca del dispositivo de metering \u2014 se expone a menor calor, extending su vida \xFAtil&quot;,&quot;No importa la ubicaci\xF3n&quot;,&quot;Solo cerca del compresor&quot;], respuesta_correcta:1, explicacion:&quot;El filtro-drier de l\xEDnea l\xEDquida dura m\xE1s instalado EN INTERIORES cerca del dispositivo de metering (TXV/pist\xF3n). Instalado cerca del condensador exterior se expone a mayor calor y temperatura c\xEDclica que puede degradar el desecante m\xE1s r\xE1pidamente.&quot; }, { id:&quot;a2l_study_181&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 la l\xEDnea de succi\xF3n debe tener la pendiente correcta hacia el compresor?&quot;, opciones:[&quot;Para evitar fugas de refrigerante&quot;,&quot;Para facilitar el retorno de aceite al compresor \u2014 el aceite circula con el refrigerante y debe poder regresar&quot;,&quot;Solo por est\xE9tica&quot;,&quot;Solo en instalaciones comerciales&quot;], respuesta_correcta:1, explicacion:&quot;La l\xEDnea de succi\xF3n debe facilitar el RETORNO DE ACEITE al compresor. El aceite circula mezclado con el vapor de refrigerante. Si la l\xEDnea de succi\xF3n no tiene la pendiente/velocidad correcta, el aceite puede acumularse en la l\xEDnea y drenar el compresor de lubricaci\xF3n.&quot; }, { id:&quot;a2l_study_182&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 es un 'oil trap' (trampa de aceite) y cu\xE1ndo se instala en una l\xEDnea de succi\xF3n?&quot;, opciones:[&quot;Un filtro para el aceite&quot;,&quot;Un sif\xF3n en la l\xEDnea de succi\xF3n en subidas verticales largas \u2014 facilita el retorno de aceite hacia arriba contra la gravedad&quot;,&quot;Una v\xE1lvula de retenci\xF3n para aceite&quot;,&quot;Solo para sistemas industriales&quot;], respuesta_correcta:1, explicacion:&quot;Un oil trap es un sif\xF3n en forma de U en la parte inferior de subidas verticales largas en la l\xEDnea de succi\xF3n. Permite que el aceite se acumule y sea arrastrado por el vapor de refrigerante subiendo. Sin ellos, el aceite puede no retornar al compresor en instalaciones con l\xEDneas verticales largas.&quot; }, { id:&quot;a2l_study_183&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es el prop\xF3sito de la l\xEDnea de nitr\xF3geno de purga durante el proceso de brazado?&quot;, opciones:[&quot;Para presurizar el sistema y detectar fugas&quot;,&quot;Para desplazar el ox\xEDgeno dentro de las tuber\xEDas durante el brazado, previniendo oxidaci\xF3n y formaci\xF3n de escama interna (scale) que da\xF1ar\xEDa v\xE1lvulas y compresores&quot;,&quot;Para enfriar las tuber\xEDas r\xE1pidamente&quot;,&quot;Para verificar que las uniones est\xE9n bien selladas&quot;], respuesta_correcta:1, explicacion:&quot;La purga de nitr\xF3geno durante el brazado desplaza el ox\xEDgeno del interior de las tuber\xEDas. Sin esta purga, el calor del brazado oxida el cobre internamente, formando escama (scale) que puede tapar la TXV, contaminar el compresor y causar fallas prematuras.&quot; }, { id:&quot;a2l_study_184&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFA qu\xE9 presi\xF3n se realiza la purga de nitr\xF3geno durante el brazado?&quot;, opciones:[&quot;Alta presi\xF3n \u2014 100 PSI o m\xE1s&quot;,&quot;Baja presi\xF3n \u2014 \xBD a 2 PSI para simplemente desplazar el ox\xEDgeno sin crear peligro&quot;,&quot;Solo se hace antes de soldar, no durante&quot;,&quot;No hay especificaci\xF3n de presi\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;La purga de nitr\xF3geno durante el brazado se hace a BAJA PRESI\xD3N: \xBD a 2 PSI. Esta presi\xF3n es suficiente para desplazar el ox\xEDgeno del interior pero no crea peligro de proyecci\xF3n de metal fundido ni problemas de seguridad.&quot; }, { id:&quot;a2l_study_185&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 tipo de brazado se usa para unir cobre a cobre en la mayor\xEDa de instalaciones HVAC?&quot;, opciones:[&quot;Soldadura de plomero (solder) con esta\xF1o y plomo&quot;,&quot;Brazado con varillas de relleno de aleaci\xF3n de plata (5-56% de plata) sin flux para cobre-cobre&quot;,&quot;Soldadura MIG&quot;,&quot;Solo pegamento especial para cobre&quot;], respuesta_correcta:1, explicacion:&quot;Para cobre a cobre en HVAC se usa brazado con varillas de relleno de aleaci\xF3n de PLATA (5-56% silver) que NO requieren flux. Para metales disimilares (cobre-aluminio, cobre-acero) s\xED se requiere flux apropiado.&quot; }, { id:&quot;a2l_study_186&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es la diferencia entre brazado (brazing) y soldadura fuerte o welding?&quot;, opciones:[&quot;Son exactamente lo mismo&quot;,&quot;Brazado une los metales por capilaridad con metal de relleno de menor punto de fusi\xF3n que los metales base \u2014 NO funde los metales base. La soldadura (welding) S\xCD funde los metales base&quot;,&quot;El brazado es para pl\xE1stico, el welding para metal&quot;,&quot;No hay diferencia significativa&quot;], respuesta_correcta:1, explicacion:&quot;Brazado = el metal de relleno (plata/cobre) se derrite por debajo del punto de fusi\xF3n de los metales base y penetra por capilaridad. Los metales base NO se derriten. Welding = los metales base S\xCD se funden. Para instalaciones HVAC siempre se usa brazado, no welding.&quot; }, { id:&quot;a2l_study_187&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es la diferencia pr\xE1ctica entre un soplete de air-acetylene y uno de oxyacetylene?&quot;, opciones:[&quot;No hay diferencia pr\xE1ctica&quot;,&quot;Air-acetylene usa ox\xEDgeno del ambiente (llama m\xE1s ancha, ~3,000\xB0F). Oxyacetylene usa cilindro separado de O2 (llama m\xE1s concentrada, ~5,400\xB0F). El air-acetylene es m\xE1s com\xFAn para HVAC&quot;,&quot;El air-acetylene es solo para plomer\xEDa&quot;,&quot;El oxyacetylene es m\xE1s seguro para A2L&quot;], respuesta_correcta:1, explicacion:&quot;Air-acetylene: usa ox\xEDgeno del ambiente, produce llama m\xE1s ancha y temperatura menor (~3,000\xB0F). M\xE1s common para trabajo HVAC/R. Oxyacetylene: usa cilindro separado de O2, llama m\xE1s concentrada y hotter (~5,400\xB0F). Para trabajo de mayor precisi\xF3n o metales m\xE1s gruesos.&quot; }, { id:&quot;a2l_study_188&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 NUNCA se debe usar presi\xF3n de ox\xEDgeno para verificar fugas en un sistema de refrigeraci\xF3n?&quot;, opciones:[&quot;Solo porque es caro&quot;,&quot;El ox\xEDgeno mezclado con aceite de compresor u otros materiales bajo presi\xF3n puede causar una EXPLOSI\xD3N \u2014 use solo nitr\xF3geno seco&quot;,&quot;Solo porque no es preciso&quot;,&quot;Solo para sistemas A2L&quot;], respuesta_correcta:1, explicacion:&quot;NUNCA ox\xEDgeno para leak check. El ox\xEDgeno a alta presi\xF3n mezclado con aceite de compresor u otros materiales org\xE1nicos puede auto-encenderse causando EXPLOSI\xD3N. Solo nitr\xF3geno seco es seguro para presurizar sistemas HVAC.&quot; }, { id:&quot;a2l_study_189&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 debe hacer el t\xE9cnico si la presi\xF3n de prueba con nitr\xF3geno CAE durante los 60 minutos?&quot;, opciones:[&quot;Es normal una ligera ca\xEDda \u2014 continuar&quot;,&quot;Hay una fuga \u2014 encontrarla con detector/agua jabonosa/UV, repararla, y repetir la prueba completa desde el inicio&quot;,&quot;Solo a\xF1adir m\xE1s nitr\xF3geno&quot;,&quot;La prueba se considera pasada si la ca\xEDda es menor al 10%&quot;], respuesta_correcta:1, explicacion:&quot;Cualquier ca\xEDda de presi\xF3n durante los 60 minutos de prueba indica FUGA. Procedimiento: localizar la fuga (detector electr\xF3nico, agua jabonosa, o UV), reparar, y repetir la prueba COMPLETA desde el inicio para verificar que no hay m\xE1s fugas.&quot; }, { id:&quot;a2l_study_190&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es la temperatura m\xE1xima para el lubricante de roscas (thread sealant) cuando se usa en tuber\xEDas de refrigeraci\xF3n?&quot;, opciones:[&quot;No importa la temperatura&quot;,&quot;Usar solo sealants espec\xEDficamente compatibles con refrigerantes y que puedan tolerar las temperaturas del sistema (cryogenic a muy alta presi\xF3n)&quot;,&quot;Solo PTFE tape est\xE1ndar de plomer\xEDa&quot;,&quot;Cualquier sealant de ferreter\xEDa&quot;], respuesta_correcta:1, explicacion:&quot;Para tuber\xEDas de refrigeraci\xF3n usar SOLO sealants (PTFE tape o compuesto) espec\xEDficamente compatibles con refrigerantes a las temperaturas del sistema. Algunos sealants de plomer\xEDa general no son compatibles con refrigerantes o no toleran las temperaturas extremas.&quot; }, { id:&quot;a2l_study_191&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es el componente m\xE1s costoso y cr\xEDtico de un sistema de refrigeraci\xF3n?&quot;, opciones:[&quot;El condensador&quot;,&quot;El compresor \u2014 su falla generalmente requiere reemplazo del sistema o reparaci\xF3n mayor&quot;,&quot;La v\xE1lvula de expansi\xF3n&quot;,&quot;El filtro-drier&quot;], respuesta_correcta:1, explicacion:&quot;El compresor es el coraz\xF3n del sistema y el componente m\xE1s costoso. Su falla puede deberse a: l\xEDquido floodback, falta de aceite, sobrecarga el\xE9ctrica, contaminaci\xF3n del sistema, o exceso de temperatura. Proteger el compresor es prioritario.&quot; }, { id:&quot;a2l_study_192&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 causa el 'liquid slugging' en un compresor y por qu\xE9 es destructivo?&quot;, opciones:[&quot;El compresor recibe demasiado vapor superheated&quot;,&quot;El compresor recibe refrigerante l\xEDquido que no puede comprimirse \u2014 causa golpe hidr\xE1ulico que puede romper v\xE1lvulas o bielas&quot;,&quot;El compresor trabaja con poco aceite&quot;,&quot;El compresor tiene voltaje incorrecto&quot;], respuesta_correcta:1, explicacion:&quot;Liquid slugging = refrigerante l\xEDquido entra al compresor (que es una bomba de vapor). El l\xEDquido no puede comprimirse como el vapor \u2014 causa un golpe hidr\xE1ulico que puede romper v\xE1lvulas de descarga, anillos del pist\xF3n, o connecting rods. Es una de las fallas m\xE1s destructivas.&quot; }, { id:&quot;a2l_study_193&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 es un 'compressor burnout' y qu\xE9 s\xEDntomas se observan?&quot;, opciones:[&quot;El compresor trabaja a m\xE1xima eficiencia&quot;,&quot;El motor del compresor se quema el\xE9ctricamente \u2014 el refrigerante y aceite presentan \xE1cidos, color oscuro, y olor a quemado. Las lecturas el\xE9ctricas muestran resistencia a tierra o entre fases incorrecta&quot;,&quot;El compresor enfr\xEDa demasiado&quot;,&quot;Solo ocurre en sistemas antiguos&quot;], respuesta_correcta:1, explicacion:&quot;Compressor burnout = falla el\xE9ctrica del motor del compresor. S\xEDntomas: olor a quemado al abrir el sistema, aceite oscuro/contaminado, presencia de \xE1cidos (prueba con acid test kit), y lecturas el\xE9ctricas incorrectas (resistencia a tierra, desequilibrio entre fases).&quot; }, { id:&quot;a2l_study_194&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 procedimiento se debe seguir despu\xE9s de un compressor burnout?&quot;, opciones:[&quot;Solo reemplazar el compresor y listo&quot;,&quot;Recuperar refrigerante en tanque separado, reemplazar compresor, instalar suction line drier, flush del sistema, instalar nuevos driers, a\xF1adir aceite limpio y refrigerante nuevo&quot;,&quot;Solo cambiar el aceite&quot;,&quot;Solo limpiar el sistema externamente&quot;], respuesta_correcta:1, explicacion:&quot;Despu\xE9s de un burnout: (1) recuperar refrigerante en cilindro SEPARADO (contaminado), (2) reemplazar compresor, (3) instalar suction line drier temporal, (4) flush del sistema, (5) instalar nuevos filtros-drier, (6) aceite POE limpio, (7) refrigerante nuevo. Verificar el sistema completo.&quot; }, { id:&quot;a2l_study_195&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 el suction line drier (drier de l\xEDnea de succi\xF3n) es temporal y debe removerse?&quot;, opciones:[&quot;Porque es muy costoso dejarlo permanente&quot;,&quot;El suction line drier est\xE1 dise\xF1ado solo para limpiar el sistema despu\xE9s de contaminaci\xF3n \u2014 debe removerse cuando se bloquee, ya que una restricci\xF3n en la succi\xF3n puede da\xF1ar el compresor por baja presi\xF3n&quot;,&quot;No es necesario removerlo&quot;,&quot;Solo se usa en sistemas A2L&quot;], respuesta_correcta:1, explicacion:&quot;El suction line drier NO es permanente \u2014 solo para cleanup post-burnout. Si se bloquea (lo cual se indica por ca\xEDda de presi\xF3n medida con gauges en sus puertos), causa restricci\xF3n en la succi\xF3n que puede da\xF1ar el compresor. Removerlo cuando se bloquee o despu\xE9s de que el sistema se ha limpiado.&quot; }, { id:&quot;a2l_study_196&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 indica que un compresor tiene falla de v\xE1lvulas internas?&quot;, opciones:[&quot;Ruido normal de operaci\xF3n&quot;,&quot;Presi\xF3n de baja alta Y presi\xF3n de alta baja simult\xE1neamente \u2014 el compresor no puede crear la diferencia de presi\xF3n normal&quot;,&quot;Solo presi\xF3n de baja alta&quot;,&quot;Solo presi\xF3n de alta baja&quot;], respuesta_correcta:1, explicacion:&quot;Falla de v\xE1lvulas del compresor: presi\xF3n de baja ALTA y presi\xF3n de alta BAJA al mismo tiempo. El compresor no puede mantener la diferencia de presi\xF3n. Diferente a un compresor que no arranca o que tiene problema el\xE9ctrico.&quot; }, { id:&quot;a2l_study_197&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFPor qu\xE9 los sistemas A2L requieren espec\xEDficamente compresores certificados para A2L?&quot;, opciones:[&quot;Solo por requisito de garant\xEDa&quot;,&quot;Los compresores para A2L tienen materiales y sellados compatibles con los nuevos refrigerantes y aceites, adem\xE1s de componentes el\xE9ctricos internos dise\xF1ados para no encender el A2L&quot;,&quot;Solo por presiones diferentes&quot;,&quot;No hay diferencia \u2014 cualquier compresor compatible por presi\xF3n funciona&quot;], respuesta_correcta:1, explicacion:&quot;Los compresores A2L certificados tienen: (1) materiales internos compatibles con HFC/HFO y POE, (2) sellados dise\xF1ados para las nuevas mezclas, y (3) componentes el\xE9ctricos internos (IS) dise\xF1ados para no generar chispa que encienda el A2L.&quot; }, { id:&quot;a2l_study_198&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 es el 'acid test' y cu\xE1ndo se realiza?&quot;, opciones:[&quot;Una prueba de limpieza del sistema&quot;,&quot;Una prueba que mide la acidez del aceite del sistema \u2014 se hace cuando se sospecha contaminaci\xF3n por burnout, humedad, o en inspecciones de mantenimiento preventivo&quot;,&quot;Solo para sistemas comerciales&quot;,&quot;Solo despu\xE9s de un burnout&quot;], respuesta_correcta:1, explicacion:&quot;El acid test mide la acidez del aceite del sistema usando un kit especial. Se realiza: (1) despu\xE9s de un burnout, (2) cuando se sospecha contaminaci\xF3n por humedad, (3) en mantenimiento preventivo en sistemas comerciales. Acidez alta indica necesidad de flush del sistema.&quot; }, { id:&quot;a2l_study_199&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFQu\xE9 verificaci\xF3n el\xE9ctrica b\xE1sica se hace a un compresor antes de reemplazarlo?&quot;, opciones:[&quot;Solo verificar que tiene voltaje&quot;,&quot;Medir resistencia de cada devanado (ohmmeter), resistencia a tierra (megohmmeter), y amperaje de operaci\xF3n vs FLA en placa&quot;,&quot;Solo verificar el capacitor&quot;,&quot;Solo medir voltaje de suministro&quot;], respuesta_correcta:1, explicacion:&quot;Verificaciones el\xE9ctricas del compresor: (1) resistencia de cada devanado (ohmmeter) \u2014 verificar que los valores son correctos y equilibrados, (2) resistencia a tierra (megohmmeter) \u2014 debe ser muy alta (Mohms), (3) amperaje de operaci\xF3n vs FLA indicado en placa.&quot; }, { id:&quot;a2l_study_200&quot;, categoria:&quot;A2L_N2&quot;, nivel:2, pregunta:&quot;\xBFCu\xE1l es la diferencia entre un compresor scroll y un compresor reciprocating (pist\xF3n)?&quot;, opciones:[&quot;No hay diferencia pr\xE1ctica&quot;,&quot;Scroll: espirales orbitales, m\xE1s silencioso y eficiente, muy com\xFAn en residencial moderno. Reciprocating: pistones, m\xE1s resistente a liquid floodback, m\xE1s com\xFAn en aplicaciones industriales&quot;,&quot;El scroll es solo para A2L&quot;,&quot;El reciprocating es m\xE1s nuevo&quot;], respuesta_correcta:1, explicacion:&quot;Scroll: dos espirales que rotan para comprimir \u2014 m\xE1s silencioso, m\xE1s eficiente, dominante en sistemas residenciales modernos, pero vulnerable a liquid floodback. Reciprocating (pist\xF3n): m\xE1s robusto ante liquid floodback, m\xE1s simple mec\xE1nicamente, com\xFAn en sistemas comerciales e industriales.&quot; }, { id:&quot;a2l_study_201&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un sistema R-454B tiene temperatura de salida normal pero la presi\xF3n de baja est\xE1 ligeramente elevada. El airflow es correcto. \xBFQu\xE9 verificar?&quot;, opciones:[&quot;Cambiar el compresor inmediatamente&quot;,&quot;Verificar: TXV atascada abierta, sobrecarga de refrigerante, o temperatura de evaporador m\xE1s alta que lo normal por carga de calor elevada&quot;,&quot;A\xF1adir refrigerante&quot;,&quot;Solo verificar el filtro&quot;], respuesta_correcta:1, explicacion:&quot;Presi\xF3n de baja ligeramente alta con airflow correcto puede indicar: TXV atascada en posici\xF3n abierta (alimentando m\xE1s refrigerante), sobrecarga de refrigerante, o simplemente una carga de calor mayor que lo normal (clima m\xE1s caliente, espacio m\xE1s ocupado).&quot; }, { id:&quot;a2l_study_202&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Al llegar a un sistema R-32 con 'no cooling', encuentras presi\xF3n de baja y alta iguales con el compresor corriendo. \xBFCu\xE1l es el diagn\xF3stico m\xE1s probable?&quot;, opciones:[&quot;El sistema necesita refrigerante&quot;,&quot;Compresor no est\xE1 comprimiendo \u2014 v\xE1lvulas rotas o falla mec\xE1nica interna&quot;,&quot;El condensador est\xE1 bloqueado&quot;,&quot;El TXV est\xE1 atascado&quot;], respuesta_correcta:1, explicacion:&quot;Presiones iguales en alta y baja con el compresor funcionando = el compresor NO EST\xC1 COMPRIMIENDO. El compresor funciona el\xE9ctrica/mec\xE1nicamente (enciende) pero sus v\xE1lvulas internas est\xE1n defectuosas o hay p\xE9rdida severa de compresi\xF3n interna.&quot; }, { id:&quot;a2l_study_203&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un sistema R-454B tiene condensador muy caliente al tacto pero la presi\xF3n de alta es normal. \xBFQu\xE9 puede indicar?&quot;, opciones:[&quot;Situaci\xF3n normal&quot;,&quot;El condensador puede tener restricci\xF3n de airflow \u2014 el refrigerante est\xE1 condensando pero transfiriendo menos calor, causando temperatura superficial alta con presi\xF3n aparentemente normal por un tiempo&quot;,&quot;El compresor est\xE1 fallando&quot;,&quot;Falta refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;Un condensador muy caliente con presi\xF3n aparentemente normal puede indicar restricci\xF3n parcial de airflow \u2014 el condensador est\xE1 sobrecalentado y eventualmente la presi\xF3n de alta comenzar\xE1 a subir. Limpiar el condensador y verificar el ventilador.&quot; }, { id:&quot;a2l_study_204&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFC\xF3mo diferencias entre un sistema R-32 bajo en refrigerante vs un sistema con restricci\xF3n en la l\xEDnea l\xEDquida?&quot;, opciones:[&quot;No se puede diferenciar&quot;,&quot;Baja carga: presi\xF3n de baja baja + superheat alto + subcooling bajo. Restricci\xF3n en l\xEDnea l\xEDquida: presi\xF3n de baja baja + superheat alto + subcooling ALTO (el refrigerante se acumula antes de la restricci\xF3n)&quot;,&quot;Son id\xE9nticos \u2014 se resuelven igual&quot;,&quot;Solo midiendo el peso del refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;La diferencia clave est\xE1 en el SUBCOOLING: baja carga de refrigerante muestra subcooling BAJO. Una restricci\xF3n en la l\xEDnea l\xEDquida muestra subcooling ALTO (el refrigerante se acumula antes de la restricci\xF3n, el sistema 'cree' que tiene suficiente pero no llega correctamente).&quot; }, { id:&quot;a2l_study_205&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un cliente reporta que el sistema R-454B enfr\xEDa bien en la ma\xF1ana pero no en las tardes calientes. \xBFCu\xE1l es la causa m\xE1s probable?&quot;, opciones:[&quot;El sistema est\xE1 en buenas condiciones&quot;,&quot;El sistema est\xE1 dise\xF1ado o cargado para condiciones normales pero en pico de calor (temperatura alta exterior) no tiene capacidad suficiente \u2014 posible subdimensionamiento o condensador sucio&quot;,&quot;El termostato est\xE1 roto&quot;,&quot;Falta refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;Sistema que enfr\xEDa bien en condiciones normales pero no en pico de calor puede indicar: sistema subdimensionado para la carga m\xE1xima, condensador parcialmente sucio (funciona bien con temperatura ambiente baja pero falla en calor extremo), o carga de refrigerante marginalmente baja.&quot; }, { id:&quot;a2l_study_206&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es el diagn\xF3stico cuando la presi\xF3n de baja es normal pero el amperaje del compresor R-32 est\xE1 muy elevado?&quot;, opciones:[&quot;El compresor est\xE1 perfecto&quot;,&quot;Posibles causas: condensador bloqueado (presi\xF3n de alta elevada que eleva amperaje), voltaje bajo, problema mec\xE1nico interno del compresor, o capacitor deficiente&quot;,&quot;El sistema necesita refrigerante&quot;,&quot;El filtro-drier est\xE1 bloqueado&quot;], respuesta_correcta:1, explicacion:&quot;Alto amperaje con presi\xF3n de baja normal puede indicar: (1) presi\xF3n de alta elevada por condensador bloqueado aumentando la carga del compresor, (2) voltaje bajo que causa sobreintensidad, (3) problema mec\xE1nico interno (rodamientos) del compresor, (4) capacitor deficiente en monof\xE1sico.&quot; }, { id:&quot;a2l_study_207&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un t\xE9cnico encuentra un sistema R-454B que fue instalado hace 3 meses y ya perdi\xF3 el 25% de su carga. \xBFCu\xE1l es el primer paso?&quot;, opciones:[&quot;Recargar el 25% perdido&quot;,&quot;ENCONTRAR Y REPARAR la fuga antes de a\xF1adir refrigerante \u2014 recargar sin reparar viola regulaciones y es in\xFAtil a largo plazo&quot;,&quot;Solo a\xF1adir la mitad y ver qu\xE9 pasa&quot;,&quot;Cambiar el sistema completo&quot;], respuesta_correcta:1, explicacion:&quot;SIEMPRE localizar y reparar la fuga ANTES de recargar. Las regulaciones EPA requieren reparar fugas. Recargar sin reparar es desperdiciar refrigerante, dinero, y potencialmente violar regulaciones de fuga si el sistema supera el umbral anual.&quot; }, { id:&quot;a2l_study_208&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un cliente reporta que el sistema hace un ruido de 'burbujeo' en la l\xEDnea l\xEDquida. \xBFQu\xE9 indica?&quot;, opciones:[&quot;Operaci\xF3n normal&quot;,&quot;Hay vapor (burbujas) en la l\xEDnea l\xEDquida \u2014 indicativo de bajo subcooling, posiblemente por baja carga de refrigerante o refrigerante evapor\xE1ndose por ca\xEDda de presi\xF3n antes de la TXV&quot;,&quot;El compresor est\xE1 haciendo ruido&quot;,&quot;El condensador tiene problemas&quot;], respuesta_correcta:1, explicacion:&quot;Ruido de burbujeo en la l\xEDnea l\xEDquida = vapor en la l\xEDnea l\xEDquida = bajo subcooling. Las burbujas de vapor bloquean la alimentaci\xF3n correcta de la TXV reduciendo la capacidad del sistema. Puede ser por: baja carga de refrigerante, subcooling insuficiente del condensador, o restricci\xF3n en la l\xEDnea l\xEDquida.&quot; }, { id:&quot;a2l_study_209&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 diagn\xF3stico se hace cuando un sistema R-32 tiene ICE form\xE1ndose en la l\xEDnea de succi\xF3n afuera del evaporador?&quot;, opciones:[&quot;El sistema funciona perfectamente \u2014 el hielo es normal&quot;,&quot;Bajo superheat \u2014 refrigerante l\xEDquido est\xE1 saliendo del evaporador y llegando a la l\xEDnea de succi\xF3n donde se congela el condensado. Posible: TXV atascada abierta, sobrecarga de refrigerante, o bajo airflow del evaporador&quot;,&quot;El sistema tiene fuga&quot;,&quot;El condensador est\xE1 sucio&quot;], respuesta_correcta:1, explicacion:&quot;Hielo en la l\xEDnea de succi\xF3n FUERA del evaporador indica superheat muy bajo \u2014 el refrigerante no termin\xF3 de evaporarse en el evaporador y sale como l\xEDquido. Causas: TXV sobredimensionada/atascada abierta, refrigerante en exceso, o bajo airflow en el evaporador.&quot; }, { id:&quot;a2l_study_210&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFC\xF3mo distingues entre ICE en el evaporador por bajo airflow vs por bajo superheat (baja carga)?&quot;, opciones:[&quot;No se puede distinguir&quot;,&quot;Bajo airflow: hielo empieza desde la entrada del evaporador donde el aire es m\xE1s fr\xEDo. Bajo superheat/baja carga: hielo tiende a formarse m\xE1s uniformemente o desde el centro/salida del evaporador&quot;,&quot;Son id\xE9nticos&quot;,&quot;Solo midiendo la carga del sistema&quot;], respuesta_correcta:1, explicacion:&quot;El patr\xF3n de hielo puede ayudar a distinguir: bajo airflow causa hielo que comienza desde la entrada del evaporador (donde el aire fr\xEDo se estanca). Bajo superheat/baja carga causa formaci\xF3n de hielo m\xE1s uniforme. Sin embargo, medir superheat y verificar airflow es m\xE1s confiable.&quot; }, { id:&quot;a2l_study_211&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un sistema R-454B nuevo fue instalado hace 1 semana y el t\xE9cnico reporta que la presi\xF3n de alta sube progresivamente durante la operaci\xF3n. \xBFQu\xE9 puede indicar?&quot;, opciones:[&quot;Funcionamiento normal en sistema nuevo&quot;,&quot;Posible presencia de no-condensables (aire) en el sistema \u2014 los gases no-condensables se acumulan en el condensador elevando la presi\xF3n de alta progresivamente&quot;,&quot;El condensador est\xE1 sucio&quot;,&quot;El compresor est\xE1 fallando&quot;], respuesta_correcta:1, explicacion:&quot;Presi\xF3n de alta que sube PROGRESIVAMENTE puede indicar no-condensables (generalmente aire) en el sistema \u2014 se acumulan en el condensador con el tiempo. Verificar: comparar presi\xF3n de saturaci\xF3n de la tabla P/T con la presi\xF3n actual del sistema cuando est\xE9 APAGADO y estabilizado.&quot; }, { id:&quot;a2l_study_212&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 indica una lectura de 'ground fault' (falla a tierra) en el motor del compresor?&quot;, opciones:[&quot;El compresor est\xE1 en perfectas condiciones&quot;,&quot;El barniz aislante del motor se ha deteriorado \u2014 hay contacto el\xE9ctrico entre los devanados y la carcasa del compresor. Generalmente indica falla o falla inminente del compresor&quot;,&quot;Solo problemas de instalaci\xF3n el\xE9ctrica&quot;,&quot;El capacitor est\xE1 defectuoso&quot;], respuesta_correcta:1, explicacion:&quot;Ground fault (falla a tierra) en el compresor = el barniz aislante del motor se ha deteriorado, permitiendo contacto el\xE9ctrico entre devanados y carcasa. Puede indicar: quemado del motor (burnout), contaminaci\xF3n severa del aceite, o degradaci\xF3n por sobrecalentamiento. El compresor generalmente necesita reemplazo.&quot; }, { id:&quot;a2l_study_213&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 pueden indicar lecturas de resistencia el\xE9ctricas DESEQUILIBRADAS entre los 3 devanados (R, S, C) de un compresor trif\xE1sico?&quot;, opciones:[&quot;Funcionamiento normal&quot;,&quot;Devanado(s) con resistencia diferente pueden indicar: devanado quemado parcialmente, cortocircuito interno, o compresor con burnout incipiente&quot;,&quot;Solo diferencia de calibraci\xF3n del instrumento&quot;,&quot;Solo indica que el compresor necesita aceite&quot;], respuesta_correcta:1, explicacion:&quot;En compresores trif\xE1sicos, las resistencias entre R-C, S-C, y T-C deben ser similares. Desequilibrio significativo puede indicar devanado quemado parcialmente o cortocircuito interno. Siempre comparar con las especificaciones del fabricante del compresor.&quot; }, { id:&quot;a2l_study_214&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un sistema R-32 de bomba de calor no calienta eficientemente en invierno aunque enfr\xEDa bien en verano. \xBFCu\xE1l es la revisi\xF3n prioritaria?&quot;, opciones:[&quot;El sistema necesita refrigerante&quot;,&quot;La v\xE1lvula de 4 v\xEDas puede no estar cambiando completamente de modo enfriamiento a calefacci\xF3n \u2014 permite bypass de refrigerante&quot;,&quot;El compresor est\xE1 fallando&quot;,&quot;El condensador est\xE1 sucio&quot;], respuesta_correcta:1, explicacion:&quot;Una v\xE1lvula de 4 v\xEDas que no cambia completamente puede hacer que parte del refrigerante tome el camino de enfriamiento incluso en modo calefacci\xF3n, reduciendo la capacidad de calefacci\xF3n. S\xEDntoma cl\xE1sico: enfr\xEDa bien pero no calienta bien (o viceversa).&quot; }, { id:&quot;a2l_study_215&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFC\xF3mo se verifica una v\xE1lvula de 4 v\xEDas defectuosa en una bomba de calor?&quot;, opciones:[&quot;Solo visualmente&quot;,&quot;Medir temperaturas en las 4 conexiones de la v\xE1lvula \u2014 un bypass interno se detectar\xE1 por temperatura incorrecta (la l\xEDnea fr\xEDa en modo calefacci\xF3n deber\xEDa ser caliente si la v\xE1lvula est\xE1 bien&quot;,&quot;Solo midiendo el amperaje del compresor&quot;,&quot;Solo verificando la presi\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;Para verificar una v\xE1lvula de 4 v\xEDas: en modo calefacci\xF3n medir temperaturas en las 4 puertos. Una v\xE1lvula con bypass muestra temperatura incorrecta \u2014 por ejemplo, en modo calefacci\xF3n la l\xEDnea de succi\xF3n deber\xEDa ser de la temperatura de retorno (caliente del espacio), no de la l\xEDnea de descarga.&quot; }, { id:&quot;a2l_study_216&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 indica cuando un sistema R-454B tiene amperaje BAJO en el compresor?&quot;, opciones:[&quot;Excelente eficiencia&quot;,&quot;Posibles causas: baja carga de refrigerante (el compresor tiene poca resistencia al comprimir gas poco denso), voltaje alto, o compresor desgastado con anillos en mal estado&quot;,&quot;El compresor est\xE1 en perfectas condiciones&quot;,&quot;El filtro est\xE1 limpio&quot;], respuesta_correcta:1, explicacion:&quot;Amperaje bajo en el compresor puede indicar: (1) baja carga de refrigerante (poco refrigerante = baja densidad del gas = menor trabajo para comprimir), (2) voltaje de l\xEDnea elevado, (3) compresor con desgaste interno (anillos deficientes que no comprimen efectivamente).&quot; }, { id:&quot;a2l_study_217&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 busca el t\xE9cnico cuando verifica 'superheat de sistema' vs 'superheat de evaporador'?&quot;, opciones:[&quot;Son exactamente lo mismo&quot;,&quot;Superheat de evaporador = en la salida del evaporador (indica la carga de la TXV). Superheat de sistema = en la entrada del compresor (indica el estado de la l\xEDnea de succi\xF3n y posible calentamiento adicional)&quot;,&quot;El superheat de sistema no se usa&quot;,&quot;Solo se mide uno de los dos&quot;], respuesta_correcta:1, explicacion:&quot;Superheat de evaporador = temperatura de succi\xF3n en la salida del evaporador menos temperatura de saturaci\xF3n. Indica si la TXV est\xE1 trabajando correctamente. Superheat de sistema = temperatura de succi\xF3n en la entrada del compresor. Diferencia entre los dos indica cu\xE1nto se calienta el vapor en la l\xEDnea de succi\xF3n.&quot; }, { id:&quot;a2l_study_218&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un sistema R-32 comercial tiene presi\xF3n de alta que FLUCT\xDAA constantemente en lugar de ser estable. \xBFQu\xE9 puede indicar?&quot;, opciones:[&quot;Funcionamiento normal&quot;,&quot;Posibles causas: TXV 'hunting' (oscilando), ventilador del condensador c\xEDclico, o fluctuaciones de carga de calor \u2014 verificar primero si el ventilador del condensador est\xE1 funcionando correctamente&quot;,&quot;Solo ruido el\xE9ctrico en el man\xF3metro&quot;,&quot;El compresor est\xE1 fallando&quot;], respuesta_correcta:1, explicacion:&quot;Fluctuaci\xF3n de presi\xF3n de alta puede indicar: ventilador del condensador que cicla (on/off) irregularmente, TXV hunting que crea fluctuaciones de presi\xF3n en toda la alta, o variaciones significativas en la carga del condensador.&quot; }, { id:&quot;a2l_study_219&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'thermal expansion valve hunting' y c\xF3mo se identifica?&quot;, opciones:[&quot;Cuando la TXV est\xE1 atascada cerrada&quot;,&quot;Cuando la TXV oscila continuamente abriendo y cerrando \u2014 se identifica por fluctuaciones continuas de superheat y presi\xF3n de baja sin llegar a estabilizarse&quot;,&quot;Cuando la TXV tiene fuga interna&quot;,&quot;Solo ocurre en sistemas A2L&quot;], respuesta_correcta:1, explicacion:&quot;TXV hunting = la v\xE1lvula no puede encontrar un punto de equilibrio y oscila continuamente. Se identifica por: superheat y presi\xF3n de baja que suben y bajan continuamente sin estabilizarse. Causas: TXV sobredimensionada, bulbo mal posicionado, o ajuste incorrecto del superheat de la TXV.&quot; }, { id:&quot;a2l_study_220&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un sistema R-454B de split residencial hace ruido de 'chasquido' (clicking) al arrancar. \xBFQu\xE9 verificar primero en el sistema el\xE9ctrico?&quot;, opciones:[&quot;Nada \u2014 es normal&quot;,&quot;Verificar el capacitor de arranque y de funcionamiento \u2014 el clicking puede indicar que el compresor intenta arrancar pero el capacitor no tiene suficiente energ\xEDa para iniciar la rotaci\xF3n&quot;,&quot;Verificar el termostato&quot;,&quot;Verificar el voltaje del sistema&quot;], respuesta_correcta:1, explicacion:&quot;El chasquido de arranque seguido de apagado puede indicar un CAPACITOR deficiente. El motor del compresor intenta iniciar la rotaci\xF3n pero el capacitor no provee suficiente torque de arranque. El capacitor con alta tensi\xF3n de descarga (capacitores para A2L) es especialmente importante verificar con medidor de capacitancia.&quot; }, { id:&quot;a2l_study_221&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la prueba el\xE9ctrica m\xE1s importante ANTES de comenzar trabajo en un sistema A2L de-energizado?&quot;, opciones:[&quot;Medir el voltaje de l\xEDnea&quot;,&quot;Verificar con mult\xEDmetro que hay cero voltaje presente DESPU\xC9S del lockout/tagout \u2014 no asumir que el sistema est\xE1 de-energizado&quot;,&quot;Solo apagar el breaker&quot;,&quot;Solo desconectar el termostato&quot;], respuesta_correcta:1, explicacion:&quot;PRIMERO: aplicar LOTO (lockout/tagout) COMPLETO, luego VERIFICAR con mult\xEDmetro que hay cero voltaje. Nunca asumir que el sistema est\xE1 de-energizado solo porque el breaker est\xE1 apagado. El t\xE9cnico que realiza el trabajo debe tener la \xFAnica llave del candado.&quot; }, { id:&quot;a2l_study_222&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'locked rotor amperage' (LRA) y por qu\xE9 importa?&quot;, opciones:[&quot;El amperaje normal de operaci\xF3n&quot;,&quot;El amperaje m\xE1ximo que el motor del compresor toma en el instante de arranque cuando el rotor est\xE1 'atascado' antes de comenzar a girar \u2014 puede ser 5-8 veces el FLA&quot;,&quot;El amperaje de fallo del motor&quot;,&quot;El amperaje m\xEDnimo de operaci\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;LRA = amperaje m\xE1ximo al arranque (antes de que el motor comience a girar). Puede ser 5-8 veces el FLA (Full Load Amperage) normal. Importante para: dimensionar los conductores, breakers y capacitores correctamente. Un capacitor deficiente hace que el LRA dure m\xE1s tiempo del normal.&quot; }, { id:&quot;a2l_study_223&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 los sistemas A2L requieren componentes el\xE9ctricos 'intrinsically safe' (IS)?&quot;, opciones:[&quot;Por el mayor consumo de energ\xEDa&quot;,&quot;Para prevenir que una falla el\xE9ctrica genere suficiente energ\xEDa para encender el A2L \u2014 los contactores y capacitores IS est\xE1n dise\xF1ados para contener chispas dentro del enclosure herm\xE9tico&quot;,&quot;Solo por reducci\xF3n de consumo&quot;,&quot;Solo es un requisito de garant\xEDa&quot;], respuesta_correcta:1, explicacion:&quot;Los componentes IS en sistemas A2L tienen enclosures herm\xE9ticos que contienen cualquier chispa o arco interno, previniendo que se exponga al ambiente donde podr\xEDa haber vapores de A2L. Si un componente IS falla, la chispa queda DENTRO del enclosure.&quot; }, { id:&quot;a2l_study_224&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 indica una lectura de resistencia a tierra de 0 ohms en el motor del compresor?&quot;, opciones:[&quot;El motor est\xE1 en perfectas condiciones&quot;,&quot;Falla completa a tierra \u2014 el barniz aislante est\xE1 completamente deteriorado. El compresor necesita reemplazo&quot;,&quot;Solo indica que est\xE1 bien aterrizado&quot;,&quot;Solo un problema de calibraci\xF3n del instrumento&quot;], respuesta_correcta:1, explicacion:&quot;Resistencia a tierra de 0 ohms (o cualquier valor bajo) = SHORT COMPLETO A TIERRA. El barniz aislante del motor est\xE1 completamente deteriorado, creando contacto directo entre devanados y carcasa met\xE1lica. El compresor NECESITA reemplazo \u2014 no es reparable en campo.&quot; }, { id:&quot;a2l_study_225&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'desequilibrio de voltaje' y c\xF3mo afecta compresores trif\xE1sicos?&quot;, opciones:[&quot;Una variaci\xF3n aceptable en sistemas trif\xE1sicos&quot;,&quot;Un desequilibrio de m\xE1s de 2% entre las tres fases puede causar sobrecalentamiento severo del motor del compresor \u2014 cada 1% de desequilibrio causa aumento desproporcionado en el calor del motor&quot;,&quot;Solo afecta a sistemas grandes&quot;,&quot;No afecta a compresores modernos&quot;], respuesta_correcta:1, explicacion:&quot;Desequilibrio de voltaje > 2% entre las 3 fases causa corrientes desequilibradas en el motor. Un desequilibrio de 3.5% puede causar aumento de temperatura del 25% en el motor. Los compresores trif\xE1sicos son muy sensibles al desequilibrio \u2014 verificar y corregir en la fuente de alimentaci\xF3n.&quot; }, { id:&quot;a2l_study_226&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFC\xF3mo se mide correctamente el amperaje de un compresor monof\xE1sico?&quot;, opciones:[&quot;Solo en la l\xEDnea de entrada al equipo&quot;,&quot;Con la pinza amperim\xE9trica en el conductor de la l\xEDnea caliente (hot wire) al compresor espec\xEDficamente \u2014 no en el conductor neutral ni en el wire completo del equipo&quot;,&quot;En el conductor neutral&quot;,&quot;Con el equipo apagado&quot;], respuesta_correcta:1, explicacion:&quot;Para medir amperaje del compresor: colocar la pinza en el HOT WIRE que va espec\xEDficamente al compresor. El conductor neutral en sistemas monof\xE1sicos lleva el mismo amperaje pero en direcci\xF3n opuesta \u2014 medir el hot wire es la pr\xE1ctica est\xE1ndar para comparar con el FLA de la placa.&quot; }, { id:&quot;a2l_study_227&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la funci\xF3n del capacitor de arranque (start capacitor) vs el capacitor de funcionamiento (run capacitor)?&quot;, opciones:[&quot;Son exactamente lo mismo&quot;,&quot;Start: alta capacitancia solo durante el arranque para proveer torque inicial, se desconecta r\xE1pidamente. Run: menor capacitancia, permanece en circuito durante toda la operaci\xF3n para mejorar eficiencia&quot;,&quot;El start cap es para motores grandes, el run cap para peque\xF1os&quot;,&quot;Solo los sistemas A2L usan run capacitors&quot;], respuesta_correcta:1, explicacion:&quot;Start capacitor: alta capacitancia (100-600 \xB5F) que provee torque adicional SOLO durante el arranque \u2014 se desconecta por el starting relay en 1-3 segundos. Run capacitor: menor capacitancia (5-60 \xB5F) que permanece en circuito DURANTE toda la operaci\xF3n para desplazamiento de fase y eficiencia.&quot; }, { id:&quot;a2l_study_228&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 indica un capacitor 'swollen' (hinchado)?&quot;, opciones:[&quot;Que est\xE1 completamente funcional&quot;,&quot;Que el capacitor ha fallado o est\xE1 pr\xF3ximo a fallar \u2014 el gas interno se ha expandido por sobrecalentamiento o falla del diel\xE9ctrico. Debe reemplazarse&quot;,&quot;Solo que es un capacitor de alta capacidad&quot;,&quot;Que el sistema tiene exceso de voltaje&quot;], respuesta_correcta:1, explicacion:&quot;Un capacitor hinchado (swollen) indica falla interna \u2014 el diel\xE9ctrico se ha degradado generando gas que expande la carcasa. Nunca usar un capacitor hinchado \u2014 puede explotar o causar falla el\xE9ctrica que da\xF1e otros componentes. Reemplazar inmediatamente.&quot; }, { id:&quot;a2l_study_229&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 causa el 'thermal overload' de un compresor y c\xF3mo se resetea?&quot;, opciones:[&quot;Una falla del compresor que requiere reemplazo&quot;,&quot;El overload protector interno del compresor abre el circuito por sobrecalentamiento \u2014 generalmente se resetea autom\xE1ticamente cuando el compresor se enfr\xEDa. La causa subyacente debe investigarse&quot;,&quot;Solo requiere resetear el breaker&quot;,&quot;Solo ocurre en sistemas viejos&quot;], respuesta_correcta:1, explicacion:&quot;El thermal overload (sobrecarga t\xE9rmica) abre el circuito del compresor cuando detecta temperatura o amperaje excesivo. Se resetea autom\xE1ticamente cuando el compresor se enfr\xEDa. La causa (voltaje bajo, presiones incorrectas, poca ventilaci\xF3n del compresor) DEBE identificarse y corregirse.&quot; }, { id:&quot;a2l_study_230&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 mide la 'resistencia de aislamiento' con un megohmmeter en el motor del compresor?&quot;, opciones:[&quot;La resistencia de los devanados del motor&quot;,&quot;La calidad del barniz aislante entre los devanados y la carcasa \u2014 un valor alto (Mohms) indica buen aislamiento, un valor bajo indica degradaci\xF3n del aislante&quot;,&quot;El amperaje m\xE1ximo del motor&quot;,&quot;La capacitancia del capacitor&quot;], respuesta_correcta:1, explicacion:&quot;El megohmmeter mide la resistencia de AISLAMIENTO entre los devanados del motor y la carcasa met\xE1lica. Valor alto (>10 MOhms) = buen aislamiento. Valor bajo = barniz deteriorado = riesgo de falla a tierra. Se realiza en compresores con sospecha de burnout o como mantenimiento preventivo.&quot; }, { id:&quot;a2l_study_231&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFC\xF3mo se ajusta el superheat de una TXV con bulbo externo?&quot;, opciones:[&quot;No se puede ajustar en campo&quot;,&quot;Girando el tornillo de ajuste en la base de la v\xE1lvula \u2014 sentido horario AUMENTA el superheat (cierra m\xE1s la v\xE1lvula), sentido antihorario DISMINUYE el superheat&quot;,&quot;Solo se ajusta en f\xE1brica&quot;,&quot;Solo cambiando el bulbo&quot;], respuesta_correcta:1, explicacion:&quot;La TXV se ajusta girando el tornillo de ajuste: HORARIO = aumenta la tensi\xF3n del resorte = aumenta el superheat (cierra m\xE1s la v\xE1lvula). ANTIHORARIO = disminuye la tensi\xF3n = disminuye el superheat. Hacer ajustes peque\xF1os (1/4 a 1/2 vuelta) y esperar 15-20 minutos para evaluar el efecto.&quot; }, { id:&quot;a2l_study_232&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFD\xF3nde se instala correctamente el bulbo de la TXV?&quot;, opciones:[&quot;Junto al compresor&quot;,&quot;En la l\xEDnea de succi\xF3n, cercano a la salida del evaporador, en posici\xF3n de las 4 a las 8 del reloj para buen contacto t\xE9rmico, aislado del ambiente exterior&quot;,&quot;En el condesador&quot;,&quot;En la l\xEDnea l\xEDquida&quot;], respuesta_correcta:1, explicacion:&quot;El bulbo de la TXV va en la l\xEDnea de SUCCI\xD3N, cerca de la SALIDA del evaporador (donde mide el superheat). Debe estar en posici\xF3n entre las 4 y las 8 del reloj para buen contacto con el refrigerante en la tuber\xEDa. Debe estar bien aislado del ambiente exterior para que solo mida la temperatura del refrigerante.&quot; }, { id:&quot;a2l_study_233&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'flash gas' y d\xF3nde ocurre en el sistema?&quot;, opciones:[&quot;Gas de escape del sistema&quot;,&quot;Una peque\xF1a porci\xF3n del refrigerante l\xEDquido que se vaporiza instant\xE1neamente al pasar por el dispositivo de metering \u2014 esta vaporizaci\xF3n enfr\xEDa el refrigerante restante&quot;,&quot;Gas en el tanque de recuperaci\xF3n&quot;,&quot;Solo en sistemas A3&quot;], respuesta_correcta:1, explicacion:&quot;Flash gas = peque\xF1a porci\xF3n del refrigerante l\xEDquido que se vaporiza inmediatamente al pasar por la v\xE1lvula de expansi\xF3n (ca\xEDda de presi\xF3n s\xFAbita). Este proceso de vaporizaci\xF3n absorbe calor latente, enfriando el refrigerante restante a la temperatura de evaporaci\xF3n correcta.&quot; }, { id:&quot;a2l_study_234&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 el refrigerante que llega a la TXV debe llegar como L\xCDQUIDO puro (100%) y no con vapor?&quot;, opciones:[&quot;No importa el estado \u2014 la TXV maneja ambos&quot;,&quot;La TXV est\xE1 dise\xF1ada para medrar L\xCDQUIDO. Si llega vapor (burbujas), la capacidad real de la v\xE1lvula se reduce significativamente porque el vapor ocupa mucho m\xE1s volumen que el l\xEDquido&quot;,&quot;Solo importa para A2L&quot;,&quot;Solo para TXV termost\xE1ticas, no electr\xF3nicas&quot;], respuesta_correcta:1, explicacion:&quot;La TXV mide el VOLUMEN de refrigerante, no la masa. El vapor ocupa ~20 veces m\xE1s volumen que el l\xEDquido a la misma presi\xF3n. Si hay vapor mezclado con el l\xEDquido, la TXV 'cree' que est\xE1 pasando m\xE1s refrigerante del que realmente est\xE1 pasando en masa, reduciendo la capacidad real del sistema.&quot; }, { id:&quot;a2l_study_235&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la se\xF1al de que una TXV tiene el bulbo 'perdido su carga' (perdi\xF3 el refrigerante interno del bulbo)?&quot;, opciones:[&quot;La TXV nunca falla de esta manera&quot;,&quot;La TXV se cierra completamente porque no hay presi\xF3n en el bulbo para abrirla \u2014 el sistema tendr\xE1 presi\xF3n de baja muy baja o en vac\xEDo&quot;,&quot;La TXV se abre completamente&quot;,&quot;No tiene efecto visible&quot;], respuesta_correcta:1, explicacion:&quot;Si el bulbo de la TXV pierde su carga (refrigerante interno), la presi\xF3n del bulbo cae a cero. Sin presi\xF3n del bulbo, solo act\xFAa el resorte que mantiene la v\xE1lvula CERRADA. El sistema tendr\xE1 presi\xF3n de baja extremadamente baja (o vac\xEDo) y el evaporador no estar\xE1 fr\xEDo.&quot; }, { id:&quot;a2l_study_236&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'MOP' (Maximum Operating Pressure) en TXVs con limitaci\xF3n?&quot;, opciones:[&quot;La presi\xF3n m\xE1xima de la l\xEDnea de alta&quot;,&quot;Un mecanismo en algunas TXV que previene que la v\xE1lvula abra completamente cuando la presi\xF3n de baja excede un valor preestablecido \u2014 protege el compresor de arrancar en condiciones de alta presi\xF3n&quot;,&quot;La presi\xF3n m\xE1xima del bulbo&quot;,&quot;Solo para sistemas industriales&quot;], respuesta_correcta:1, explicacion:&quot;MOP (Maximum Operating Pressure) = caracter\xEDstica de algunas TXV que limita la apertura m\xE1xima cuando la presi\xF3n de evaporador excede un valor establecido. Esto previene que el compresor arranque con carga excesiva (alta presi\xF3n de baja) despu\xE9s de un apagado largo en ambiente caliente.&quot; }, { id:&quot;a2l_study_237&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1les son las se\xF1ales de una TXV atascada en posici\xF3n CERRADA?&quot;, opciones:[&quot;Presiones de alta elevadas&quot;,&quot;Presi\xF3n de baja extremadamente baja o en vac\xEDo, superheat muy alto, l\xEDnea de succi\xF3n caliente y seca \u2014 el evaporador 'muere de hambre' sin refrigerante&quot;,&quot;Presi\xF3n de baja normal&quot;,&quot;Solo un ruido inusual&quot;], respuesta_correcta:1, explicacion:&quot;TXV atascada cerrada: el evaporador recibe poco o nada de refrigerante. S\xEDntomas: presi\xF3n de baja MUY baja o vac\xEDo, superheat extremadamente alto (l\xEDnea de succi\xF3n muy caliente y seca), sin enfriamiento, y posible formaci\xF3n de hielo solo en el inicio del evaporador.&quot; }, { id:&quot;a2l_study_238&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la ventaja de una EEV (electronic expansion valve) sobre una TXV termost\xE1tica?&quot;, opciones:[&quot;La EEV es m\xE1s barata&quot;,&quot;La EEV puede ajustarse electr\xF3nicamente por el controlador del sistema con mucha mayor precisi\xF3n y velocidad, respondiendo a condiciones cambiantes de manera m\xE1s eficiente que la TXV mec\xE1nica&quot;,&quot;La TXV es siempre mejor&quot;,&quot;No hay diferencia pr\xE1ctica&quot;], respuesta_correcta:1, explicacion:&quot;La EEV se controla electr\xF3nicamente (pasos de motor stepper), permitiendo ajuste mucho m\xE1s preciso y r\xE1pido que la TXV mec\xE1nica. Los sistemas modernos A2L con controladores inteligentes usan EEV para optimizar la eficiencia bajo cualquier condici\xF3n de carga.&quot; }, { id:&quot;a2l_study_239&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 la TXV necesita un diferencial de presi\xF3n m\xEDnimo para funcionar correctamente?&quot;, opciones:[&quot;No necesita diferencial espec\xEDfico&quot;,&quot;La TXV require que el lado de alta sea significativamente mayor que el lado de baja para funcionar \u2014 si el diferencial es muy peque\xF1o, no puede controlar el flujo correctamente&quot;,&quot;Solo para TXVs antiguas&quot;,&quot;Solo en climas fr\xEDos&quot;], respuesta_correcta:1, explicacion:&quot;La TXV necesita un diferencial de presi\xF3n adecuado entre alta y baja para funcionar correctamente (generalmente al menos 100 PSI de diferencial en sistemas de alta presi\xF3n). Diferencial muy bajo hace que la v\xE1lvula sea inestable o no pueda regular el flujo apropiadamente.&quot; }, { id:&quot;a2l_study_240&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 causa que una TXV quede atascada en posici\xF3n ABIERTA?&quot;, opciones:[&quot;El bulbo pierde su carga&quot;,&quot;Contaminaci\xF3n en el orificio de la v\xE1lvula, resorte roto, o da\xF1o del diafragma \u2014 la v\xE1lvula no puede cerrarse correctamente causando inundaci\xF3n del evaporador&quot;,&quot;La TXV siempre se ataca cerrada&quot;,&quot;Solo ocurre en sistemas A2L&quot;], respuesta_correcta:1, explicacion:&quot;TXV atascada abierta: contaminaci\xF3n en el orificio de la v\xE1lvula, resorte roto o debilitado, o da\xF1o del diafragma de control. S\xEDntomas: superheat muy bajo o negativo (refrigerante l\xEDquido al compresor), presi\xF3n de baja alta, y potencial liquid floodback al compresor.&quot; }, { id:&quot;a2l_study_241&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la temperatura de condensaci\xF3n \xF3ptima para un sistema de A/C residencial con R-454B?&quot;, opciones:[&quot;Igual que la temperatura del aire exterior&quot;,&quot;La temperatura de condensaci\xF3n debe ser aproximadamente 20-30\xB0F MAYOR que la temperatura del aire exterior para que haya transferencia de calor adecuada&quot;,&quot;Igual que la temperatura interior&quot;,&quot;No hay temperatura \xF3ptima&quot;], respuesta_correcta:1, explicacion:&quot;La temperatura de condensaci\xF3n debe ser t\xEDpicamente 20-30\xB0F m\xE1s alta que la temperatura del aire exterior (approach temperature). Si la temperatura exterior es 95\xB0F, la temperatura de condensaci\xF3n deber\xEDa ser ~115-125\xB0F. Mayor diferencia = mayor transferencia de calor.&quot; }, { id:&quot;a2l_study_242&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 causa que el condensador se 'sub-enfr\xEDe' excesivamente?&quot;, opciones:[&quot;La temperatura exterior es baja&quot;,&quot;Exceso de refrigerante en el sistema \u2014 el refrigerante extra se acumula en el condensador causando subcooling mayor al dise\xF1ado&quot;,&quot;El ventilador del condensador est\xE1 demasiado r\xE1pido&quot;,&quot;El compresor es demasiado eficiente&quot;], respuesta_correcta:1, explicacion:&quot;Subcooling excesivo generalmente indica EXCESO DE REFRIGERANTE en el sistema. El refrigerante extra se acumula en el condensador, aumentando el subcooling pero tambi\xE9n reduciendo la superficie disponible para condensaci\xF3n (elevando la presi\xF3n de alta).&quot; }, { id:&quot;a2l_study_243&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 ocurre con el sistema cuando el ventilador del condensador falla completamente?&quot;, opciones:[&quot;El sistema sigue funcionando sin problemas&quot;,&quot;La presi\xF3n de alta sube r\xE1pidamente hasta disparar el presostato de alta o el thermal overload del compresor \u2014 el sistema se apaga por protecci\xF3n&quot;,&quot;Solo reduce la eficiencia un poco&quot;,&quot;Solo aumenta el ruido&quot;], respuesta_correcta:1, explicacion:&quot;Sin ventilador del condensador: el calor no puede disiparse al exterior, la presi\xF3n de alta sube r\xE1pidamente. El presostato de alta presi\xF3n (high pressure cutout) abre el circuito del compresor por protecci\xF3n. El sistema cicla on/off o se apaga completamente.&quot; }, { id:&quot;a2l_study_244&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 se usa agua jabonosa para detectar fugas en la bobina del condensador despu\xE9s de una limpieza qu\xEDmica?&quot;, opciones:[&quot;La espuma del jab\xF3n hace m\xE1s f\xE1cil ver la suciedad&quot;,&quot;Si la bobina tiene grietas microsc\xF3picas o uniones debilitadas por la limpieza qu\xEDmica, la agua jabonosa formar\xE1 burbujas en los puntos de fuga al estar el sistema bajo presi\xF3n de nitr\xF3geno&quot;,&quot;El agua jabonosa limpia mejor&quot;,&quot;Solo por tradici\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;Despu\xE9s de limpiar un condensador con qu\xEDmicos \xE1cidos, es recomendable hacer leak check con agua jabonosa bajo presi\xF3n de nitr\xF3geno. Los qu\xEDmicos de limpieza pueden debilitar uniones o revelar grietas microsc\xF3picas existentes que el sistema presurizado resaltar\xE1 con burbujas.&quot; }, { id:&quot;a2l_study_245&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'approach temperature' del condensador y qu\xE9 indica?&quot;, opciones:[&quot;La temperatura del refrigerante entrando al condensador&quot;,&quot;La diferencia entre la temperatura de condensaci\xF3n (saturaci\xF3n) y la temperatura del aire exterior entrando al condensador \u2014 indica la eficiencia de transferencia de calor del condensador&quot;,&quot;La temperatura del aire saliendo del condensador&quot;,&quot;Solo se mide en sistemas comerciales&quot;], respuesta_correcta:1, explicacion:&quot;Approach temperature = temperatura de saturaci\xF3n del condensador - temperatura del aire de entrada al condensador. Un approach bajo (bueno) indica que el condensador est\xE1 transfiriendo calor eficientemente. Un approach alto puede indicar condensador sucio, airflow insuficiente, o sistema sobredimensionado.&quot; }, { id:&quot;a2l_study_246&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la temperatura de saturaci\xF3n \xF3ptima del evaporador en un sistema de confort de A/C?&quot;, opciones:[&quot;Igual que la temperatura del cuarto&quot;,&quot;T\xEDpicamente 35-45\xB0F para balance entre capacidad de enfriamiento y extracci\xF3n de humedad del aire \u2014 debajo de 32\xB0F el evaporador se congelar\xEDa&quot;,&quot;0\xB0F (temperatura de congelamiento)&quot;,&quot;70\xB0F (temperatura del cuarto)&quot;], respuesta_correcta:1, explicacion:&quot;La temperatura de saturaci\xF3n del evaporador en A/C de confort t\xEDpicamente es 35-45\xB0F. Esto: (1) permite enfriamiento eficiente, (2) permite condensaci\xF3n de humedad (dehumidification) en la bobina, y (3) est\xE1 sobre 32\xB0F para prevenir congelamiento en condiciones normales de operaci\xF3n.&quot; }, { id:&quot;a2l_study_247&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 el evaporador puede congelarse aun cuando el sistema tiene carga de refrigerante correcta?&quot;, opciones:[&quot;El evaporador no puede congelarse con carga correcta&quot;,&quot;El bajo airflow (filtro tapado, ventilador deficiente, bobina sucia) reduce la carga de calor al evaporador, haciendo que la temperatura de saturaci\xF3n baje por debajo de 32\xB0F \u2014 el evaporador se congela incluso con la carga correcta&quot;,&quot;Solo se congela por exceso de refrigerante&quot;,&quot;Solo en climas muy fr\xEDos&quot;], respuesta_correcta:1, explicacion:&quot;El evaporador se congela cuando la temperatura de saturaci\xF3n baja de 32\xB0F. Causas: (1) bajo airflow (m\xE1s com\xFAn \u2014 el menos calor que llega, m\xE1s baja la temperatura), (2) baja carga de refrigerante (superheat bajo en evaporador), o (3) temperatura exterior muy baja en ciertos sistemas.&quot; }, { id:&quot;a2l_study_248&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFC\xF3mo se descongela correctamente un evaporador congelado antes de diagnosticar el sistema?&quot;, opciones:[&quot;Con soplete de propano directamente en el hielo&quot;,&quot;Apagando el compresor y dejando el ventilador del evaporador corriendo (modo 'fan only') hasta que el hielo se derrita naturalmente&quot;,&quot;Con agua caliente directamente&quot;,&quot;Simplemente esperar con el sistema apagado completamente&quot;], respuesta_correcta:1, explicacion:&quot;Para descongelar un evaporador: (1) APAGAR el compresor, (2) mantener el ventilador del evaporador funcionando en modo 'fan only' \u2014 esto hace circular el aire templado del cuarto sobre la bobina congelada, descongel\xE1ndola m\xE1s r\xE1pido que apagado completamente. NUNCA usar soplete ni calor directo en la bobina.&quot; }, { id:&quot;a2l_study_249&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'temperature split' y cu\xE1l es el rango normal para A/C residencial?&quot;, opciones:[&quot;La diferencia entre interior y exterior&quot;,&quot;La diferencia de temperatura entre el aire que ENTRA y el aire que SALE del evaporador \u2014 rango normal: 16-22\xB0F dependiendo de la humedad relativa y la eficiencia del sistema&quot;,&quot;Solo se mide en sistemas comerciales&quot;,&quot;No tiene valor de referencia&quot;], respuesta_correcta:1, explicacion:&quot;Temperature split = temperatura de retorno (entrada al evaporador) - temperatura de suministro (salida). Normal: 16-22\xB0F en sistemas residenciales correctamente cargados y con airflow adecuado. Menor a 16\xB0F puede indicar airflow alto, baja carga, o problema de refrigerante. Mayor a 22\xB0F puede indicar airflow bajo.&quot; }, { id:&quot;a2l_study_250&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 la DEHUMIDIFICATION (extracci\xF3n de humedad) del evaporador es afectada por el airflow?&quot;, opciones:[&quot;El airflow no afecta la deshumidificaci\xF3n&quot;,&quot;Mayor airflow = menos tiempo de contacto entre el aire h\xFAmedo y la bobina fr\xEDa = menos condensaci\xF3n de humedad. Menor airflow (325-350 CFM/ton) = m\xE1s tiempo de contacto = m\xE1s deshumidificaci\xF3n&quot;,&quot;La deshumidificaci\xF3n no depende del airflow&quot;,&quot;Solo en climas tropicales&quot;], respuesta_correcta:1, explicacion:&quot;Para mayor deshumidificaci\xF3n: reducir el airflow (325-350 CFM/ton) para aumentar el tiempo de contacto entre el aire y la bobina fr\xEDa, permitiendo m\xE1s condensaci\xF3n de humedad. Para condiciones de alta carga sensible (calor seco): aumentar el airflow (425-450 CFM/ton) para mayor enfriamiento y menos deshumidificaci\xF3n.&quot; }, { id:&quot;a2l_study_251&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1les son los 4 componentes principales del ciclo b\xE1sico de refrigeraci\xF3n por compresi\xF3n de vapor?&quot;, opciones:[&quot;Compresor, bomba, condensador, evaporador&quot;,&quot;Compresor, condensador, dispositivo de expansi\xF3n (metering device), evaporador&quot;,&quot;Compresor, filtro, condensador, v\xE1lvula&quot;,&quot;Compresor, capacitor, condensador, TXV&quot;], respuesta_correcta:1, explicacion:&quot;Los 4 componentes b\xE1sicos del ciclo de vapor comprimido son: (1) COMPRESOR \u2014 comprime el vapor, (2) CONDENSADOR \u2014 libera calor al exterior, (3) DISPOSITIVO DE EXPANSI\xD3N \u2014 reduce presi\xF3n/temperatura, (4) EVAPORADOR \u2014 absorbe calor del espacio.&quot; }, { id:&quot;a2l_study_252&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la diferencia entre un sistema split y un sistema packaged?&quot;, opciones:[&quot;Son exactamente lo mismo&quot;,&quot;Split: unidades separadas interior (evaporador) y exterior (condensador+compresor). Packaged: todos los componentes en una sola unidad (generalmente en el techo o junto al edificio)&quot;,&quot;El split es siempre m\xE1s eficiente&quot;,&quot;El packaged solo se usa en industrial&quot;], respuesta_correcta:1, explicacion:&quot;Split: dos unidades separadas conectadas por l\xEDneas de refrigerante \u2014 unidad interior (evaporador + ventilador interior) y unidad exterior (condensador + compresor + ventilador exterior). Packaged: todos los componentes HVAC en un solo gabinete, generalmente rooftop (techo) en sistemas comerciales.&quot; }, { id:&quot;a2l_study_253&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la diferencia funcional entre una bomba de calor y un sistema de solo enfriamiento?&quot;, opciones:[&quot;No hay diferencia&quot;,&quot;Una bomba de calor puede invertir el ciclo de refrigeraci\xF3n con una v\xE1lvula de 4 v\xEDas \u2014 el condensador y el evaporador intercambian funciones para proveer tanto enfriamiento como calefacci\xF3n&quot;,&quot;La bomba de calor usa diferente refrigerante&quot;,&quot;La bomba de calor no puede enfriar&quot;], respuesta_correcta:1, explicacion:&quot;Una bomba de calor tiene una v\xE1lvula de 4 v\xEDas que invierte la direcci\xF3n del flujo de refrigerante. En modo enfriamiento: el interior act\xFAa como evaporador (absorbe calor). En modo calefacci\xF3n: el exterior act\xFAa como evaporador (extrae calor del exterior) y el interior como condensador (libera calor al interior).&quot; }, { id:&quot;a2l_study_254&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es un sistema VRF (Variable Refrigerant Flow)?&quot;, opciones:[&quot;Un sistema de caudal variable de aire&quot;,&quot;Un sistema donde el compresor de velocidad variable y las v\xE1lvulas electr\xF3nicas controlan la cantidad de refrigerante que va a cada unidad interior, permitiendo control individual de m\xFAltiples zonas&quot;,&quot;Solo para sistemas industriales&quot;,&quot;Un sistema de alta presi\xF3n especial&quot;], respuesta_correcta:1, explicacion:&quot;VRF = Variable Refrigerant Flow. El compresor de velocidad variable modula su capacidad seg\xFAn la demanda. Las EEV en cada unidad interior controlan el flujo individualmente. Permite que m\xFAltiples unidades interiores operen independientemente con diferentes temperaturas en un edificio.&quot; }, { id:&quot;a2l_study_255&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1les son las ventajas del VRF sobre sistemas tradicionales?&quot;, opciones:[&quot;El VRF es m\xE1s simple&quot;,&quot;Mayor eficiencia energ\xE9tica (inverter/variable speed), control individual por zona, sin ductos en la mayor\xEDa de instalaciones, y capacidad de recuperaci\xF3n de calor (algunos modelos pueden enfriar y calentar simult\xE1neamente zonas diferentes)&quot;,&quot;El VRF solo enfr\xEDa, no calienta&quot;,&quot;El VRF es m\xE1s barato que cualquier alternativa&quot;], respuesta_correcta:1, explicacion:&quot;Ventajas del VRF: (1) eficiencia superior con compresor inverter de velocidad variable, (2) control individual de m\xFAltiples zonas simult\xE1neamente, (3) sin ductos en instalaciones de expansi\xF3n directa, (4) algunos modelos calefaccionan algunas zonas mientras enfr\xEDan otras simult\xE1neamente (recuperaci\xF3n de calor).&quot; }, { id:&quot;a2l_study_256&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la diferencia entre un sistema de expansi\xF3n directa (DX) y un sistema de agua helada (chilled water)?&quot;, opciones:[&quot;No hay diferencia&quot;,&quot;DX: el refrigerante circula directamente hasta los espacios a acondicionar. Agua helada: el refrigerante solo circula en el chiller central, enfr\xEDa agua que luego circula a las unidades terminales&quot;,&quot;El DX siempre es m\xE1s eficiente&quot;,&quot;El agua helada solo se usa en residencial&quot;], respuesta_correcta:1, explicacion:&quot;DX (Direct Expansion): el refrigerante circula directamente a los serpentines de enfriamiento en los espacios. Agua helada: el refrigerante se usa solo en el chiller central para enfriar agua; el agua helada circula a las unidades terminales (fan coil units) en el edificio. Los chillers son sistemas de baja presi\xF3n con grandes capacidades.&quot; }, { id:&quot;a2l_study_257&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1ndo se usa el proceso de 'pump down' en un sistema de refrigeraci\xF3n?&quot;, opciones:[&quot;Para a\xF1adir refrigerante&quot;,&quot;Para transferir el refrigerante del sistema al receptor para almacenamiento, permitiendo trabajo en ciertas partes del sistema sin recuperar todo el refrigerante&quot;,&quot;Para limpiar el sistema&quot;,&quot;Solo en sistemas grandes&quot;], respuesta_correcta:1, explicacion:&quot;Pump down = proceso de bombear el refrigerante del evaporador y l\xEDneas de baja hacia el receptor o condensador para almacenamiento temporal. Permite trabajar en el lado de baja del sistema (cambiar TXV, filtro, etc.) sin necesitar recuperar todo el refrigerante del sistema.&quot; }, { id:&quot;a2l_study_258&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es el 'balance point' en una bomba de calor y por qu\xE9 importa?&quot;, opciones:[&quot;El punto donde las presiones alta y baja se igualan&quot;,&quot;La temperatura exterior a la que la bomba de calor ya no puede satisfacer la demanda de calefacci\xF3n sin asistencia el\xE9ctrica adicional&quot;,&quot;El punto de m\xE1xima eficiencia&quot;,&quot;Solo para sistemas comerciales&quot;], respuesta_correcta:1, explicacion:&quot;Balance point = temperatura exterior por debajo de la cual la bomba de calor no puede proveer suficiente calor para mantener la temperatura interior deseada sin calefacci\xF3n auxiliar (resistencias el\xE9ctricas). Generalmente 30-40\xB0F para la mayor\xEDa de climas templados. Abajo del balance point, la calefacci\xF3n auxiliar activa.&quot; }, { id:&quot;a2l_study_259&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 el ciclo de refrigeraci\xF3n b\xE1sico NO cambia cuando se usa un refrigerante A2L como R-32?&quot;, opciones:[&quot;S\xED cambia completamente&quot;,&quot;El ciclo termodin\xE1mico es el mismo: compresi\xF3n, condensaci\xF3n, expansi\xF3n, evaporaci\xF3n. Lo que cambia son las presiones/temperaturas espec\xEDficas del refrigerante y los requisitos de seguridad adicionales por la inflamabilidad&quot;,&quot;El A2L requiere un ciclo diferente&quot;,&quot;Solo los componentes cambian&quot;], respuesta_correcta:1, explicacion:&quot;El ciclo de compresi\xF3n de vapor b\xE1sico es el mismo independientemente del refrigerante: comprimir vapor, condensar a l\xEDquido liberando calor, expandir reduciendo temperatura, evaporar absorbiendo calor. Lo que cambia son las presiones/temperaturas de operaci\xF3n del refrigerante y los requisitos de seguridad adicionales.&quot; }, { id:&quot;a2l_study_260&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 verificaci\xF3n debe hacer el t\xE9cnico en el airflow ANTES de diagnosticar un problema de refrigerante?&quot;, opciones:[&quot;El airflow no necesita verificarse&quot;,&quot;Verificar: filter limpio, ventilador funcional a velocidad correcta, bobina limpia, y que los CFM/ton coincidan con los requisitos del fabricante. Un airflow incorrecto simula problemas de carga de refrigerante&quot;,&quot;Solo verificar el filtro&quot;,&quot;Solo medir la temperatura de suministro&quot;], respuesta_correcta:1, explicacion:&quot;SIEMPRE verificar el airflow antes de diagnosticar refrigerante. El airflow afecta directamente el superheat, subcooling, y temperature split. Un filtro tapado o ventilador deficiente puede crear s\xEDntomas id\xE9nticos a una carga de refrigerante incorrecta, llevando a diagn\xF3sticos y 'soluciones' equivocadas.&quot; }, { id:&quot;a2l_study_261&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 establece ASHRAE Standard 15 sobre cuartos de m\xE1quinas con sistemas A2L?&quot;, opciones:[&quot;No aplica a cuartos de m\xE1quinas&quot;,&quot;Regula el dise\xF1o, ventilaci\xF3n, sensores de seguridad y l\xEDmites de concentraci\xF3n de refrigerante permitidos en cuartos de m\xE1quinas con equipos HVAC incluyendo los que usan A2L&quot;,&quot;Solo para instalaciones residenciales&quot;,&quot;Solo para sistemas con m\xE1s de 1,000 lb de refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;ASHRAE 15 establece requisitos para cuartos de m\xE1quinas: ventilaci\xF3n m\xEDnima requerida, sensores de refrigerante (activos para A2L), l\xEDmites de concentraci\xF3n, alarmas, y procedimientos de emergencia. Para sistemas con A2L, los requisitos son m\xE1s estrictos que para A1.&quot; }, { id:&quot;a2l_study_262&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 restricci\xF3n adicional aplica a sistemas A2L instalados en espacios debajo del nivel del suelo (basements)?&quot;, opciones:[&quot;No hay restricciones adicionales&quot;,&quot;Los refrigerantes m\xE1s pesados que el aire (incluyendo A2L) tienden a acumularse en espacios bajos como s\xF3tanos \u2014 se requieren consideraciones adicionales de ventilaci\xF3n y sensores para prevenir acumulaci\xF3n de concentraciones inflamables&quot;,&quot;Solo requieren un extinguidor extra&quot;,&quot;No se permite A2L en s\xF3tanos&quot;], respuesta_correcta:1, explicacion:&quot;Los A2L son m\xE1s pesados que el aire y se acumulan en puntos bajos como s\xF3tanos. Para instalaciones en basement u otros espacios bajos, se deben considerar: sensores activos en los puntos de posible acumulaci\xF3n (nivel del piso), ventilaci\xF3n mec\xE1nica hacia arriba o al exterior, y posiblemente restricciones de carga m\xE1xima.&quot; }, { id:&quot;a2l_study_263&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 requiere ASHRAE 15.2 antes de instalar un sistema A2L en una ubicaci\xF3n residencial espec\xEDfica?&quot;, opciones:[&quot;Solo verificar que el equipo sea A2L certificado&quot;,&quot;Evaluar la ubicaci\xF3n para: volumen de espacio (dispersal volume), clasificaci\xF3n de ocupaci\xF3n, fuentes potenciales de ignici\xF3n, y que cumpla los requisitos de carga m\xE1xima (m1 o m2) para esa ubicaci\xF3n espec\xEDfica&quot;,&quot;Solo obtener el permiso de construcci\xF3n&quot;,&quot;Solo verificar que el espacio tiene toma de corriente&quot;], respuesta_correcta:1, explicacion:&quot;ASHRAE 15.2 requiere evaluar la ubicaci\xF3n espec\xEDfica para: (1) volumen del espacio (dispersal volume suficiente para la carga del sistema), (2) clasificaci\xF3n de ocupaci\xF3n residencial, (3) fuentes potenciales de ignici\xF3n cercanas, y (4) verificar que la carga del sistema no exceda los l\xEDmites m1 o m2 para esa ubicaci\xF3n.&quot; }, { id:&quot;a2l_study_264&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la consecuencia de instalar un sistema A2L sin verificar el dispersal volume requerido?&quot;, opciones:[&quot;No hay consecuencias legales&quot;,&quot;Una fuga total del sistema podr\xEDa crear concentraciones de refrigerante por encima del LFL en el espacio, representando riesgo de ignici\xF3n. Tambi\xE9n viola los c\xF3digos de instalaci\xF3n&quot;,&quot;Solo reduce la eficiencia&quot;,&quot;Solo afecta la garant\xEDa&quot;], respuesta_correcta:1, explicacion:&quot;Si el dispersal volume es insuficiente: una fuga total del sistema podr\xEDa crear una concentraci\xF3n de refrigerante por ENCIMA del LFL en el espacio, representando riesgo de ignici\xF3n. La instalaci\xF3n tambi\xE9n viola c\xF3digos ASHRAE 15.2, exponiendo al instalador a responsabilidad legal.&quot; }, { id:&quot;a2l_study_265&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 es una 'control area' en el contexto de almacenamiento de refrigerantes inflamables?&quot;, opciones:[&quot;El \xE1rea de trabajo del t\xE9cnico&quot;,&quot;Una secci\xF3n de un edificio con l\xEDmites definidos (paredes, pisos, techos resistentes al fuego) que se usa para calcular la cantidad m\xE1xima de materiales peligrosos permitidos en esa secci\xF3n&quot;,&quot;El \xE1rea alrededor del equipo para mantenimiento&quot;,&quot;Solo para edificios comerciales&quot;], respuesta_correcta:1, explicacion:&quot;Control area = secci\xF3n de un edificio con l\xEDmites definidos (paredes, pisos, techos con cierta resistencia al fuego) que determina cu\xE1nta cantidad de material peligroso (incluyendo refrigerante inflamable) puede almacenarse en esa secci\xF3n. Las regulaciones de almacenamiento limitan la cantidad por control area.&quot; }, { id:&quot;a2l_study_266&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 est\xE1ndar UL espec\xEDficamente cubre los equipos de refrigeraci\xF3n comercial split con A2L (sistemas con unidades condensadoras remotas)?&quot;, opciones:[&quot;UL 60335-2-40&quot;,&quot;UL 60335-2-89 \u2014 cubre dise\xF1o y especificaciones para refrigeraci\xF3n comercial split-type&quot;,&quot;UL 508&quot;,&quot;UL 1004&quot;], respuesta_correcta:1, explicacion:&quot;UL 60335-2-89 ('2-89') cubre el dise\xF1o y especificaciones de prueba para sistemas de refrigeraci\xF3n comercial SPLIT-TYPE \u2014 equipos con unidades condensadoras remotas (walk-in coolers, refrigeraci\xF3n de supermercados) que pueden usar A2L.&quot; }, { id:&quot;a2l_study_267&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 debe verificar el t\xE9cnico sobre el permiso antes de instalar un sistema A2L en una instalaci\xF3n comercial?&quot;, opciones:[&quot;No se requieren permisos para A2L&quot;,&quot;Verificar que se obtuvo el permiso de construcci\xF3n/mec\xE1nico apropiado de la jurisdicci\xF3n local, y que la instalaci\xF3n cumple tanto con los c\xF3digos del permiso como con ASHRAE 15 y los requerimientos del fabricante&quot;,&quot;Solo verificar el permiso de electricidad&quot;,&quot;Solo el permiso el\xE9ctrico es necesario para A2L&quot;], respuesta_correcta:1, explicacion:&quot;Para instalaciones comerciales A2L: (1) verificar que se obtuvo el permiso mec\xE1nico/de construcci\xF3n apropiado, (2) la instalaci\xF3n debe cumplir los c\xF3digos del permiso, ASHRAE 15 (comercial), los requisitos de UL del equipo, y los requerimientos del fabricante. El inspector puede requerir verificaciones espec\xEDficas para A2L.&quot; }, { id:&quot;a2l_study_268&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1ndo se considera que el patr\xF3n de recargas de un sistema A2L es prueba de fuga que requiere acci\xF3n?&quot;, opciones:[&quot;Cuando se recarga m\xE1s de 5 lb a la vez&quot;,&quot;Cuando el sistema ha necesitado ser recargado al menos una vez dentro de un per\xEDodo de 3 a\xF1os \u2014 se debe identificar y reparar la fuga&quot;,&quot;Solo si el propietario se queja&quot;,&quot;Solo para sistemas con m\xE1s de 50 lb&quot;], respuesta_correcta:1, explicacion:&quot;El patr\xF3n de recarga al menos una vez en 3 a\xF1os se considera PRUEBA de fuga. La fuga DEBE identificarse, repararse, y el sistema verificarse antes de recargar. Documentar la reparaci\xF3n en la etiqueta del sistema.&quot; }, { id:&quot;a2l_study_269&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 documenta el t\xE9cnico en la etiqueta del sistema cada vez que hace servicio en un sistema A2L?&quot;, opciones:[&quot;Solo la fecha de servicio&quot;,&quot;Fecha del servicio Y cantidad de refrigerante a\xF1adido (si se a\xF1adi\xF3 alguno) \u2014 esto sirve como registro de servicio y evidencia de patr\xF3n de fuga si es necesario&quot;,&quot;Solo el nombre del t\xE9cnico&quot;,&quot;No se requiere documentaci\xF3n de service en la etiqueta&quot;], respuesta_correcta:1, explicacion:&quot;La etiqueta permanente en sistemas A2L sirve tambi\xE9n como registro de servicio. En cada servicio donde se a\xF1ada refrigerante: documentar la fecha y la cantidad a\xF1adida. Este registro permite identificar patrones de fuga con el tiempo.&quot; }, { id:&quot;a2l_study_270&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 establece OSHA sobre la clasificaci\xF3n de ambientes inflamables y las herramientas que se usan?&quot;, opciones:[&quot;OSHA no regula el tipo de herramientas&quot;,&quot;Los ambientes con gases inflamables se clasifican como Clase I Divisi\xF3n 2 seg\xFAn NFPA 70 / NEC \u2014 se requieren herramientas y equipos sin chispa, sin arco en estas \xE1reas&quot;,&quot;Solo se requieren guantes especiales&quot;,&quot;Solo aplica a industrias petroqu\xEDmicas&quot;], respuesta_correcta:1, explicacion:&quot;OSHA junto con NFPA 70 (NEC) clasifica los ambientes con gases inflamables como Clase I Divisi\xF3n 2. En estas \xE1reas se requieren herramientas y equipos espec\xEDficamente certificados para ambientes inflamables (sin chispa, sin arco el\xE9ctrico). Aplica cuando se trabaja con A2L, A2, y A3 refrigerantes.&quot; }, { id:&quot;a2l_study_271&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es el principal desaf\xEDo de instalar un sistema VRF con R-32 en un edificio de m\xFAltiples pisos?&quot;, opciones:[&quot;El R-32 no puede usarse en VRF&quot;,&quot;Calcular y verificar los l\xEDmites de carga por piso/zona (dispersal volume y clasificaci\xF3n de ocupaci\xF3n), y asegurar que la distribuci\xF3n de carga total del sistema no exceda los l\xEDmites de seguridad para ninguna zona individual&quot;,&quot;Solo el peso del equipo&quot;,&quot;Solo la instalaci\xF3n el\xE9ctrica&quot;], respuesta_correcta:1, explicacion:&quot;El principal desaf\xEDo en VRF con A2L en m\xFAltiples pisos es calcular y gestionar los l\xEDmites de carga por zona: cada espacio atendido debe tener suficiente dispersal volume para la porci\xF3n de carga que recibe, considerando la clasificaci\xF3n de ocupaci\xF3n de cada piso/zona individual.&quot; }, { id:&quot;a2l_study_272&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 precauci\xF3n especial aplica cuando se hace servicio en un sistema VRF A2L en un edificio ocupado?&quot;, opciones:[&quot;No hay precauciones adicionales para edificios ocupados&quot;,&quot;Establecer un per\xEDmetro de seguridad, verificar que el \xE1rea de trabajo est\xE1 bien ventilada, tener extinguidor disponible, y coordinar con los ocupantes para evacuar las \xE1reas adyacentes si hay riesgo de fuga durante el servicio&quot;,&quot;Solo avisar al propietario&quot;,&quot;Solo necesitas guantes adicionales&quot;], respuesta_correcta:1, explicacion:&quot;Trabajar en sistemas A2L en edificios ocupados requiere: (1) establecer per\xEDmetro de seguridad, (2) verificar ventilaci\xF3n del \xE1rea de trabajo, (3) coordinar evacuaci\xF3n de \xE1reas adyacentes si hay riesgo de fuga durante el servicio, (4) tener extinguidor y detector de refrigerante disponibles.&quot; }, { id:&quot;a2l_study_273&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 diferencia el servicio de sistemas VRF de sistemas split convencionales en t\xE9rminos de recuperaci\xF3n A2L?&quot;, opciones:[&quot;No hay diferencia&quot;,&quot;Los sistemas VRF tienen m\xE1s refrigerante total distribuido en m\xFAltiples unidades y largas l\xEDneas \u2014 la recuperaci\xF3n es m\xE1s compleja y puede requerir equipos de mayor capacidad. Adem\xE1s, recuperar desde m\xFAltiples unidades independientes requiere planificaci\xF3n cuidadosa&quot;,&quot;Los sistemas VRF no requieren recuperaci\xF3n&quot;,&quot;Solo la cantidad de refrigerante es diferente&quot;], respuesta_correcta:1, explicacion:&quot;Los sistemas VRF tienen caracter\xEDsticas que complican la recuperaci\xF3n: (1) gran cantidad total de refrigerante (pueden tener cientos de libras), (2) refrigerante distribuido en m\xFAltiples unidades interiores y largas l\xEDneas, (3) m\xFAltiples circuitos separados que deben recuperarse. Planificar la recuperaci\xF3n con cuidado, verificar que se recupera de todos los circuitos.&quot; }, { id:&quot;a2l_study_274&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 significa 'heat recovery VRF' y qu\xE9 lo diferencia del VRF est\xE1ndar?&quot;, opciones:[&quot;El VRF que solo recupera calor del exterior&quot;,&quot;Un sistema VRF que puede SIMULT\xC1NEAMENTE enfriar algunas zonas y calentar otras \u2014 el calor 'recuperado' de las zonas que se enfr\xEDan se transfiere a las zonas que necesitan calefacci\xF3n&quot;,&quot;Un VRF con recuperador de calor externo&quot;,&quot;Solo para climas fr\xEDos&quot;], respuesta_correcta:1, explicacion:&quot;Heat Recovery VRF: un sistema de 3 tubos (tuber\xEDa de alta, baja, y una tercera para transferencia de calor) que permite enfriar y calentar simult\xE1neamente zonas diferentes del mismo edificio. El calor extra\xEDdo de las zonas en modo enfriamiento se transfiere a las zonas que necesitan calefacci\xF3n \u2014 alta eficiencia energ\xE9tica.&quot; }, { id:&quot;a2l_study_275&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1les son los desaf\xEDos espec\xEDficos de trabajar con R-32 en sistemas multi-split vs R-410A?&quot;, opciones:[&quot;No hay diferencias&quot;,&quot;Los sistemas R-32 requieren: (1) herramientas y manifolds rated para A2L, (2) carga precisa en l\xEDquido si es R-454B (R-32 puro puede ser gas o l\xEDquido), (3) nitrogen sweep despu\xE9s de recuperaci\xF3n, (4) verificar label matching de todos los componentes, (5) etiqueta UL post-instalaci\xF3n&quot;,&quot;El R-32 es m\xE1s f\xE1cil de manejar&quot;,&quot;Solo la diferencia de presi\xF3n importa&quot;], respuesta_correcta:1, explicacion:&quot;Trabajar con R-32 vs R-410A requiere consideraciones adicionales: (1) herramientas y manifolds certificados A2L, (2) label matching de componentes, (3) nitrogen sweep despu\xE9s de recuperaci\xF3n antes de soldar, (4) etiqueta UL permanente post-instalaci\xF3n, (5) evaluaci\xF3n del sitio para requisitos A2L, y (6) lockout/tagout con mult\xEDmetro para verificar de-energizaci\xF3n.&quot; }, { id:&quot;a2l_study_276&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 el R-32 tiene presiones ligeramente MAYORES que el R-410A a la misma temperatura?&quot;, opciones:[&quot;Por error de fabricaci\xF3n \u2014 deber\xEDan ser iguales&quot;,&quot;El R-32 tiene una curva de presi\xF3n de saturaci\xF3n diferente a la del R-410A \u2014 aunque similar, el R-32 puro genera presiones un poco m\xE1s altas porque es un componente individual sin el 'efecto de mezcla' del R-125 en el R-410A&quot;,&quot;Por diferencia de tama\xF1o molecular&quot;,&quot;No hay diferencia real de presi\xF3n&quot;], respuesta_correcta:1, explicacion:&quot;El R-32 es un refrigerante puro con su propia curva P-T \xFAnica. El R-410A es mezcla de R-32 y R-125. La adici\xF3n de R-125 modifica las propiedades de la mezcla. El R-32 puro opera a presiones ligeramente m\xE1s altas que el R-410A a la misma temperatura de saturaci\xF3n.&quot; }, { id:&quot;a2l_study_277&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 el R-454B y el R-410A tienen presiones de operaci\xF3n muy similares?&quot;, opciones:[&quot;Por coincidencia&quot;,&quot;El R-454B fue dise\xF1ado espec\xEDficamente para tener presiones de operaci\xF3n similares al R-410A, facilitando la transici\xF3n \u2014 los fabricantes pueden dise\xF1ar sistemas R-454B con dimensiones de componentes similares a los sistemas R-410A existentes&quot;,&quot;Todos los HFCs tienen las mismas presiones&quot;,&quot;No tienen presiones similares&quot;], respuesta_correcta:1, explicacion:&quot;R-454B fue dise\xF1ado como SUCESOR COMPATIBLE del R-410A. Mantener presiones similares es una decisi\xF3n de dise\xF1o intencional para: (1) facilitar la transici\xF3n para fabricantes que ya dise\xF1an para R-410A, (2) permitir sistemas con componentes de dimensiones similares, (3) minimizar cambios en los procesos de manufactura.&quot; }, { id:&quot;a2l_study_278&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 significa que el R-32 es un 'refrigerante de composici\xF3n constante'?&quot;, opciones:[&quot;Que nunca cambia de estado&quot;,&quot;Que es un refrigerante puro de un solo componente \u2014 su composici\xF3n no cambia bajo ninguna circunstancia, incluyendo fugas. No fracciona&quot;,&quot;Que solo funciona a temperatura constante&quot;,&quot;Solo aplica a almacenamiento&quot;], respuesta_correcta:1, explicacion:&quot;'Composici\xF3n constante' = refrigerante puro de un solo componente que NO FRACCIONA bajo ninguna condici\xF3n. Si un sistema R-32 pierde refrigerante por fuga, el refrigerante restante en el sistema tiene EXACTAMENTE la misma composici\xF3n que antes. Esto facilita el topped off y el diagn\xF3stico.&quot; }, { id:&quot;a2l_study_279&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 implica el 'fractionation' del R-454B en una fuga lenta?&quot;, opciones:[&quot;No hay implicaciones pr\xE1cticas&quot;,&quot;En una fuga lenta, el R-32 (m\xE1s vol\xE1til, mayor presi\xF3n de vapor) puede escapar a mayor velocidad que el R-1234yf, cambiando gradualmente la composici\xF3n del refrigerante restante y las propiedades del sistema&quot;,&quot;Solo afecta al GWP&quot;,&quot;Solo ocurre en fugas grandes&quot;], respuesta_correcta:1, explicacion:&quot;En fugas lentas de R-454B, el fraccionamiento puede causar que el R-32 (componente m\xE1s vol\xE1til) escape preferencialmente, alterando gradualmente la composici\xF3n de la mezcla restante. Esto cambia la relaci\xF3n P-T, el GWP efectivo, y puede afectar el desempe\xF1o del sistema. Por esto, las fugas de R-454B deben repararse y el sistema recargarse completamente.&quot; }, { id:&quot;a2l_study_280&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es el significado de 'HFC/HFO blend' en el nombre de R-454B?&quot;, opciones:[&quot;Solo una descripci\xF3n t\xE9cnica sin significado pr\xE1ctico&quot;,&quot;Indica que la mezcla contiene tanto un componente HFC (R-32) como un componente HFO (R-1234yf) \u2014 esta combinaci\xF3n permite lograr bajo GWP (del HFO) con propiedades operativas manejables (del HFC)&quot;,&quot;Solo aplica a sistemas automotrices&quot;,&quot;Significa que tiene dos aceites diferentes&quot;], respuesta_correcta:1, explicacion:&quot;HFC/HFO blend indica que R-454B combina: R-32 (HFC) + R-1234yf (HFO). El HFC (R-32) aporta presiones y caracter\xEDsticas operativas conocidas y manejables. El HFO (R-1234yf) aporta el GWP muy bajo. La mezcla logra: presiones similares a R-410A, GWP=466, y clasificaci\xF3n A2L.&quot; }, { id:&quot;a2l_study_281&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 algunos t\xE9cnicos describen al R-32 como 'medio componente' del R-410A?&quot;, opciones:[&quot;Por error \u2014 R-32 no tiene relaci\xF3n con R-410A&quot;,&quot;R-410A es una mezcla de R-32 (50%) + R-125 (50%). El R-32 es literalmente UNO DE LOS DOS COMPONENTES del R-410A \u2014 la diferencia es que el R-410A tiene R-125 adicional que modifica sus propiedades&quot;,&quot;El R-32 solo se usa como componente&quot;,&quot;Solo es una descripci\xF3n informal sin base t\xE9cnica&quot;], respuesta_correcta:1, explicacion:&quot;R-410A = R-32 (50%) + R-125 (50%). El R-32 es literalmente la mitad del R-410A. Al eliminar el R-125 (que tiene GWP=3,500), el R-32 solo tiene GWP=675 vs R-410A GWP=2,088. Esta relaci\xF3n explica por qu\xE9 el R-32 tiene presiones similares al R-410A pero es A2L porque sin el R-125 la mezcla es levemente inflamable.&quot; }, { id:&quot;a2l_study_282&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 el R-125 se a\xF1adi\xF3 al R-32 para crear el R-410A originalmente?&quot;, opciones:[&quot;Para mejorar el GWP&quot;,&quot;Para hacer la mezcla no inflamable (A1) \u2014 el R-32 solo es A2L, pero la adici\xF3n de R-125 en proporci\xF3n adecuada crea una mezcla A1. El precio pagado fue un GWP m\xE1s alto&quot;,&quot;Para reducir el costo&quot;,&quot;Para aumentar la capacidad de enfriamiento&quot;], respuesta_correcta:1, explicacion:&quot;El R-125 (no inflamable, A1) se a\xF1adi\xF3 al R-32 (levemente inflamable, A2L) para crear R-410A A1 (no inflamable). Esto fue importante cuando los A2L no estaban bien aceptados por la industria. El costo fue aumentar el GWP (R-125 tiene GWP=3,500, mucho mayor que R-32=675).&quot; }, { id:&quot;a2l_study_283&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es el principal uso del R-1234yf en la actualidad?&quot;, opciones:[&quot;Reemplazar R-410A en sistemas residenciales&quot;,&quot;A/C automotriz \u2014 reemplaza el R-134a (GWP=1,430) con GWP<1, cumpliendo regulaciones europeas y norteamericanas de bajas emisiones de GHG para veh\xEDculos nuevos&quot;,&quot;Solo como componente de mezclas&quot;,&quot;Solo en aplicaciones industriales&quot;], respuesta_correcta:1, explicacion:&quot;R-1234yf es el refrigerante DOMINANTE en A/C automotriz nuevo, reemplazando al R-134a. Con GWP<1 cumple las regulaciones de la UE (Mac Directive 2006/40/EC) y norteamericanas que requieren GWP<150 para sistemas de A/C de veh\xEDculos nuevos.&quot; }, { id:&quot;a2l_study_284&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 la R-1234yf es muy dif\xEDcil de encender a pesar de ser A2L?&quot;, opciones:[&quot;No es dif\xEDcil de encender \u2014 es el m\xE1s peligroso de los A2L&quot;,&quot;Su MIE extremadamente alto (5,000-10,000 mJ) lo hace el m\xE1s dif\xEDcil de encender entre los A2L. Para comparar, el propano tiene MIE=0.25 mJ y una buj\xEDa produce 20-30 mJ \u2014 muy por debajo del umbral del R-1234yf&quot;,&quot;Su LFL alto lo hace seguro&quot;,&quot;Solo por el color del cilindro&quot;], respuesta_correcta:1, explicacion:&quot;R-1234yf tiene MIE=5,000-10,000 mJ \u2014 extraordinariamente dif\xEDcil de encender. Una buj\xEDa de alto voltaje produce solo 20-30 mJ. Esto significa que pr\xE1cticamente ning\xFAn dispositivo el\xE9ctrico dom\xE9stico normal puede encender R-1234yf, haci\xE9ndolo muy seguro en la pr\xE1ctica a pesar de su clasificaci\xF3n t\xE9cnica A2L.&quot; }, { id:&quot;a2l_study_285&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es el impacto del R-466A en la transici\xF3n a bajos GWP comparado con R-454B?&quot;, opciones:[&quot;R-466A siempre es mejor que R-454B&quot;,&quot;R-466A ofrece GWP=733 con clasificaci\xF3n A1 (no inflamable) \u2014 ventaja: sin complejidades de seguridad A2L. Desventaja: GWP mayor que R-454B (466). La elecci\xF3n depende de si el instalador prefiere eliminar complejidades A2L vs lograr el GWP m\xE1s bajo posible&quot;,&quot;R-454B es siempre mejor&quot;,&quot;No hay diferencia pr\xE1ctica entre ellos&quot;], respuesta_correcta:1, explicacion:&quot;R-466A vs R-454B es un balance entre seguridad y GWP: R-466A (GWP=733, A1 \u2014 no inflamable) elimina las complejidades de seguridad A2L pero tiene GWP m\xE1s alto. R-454B (GWP=466, A2L) logra mayor reducci\xF3n de GWP pero requiere todas las precauciones de seguridad A2L. La elecci\xF3n depende de los requisitos del cliente y del instalador.&quot; }, { id:&quot;a2l_study_286&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFPor qu\xE9 la industria HVAC est\xE1 en transici\xF3n hacia refrigerantes A2L si los A1 son m\xE1s seguros?&quot;, opciones:[&quot;Por capricho del mercado&quot;,&quot;Los A1 disponibles (R-410A, R-404A) tienen GWP muy alto. Los nuevos A2L ofrecen reducci\xF3n significativa de GWP mientras mantienen eficiencia operativa similar \u2014 el beneficio ambiental justifica las precauciones de seguridad adicionales&quot;,&quot;Los A2L son m\xE1s baratos&quot;,&quot;Solo por regulaci\xF3n sin raz\xF3n t\xE9cnica&quot;], respuesta_correcta:1, explicacion:&quot;La transici\xF3n a A2L es impulsada por regulaciones ambientales (Montreal Protocol Kigali Amendment, EPA SNAP) que requieren reducir GWP de refrigerantes. Los nuevos A2L (R-32, R-454B) ofrecen reducci\xF3n de GWP del 68-78% vs R-410A mientras mantienen eficiencia similar. El impacto ambiental reducido justifica las precauciones adicionales de seguridad.&quot; }, { id:&quot;a2l_study_287&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1ndo se espera que la mayor\xEDa de fabricantes de equipos residenciales en USA hayan completado la transici\xF3n a A2L?&quot;, opciones:[&quot;Ya completaron en 2020&quot;,&quot;2025-2026 es el per\xEDodo principal de transici\xF3n \u2014 los equipos de mayor eficiencia (SEER2 m\xEDnimo) aprobados por la EPA ya son principalmente A2L&quot;,&quot;No hay fecha espec\xEDfica \u2014 es voluntario&quot;,&quot;2030 o despu\xE9s&quot;], respuesta_correcta:1, explicacion:&quot;La transici\xF3n principal a A2L en residencial USA ocurre en 2025-2026. Los nuevos requisitos de eficiencia (SEER2) combinados con las aprobaciones de EPA SNAP 23 impulsaron a los principales fabricantes a lanzar sus l\xEDneas A2L (principalmente R-454B) para cumplir simult\xE1neamente con eficiencia y GWP reducido.&quot; }, { id:&quot;a2l_study_288&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 implica para los t\xE9cnicos en servicio el per\xEDodo de transici\xF3n A2L cuando hay tanto R-410A como R-454B en el mercado?&quot;, opciones:[&quot;No hay implicaciones \u2014 los sistemas son intercambiables&quot;,&quot;Los t\xE9cnicos deben: (1) verificar SIEMPRE el refrigerante en la placa de datos, (2) tener equipo compatible con ambos refrigerantes, (3) nunca mezclar R-410A y R-454B, (4) conocer los procedimientos A2L adicionales para sistemas R-454B&quot;,&quot;Solo se necesita un manifold diferente&quot;,&quot;Solo necesitan nueva capacitaci\xF3n una vez&quot;], respuesta_correcta:1, explicacion:&quot;Durante la transici\xF3n, los t\xE9cnicos pueden encontrar AMBOS refrigerantes en el campo. Esto requiere: (1) verificar SIEMPRE la placa de datos antes de comenzar, (2) tener herramientas compatibles con A2L, (3) nunca mezclar refrigerantes, (4) aplicar procedimientos A2L adicionales cuando corresponda, y (5) mantener cilindros de recuperaci\xF3n separados.&quot; }, { id:&quot;a2l_study_289&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la diferencia en precio t\xEDpica entre el R-454B y el R-410A y por qu\xE9?&quot;, opciones:[&quot;Son exactamente del mismo precio&quot;,&quot;R-454B generalmente cuesta m\xE1s que R-410A \u2014 contiene R-1234yf (HFO) que es m\xE1s costoso de producir que los HFC tradicionales. Los costos deben bajar con mayor escala de producci\xF3n&quot;,&quot;El R-454B siempre es m\xE1s barato&quot;,&quot;El costo no importa para el t\xE9cnico&quot;], respuesta_correcta:1, explicacion:&quot;R-454B t\xEDpicamente cuesta m\xE1s que R-410A porque contiene R-1234yf (HFO), cuya s\xEDntesis es m\xE1s compleja y costosa que los HFC tradicionales. Con la mayor escala de producci\xF3n y la reducci\xF3n del R-410A, se espera que los precios de los A2L se normalicen con el tiempo.&quot; }, { id:&quot;a2l_study_290&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 habilidades adicionales necesita un t\xE9cnico para estar preparado para la era A2L?&quot;, opciones:[&quot;Solo aprender el nombre de los nuevos refrigerantes&quot;,&quot;Capacitaci\xF3n en seguridad A2L (label matching, nitrogen sweep, herramientas spark-free, nitrogen decay test), manejo de tablas P/T de nuevos refrigerantes, familiarizaci\xF3n con sensores activos, y actualizaci\xF3n en c\xF3digos ASHRAE 15/15.2&quot;,&quot;Solo una certificaci\xF3n adicional&quot;,&quot;No se necesitan habilidades nuevas&quot;], respuesta_correcta:1, explicacion:&quot;Para la era A2L los t\xE9cnicos necesitan: (1) capacitaci\xF3n en seguridad espec\xEDfica A2L, (2) conocer las tablas P/T de R-32, R-454B, R-452B, (3) procedimientos de instalaci\xF3n adicionales (label matching, prueba de presi\xF3n 60 min, nitrogen sweep, decay test), (4) conocer y cumplir ASHRAE 15.2, y (5) familiarizarse con sensores activos y requisitos de documentaci\xF3n UL.&quot; }, { id:&quot;a2l_study_291&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un t\xE9cnico de otro estado llega a dar servicio a un equipo R-454B nuevo. Al abrir el manifold dice que las presiones son iguales que el R-410A as\xED que no necesita la tabla P/T de R-454B. \xBFEst\xE1 en lo correcto?&quot;, opciones:[&quot;S\xED \u2014 son casi id\xE9nticas as\xED que es correcto&quot;,&quot;No \u2014 aunque las presiones son similares, existen diferencias importantes especialmente en las columnas Liquid/Vapor del R-454B (mezcla zeotr\xF3pica). Siempre usar la tabla P/T correcta para el refrigerante espec\xEDfico&quot;,&quot;S\xED pero solo para diagn\xF3stico b\xE1sico&quot;,&quot;No importa la tabla \u2014 las presiones hablan solas&quot;], respuesta_correcta:1, explicacion:&quot;INCORRECTO. Aunque R-454B tiene presiones similares a R-410A, existen diferencias: (1) R-454B es zeotr\xF3pico con dos columnas (Liquid/Vapor), (2) los valores espec\xEDficos difieren, (3) usar la tabla incorrecta lleva a c\xE1lculos de superheat y subcooling err\xF3neos y posiblemente a carga incorrecta del sistema.&quot; }, { id:&quot;a2l_study_292&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Al revisar un minisplit nuevo R-32, el t\xE9cnico nota que el sistema enfr\xEDa pero la unidad interior chorrea agua excesivamente. \xBFCu\xE1l es la causa m\xE1s probable?&quot;, opciones:[&quot;El sistema necesita m\xE1s refrigerante&quot;,&quot;El drenaje del condensado est\xE1 obstruido o incorrecto \u2014 el agua que el evaporador extrae de la humedad del aire no puede drenar y desborda&quot;,&quot;El compresor est\xE1 fallando&quot;,&quot;El sistema tiene exceso de refrigerante&quot;], respuesta_correcta:1, explicacion:&quot;El desbordamiento de agua de la unidad interior casi siempre es un PROBLEMA DE DRENAJE: l\xEDnea de drenaje obstruida (algas, suciedad), pendiente incorrecta del drenaje, o bandeja de condensado llena. El sistema puede estar extrayendo la cantidad correcta de humedad pero el agua no puede salir.&quot; }, { id:&quot;a2l_study_293&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un instalador joven conecta R-454B nuevo a un sistema que anteriormente ten\xEDa R-410A sin cambiar el aceite. \xBFQu\xE9 problema puede surgir?&quot;, opciones:[&quot;Ninguno \u2014 los aceites son compatibles&quot;,&quot;El aceite POE en el sistema puede estar contaminado con residuos de operaciones previas. M\xE1s importante: si el sistema anterior usaba aceite mineral (en caso de retrofit desde R-22), eso es incompatible con el R-454B&quot;,&quot;Solo reduce la eficiencia&quot;,&quot;Solo afecta la garant\xEDa&quot;], respuesta_correcta:1, explicacion:&quot;Si el sistema anterior tambi\xE9n ten\xEDa R-410A (y por tanto POE), la contaminaci\xF3n cruzada del aceite POE generalmente es aceptable. PERO si hubo alg\xFAn sistema anterior con aceite mineral y no se limpi\xF3 completamente, el aceite mineral residual ser\xE1 incompatible con el R-454B/POE. Siempre verificar el historial del sistema.&quot; }, { id:&quot;a2l_study_294&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un t\xE9cnico recibe una llamada de emergencia: el cliente reporta que el sistema de A/C hizo un 'pop' fuerte y dej\xF3 de funcionar. Al llegar, el t\xE9cnico huele algo inusual. \xBFCu\xE1l es el protocolo?&quot;, opciones:[&quot;Conectar el manifold inmediatamente para revisar presiones&quot;,&quot;NO entrar hasta verificar con detector de gases que el \xE1rea es segura. Si es un sistema A2L y hay fuga, hay riesgo de ignici\xF3n. Ventilar el \xE1rea, verificar con detector, asegurar que no hay fuentes de ignici\xF3n antes de entrar a dar servicio&quot;,&quot;Solo abrir ventanas y entrar&quot;,&quot;Llamar a los bomberos inmediatamente sin verificar&quot;], respuesta_correcta:1, explicacion:&quot;Protocolo correcto: (1) NO entrar hasta verificar con detector, (2) si hay olor inusual y es sistema A2L, sospechar fuga, (3) ventilar el \xE1rea desde el exterior si es posible, (4) verificar con detector de gases antes de entrar, (5) eliminar fuentes de ignici\xF3n, (6) solo entonces proceder a diagnosticar. El 'pop' puede indicar ruptura de componente con liberaci\xF3n de refrigerante.&quot; }, { id:&quot;a2l_study_295&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un t\xE9cnico tiene que hacer una reparaci\xF3n de soldadura en un sistema R-32 que est\xE1 instalado en un peque\xF1o cuarto de servidores con poca ventilaci\xF3n. \xBFCu\xE1les son las consideraciones de seguridad especiales?&quot;, opciones:[&quot;Ninguna especial \u2014 soldar es soldar&quot;,&quot;ANTES de soldar: (1) recuperar el R-32, (2) nitrogen sweep completo, (3) verificar con detector que no hay vapores, (4) establecer ventilaci\xF3n mec\xE1nica adicional para el trabajo con soplete, (5) tener extinguidor disponible, (6) minimizar el tiempo de trabajo en el espacio confinado&quot;,&quot;Solo abrir la puerta del cuarto&quot;,&quot;Solo apagar el R-32 y soldar normalmente&quot;], respuesta_correcta:1, explicacion:&quot;Cuarto peque\xF1o + R-32 + soldadura = riesgo alto. Protocolo: (1) recuperar R-32 completamente, (2) nitrogen sweep, (3) verificar con detector que no hay vapores residuales, (4) establecer ventilaci\xF3n mec\xE1nica para durante el trabajo con soplete (el soplete consume ox\xEDgeno y puede liberar gases de combusti\xF3n), (5) extinguidor a mano, (6) trabajar r\xE1pido y verificar el \xE1rea frecuentemente.&quot; }, { id:&quot;a2l_study_296&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un propietario pregunta si puede instalar m\xE1s refrigerante R-454B del que especifica el fabricante para mejorar el enfriamiento. \xBFCu\xE1l es la respuesta correcta?&quot;, opciones:[&quot;S\xED \u2014 m\xE1s refrigerante siempre mejora el enfriamiento&quot;,&quot;NO. La carga m\xE1xima est\xE1 determinada por el dispersal volume del espacio y los l\xEDmites de seguridad A2L. Exceder la carga del fabricante puede: violar los l\xEDmites de seguridad, reducir la eficiencia, y anular la garant\xEDa&quot;,&quot;Depende del espacio disponible&quot;,&quot;Solo est\xE1 limitado por el tama\xF1o del sistema&quot;], respuesta_correcta:1, explicacion:&quot;NO. La carga de R-454B est\xE1 determinada por: (1) las especificaciones del fabricante (que ya optimizaron la carga para m\xE1xima eficiencia), (2) el dispersal volume del espacio (l\xEDmite de seguridad A2L), y (3) los l\xEDmites m1/m2 de los c\xF3digos de instalaci\xF3n. Exceder la carga NO mejora el enfriamiento \u2014 reduce la eficiencia y puede crear condiciones inseguras.&quot; }, { id:&quot;a2l_study_297&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFQu\xE9 debe hacer un t\xE9cnico que descubre que se us\xF3 el aceite incorrecto (mineral en lugar de POE) en un sistema R-32 nuevo?&quot;, opciones:[&quot;Nada \u2014 el sistema funcionar\xE1 igual&quot;,&quot;Recuperar el R-32 en cilindro separado, drenar el aceite mineral incorrecto, hacer nitrogen sweep, instalar nuevos filtros-drier, a\xF1adir la cantidad correcta de POE especificada por el fabricante, recargar con el R-32 recuperado si est\xE1 en buen estado&quot;,&quot;Solo a\xF1adir POE encima del aceite mineral&quot;,&quot;Solo cambiar el filtro-drier&quot;], respuesta_correcta:1, explicacion:&quot;Procedimiento obligatorio cuando hay aceite incorrecto: (1) recuperar el R-32 en cilindro separado para reutilizar si no est\xE1 contaminado, (2) drenar el aceite mineral incorrecto completamente, (3) nitrogen sweep para limpiar residuos, (4) instalar nuevos filtros-drier, (5) a\xF1adir la cantidad exacta de POE especificado por el fabricante, (6) recargar con el R-32 recuperado.&quot; }, { id:&quot;a2l_study_298&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Durante una instalaci\xF3n de sistema R-454B, el t\xE9cnico nota que uno de los componentes (el filtro-drier) tiene etiqueta que dice 'Compatible with HFCs including R-410A' pero NO menciona A2L ni R-454B. \xBFPuede instalarse?&quot;, opciones:[&quot;S\xED \u2014 todos los HFCs son iguales para el drier&quot;,&quot;NO \u2014 label matching requiere que CADA componente est\xE9 espec\xEDficamente certificado para A2L. Un drier certificado solo para R-410A/HFCs A1 puede no tener los materiales internos correctos para A2L. La instalaci\xF3n NO puede proceder&quot;,&quot;S\xED si es del mismo fabricante&quot;,&quot;Solo si es de alta calidad&quot;], respuesta_correcta:1, explicacion:&quot;NO PUEDE INSTALARSE. El principio de label matching es ABSOLUTO: cada componente debe estar certificado espec\xEDficamente para A2L y para el refrigerante espec\xEDfico. Un drier certificado para R-410A puede no tener materiales compatibles con R-454B o no estar dise\xF1ado para ambiente inflamable. Reemplazar con drier certificado A2L.&quot; }, { id:&quot;a2l_study_299&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;Un cliente llama diciendo que su sistema R-32 nuevo tiene un olor extra\xF1o que sali\xF3 de una vez y ya no se repite. \xBFCu\xE1l es la respuesta correcta del t\xE9cnico?&quot;, opciones:[&quot;Decirle que es normal \u2014 los sistemas nuevos tienen olores&quot;,&quot;Investigar la situaci\xF3n: verificar si hubo fuga de R-32 (el R-32 tiene ligero olor perceptible en altas concentraciones), verificar que el sistema est\xE1 funcionando correctamente y que no hay fuga activa. Si hubo fuga, verificar que el \xE1rea fue bien ventilada y que no hay fuentes de ignici\xF3n&quot;,&quot;Solo decirle que ya pas\xF3&quot;,&quot;Solo cambiar el filtro de aire&quot;], respuesta_correcta:1, explicacion:&quot;Un olor inusual en sistema con A2L debe tomarse en serio: (1) puede haber habido una fuga de R-32 (perceptible en altas concentraciones), (2) verificar el sistema para confirmar operaci\xF3n correcta y ausencia de fuga activa, (3) verificar que el \xE1rea fue bien ventilada, (4) documentar el incidente. Si hay fuga activa, seguir el protocolo de evacuaci\xF3n/ventilaci\xF3n.&quot; }, { id:&quot;a2l_study_300&quot;, categoria:&quot;A2L_N3&quot;, nivel:3, pregunta:&quot;\xBFCu\xE1l es la responsabilidad del t\xE9cnico si instala un sistema A2L sin seguir el procedimiento de label matching y posteriormente hay un incidente de ignici\xF3n?&quot;, opciones:[&quot;Ninguna \u2014 es responsabilidad del fabricante&quot;,&quot;El t\xE9cnico tiene responsabilidad legal significativa \u2014 no seguir los procedimientos de instalaci\xF3n requeridos (label matching, c\xF3digos de instalaci\xF3n) puede resultar en: responsabilidad civil por da\xF1os, p\xE9rdida de licencia, y potencialmente procesamiento criminal si hay lesiones&quot;,&quot;Solo pierde la garant\xEDa del fabricante&quot;,&quot;Solo si firm\xF3 algo espec\xEDfico&quot;], respuesta_correcta:1, explicacion:&quot;El t\xE9cnico que instala sin seguir los procedimientos requeridos (label matching, c\xF3digos ASHRAE, UL, etc.) asume responsabilidad legal significativa en caso de incidente. Esto incluye: responsabilidad civil por da\xF1os a propiedad y personas, posible p\xE9rdida de licencia/certificaci\xF3n, y en casos de negligencia grave con lesiones, potencial responsabilidad criminal.&quot; },];",question:"What is the technician's liability if they install an A2L system without following label matching procedures and an ignition incident subsequently occurs?",options:["No responsibility \u2014 the system was installed correctly","Full legal and financial responsibility \u2014 failure to follow label matching and manufacturer procedures means the technician and their company can be held liable for damages, injuries, or deaths resulting from the incident","Only responsibility to replace the component","Only the manufacturer is responsible"],explanation:"Full legal and financial responsibility \u2014 failure to follow label matching and manufacturer procedures means the technician and their company can be held liable for all damages, injuries, or deaths resulting from the incident. The warranty is also voided."},{id:"a2l_301",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l de los siguientes NO es un factor que hace a los A2L m\xE1s seguros que los A3?",opciones:["Mayor MIE (m\xE1s dif\xEDciles de encender)","Mayor LFL (requieren m\xE1s concentraci\xF3n)","Mayor GWP (mayor calentamiento global)","Menor velocidad de llama"],respuesta_correcta:2,explicacion:"El GWP NO es un factor de seguridad \u2014 es un factor ambiental. Los factores de seguridad que hacen a los A2L m\xE1s seguros que A3 son: mayor MIE, mayor LFL, menor calor de combusti\xF3n, y menor velocidad de llama.",question:"Which of the following is NOT a factor that makes A2L safer than A3?",options:["Higher MIE (Minimum Ignition Energy)","Lower GWP (Global Warming Potential)","Lower burning velocity (\u226410 cm/s)","Higher LFL (Lower Flammability Limit)"],explanation:"Lower GWP is an environmental characteristic, NOT a safety factor. The 4 SAFETY factors that make A2L safer than A3 are: (1) higher MIE, (2) higher LFL, (3) lower heat of combustion, and (4) lower burning velocity."},{id:"a2l_302",categoria:"A2L_EXAMEN",pregunta:"La velocidad de llama m\xE1xima para que un refrigerante sea clasificado como A2L es:",opciones:["Menos de 5 cm/s","10 cm/s o menos","Entre 10-46 cm/s","Sin l\xEDmite de velocidad"],respuesta_correcta:1,explicacion:"La definici\xF3n de A2L incluye velocidad de llama de 10 cm/s o MENOS. Esta baja velocidad es parte de por qu\xE9 se les llama 'levemente inflamables' \u2014 el fuego se propaga muy lentamente comparado con A3 (propano: 46 cm/s).",question:"The maximum burning velocity for a refrigerant to be classified as A2L is:",options:["46 cm/s","23 cm/s","10 cm/s","1 cm/s"],explanation:"A2L classification requires a MAXIMUM burning velocity of 10 cm/s. R-32 has 6.7 cm/s, well within the limit. Above 10 cm/s the refrigerant would be classified as A2 (lower flammability) instead of A2L."},{id:"a2l_303",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el nivel de vac\xEDo que debe alcanzarse en el vacuum decay test de una instalaci\xF3n A2L?",opciones:["1,000 micrones","2,000 micrones","500 micrones o menos","5,000 micrones"],respuesta_correcta:2,explicacion:"El objetivo de evacuaci\xF3n para instalaciones A2L es 500 micrones o menos. Despu\xE9s, el decay test verifica que la presi\xF3n no suba m\xE1s de 1,500 micrones en 10 minutos despu\xE9s de aislar el sistema de la bomba.",question:"What is the vacuum level that must be reached in the vacuum decay test of an A2L installation?",options:["1,000 microns","500 microns","200 microns","50 microns"],explanation:"The vacuum decay test requires reaching 500 microns. After reaching this level, the system is isolated from the pump and the pressure rise is monitored for 10 minutes \u2014 no more than 1,500 microns rise."},{id:"a2l_304",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 documento debe entregar el t\xE9cnico al propietario al completar una instalaci\xF3n A2L?",opciones:["Solo la factura del servicio","Los manuales de instalaci\xF3n y servicio del fabricante, revis\xE1ndolos con el propietario","Solo la etiqueta UL del sistema","Solo el n\xFAmero de serie del equipo"],respuesta_correcta:1,explicacion:"Es obligatorio entregar los manuales de instalaci\xF3n y servicio del fabricante al propietario o dejarlos con el equipo. El t\xE9cnico debe tomar tiempo para revisar esta documentaci\xF3n con el propietario.",question:"What document must the technician deliver to the owner upon completing an A2L installation?",options:["Only the invoice","The manufacturer's installation and service manuals","Only the warranty card","Only the system serial number"],explanation:"The manufacturer's installation and service manuals must be delivered to the owner (or left with the equipment). The technician should take time to review them with the owner."},{id:"a2l_305",categoria:"A2L_EXAMEN",pregunta:"Al recuperar A2L de un sistema, \xBFcu\xE1ndo debe moverse el cilindro de recuperaci\xF3n?",opciones:["Puede quedarse donde est\xE1 durante las reparaciones","Inmediatamente despu\xE9s de la recuperaci\xF3n, antes de cualquier trabajo con soplete o herramientas que generen chispa","Solo si el t\xE9cnico quiere mayor comodidad","Solo en trabajos de m\xE1s de 2 horas"],respuesta_correcta:1,explicacion:"El cilindro de A2L recuperado debe moverse a distancia segura del \xE1rea de trabajo INMEDIATAMENTE despu\xE9s de la recuperaci\xF3n y ANTES de usar soplete o cualquier herramienta que genere chispa o arco el\xE9ctrico.",question:"When recovering A2L from a system, when should the recovery cylinder be moved?",options:["After the system is completely repaired","BEFORE any work with fire or sparks \u2014 move the cylinder to a safe distance from the work area","Only when leaving the job","It is not necessary to move it"],explanation:"Move the recovery cylinder to a safe distance from the work area BEFORE any work with fire or sparks \u2014 not after. A cylinder with flammable refrigerant is a hazard source if near fire or sparks."},{id:"a2l_306",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la funci\xF3n principal de los sensores ACTIVOS en sistemas A2L?",opciones:["Solo emitir una alarma sonora","Alarma sonora PLUS activar respuestas autom\xE1ticas: ventilaci\xF3n mec\xE1nica, pump down, y/o apagado del sistema","Solo visual \u2014 no tienen alarma sonora","Activar solo el apagado del compresor"],respuesta_correcta:1,explicacion:"Los sensores activos hacen m\xE1s que alertar \u2014 activan respuestas autom\xE1ticas ante una concentraci\xF3n de refrigerante que supera el umbral: ventilaci\xF3n mec\xE1nica, pump down autom\xE1tico del sistema, y/o apagado completo. Los pasivos solo alarman.",question:"What is the primary function of ACTIVE sensors in A2L systems?",options:["Measure system efficiency","Detect refrigerant leaks and activate ventilation or pump-down to prevent flammable concentrations from accumulating","Measure system temperature","Only for commercial installations"],explanation:"Active sensors detect refrigerant leaks and trigger response actions: activate mechanical ventilation to dilute vapors, trigger automatic pump-down to reduce the amount of refrigerant that can leak, or sound an alarm \u2014 all designed to prevent flammable concentrations from accumulating."},{id:"a2l_307",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el componente del ciclo de refrigeraci\xF3n que debe verificarse PRIMERO al diagnosticar problemas de enfriamiento?",opciones:["El compresor","El airflow (flujo de aire) \u2014 filtro, ventilador, y bobina","La v\xE1lvula de expansi\xF3n","La carga de refrigerante"],respuesta_correcta:1,explicacion:"SIEMPRE verificar el airflow PRIMERO antes de diagnosticar refrigerante. Un airflow incorrecto simula casi cualquier problema de carga de refrigerante. Verificar: filtro limpio, ventilador funcionando a velocidad correcta, y bobina limpia.",question:"What is the refrigeration cycle component that should be checked FIRST when diagnosing cooling problems?",options:["The compressor","The airflow \u2014 verify filter, fan, and coil before diagnosing refrigerant issues","The TXV","The condenser"],explanation:"ALWAYS check AIRFLOW first: clean filter, working fan at the correct speed, clean coil, and CFM/ton per manufacturer specs. Incorrect airflow mimics refrigerant charge problems and can lead to misdiagnosis."},{id:"a2l_308",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 precauci\xF3n aplica al descargar un capacitor en un sistema A2L?",opciones:["No hay diferencias con sistemas A1","Usar resistor o descargador que no genere chispa \u2014 el cortocircuito directo con destornillador est\xE1 PROHIBIDO","Solo usar guantes","No es necesario descargar capacitores en A2L"],respuesta_correcta:1,explicacion:"En sistemas A2L, el cortocircuito directo de capacitores (destornillador en terminales) est\xE1 PROHIBIDO porque genera chispa que puede encender el refrigerante. Usar un descargador con resistencia que disipe la energ\xEDa sin generar chispa.",question:"What precaution applies when discharging a capacitor in an A2L system?",options:["Discharge directly with screwdriver \u2014 faster","Use a resistor or discharge tool that does not generate a spark to avoid potential A2L ignition","It is not necessary to discharge","Wait for it to self-discharge"],explanation:"In A2L systems, use a RESISTOR or spark-free discharge tool. Direct short-circuiting with a screwdriver is PROHIBITED because it generates a spark that could ignite A2L refrigerant in the area."},{id:"a2l_309",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l de los siguientes NO es un elemento requerido en la etiqueta permanente UL de un sistema A2L?",opciones:["Nombre e informaci\xF3n de contacto del contratista","Nivel de vac\xEDo alcanzado","Costo total de la instalaci\xF3n","Carga total de refrigerante (tipo, libras y onzas)"],respuesta_correcta:2,explicacion:"El COSTO de la instalaci\xF3n no es un elemento requerido en la etiqueta permanente UL. Los elementos requeridos son: contratista, nivel de vac\xEDo, presi\xF3n de prueba, fecha, tipo de refrigerante, y carga total.",question:"Which of the following is NOT a required element on the permanent UL label of an A2L system?",options:["Contractor name","Technician's Social Security number","Vacuum level achieved","Refrigerant type and total charge"],explanation:"The technician's Social Security number is NEVER included on the equipment label. The required elements include: contractor/technician name, vacuum level, test pressure, date, refrigerant type, and total charge."},{id:"a2l_310",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el tiempo m\xEDnimo para la prueba de presi\xF3n con nitr\xF3geno en una instalaci\xF3n A2L nueva?",opciones:["15 minutos","30 minutos","60 minutos m\xEDnimo","Solo hasta que estabilice la presi\xF3n"],respuesta_correcta:2,explicacion:"La prueba de presi\xF3n con nitr\xF3geno seco en instalaciones A2L debe durar M\xCDNIMO 60 minutos sin ninguna ca\xEDda de presi\xF3n. Esto verifica que el sistema es completamente herm\xE9tico antes de proceder a evacuar.",question:"What is the minimum time for the nitrogen pressure test in a new A2L installation?",options:["15 minutes","30 minutes","60 minutes","120 minutes"],explanation:"A2L pressure test requires a minimum of 60 minutes with ZERO pressure drop. This is longer than some traditional installations to ensure the integrity of an A2L system where even small leaks release flammable refrigerant."},{id:"a2l_311",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 el refrigerante l\xEDquido es peligroso si contacta la piel o los ojos?",opciones:["No es peligroso \u2014 los refrigerantes modernos son seguros al tacto","Causa quemaduras por fr\xEDo (frostbite) al vaporizarse r\xE1pidamente \u2014 puede causar da\xF1o permanente en los ojos","Solo es peligroso si es t\xF3xico","Solo si el contacto es prolongado"],respuesta_correcta:1,explicacion:"El refrigerante l\xEDquido al vaporizarse r\xE1pidamente en la piel absorbe calor intensamente causando quemaduras por fr\xEDo (frostbite). En los ojos puede causar da\xF1o serio o ceguera permanente. SIEMPRE usar gafas de seguridad y guantes.",question:"Why is liquid refrigerant dangerous if it contacts skin or eyes?",options:["It is not dangerous \u2014 refrigerants are safe on contact","Rapid vaporization causes cold burns (frostbite) on skin and can cause serious eye damage or blindness","Only causes mild irritation","Only dangerous if the refrigerant is toxic"],explanation:"Liquid refrigerant rapidly vaporizing on skin causes COLD BURNS (frostbite). In eyes it can cause permanent damage or blindness. The rapid phase change from liquid to gas absorbs heat from skin/eye tissue causing severe thermal injury."},{id:"a2l_312",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el proceso obligatorio antes de usar soplete en un sistema que ten\xEDa A2L?",opciones:["Solo apagar el sistema","Recuperar el A2L y hacer nitrogen sweep para desplazar vapores de refrigerante en el aceite del sistema","Solo verificar con el olfato que no hay olor","Solo esperar 30 minutos despu\xE9s de recuperar"],respuesta_correcta:1,explicacion:"OBLIGATORIO: (1) recuperar el A2L completamente, (2) nitrogen sweep \u2014 purgar con nitr\xF3geno seco para desplazar vapores de refrigerante que el aceite POE puede retener. Solo entonces es seguro usar soplete.",question:"What is the mandatory process before using a torch on a system that had A2L?",options:["Only turn off the system","Recover the A2L, nitrogen sweep, verify with gas detector that the area is free of flammable vapors, then proceed with torch work","Only open a window","Only ensure there are no visible leaks"],explanation:"Before using torch on a system that had A2L: (1) recover all A2L, (2) nitrogen sweep to displace vapors retained in the oil, (3) verify with gas detector that the area is free of flammable vapors, THEN proceed with torch work."},{id:"a2l_313",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 indican las siglas LOTO y cu\xE1ndo son obligatorias en trabajo con A2L?",opciones:["Lock Out Tag Out \u2014 opcional para t\xE9cnicos con experiencia","Lockout/Tagout \u2014 SIEMPRE obligatorio antes de cualquier trabajo el\xE9ctrico en sistemas A2L, seguido de verificaci\xF3n con mult\xEDmetro de cero voltaje","Solo cuando el cliente lo pide","Solo en instalaciones industriales"],respuesta_correcta:1,explicacion:"LOTO (Lockout/Tagout) es SIEMPRE obligatorio antes de trabajar en sistemas de-energizados. El t\xE9cnico aplica su candado, guarda la \xFAnica llave, y verifica con mult\xEDmetro que NO hay voltaje. En sistemas A2L es especialmente cr\xEDtico porque las chispas el\xE9ctricas pueden encender el refrigerante.",question:"What do the initials LOTO stand for and when are they mandatory in A2L work?",options:["Lock Out / Tag Out \u2014 mandatory whenever working on energized A2L equipment to prevent accidental startup","Label Out / Test Out \u2014 only for testing","Leak Out / Tighten Out \u2014 only for leak repairs","Low Output / Temperature Out \u2014 only for temperature work"],explanation:"LOTO = Lock Out / Tag Out \u2014 mandatory whenever working on energized or potentially energized A2L equipment. The technician locks the disconnect with a padlock (they keep the only key) and tags it to prevent anyone from accidentally re-energizing the system."},{id:"a2l_314",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la consecuencia de instalar tuber\xEDas A2L dentro de paredes SIN protecci\xF3n strike plates?",opciones:["Solo viola la garant\xEDa del fabricante","Viola los c\xF3digos de instalaci\xF3n y crea riesgo de perforaci\xF3n accidental que causar\xEDa fuga de refrigerante inflamable en la pared","Solo es un problema est\xE9tico","No hay consecuencias significativas"],respuesta_correcta:1,explicacion:"Las tuber\xEDas A2L dentro de paredes o pisos deben estar protegidas con strike plates (planchas met\xE1licas). Sin esta protecci\xF3n: (1) viola los c\xF3digos de instalaci\xF3n, (2) crea riesgo de perforaci\xF3n accidental durante trabajos de construcci\xF3n o remodelaci\xF3n, que causar\xEDa fuga de refrigerante inflamable en un espacio cerrado.",question:"What is the consequence of installing A2L tubing inside walls WITHOUT strike plate protection?",options:["No consequences \u2014 tubing inside walls doesn't need protection","Risk of accidental puncture during future construction or renovation, potentially releasing flammable refrigerant into the wall cavity or occupied space","Only affects aesthetics","Only a minor code violation without safety implications"],explanation:"Without strike plates, future construction work (nails, screws, drill bits) could accidentally puncture the A2L tubing, releasing flammable refrigerant into the wall cavity or occupied space \u2014 creating both a refrigerant leak and an ignition hazard."},{id:"a2l_315",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 tipo de extinguidor se requiere al trabajar con refrigerantes A2L?",opciones:["Clase A \u2014 combustibles s\xF3lidos","Clase B (polvo seco) o ABC","Clase C \u2014 equipos el\xE9ctricos \xFAnicamente","Clase D \u2014 metales combustibles"],respuesta_correcta:1,explicacion:"Clase B (polvo seco, Dry Powder) o ABC. La Clase B es el tipo apropiado para gases y l\xEDquidos inflamables. Tenerlo disponible y SABER USARLO antes de comenzar cualquier trabajo con A2L.",question:"What type of fire extinguisher is required when working with A2L refrigerants?",options:["Class A (solid combustibles)","Class B (dry powder) or ABC","Class C (electrical only)","Any available extinguisher"],explanation:"Class B (dry powder) or ABC fire extinguisher. Class B covers flammable gases and liquids. Must be available and the technician must know how to use it before beginning any A2L work."},{id:"a2l_316",categoria:"A2L_EXAMEN",pregunta:"Seg\xFAn las regulaciones, \xBFcu\xE1ntas veces en un per\xEDodo de 3 a\xF1os debe recargarse un sistema A2L para que se considere prueba de fuga?",opciones:["3 veces o m\xE1s","2 veces o m\xE1s","Al menos 1 vez","Solo si se pierde m\xE1s del 20% de la carga"],respuesta_correcta:2,explicacion:"Al menos UNA recarga en un per\xEDodo de 3 a\xF1os se considera prueba de fuga seg\xFAn las regulaciones. Una vez establecida esta evidencia, la fuga debe identificarse, repararse, y verificarse antes de cualquier recarga.",question:"According to regulations, how many times within a 3-year period must an A2L system be recharged for it to be considered proof of a leak?",options:["3 times","2 times","At least once","The number of recharges is not regulated"],explanation:"At least ONCE in a 3-year period constitutes proof of a leak. The leak must be identified, repaired, and documented before recharging. Simply recharging without repair violates regulations."},{id:"a2l_317",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 tipo de herramientas son requeridas al trabajar en ambientes con refrigerantes inflamables A2L?",opciones:["Cualquier herramienta certificada UL","Herramientas certificadas spark-free (sin chispa, sin arco) para ambientes inflamables \u2014 Clase I Divisi\xF3n 2","Solo herramientas manuales","Solo herramientas el\xE9ctricas de doble aislamiento"],respuesta_correcta:1,explicacion:"Los ambientes con A2L son Clase I Divisi\xF3n 2 (NFPA 70/NEC). En estos ambientes se requieren herramientas espec\xEDficamente certificadas para ambientes inflamables (spark-free) \u2014 ni chispas ni arcos el\xE9ctricos que puedan encender el refrigerante.",question:"What type of tools are required when working in environments with flammable A2L refrigerants?",options:["Any standard tools","Spark-free tools certified for flammable environments","Only hand tools","Only insulated tools"],explanation:"Spark-free tools certified for flammable environments per NFPA 70/NEC requirements. Standard tools can generate sparks that could ignite flammable A2L refrigerant concentrations in the work area."},{id:"a2l_318",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 indica el s\xEDmbolo ISO 7010-W021 en la placa de datos de un equipo?",opciones:["Certificaci\xF3n de calidad ISO","Advertencia de llama \u2014 el equipo contiene refrigerante inflamable","Certificaci\xF3n de eficiencia energ\xE9tica","Advertencia de alta tensi\xF3n el\xE9ctrica"],respuesta_correcta:1,explicacion:"El s\xEDmbolo ISO 7010-W021 (tri\xE1ngulo amarillo con llama negra) indica ADVERTENCIA DE LLAMA \u2014 el equipo contiene refrigerante inflamable. Debe estar visible en la placa de datos cerca de donde se indica el tipo y cantidad de refrigerante.",question:"What does the ISO 7010-W021 symbol on an equipment nameplate indicate?",options:["Quality certification","Warning: flammable refrigerant \u2014 flame symbol in yellow triangle","Environmental certification","High voltage warning"],explanation:"ISO 7010-W021 is the flame warning symbol (yellow triangle with black flame) \u2014 it indicates the equipment uses flammable refrigerant and must only be serviced by trained personnel."},{id:"a2l_319",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la distancia m\xEDnima requerida de no fumar al transportar gases inflamables seg\xFAn DOT?",opciones:["10 pies","25 pies","50 pies","100 pies"],respuesta_correcta:1,explicacion:"El DOT proh\xEDbe fumar dentro de 25 pies de gases inflamables durante el transporte. Esta es una de las varias restricciones del DOT para el transporte seguro de refrigerantes inflamables.",question:"What is the minimum no-smoking distance required when transporting flammable gases per DOT?",options:["10 feet","25 feet","50 feet","100 feet"],explanation:"DOT requires no smoking within 25 feet of flammable gases during transport. The technician must also carry written gas inventory, SDS for each refrigerant, and security measures against unauthorized access."},{id:"a2l_320",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1ndo se considera que una v\xE1lvula de alivio de presi\xF3n que se ha activado en un sistema A2L est\xE1 lista para continuar usando?",opciones:["Inmediatamente \u2014 si la presi\xF3n baj\xF3 es segura","Despu\xE9s de inspeccionarla visualmente","NUNCA \u2014 debe reemplazarse con una v\xE1lvula nueva de las mismas especificaciones","Solo despu\xE9s de enviarla a recalibraci\xF3n"],respuesta_correcta:2,explicacion:"Una v\xE1lvula de alivio que se ha activado (abierto) DEBE reemplazarse. Una v\xE1lvula que ya se activ\xF3 puede no cerrar completamente o no abrir a la presi\xF3n correcta en el futuro. SIEMPRE reemplazar con v\xE1lvula nueva de las mismas especificaciones.",question:"When is a pressure relief valve that has been activated on an A2L system considered ready for continued use?",options:["Immediately after it closes \u2014 it is designed to reseat","The valve should be inspected and tested before resuming operation \u2014 if it activated once, the underlying overpressure condition must be identified and corrected","Only after 24 hours of rest","Only after being sent to the factory"],explanation:"A pressure relief valve that has activated should be INSPECTED and TESTED before resuming operation. The underlying overpressure condition that caused activation must be identified and corrected. The valve may have lost proper seating and could leak."},{id:"a2l_321",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1nto puede llenarse M\xC1XIMO un tanque de recuperaci\xF3n con refrigerante A2L?",opciones:["60% de su capacidad","70% de su capacidad","80% de su capacidad","100% de su capacidad"],respuesta_correcta:2,explicacion:"Los tanques de recuperaci\xF3n NO deben llenarse m\xE1s del 80% de su capacidad (f\xF3rmula: WC \xD7 0.80 + TW = peso m\xE1ximo total). El 20% restante permite la expansi\xF3n t\xE9rmica del refrigerante sin riesgo de ruptura.",question:"How much can a recovery tank be filled MAXIMUM with A2L refrigerant?",options:["60%","70%","80%","100%"],explanation:"80% maximum. The remaining 20% provides expansion space. The formula (WC x 0.80) + TW gives the maximum scale weight during recovery."},{id:"a2l_322",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el primer paso al llegar a un trabajo con posible fuga activa de A2L?",opciones:["Conectar el manifold para revisar presiones","Verificar con detector de gases y NO entrar hasta confirmar que el \xE1rea es segura \u2014 evaluar fuentes de ignici\xF3n y ventilar antes de entrar","Apagar el equipo desde el exterior","Llamar a los bomberos inmediatamente"],respuesta_correcta:1,explicacion:"Con posible fuga activa: (1) verificar con detector de gases ANTES de entrar, (2) evaluar fuentes de ignici\xF3n, (3) ventilar el \xE1rea desde el exterior si es posible, (4) verificar que el \xE1rea est\xE9 libre de vapores inflamables ANTES de entrar y comenzar el diagn\xF3stico.",question:"What is the first step upon arriving at a job with a possible active A2L leak?",options:["Connect the manifold to check pressures","Evacuate the area, ventilate, verify with gas detector that it is safe before entering to service","Only turn off the equipment","Only open windows and proceed"],explanation:"EVACUATE the area, VENTILATE, verify with gas detector that it is safe (check low points where vapors accumulate) and free of ignition sources before entering to service. Never assume the concentration is safe."},{id:"a2l_323",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 caracter\xEDstica de los componentes el\xE9ctricos los hace 'intrinsically safe' (IS) para uso con A2L?",opciones:["Consumo de energ\xEDa reducido","Dise\xF1ados para no liberar suficiente energ\xEDa para encender el A2L \u2014 los enclosures contienen cualquier chispa o arco el\xE9ctrico interno","Certificaci\xF3n de mayor eficiencia","Solo una denominaci\xF3n de marketing"],respuesta_correcta:1,explicacion:"Los componentes IS tienen enclosures herm\xE9ticos que contienen cualquier chispa o arco el\xE9ctrico DENTRO del componente, previniendo que se exponga al ambiente donde puede haber vapores de A2L. Si el componente falla internamente, la chispa queda contenida.",question:"What characteristic of electrical components makes them 'intrinsically safe' (IS) for use with A2L?",options:["They have higher efficiency ratings","They are designed so that no internal electrical failure can release enough energy to ignite an A2L-air mixture \u2014 sparks are contained within sealed enclosures","They are waterproof","They have lower voltage ratings"],explanation:"IS components have SEALED ENCLOSURES that contain any internal spark or electrical arc, preventing it from reaching the surrounding atmosphere where A2L vapors might be present. The energy released in a failure stays contained within the enclosure."},{id:"a2l_324",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 los refrigerantes son especialmente peligrosos en espacios confinados aunque sean A1 (no inflamables)?",opciones:["No son peligrosos en espacios confinados si son A1","Todos los refrigerantes (incluyendo A1) pueden causar asfixia al desplazar el ox\xEDgeno del aire \u2014 la mayor\xEDa de accidentes mortales con refrigerantes son por asfixia","Solo los A2L son peligrosos en espacios confinados","Solo en espacios sin ventanas"],respuesta_correcta:1,explicacion:"TODOS los refrigerantes son peligrosos en espacios confinados porque desplazan el ox\xEDgeno del aire, pudiendo causar ASFIXIA. La mayor\xEDa de muertes relacionadas con refrigerantes son por asfixia por falta de ox\xEDgeno, no por toxicidad directa del refrigerante.",question:"Why are refrigerants especially dangerous in confined spaces even if they are A1 (non-flammable)?",options:["They are not dangerous if non-flammable","ALL refrigerants displace oxygen and can cause asphyxiation in confined spaces \u2014 most fatal refrigerant accidents are from ASPHYXIATION, not toxicity or flammability","Only dangerous if the space is very small","Only hydrocarbon refrigerants are dangerous"],explanation:"ALL refrigerants (A1, A2L, A3) displace oxygen from the air in confined spaces. Most FATAL refrigerant accidents are from ASPHYXIATION (oxygen displacement), not from toxicity or flammability. Even non-flammable, non-toxic refrigerants are deadly in confined spaces."},{id:"a2l_325",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el \xE1cido que se forma cuando un refrigerante con fl\xFAor (incluyendo A1 como R-410",opciones:["se quema o se somete a calor extremo?A) \xC1cido clorh\xEDdrico (HCl)","\xC1cido sulf\xFArico (H2SO4)","\xC1cido fluorh\xEDdrico (HF)","\xC1cido n\xEDtrico (HNO3)"],respuesta_correcta:2,explicacion:"El \xE1cido fluorh\xEDdrico (HF) puede formarse cuando CUALQUIER refrigerante con fl\xFAor (incluyendo todos los HFC como R-410A, R-134a, y tambi\xE9n los A2L como R-32) se quema o se somete a calor extremo. El HF es irritante pulmonar y corrosivo en la piel.",question:"What acid is formed when a fluorine-containing refrigerant (including A1 like R-410A) decomposes near an open flame?",options:["Acetic acid (vinegar)","Hydrofluoric acid (HF) \u2014 extremely corrosive and toxic, can penetrate skin and damage bones","Carbon dioxide","Sulfuric acid"],explanation:"When fluorine-containing refrigerants (HFCs, HFOs, including A1 like R-410A) decompose near an open flame or very hot surface, they can form HYDROFLUORIC ACID (HF) \u2014 extremely corrosive and toxic. This is why a one-time odor event near an A2L system should be investigated immediately."},{id:"a2l_326",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el GWP del refrigerante que la EPA y los principales fabricantes han adoptado como sucesor principal del R-410A en residencial?",opciones:["675 \u2014 R-32","733 \u2014 R-466A","466 \u2014 R-454B","2,088 \u2014 R-410A"],respuesta_correcta:2,explicacion:"R-454B con GWP=466 es el sucesor principal del R-410A en residencial. Es el que adoptaron los principales fabricantes (Carrier, Trane, Lennox, etc.) para sus l\xEDneas residenciales nuevas comenzando en 2025.",question:"What is the GWP of the refrigerant that the EPA and major manufacturers have adopted as the primary successor to R-410A in residential?",options:["675 (R-32)","466 (R-454B)","2,088 (R-410A)","733 (R-466A)"],explanation:"R-454B with GWP=466 is the refrigerant adopted by the EPA and major US manufacturers as the primary successor to R-410A in residential applications. It offers a 78% GWP reduction while maintaining similar operating pressures."},{id:"a2l_327",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l de los siguientes refrigerantes A2L es un compuesto PURO (no mezcla) y puede cargarse en gas o l\xEDquido?",opciones:["R-454B","R-452B","R-32","R-466A"],respuesta_correcta:2,explicacion:"R-32 es el \xFAnico refrigerante A2L puro de un solo componente entre los listados. Por ser puro, NO fracciona y puede cargarse como gas o l\xEDquido sin cambiar su composici\xF3n. R-454B y R-452B son mezclas que deben cargarse siempre en l\xEDquido.",question:"Which of the following A2L refrigerants is a PURE compound (not a blend) and can be charged as gas or liquid?",options:["R-454B","R-452B","R-32","R-466A"],explanation:"R-32 is a PURE (single component) refrigerant that does not fractionate and can be charged as gas or liquid. R-454B and R-452B are blends that must be charged as liquid to prevent fractionation."},{id:"a2l_328",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el principio de 'label matching' en la instalaci\xF3n de sistemas A2L?",opciones:["Verificar que la etiqueta del cilindro coincida con el manifold","Verificar que TODOS los componentes del sistema est\xE9n certificados para A2L antes de proceder con la instalaci\xF3n","Asegurarse que las etiquetas del equipo est\xE9n visibles","Verificar que el n\xFAmero de modelo coincida con el manual"],respuesta_correcta:1,explicacion:"Label matching = verificar que CADA componente individual (compresor, condensador, evaporador, TXV, filtro-drier, v\xE1lvulas, etc.) est\xE9 espec\xEDficamente certificado y etiquetado para uso con A2L. Si cualquier componente NO est\xE1 rated para A2L, la instalaci\xF3n NO puede proceder.",question:"What is the principle of 'label matching' in A2L system installation?",options:["Matching cylinder labels to manifold gauges","Verifying that EVERY component (evaporator, condenser, compressor, TXV, valves, drier, etc.) is specifically certified for A2L before proceeding with installation","Making visual labels match","Matching the model number to the manual"],explanation:"Label matching = verifying that EVERY component in the A2L system (evaporator, condenser, compressor, TXV, valves, drier, wiring, etc.) is specifically certified for A2L operation. If ANY component is not rated for A2L, the installation CANNOT proceed."},{id:"a2l_329",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la diferencia cr\xEDtica en la carga entre R-454B y R-32?",opciones:["No hay diferencia","R-454B SIEMPRE debe cargarse en estado L\xCDQUIDO (mezcla zeotr\xF3pica). R-32 puede cargarse como gas O l\xEDquido (refrigerante puro)","R-32 siempre l\xEDquido, R-454B puede ser gas","Ambos deben cargarse siempre en gas"],respuesta_correcta:1,explicacion:"R-454B es mezcla zeotr\xF3pica \u2014 SIEMPRE l\xEDquido para prevenir fraccionamiento (el R-32 m\xE1s vol\xE1til saldr\xEDa primero cambiando la composici\xF3n). R-32 es refrigerante puro \u2014 NO fracciona, puede ser gas o l\xEDquido sin consecuencias.",question:"What is the critical difference in charging between R-454B and R-32?",options:["No difference \u2014 both are charged the same way","R-454B must ALWAYS be charged as LIQUID (zeotropic blend that fractionates). R-32 can be charged as gas OR liquid (pure compound that does not fractionate)","R-32 must be liquid, R-454B can be gas","Both must be charged as gas"],explanation:"R-454B must ALWAYS be charged as LIQUID because it is a zeotropic blend \u2014 charging as gas would cause the more volatile R-32 to exit first, changing the composition. R-32 is a pure compound that does NOT fractionate and can be charged as gas or liquid."},{id:"a2l_330",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el temperature glide aproximado del R-454B?",opciones:["0\xB0F \u2014 es azeotr\xF3pico","Aproximadamente 2.5\xB0F","Aproximadamente 10\xB0F","Aproximadamente 16\xB0F"],respuesta_correcta:1,explicacion:"R-454B tiene glide muy bajo de aproximadamente 2.5\xB0F. Aunque t\xE9cnicamente es zeotr\xF3pico, su glide es tan peque\xF1o que en la pr\xE1ctica se comporta casi como refrigerante puro para los c\xE1lculos de superheat y subcooling.",question:"What is the approximate temperature glide of R-454B?",options:["0\xB0F (azeotropic)","Approximately 1-2\xB0F","Approximately 5-8\xB0F","More than 15\xB0F"],explanation:"R-454B has a temperature glide of approximately 1-2\xB0F. This is relatively small for a zeotropic blend but important for accurate superheat and subcooling calculations using the correct Liquid (bubble) and Vapor (dew) columns of the P/T chart."},{id:"a2l_331",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el aceite lubricante correcto para sistemas con R-32 o R-454B?",opciones:["Aceite mineral (MO)","Aceite alquilbenceno (AB)","Aceite PAG","Aceite POE (Polyolester)"],respuesta_correcta:3,explicacion:"R-32, R-454B y todos los refrigerantes HFC/HFO requieren aceite POE (Polyolester). El aceite mineral NO es miscible con estos refrigerantes y se acumula en el evaporador, reduciendo la eficiencia y eventualmente drenando de lubricaci\xF3n el compresor.",question:"What is the correct lubricant oil for R-32 or R-454B systems?",options:["Mineral oil (MO)","POE oil (Polyolester)","PAG oil","Alkylbenzene oil (AB)"],explanation:"R-32 and R-454B both require POE (Polyolester) oil. Mineral oil is NOT miscible with these HFC/HFO refrigerants and will cause heat transfer problems and compressor lubrication failure if used."},{id:"a2l_332",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 es un refrigerante HFO y por qu\xE9 tiene GWP tan bajo?",opciones:["Un HFC con bajo GWP por regulaci\xF3n","Un hidrofluoroolefin con al menos un doble enlace de carbono \u2014 este doble enlace hace que se degrade r\xE1pidamente en la trop\xF3sfera en d\xEDas/semanas vs a\xF1os para los HFC","Un refrigerante natural como el amoniaco","Un HFC mezclado con agua para reducir el GWP"],respuesta_correcta:1,explicacion:"HFO (Hydrofluoroolefin) = contiene un doble enlace de carbono (C=C). Este doble enlace reacciona r\xE1pidamente con radicales OH en la trop\xF3sfera, degradando el HFO en d\xEDas o semanas. Por eso su GWP es casi cero \u2014 desaparece de la atm\xF3sfera antes de causar calentamiento significativo.",question:"What is an HFO refrigerant and why does it have such low GWP?",options:["A hydrocarbon with low toxicity","A Hydrofluoroolefin with a carbon double bond that degrades rapidly in the atmosphere (days vs years), resulting in GWP<1","A natural refrigerant like CO2","An HFC with modified formula"],explanation:"HFO (Hydrofluoroolefin) contains a carbon DOUBLE BOND that causes rapid degradation in the troposphere (days vs years for HFCs). This rapid atmospheric breakdown results in GWP<1 for pure HFOs like R-1234yf."},{id:"a2l_333",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el RCL (Refrigerant Concentration Limit) del R-32?",opciones:["140,000 PPM","50,000 PPM","36,000 PPM","5,300 PPM"],respuesta_correcta:2,explicacion:"R-32 tiene RCL=36,000 PPM. Este es el l\xEDmite m\xE1s restrictivo entre toxicidad, asfixia e inflamabilidad. Comparado: R-410A (A1)=140,000 PPM, propano (A3)=5,300 PPM. El RCL de A2L es intermedio.",question:"What is the RCL (Refrigerant Concentration Limit) of R-32?",options:["140,000 PPM (same as R-410A)","36,000 PPM","19,000 PPM (same as R-454B)","5,300 PPM (same as propane)"],explanation:"R-32 has RCL=36,000 PPM. The RCL is the most restrictive concentration limit considering toxicity, asphyxiation, and flammability. For comparison: R-410A (A1)=140,000 PPM, R-290 propane (A3)=5,300 PPM."},{id:"a2l_334",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 los cilindros de refrigerante inflamable tienen una banda roja?",opciones:["Indica que el cilindro est\xE1 lleno","AHRI Guideline N requiere que todos los cilindros con refrigerante inflamable tengan una banda roja para identificarlos visualmente como inflamables","Indica que el cilindro necesita recertificaci\xF3n","Indica que el contenido es reciclado"],respuesta_correcta:1,explicacion:"AHRI Guideline N establece que los cilindros con refrigerante inflamable deben tener una BANDA ROJA en la parte superior. Esta codificaci\xF3n visual permite al t\xE9cnico identificar r\xE1pidamente que el contenido es inflamable.",question:"Why do flammable refrigerant cylinders have a red band?",options:["To indicate the cylinder is new","To visually identify that the cylinder contains FLAMMABLE refrigerant per AHRI Guideline N","To indicate the cylinder is for recovery only","To indicate the cylinder is high pressure"],explanation:"AHRI Guideline N establishes that cylinders with flammable refrigerant must have a RED BAND on the top to visually identify them as containing flammable material. All modern refrigerant cylinders use light gray/green bodies."},{id:"a2l_335",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la presi\xF3n aproximada del R-32 a 45\xB0F de temperatura de saturaci\xF3n?",opciones:["68-75 PSI (igual que R-22)","118-125 PSI (igual que R-410A)","133 PSI (ligeramente mayor que R-410A)","200 PSI"],respuesta_correcta:2,explicacion:"R-32 a 45\xB0F de saturaci\xF3n \u2248 133 PSI. Es ligeramente MAYOR que R-410A (~130 PSI) a la misma temperatura. Los manifolds y herramientas deben estar rated para las presiones del R-32 espec\xEDficamente.",question:"What is the approximate pressure of R-32 at 45\xB0F saturation temperature?",options:["68-75 PSI (similar to R-22)","~133 PSI (slightly higher than R-410A)","250 PSI","50 PSI"],explanation:"R-32 at 45\xB0F saturation: approximately 133 PSI. This is slightly higher than R-410A (~130 PSI) at the same temperature. Tools, manifolds, and hoses must be rated for these pressures."},{id:"a2l_336",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l de los siguientes es el \xFAnico refrigerante de bajo GWP con clasificaci\xF3n A1 (no inflamable)?",opciones:["R-32 (GWP=675)","R-454B (GWP=466)","R-466A (GWP=733)","R-1234yf (GWP<1)"],respuesta_correcta:2,explicacion:"R-466A (GWP=733) es el \xFAnico entre los nuevos refrigerantes de bajo GWP con clasificaci\xF3n A1 (NO inflamable). Esto lo hace \xFAnico \u2014 reduce el GWP significativamente comparado con R-410A (2,088) sin requerir las precauciones de seguridad A2L.",question:"Which of the following is the only low-GWP refrigerant with A1 (non-flammable) classification?",options:["R-32","R-454B","R-466A","R-1234yf"],explanation:"R-466A is the only new low-GWP refrigerant that achieves A1 (non-flammable) classification with GWP=733. All other new low-GWP alternatives (R-32, R-454B, R-452B, R-1234yf) are classified A2L."},{id:"a2l_337",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la composici\xF3n del R-454B?",opciones:["R-32 + R-125 + R-1234yf (ternaria)","R-32 (31.6%) + R-1234yf (68.4%) (binaria HFC/HFO)","R-410A + R-1234yf","R-32 \xFAnicamente"],respuesta_correcta:1,explicacion:"R-454B = R-32 (HFC, 31.6%) + R-1234yf (HFO, 68.4%). Esta mezcla binaria combina: las propiedades operativas del R-32 con el muy bajo GWP del R-1234yf, resultando en GWP=466 y presiones similares al R-410A.",question:"What is the composition of R-454B?",options:["R-32 (50%) + R-125 (50%)","R-32 (31.6%) + R-1234yf (68.4%)","R-32 (70%) + R-1234yf (30%)","R-125 + R-1234yf"],explanation:"R-454B = R-32 (31.6%) + R-1234yf (68.4%). This HFC+HFO blend achieves low GWP (466) from the HFO component while maintaining operating pressures similar to R-410A from the HFC component."},{id:"a2l_338",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la temperatura de auto-ignici\xF3n del R-32?",opciones:["200\xB0C (392\xB0F)","405\xB0C (761\xB0F)","648\xB0C (1,198\xB0F)","100\xB0C (212\xB0F)"],respuesta_correcta:2,explicacion:"R-32 tiene auto-ignici\xF3n a 648\xB0C (1,198\xB0F). Esta temperatura es extremadamente alta \u2014 las superficies calientes de equipos HVAC normales (generalmente <200\xB0C) no pueden encender el R-32 por auto-ignici\xF3n.",question:"What is the auto-ignition temperature of R-32?",options:["200\xB0C (392\xB0F)","405\xB0C (761\xB0F)","648\xB0C (1,198\xB0F)","100\xB0C (212\xB0F)"],explanation:"R-32 has an auto-ignition temperature of 648\xB0C (1,198\xB0F). Normal HVAC equipment surfaces never reach this temperature (generally <200\xB0C), meaning hot surfaces on typical equipment cannot ignite R-32."},{id:"a2l_339",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 es el 'fractionation' del R-454B y cu\xE1ndo es un problema?",opciones:["La separaci\xF3n del refrigerante por temperatura \u2014 solo ocurre en invierno","En fugas lentas, el R-32 m\xE1s vol\xE1til puede escapar preferentemente, cambiando gradualmente la composici\xF3n de la mezcla restante y alterando las propiedades del sistema","Solo en cilindros de almacenamiento","El fraccionamiento es siempre beneficioso"],respuesta_correcta:1,explicacion:"Fraccionamiento del R-454B: en fugas lentas, el componente m\xE1s vol\xE1til (R-32) puede escapar a mayor velocidad que el R-1234yf, cambiando gradualmente la composici\xF3n. Esto altera la relaci\xF3n P-T, el GWP efectivo, y puede afectar el desempe\xF1o. Las fugas deben repararse y el sistema recargarse completamente.",question:"What is 'fractionation' of R-454B and when is it a problem?",options:["The process of removing refrigerant from the system","The preferential escape of the more volatile component (R-32) during a slow leak, changing the blend composition \u2014 a problem during slow leaks in zeotropic blends","A chemical reaction with POE oil","Only a problem during storage"],explanation:"Fractionation is the preferential escape of the more volatile component (R-32) during a slow leak in the zeotropic blend R-454B. It changes the remaining composition, affecting P-T relationships and performance. This is why R-454B leaks must be fully repaired and the system completely recharged."},{id:"a2l_340",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 el R-32 se describe a veces como el 'medio componente' del R-410A?",opciones:["Por error \u2014 no tienen relaci\xF3n","R-410A = R-32 (50%) + R-125 (50%). El R-32 es literalmente uno de los dos componentes. Al eliminar el R-125 (GWP=3,500), el resultado es R-32 puro con GWP=675 pero levemente inflamable (A2L)","Solo se parecen en nombre","Solo tienen presiones similares"],respuesta_correcta:1,explicacion:"R-410A es exactamente 50% R-32 + 50% R-125. Al eliminar el R-125 se obtiene R-32 puro. El R-125 se agreg\xF3 originalmente para hacer la mezcla A1 (no inflamable), pero el precio fue aumentar el GWP. El R-32 solo tiene GWP=675 pero es A2L.",question:"Why is R-32 sometimes described as 'half the component' of R-410A?",options:["R-32 has no relation to R-410A","R-410A = R-32 (50%) + R-125 (50%). R-32 is literally half of R-410A by composition. Without R-125, R-32 alone has lower GWP but is A2L instead of A1","R-32 is half the price of R-410A","Only a marketing term"],explanation:"R-410A = R-32 (50%) + R-125 (50%). R-32 is literally one of the two components. Without R-125 (GWP=3,500), R-32 alone has GWP=675 vs R-410A's 2,088. But removing R-125 also removes the flammability suppression, making R-32 A2L instead of A1."},{id:"a2l_341",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1ntos a\xF1os de vigencia tiene la certificaci\xF3n EPA 608?",opciones:["2 a\xF1os","5 a\xF1os","10 a\xF1os","Es permanente \u2014 no expira"],respuesta_correcta:3,explicacion:"La certificaci\xF3n EPA 608 es PERMANENTE \u2014 nunca expira una vez obtenida. Es v\xE1lida de por vida. Esto la diferencia de otras certificaciones como OSHA-10 (5 a\xF1os) o NATE (renovaci\xF3n cada 2 a\xF1os).",question:"How many years is EPA 608 certification valid?",options:["5 years","10 years","25 years","Permanent \u2014 it never expires"],explanation:"EPA 608 certification is PERMANENT \u2014 it never expires. Once obtained, it is valid for life. Different from some other certifications like OSHA-10 (expires) or NATE (requires renewal)."},{id:"a2l_342",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el LFL del R-32 y qu\xE9 significa para la seguridad?",opciones:["2.1% \u2014 igual que propano, muy peligroso","6.2% \u2014 moderadamente inflamable","14.4% \u2014 requiere alta concentraci\xF3n para encenderse, m\xE1s seguro","3.9% \u2014 levemente inflamable"],respuesta_correcta:2,explicacion:"R-32 tiene LFL=14.4%. Esto significa que se necesita una concentraci\xF3n MUY ALTA de R-32 en el aire para que se pueda encender \u2014 m\xE1s del 14.4% del volumen del aire. Comparado con propano (LFL=2.1%), el R-32 es mucho m\xE1s dif\xEDcil de alcanzar condiciones inflamables.",question:"What is the LFL of R-32 and what does it mean for safety?",options:["6.2% \u2014 very easy to ignite","14.4% \u2014 requires high concentration to ignite, making it relatively safe in small leaks as the concentration rarely reaches LFL in open spaces","2.1% \u2014 extremely dangerous","0% \u2014 non-flammable"],explanation:"R-32 LFL=14.4% means the air must contain 14.4% R-32 concentration before it becomes flammable. This is relatively high \u2014 in most real-world leak scenarios in ventilated spaces, R-32 concentration rarely reaches this level, making it relatively safe."},{id:"a2l_343",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 los HFO refrigerantes son levemente inflamables (A2L) si su estructura qu\xEDmica es 'incompleta'?",opciones:["Por error de clasificaci\xF3n \u2014 deber\xEDan ser A1","El doble enlace de carbono (olefin) en la estructura del HFO es el mismo que hace que el refrigerante se degrade r\xE1pido (bajo GWP) y tambi\xE9n lo hace levemente inflamable","Son m\xE1s inflamables que los HFC","Su inflamabilidad viene del fl\xFAor"],respuesta_correcta:1,explicacion:"La misma caracter\xEDstica estructural que da GWP bajo al HFO (el doble enlace de carbono) tambi\xE9n lo hace levemente inflamable. El doble enlace es reactivo \u2014 reacciona r\xE1pido con la atm\xF3sfera (bajo GWP) y tambi\xE9n tiene menor energ\xEDa de activaci\xF3n para la combusti\xF3n (A2L).",question:"Why are HFO refrigerants mildly flammable (A2L) if their chemical structure is 'incomplete'?",options:["They are not flammable \u2014 the classification is wrong","The carbon double bond (unsaturated) that gives them low GWP also makes them slightly reactive and flammable \u2014 the same feature that causes rapid atmospheric degradation also allows combustion","Only because of their molecular weight","Only because the EPA classified them that way"],explanation:"The carbon double bond in HFOs that causes rapid atmospheric degradation (giving them low GWP) also makes the molecule slightly reactive and combustible. The same structural feature that is environmentally beneficial also introduces mild flammability."},{id:"a2l_344",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el MIE del R-1234yf que lo hace el m\xE1s dif\xEDcil de encender entre los A2L?",opciones:["30-100 mJ","100-300 mJ","500-1,000 mJ","5,000-10,000 mJ"],respuesta_correcta:3,explicacion:"R-1234yf tiene MIE=5,000-10,000 mJ \u2014 el m\xE1s alto entre los A2L. Una buj\xEDa de alto voltaje produce solo 20-30 mJ. Esto hace pr\xE1cticamente imposible encender R-1234yf con equipo el\xE9ctrico dom\xE9stico normal, a pesar de su clasificaci\xF3n t\xE9cnica A2L.",question:"What is the MIE of R-1234yf that makes it the most difficult to ignite among A2L refrigerants?",options:["0.25 mJ","30-100 mJ","5,000-10,000 mJ","500 mJ"],explanation:"R-1234yf has MIE=5,000-10,000 mJ \u2014 by far the highest among A2L refrigerants. For comparison: a high-voltage spark plug produces only 20-30 mJ, making it virtually impossible for normal electrical devices to ignite R-1234yf."},{id:"a2l_345",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l de los siguientes refrigerantes tiene el GWP m\xE1s BAJO?",opciones:["R-32 (GWP=675)","R-454B (GWP=466)","R-1234yf (GWP<1)","R-466A (GWP=733)"],respuesta_correcta:2,explicacion:"R-1234yf tiene GWP<1, el m\xE1s bajo entre los listados \u2014 pr\xE1cticamente neutro para el clima. Sin embargo, su uso principal es en A/C automotriz. R-454B (GWP=466) es el de menor GWP para A/C residencial de los que reemplazan R-410A.",question:"Which of the following refrigerants has the LOWEST GWP?",options:["R-32 (GWP=675)","R-454B (GWP=466)","R-1234yf (GWP<1)","R-466A (GWP=733)"],explanation:"R-1234yf has GWP<1, the lowest among the options. R-454B=466, R-32=675, R-466A=733. Pure HFO refrigerants have the lowest GWP due to their rapid atmospheric degradation."},{id:"a2l_346",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l refrigerante fue el primero en ser eliminado por el Protocolo de Montreal por da\xF1o a la capa de ozono?",opciones:["R-22 (HCFC)","R-410A (HF","C) CFC refrigerantes como R-12 y R-11","R-404A (HFC)"],respuesta_correcta:2,explicacion:"Los CFCs (R-12, R-11, R-500, R-502, etc.) fueron los primeros en eliminarse bajo el Protocolo de Montreal (1987). Los HCFCs (R-22) siguieron despu\xE9s. Los HFCs (R-410A, R-134a) no afectan el ozono pero tienen alto GWP, por lo que la Enmienda de Kigali (2016) los est\xE1 reduciendo.",question:"Which refrigerant was the first to be phased out by the Montreal Protocol for ozone layer damage?",options:["R-22 (HCFC)","R-12 (CFC)","R-410A (HFC)","R-134a (HFC)"],explanation:"R-12 (CFC-12, Freon 12) was among the first refrigerants to be phased out by the Montreal Protocol (1987) due to its high ODP. CFC production was banned in the USA in 1996."},{id:"a2l_347",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el GWP del CO2 y por qu\xE9 se usa como referencia?",opciones:["GWP=100","GWP=10","GWP=1 \u2014 es la referencia base","GWP=0"],respuesta_correcta:2,explicacion:"El CO2 (R-744) tiene GWP=1 y es la referencia base por definici\xF3n. TODOS los refrigerantes y gases de efecto invernadero se comparan contra el CO2 \u2014 cu\xE1ntas veces m\xE1s calentamiento causan que 1 kg de CO2 durante 100 a\xF1os.",question:"What is the GWP of CO2 and why is it used as a reference?",options:["GWP=0 \u2014 it is a natural gas","GWP=1 \u2014 it is the baseline reference because it is the most common greenhouse gas used for comparison over 100 years","GWP=100","GWP=10"],explanation:"CO2 (R-744) has GWP=1 by definition \u2014 it is the BASELINE REFERENCE. All other refrigerants' GWP values express how many times more warming potential they have compared to CO2 over 100 years."},{id:"a2l_348",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 ocurre si se mezclan R-32 y R-454B en el mismo sistema de recuperaci\xF3n?",opciones:["No hay problema \u2014 ambos son A2L","Se crea una mezcla con composici\xF3n, relaci\xF3n P-T, y GWP desconocidos que no puede reciclarse ni reclamarse correctamente","Solo reduce la eficiencia","Solo cambia el color del aceite"],respuesta_correcta:1,explicacion:"Mezclar diferentes refrigerantes en el mismo cilindro de recuperaci\xF3n crea una mezcla desconocida con propiedades impredecibles. No puede ser reciclada correctamente ni reclamada a est\xE1ndar ARI 700. SIEMPRE cilindros separados para cada tipo de refrigerante.",question:"What happens if R-32 and R-454B are mixed in the same recovery system?",options:["Nothing \u2014 they can be mixed safely","Contamination of both refrigerants \u2014 they have different compositions and cannot be separated back to their original states. The mixed refrigerant must be sent to a certified reclaimer","Only the color changes","Only the pressure changes slightly"],explanation:"Mixing R-32 and R-454B contaminates BOTH refrigerants. They have different compositions and cannot be separated back to their original states in the field. The contaminated mixed refrigerant must be sent to a certified reclaimer for processing. Always use SEPARATE recovery cylinders for each refrigerant."},{id:"a2l_349",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 diferencia hay entre m1 y m2 en t\xE9rminos de carga m\xE1xima para sistemas A2L?",opciones:["m1 = inicial, m2 = recarga","m1 = carga m\xE1xima SIN estrategias de mitigaci\xF3n. m2 = carga m\xE1xima CON estrategias activas de mitigaci\xF3n instaladas (sensores activos, ventilaci\xF3n mec\xE1nica)","No hay diferencia significativa","m1 = comercial, m2 = residencial"],respuesta_correcta:1,explicacion:"m1 = carga m\xE1xima permitida en instalaciones SIN medidas de mitigaci\xF3n activa. m2 = carga m\xE1xima permitida CUANDO se instalan estrategias de mitigaci\xF3n (sensores activos, ventilaci\xF3n mec\xE1nica, pump down autom\xE1tico). La m2 es mayor porque el riesgo est\xE1 controlado activamente.",question:"What is the difference between m1 and m2 in terms of maximum charge for A2L systems?",options:["m1 and m2 are the same thing","m1 = maximum charge WITHOUT active mitigation measures. m2 = maximum charge WITH active mitigation (sensors, ventilation, pump-down). m2 is always greater than m1","m1 is for residential, m2 for commercial","m1 is metric, m2 is imperial"],explanation:"m1 = maximum refrigerant charge allowed WITHOUT active mitigation measures (sensors, ventilation, pump-down). m2 = maximum charge WITH active mitigation installed and operating. m2 is always greater than m1 because the mitigation measures provide additional safety."},{id:"a2l_350",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la principal diferencia de seguridad entre el R-454B y el R-290 (propano) siendo ambos levemente inflamables?",opciones:["No hay diferencia significativa \u2014 ambos son peligrosos igual","R-454B: MIE=100-300 mJ, LFL=11.8%, vel. llama=5.2 cm/s. R-290: MIE=0.25 mJ, LFL=2.1%, vel. llama=46 cm/s. El R-454B es DR\xC1STICAMENTE m\xE1s dif\xEDcil de encender y menos peligroso si se enciende","R-290 es m\xE1s seguro que R-454B","Solo la diferencia de presi\xF3n importa"],respuesta_correcta:1,explicacion:"La diferencia de seguridad entre R-454B y R-290 es dram\xE1tica: R-290 es A3 (alta inflamabilidad) no A2L. MIE del R-290 es 0.25 mJ (una chispa est\xE1tica puede encenderlo) vs R-454B (100-300 mJ). LFL del R-290 es 2.1% vs 11.8% del R-454B. Velocidad de llama del R-290 es 46 cm/s vs 5.2 cm/s. El R-454B es mucho m\xE1s seguro.",question:"What is the main safety difference between R-454B and R-290 (propane) given both are mildly flammable?",options:["No safety difference \u2014 both are the same flammability class","R-454B has higher MIE (harder to ignite), higher LFL (needs more concentration), lower heat of combustion, and lower burning velocity than R-290 \u2014 all making R-454B significantly safer than propane despite both being technically 'flammable'","R-290 is actually safer than R-454B","Only the GWP is different"],explanation:"R-454B vs R-290 (propane): both are technically flammable, but R-454B has (1) much higher MIE (harder to ignite), (2) higher LFL (needs more concentration), (3) lower heat of combustion (less fire energy), and (4) lower burning velocity. These make R-454B significantly safer than propane in practice."},{id:"a2l_351",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el orden correcto de operaciones para una instalaci\xF3n A2L nueva?",opciones:["Instalar \u2192 cargar \u2192 probar","Evaluar sitio \u2192 label matching \u2192 instalar \u2192 prueba N2 60 min \u2192 evacuaci\xF3n 500 \xB5 \u2192 decay test \u2192 cargar \u2192 etiqueta UL","Cargar \u2192 probar \u2192 ajustar","Solo instalar y encender"],respuesta_correcta:1,explicacion:"El orden correcto es: (1) Evaluar sitio (dispersal volume, ocupaci\xF3n), (2) Label matching de todos los componentes, (3) Instalaci\xF3n con purga N2 durante brazado, (4) Prueba de presi\xF3n N2 60 min sin ca\xEDda, (5) Evacuaci\xF3n a 500 micrones, (6) Decay test, (7) Carga del refrigerante, (8) Etiqueta permanente UL.",question:"What is the correct order of operations for a new A2L installation?",options:["Charge \u2192 leak test \u2192 evacuate","Evaluate site \u2192 label matching \u2192 install with N2 purge during brazing \u2192 N2 pressure test (60 min, zero drop) \u2192 evacuate to 500 microns \u2192 decay test \u2192 charge refrigerant \u2192 permanent UL label","Install \u2192 evacuate \u2192 charge \u2192 verify","Just install and start up"],explanation:"Correct order: (1) Evaluate site for A2L, (2) label matching, (3) install with N2 purge during brazing, (4) N2 pressure test (60 min, zero drop), (5) evacuation to 500 microns, (6) decay test, (7) charge refrigerant by weight, (8) permanent UL label with all required information."},{id:"a2l_352",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el criterio para pasar el vacuum decay test en una instalaci\xF3n A2L?",opciones:["La presi\xF3n no debe subir nada","La presi\xF3n no debe subir m\xE1s de 1,500 micrones en 10 minutos despu\xE9s de aislar el sistema de la bomba","Alcanzar 500 micrones es suficiente","La presi\xF3n puede subir hasta 5,000 micrones"],respuesta_correcta:1,explicacion:"Vacuum decay test: despu\xE9s de alcanzar 500 micrones, aislar el sistema de la bomba. La presi\xF3n NO debe subir m\xE1s de 1,500 micrones en los siguientes 10 minutos. Si sube m\xE1s: hay fuga o humedad \u2014 investigar la causa antes de cargar refrigerante.",question:"What is the criterion for passing the vacuum decay test in an A2L installation?",options:["No pressure rise at all","Pressure must not rise more than 1,500 microns in 10 minutes after isolating from the pump at 500 microns","Only reaching 500 microns is sufficient","Pressure can rise up to 5,000 microns"],explanation:"After reaching 500 microns, isolate from the pump. The pressure must NOT rise more than 1,500 microns in 10 minutes. If it rises more: there is a leak (fast continuous rise) or moisture (slow rise that stabilizes) \u2014 investigate before charging."},{id:"a2l_353",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 es especialmente importante el nitrogen sweep ANTES de usar soplete en sistemas con A2L?",opciones:["Solo para limpiar las tuber\xEDas","El aceite POE puede retener vapores de refrigerante A2L inflamable despu\xE9s de la recuperaci\xF3n \u2014 el nitr\xF3geno los desplaza, previniendo ignici\xF3n cuando se usa soplete","Solo en sistemas grandes","Solo si el sistema ten\xEDa fuga"],respuesta_correcta:1,explicacion:"El aceite POE retiene vapores de refrigerante A2L despu\xE9s de la recuperaci\xF3n. Un nitrogen sweep (purga con N2 seco) desplaza estos vapores antes de usar soplete, previniendo que los vapores residuales en el aceite sean encendidos por la llama del soplete.",question:"Why is nitrogen sweep especially important BEFORE using a torch on systems with A2L?",options:["Only for tradition","System oil (POE) can retain flammable A2L vapors \u2014 nitrogen displaces these trapped vapors making it safe to use a torch. Without nitrogen sweep, residual A2L in the oil could ignite","Only to clean the pipes","Only for systems older than 10 years"],explanation:"After recovering A2L, the POE oil retains dissolved flammable refrigerant vapors. When the torch heats the pipes, these trapped vapors can be released and ignite. Nitrogen sweep displaces these trapped vapors, making torch use safe."},{id:"a2l_354",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1les son los 3 m\xE9todos principales para cargar un sistema de refrigeraci\xF3n?",opciones:["Solo por lectura de presiones","Por peso (escala), por superheat, y por subcooling","Solo por superheat","Solo por lectura visual de la mirilla"],respuesta_correcta:1,explicacion:"Los 3 m\xE9todos principales son: (1) Carga cr\xEDtica por PESO \u2014 m\xE1s precisa, usando escala, (2) Por SUPERHEAT \u2014 apropiado para sistemas con metering fijo (pist\xF3n/cap tube), (3) Por SUBCOOLING \u2014 apropiado para sistemas con TXV. El fabricante especifica cu\xE1l usar.",question:"What are the 3 main methods for charging a refrigeration system?",options:["Only by weight","Critical charge by weight (scale), by superheat, and by subcooling","Only by superheat","Only by sight glass"],explanation:"The three main methods: (1) Critical charge by weight \u2014 most precise, manufacturer-specified, (2) By superheat \u2014 for fixed metering devices (piston/cap tube), (3) By subcooling \u2014 for systems with TXV. The manufacturer specifies which method to use."},{id:"a2l_355",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1ndo deben reutilizarse tuber\xEDas existentes de un sistema R-410A para instalar un sistema R-454B?",opciones:["Nunca \u2014 siempre tuber\xEDas nuevas","Si cumplen est\xE1ndares, son el tama\xF1o correcto, est\xE1n limpias, y pasan prueba de presi\xF3n con nitr\xF3geno. Si el sistema previo fue R-22 con aceite mineral, considerar nitrogen sweep para limpiar residuos","Solo si tienen menos de 5 a\xF1os","Solo si son de cobre tipo L"],respuesta_correcta:1,explicacion:"Las tuber\xEDas pueden reutilizarse SI: cumplen est\xE1ndares, son el tama\xF1o y longitud correctos para el nuevo sistema, est\xE1n limpias, y pasan prueba de presi\xF3n. IMPORTANTE: si el sistema anterior fue R-22 (aceite mineral), considerar nitrogen sweep para eliminar residuos de mineral que son incompatibles con el POE del nuevo sistema.",question:"When should existing tubing from an R-410A system be reused for installing an R-454B system?",options:["Always \u2014 they are universal","Only when verified: tubing meets standards, is the correct size, is clean (no excessive mineral oil residue), and passes the nitrogen pressure test","Never \u2014 always install new tubing","Only if the tubing is less than 5 years old"],explanation:"Only when verified: (1) tubing meets applicable standards, (2) is the correct size and length for the new system, (3) is clean (no contamination, no excessive mineral oil from previous R-22 system), and (4) passes the nitrogen pressure test (60 minutes, zero drop)."},{id:"a2l_356",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 debe hacer el t\xE9cnico cuando identifica un componente sin certificaci\xF3n A2L durante la inspecci\xF3n de label matching?",opciones:["Instalarlo de todas formas si es del mismo tama\xF1o","La instalaci\xF3n NO puede proceder \u2014 ese componente debe reemplazarse con uno certificado A2L antes de continuar","Solo documentarlo y continuar","Solo si es el compresor"],respuesta_correcta:1,explicacion:"El label matching es ABSOLUTO \u2014 si un solo componente no est\xE1 certificado para A2L, la instalaci\xF3n NO puede proceder. Ese componente espec\xEDfico debe ser reemplazado con uno certificado A2L antes de continuar con cualquier parte de la instalaci\xF3n.",question:"What should the technician do when identifying a component without A2L certification during label matching inspection?",options:["Install it anyway \u2014 it will probably work","Stop the installation and replace with the correct A2L-certified component. NEVER install a non-A2L-certified component in an A2L system","Call the manufacturer for verbal approval","Only document it on the label"],explanation:"STOP the installation. Replace the non-certified component with a properly A2L-certified one. NEVER install a component that is not specifically certified for A2L \u2014 it could become an ignition source or fail unsafely in a flammable environment."},{id:"a2l_357",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 protecci\xF3n f\xEDsica requieren las tuber\xEDas A2L que pasan por estructuras de madera (paredes, pisos)?",opciones:["Ninguna \u2014 el cobre es suficientemente resistente","Strike plates (planchas met\xE1licas protectoras) para prevenir perforaciones accidentales por clavos, tornillos, o herramientas","Solo aislamiento t\xE9rmico adicional","Solo est\xE1n bien soldadas"],respuesta_correcta:1,explicacion:"Las tuber\xEDas A2L dentro de estructuras de madera DEBEN tener strike plates (planchas met\xE1licas) para protegerlas de perforaciones accidentales. Una perforaci\xF3n crear\xEDa una fuga de refrigerante inflamable en un espacio potencialmente cerrado \u2014 riesgo de ignici\xF3n.",question:"What physical protection do A2L tubing passing through wood structures (walls, floors) require?",options:["No protection needed","Strike plates or metal shields to prevent accidental punctures from nails, screws, or drill bits during future construction","Only thermal insulation","Only conduit"],explanation:"Strike plates (metal plates) or other metal shields to prevent accidental punctures from nails, screws, or drill bits during future construction or renovation. A punctured A2L line inside a wall releases flammable refrigerant into the structure."},{id:"a2l_358",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 especificaci\xF3n de carga se aplica cuando el fabricante especifica 'critical charge'?",opciones:["A\xF1adir refrigerante hasta que las presiones parezcan normales","Cargar por peso exacto seg\xFAn las especificaciones del fabricante \u2014 la cantidad exacta especificada para el sistema con la longitud de l\xEDnea instalada","Solo hasta que la mirilla quede limpia","Solo el 80% de la carga especificada"],respuesta_correcta:1,explicacion:"Critical charge = cargar por peso EXACTO seg\xFAn especificaciones del fabricante. Es el m\xE9todo m\xE1s preciso. Especialmente importante para sistemas A2L donde la carga m\xE1xima est\xE1 restringida por el dispersal volume y los l\xEDmites de seguridad del c\xF3digo.",question:"What charge specification applies when the manufacturer specifies 'critical charge'?",options:["The maximum EPA-allowed charge","Charge by exact weight per manufacturer specifications \u2014 the factory-specified charge accounts for efficiency, safety limits, and specific line lengths","Charge until pressures stabilize","Charge until sight glass is clear"],explanation:"Critical charge = charge by EXACT WEIGHT per manufacturer specifications. The factory-specified charge accounts for maximum efficiency, A2L safety limits (m1/m2), and the specific line lengths of the installation. Do not add more or less."},{id:"a2l_359",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1ndo DEBE reemplazarse el filtro-drier en un sistema de refrigeraci\xF3n?",opciones:["Solo cuando se bloquea visiblemente","Siempre que el sistema se abra para reparaci\xF3n, y cuando hay evidencia de contaminaci\xF3n","Solo una vez al a\xF1o","Solo despu\xE9s de 10 a\xF1os"],respuesta_correcta:1,explicacion:"El filtro-drier DEBE reemplazarse: (1) SIEMPRE que el sistema se abra para reparaci\xF3n (se expone al aire y absorbe humedad), (2) cuando hay evidencia de humedad o \xE1cidos, (3) despu\xE9s de un burnout de compresor. Un drier saturado es peor que no tenerlo.",question:"When MUST the filter-drier be replaced in a refrigeration system?",options:["Only when completely blocked","Whenever the system is opened for repair, when there is evidence of moisture or acid contamination, and after a compressor burnout","Only once per year","Only after compressor replacement"],explanation:"The filter-drier MUST be replaced: (1) whenever the system is opened for repair (exposure to air = moisture absorption), (2) when moisture or acid contamination is evident, and (3) after a compressor burnout (the drier captures acid and contaminant particles)."},{id:"a2l_360",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 los sistemas de bomba de calor requieren filtros-drier bi-flow?",opciones:["Son m\xE1s baratos","El refrigerante fluye en AMBAS DIRECCIONES dependiendo del modo (enfriamiento vs calefacci\xF3n) \u2014 el bi-flow permite filtraci\xF3n correcta en las dos direcciones","Solo por conveniencia","Solo en sistemas grandes"],respuesta_correcta:1,explicacion:"En una bomba de calor, el ciclo se invierte entre modo enfriamiento y calefacci\xF3n. El refrigerante fluye en una direcci\xF3n en enfriamiento y en la direcci\xF3n opuesta en calefacci\xF3n. Los filtros-drier BI-FLOW est\xE1n dise\xF1ados para filtrar y absorber humedad correctamente en ambas direcciones.",question:"Why do heat pump systems require bi-flow filter-driers?",options:["They don't \u2014 standard driers work fine","Because refrigerant flows in BOTH directions depending on heating/cooling mode \u2014 a standard one-direction drier would block flow in reverse","Only for aesthetic reasons","Only required by some manufacturers"],explanation:"Heat pumps reverse refrigerant flow direction between heating and cooling modes. A standard one-directional drier would block flow in one direction. BI-FLOW driers allow flow in both directions, functioning correctly in both modes."},{id:"a2l_361",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 indica si la presi\xF3n sube R\xC1PIDAMENTE y de manera continua en el decay test?",opciones:["El sistema complet\xF3 la evacuaci\xF3n correctamente","Hay una FUGA activa \u2014 la presi\xF3n sube r\xE1pido porque aire est\xE1 entrando al sistema por una fuga","Hay humedad en el sistema","La bomba de vac\xEDo es demasiado peque\xF1a"],respuesta_correcta:1,explicacion:"Subida R\xC1PIDA y continua de presi\xF3n en el decay test = FUGA en el sistema. El aire est\xE1 entrando activamente por la fuga. Si la presi\xF3n sube lentamente y se estabiliza, generalmente indica humedad (la humedad se evapora hasta alcanzar equilibrio). Si no sube significativamente, la evacuaci\xF3n fue exitosa.",question:"What does it indicate if the pressure rises RAPIDLY and continuously during the decay test?",options:["Normal system behavior","There is a LEAK in the system \u2014 the system cannot maintain vacuum and air is entering through the leak point","Only moisture in the system","The pump is too small"],explanation:"Rapid continuous pressure rise during the decay test = LEAK. The system cannot maintain vacuum because air is entering through a leak point. The leak must be found, repaired, and the test repeated from the beginning."},{id:"a2l_362",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la funci\xF3n del acumulador en la l\xEDnea de succi\xF3n de un sistema de bomba de calor?",opciones:["Almacenar refrigerante adicional","Prevenir que refrigerante l\xEDquido entre al compresor (liquid floodback) \u2014 especialmente importante en sistemas de bomba de calor que pueden tener condiciones de arranque dif\xEDciles","Filtrar el aceite del sistema","Regular el superheat del sistema"],respuesta_correcta:1,explicacion:"El acumulador est\xE1 en la l\xEDnea de succi\xF3n y proporciona espacio para que cualquier l\xEDquido residual se vaporice antes de llegar al compresor. En bombas de calor es especialmente importante porque el cambio de modo y las condiciones de arranque pueden enviar l\xEDquido a la l\xEDnea de succi\xF3n.",question:"What is the function of the accumulator in the suction line of a heat pump system?",options:["Regulate high-side pressure","Prevent liquid refrigerant from entering the compressor, which is especially important in heat pumps where liquid can migrate to the suction during defrost and mode changes","Store extra refrigerant","Filter the oil"],explanation:"The accumulator prevents liquid refrigerant from entering the compressor, which is especially critical in heat pumps where liquid refrigerant can migrate to the suction line during defrost cycles and mode changes (heating to cooling transitions)."},{id:"a2l_363",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 la purga de nitr\xF3geno durante el brazado debe hacerse a BAJA presi\xF3n (\xBD-2 PSI)?",opciones:["La presi\xF3n alta da\xF1a el sistema","La baja presi\xF3n (\xBD-2 PSI) es suficiente para desplazar el ox\xEDgeno sin crear peligro de proyecci\xF3n de metal fundido o accidente","Solo para ahorrar nitr\xF3geno","No importa la presi\xF3n durante el brazado"],respuesta_correcta:1,explicacion:"La purga de nitr\xF3geno durante el brazado a \xBD-2 PSI: (1) es suficiente para desplazar el ox\xEDgeno y prevenir oxidaci\xF3n interna, (2) a presi\xF3n mayor existe riesgo de que el gas desplace metal fundido durante el brazado, (3) la baja presi\xF3n permite verificar f\xE1cilmente que est\xE1 saliendo por el otro extremo.",question:"Why must the nitrogen purge during brazing be done at LOW pressure (1/2-2 PSI)?",options:["Low pressure is not important during N2 purge","To simply displace oxygen without creating danger of molten metal projection or safety hazards \u2014 only 1/2 to 2 PSI is needed to push oxygen out","Only for aesthetic reasons","High pressure is actually recommended"],explanation:"Low pressure (1/2 to 2 PSI) is sufficient to displace oxygen from inside the tubing. High pressure could: (1) project molten brazing material creating safety hazards, (2) blow out the molten joint before it solidifies, or (3) create excessive force in the pipe."},{id:"a2l_364",categoria:"A2L_EXAMEN",pregunta:"\xBFD\xF3nde debe instalarse correctamente el bulbo de la TXV?",opciones:["En la l\xEDnea l\xEDquida cerca del condensador","En la l\xEDnea de succi\xF3n cercano a la salida del evaporador, posici\xF3n 4-8 del reloj, bien aislado del ambiente exterior","En la entrada del evaporador","Junto al compresor"],respuesta_correcta:1,explicacion:"El bulbo de la TXV va en la l\xEDnea de SUCCI\xD3N, cerca de la SALIDA del evaporador. Posici\xF3n correcta: 4-8 del reloj para buen contacto con el refrigerante. Debe estar bien AISLADO del ambiente exterior para que solo mida la temperatura del refrigerante, no la temperatura del aire.",question:"Where should the TXV sensing bulb be correctly installed?",options:["Next to the compressor","On the suction line, close to the evaporator outlet, in the 4 to 8 o'clock position for good thermal contact, insulated from ambient","On the liquid line near the TXV body","On the condenser outlet"],explanation:"The TXV sensing bulb goes on the SUCTION LINE, close to the EVAPORATOR OUTLET, positioned between 4 and 8 o'clock for good thermal contact with the pipe, and insulated from ambient temperature so it only senses refrigerant temperature."},{id:"a2l_365",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la causa m\xE1s com\xFAn del 'TXV hunting' (oscilaci\xF3n continua)?",opciones:["TXV defectuosa \u2014 reemplazar siempre","TXV sobredimensionada para el sistema, bulbo mal posicionado o mal aislado, o superheat ajustado incorrectamente","El sistema tiene exceso de refrigerante","El condensador est\xE1 muy limpio"],respuesta_correcta:1,explicacion:"Las causas m\xE1s comunes de TXV hunting (oscilaci\xF3n): (1) TXV sobredimensionada \u2014 no puede encontrar punto estable de operaci\xF3n a baja carga, (2) bulbo mal posicionado o mal aislado \u2014 mide temperatura incorrecta, (3) ajuste de superheat incorrecto \u2014 la v\xE1lvula oscila alrededor de un punto de ajuste inadecuado.",question:"What is the most common cause of 'TXV hunting' (continuous oscillation)?",options:["TXV stuck closed","Oversized TXV, improperly positioned sensing bulb, or incorrect superheat adjustment \u2014 the valve cannot find equilibrium and oscillates continuously","Only occurs in old TXVs","Only in A2L systems"],explanation:"The most common cause of TXV hunting is an OVERSIZED TXV for the application, a MISPOSITIONED sensing bulb (not making good thermal contact or not properly insulated), or incorrect factory superheat setting. The valve cannot find equilibrium and oscillates between open and closed."},{id:"a2l_366",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la funci\xF3n del gas ballast en la bomba de vac\xEDo y cu\xE1ndo debe CERRARSE?",opciones:["Siempre abierto para mayor eficiencia","Previene condensaci\xF3n de agua en el aceite durante evacuaci\xF3n inicial \u2014 debe CERRARSE para alcanzar el vac\xEDo profundo final (por debajo de 5,000 micrones hacia 500)","Solo para sistemas muy h\xFAmedos","No tiene funci\xF3n pr\xE1ctica"],respuesta_correcta:1,explicacion:"Gas ballast: abierto durante la evacuaci\xF3n inicial previene condensaci\xF3n de agua en el aceite (extiende su vida \xFAtil). Pero con el ballast abierto NO se puede alcanzar el vac\xEDo profundo final. CERRAR el ballast para la etapa final (500 micrones). Esto es especialmente importante para A2L donde el vac\xEDo completo es cr\xEDtico.",question:"What is the function of the gas ballast on the vacuum pump and when should it be CLOSED?",options:["The gas ballast has no function","The gas ballast allows air intake during evacuation to prevent water condensation in the pump oil. It must be CLOSED for the final deep vacuum stage (below 5,000 microns) to reach 500 microns","The gas ballast should always be open","The gas ballast only applies to large pumps"],explanation:"The gas ballast allows air entry to prevent water condensation in the pump oil (useful during the initial degassing stage). It must be CLOSED for the final deep vacuum stage below 5,000 microns \u2014 with ballast open, the pump cannot reach 500 microns."},{id:"a2l_367",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 causa el 'liquid slugging' en un compresor?",opciones:["El compresor trabaja con voltaje alto","Refrigerante L\xCDQUIDO entra al compresor \u2014 no puede comprimirse y causa golpe hidr\xE1ulico que puede romper v\xE1lvulas, anillos o bielas","El compresor trabaja con poco aceite","El sistema tiene presi\xF3n alta excesiva"],respuesta_correcta:1,explicacion:"Liquid slugging = refrigerante l\xEDquido entra al compresor (dise\xF1ado para comprimir vapor). El l\xEDquido es incompresible \u2014 el golpe hidr\xE1ulico puede romper v\xE1lvulas de descarga, anillos del pist\xF3n, connecting rods, o el espejo del cilindro. Es una de las fallas m\xE1s destructivas y costosas.",question:"What causes 'liquid slugging' in a compressor?",options:["Compressor running normally","Liquid refrigerant entering the compressor from the suction line \u2014 the incompressible liquid causes hydraulic hammer that can break discharge valves, piston rings, or connecting rods","Compressor running with low oil","Compressor running with incorrect voltage"],explanation:"Liquid slugging = liquid refrigerant entering the compressor suction. Since liquid is incompressible, it creates a hydraulic hammer on the compression stroke that can break discharge valves, piston rings, or connecting rods. Caused by: TXV stuck open, low evaporator airflow, or refrigerant migration during off-cycle."},{id:"a2l_368",categoria:"A2L_EXAMEN",pregunta:"Despu\xE9s de un compressor burnout, \xBFcu\xE1l es el paso ADICIONAL cr\xEDtico antes de instalar el nuevo compresor?",opciones:["Solo instalar el nuevo compresor","Instalar suction line drier temporal para limpiar el sistema de \xE1cidos y part\xEDculas del burnout","Solo cambiar el aceite","Solo limpiar el exterior del sistema"],respuesta_correcta:1,explicacion:"Despu\xE9s de burnout: (1) recuperar refrigerante en cilindro SEPARADO (contaminado), (2) reemplazar compresor, (3) instalar SUCTION LINE DRIER temporal para capturar \xE1cidos y part\xEDculas que quedaron del burnout, (4) flush, (5) nuevos driers, (6) aceite POE limpio, (7) refrigerante nuevo. El suction line drier limpia el sistema en los primeros ciclos de operaci\xF3n.",question:"After a compressor burnout, what is the critical ADDITIONAL step before installing the new compressor?",options:["No additional steps \u2014 just install the new compressor","Install a suction line drier to capture residual acid and contaminant particles from the burnout, then flush the system, replace liquid line driers, and add clean POE oil","Only change the capacitor","Only change the contactor"],explanation:"After a burnout, the ADDITIONAL critical step is installing a SUCTION LINE DRIER to capture residual acid and contaminant particles from the burnout before they reach the new compressor. Also flush the system, replace liquid line driers, and add clean POE oil."},{id:"a2l_369",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 verifica el t\xE9cnico con la f\xF3rmula (WC \xD7 0.80) + TW durante la recuperaci\xF3n de A2L?",opciones:["La eficiencia de la m\xE1quina de recuperaci\xF3n","El peso m\xE1ximo total del cilindro de recuperaci\xF3n incluyendo el refrigerante \u2014 para no llenarlo m\xE1s del 80% de su capacidad","La presi\xF3n m\xE1xima del sistema","La cantidad total de refrigerante en el sistema"],respuesta_correcta:1,explicacion:"(WC \xD7 0.80) + TW = peso m\xE1ximo total del cilindro lleno al 80%. WC (Water Capacity) y TW (Tare Weight) est\xE1n estampados en el collar del cilindro. Monitorear el peso con la escala durante la recuperaci\xF3n para no exceder este valor.",question:"What does the technician verify with the formula (WC x 0.80) + TW during A2L recovery?",options:["The system pressure","The maximum total weight of the recovery cylinder to ensure it is not filled beyond 80% capacity \u2014 WC (water capacity) x 0.80 + TW (tare weight) = max weight on scale","The refrigerant temperature","The cylinder's next test date"],explanation:"The technician uses (WC x 0.80) + TW to calculate the MAXIMUM WEIGHT the recovery cylinder can show on the scale. WC and TW are stamped on the collar. This ensures the cylinder is not filled beyond 80% capacity, leaving room for thermal expansion."},{id:"a2l_370",categoria:"A2L_EXAMEN",pregunta:"\xBFPor qu\xE9 NUNCA se debe usar ox\xEDgeno para presurizar sistemas HVAC para prueba de fugas?",opciones:["Solo por costo \u2014 el nitr\xF3geno es m\xE1s barato","El ox\xEDgeno a alta presi\xF3n mezclado con aceite de compresor u otros materiales org\xE1nicos puede causar explosi\xF3n \u2014 SIEMPRE usar nitr\xF3geno seco","Solo porque es dif\xEDcil de conseguir","Solo en sistemas con A2L"],respuesta_correcta:1,explicacion:"NUNCA ox\xEDgeno para leak check. El O2 a alta presi\xF3n en presencia de aceite de compresor u otros materiales org\xE1nicos puede crear condiciones de auto-ignici\xF3n y EXPLOSI\xD3N. Esta es una de las reglas de seguridad m\xE1s cr\xEDticas en HVAC/R independientemente del refrigerante.",question:"Why should oxygen NEVER be used to pressurize HVAC systems for leak testing?",options:["Only because it is expensive","Oxygen mixed with compressor oil or other organic materials under pressure can cause a violent EXPLOSION \u2014 always use only dry nitrogen for pressurization","Only because it gives false readings","Only for A2L systems"],explanation:"Oxygen under pressure mixed with compressor oil or other organic materials can self-ignite, causing a violent EXPLOSION. This applies to ALL refrigeration systems, not just A2L. ALWAYS use only dry nitrogen for pressurization and leak testing."},{id:"a2l_371",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1ndo se realiza el 'acid test' del aceite en un sistema de refrigeraci\xF3n?",opciones:["Solo como mantenimiento preventivo anual","Cuando se sospecha burnout, contaminaci\xF3n por humedad, o como parte del diagn\xF3stico de fallas inexplicables del compresor","Solo en sistemas comerciales grandes","No se realiza en campo \u2014 solo en laboratorio"],respuesta_correcta:1,explicacion:"El acid test se realiza cuando: (1) se sospecha compressor burnout, (2) hay evidencia de humedad o contaminaci\xF3n, (3) el sistema tiene problemas inexplicables del compresor, (4) como mantenimiento preventivo en sistemas comerciales. El kit de acid test mide la acidez del aceite y del refrigerante.",question:"When is the 'acid test' of the oil performed in a refrigeration system?",options:["Only during annual maintenance","After a compressor burnout, when moisture or acid contamination is suspected, and during preventive maintenance on commercial systems","Only when the oil changes color","Only after adding new refrigerant"],explanation:"The acid test is performed: (1) after a compressor burnout to determine contamination level, (2) when moisture or acid contamination is suspected (poor system performance, unusual oil color), and (3) during preventive maintenance on commercial systems to catch problems early."},{id:"a2l_372",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 indica cuando la temperatura de salida del condensador (l\xEDnea l\xEDquida) es igual a la temperatura del aire exterior?",opciones:["El condensador est\xE1 trabajando excelentemente","El subcooling es 0\xB0F \u2014 el refrigerante est\xE1 justo en el punto de saturaci\xF3n. Puede haber burbujas de vapor en la l\xEDnea l\xEDquida. El sistema puede necesitar refrigerante o el condensador puede estar sobredimensionado","El sistema est\xE1 en perfectas condiciones","Solo ocurre en climas muy fr\xEDos"],respuesta_correcta:1,explicacion:"Si la temperatura de l\xEDnea l\xEDquida = temperatura de saturaci\xF3n del condensador, el subcooling es 0. Esto puede indicar: (1) sistema bajo en refrigerante, (2) condensador sobredimensionado que sobre-enfr\xEDa naturalmente a 0\xB0F de subcooling (raro), o (3) condici\xF3n de temperatura exterior muy baja. Investigar seg\xFAn el contexto.",question:"What does it indicate when the condenser outlet (liquid line) temperature equals the outdoor air temperature?",options:["Perfect system operation","Zero subcooling \u2014 the refrigerant is not being subcooled below its saturation temperature, indicating possible low charge, dirty condenser, or condenser fan problem","The condenser is oversized","The system has too much refrigerant"],explanation:"If the liquid line temperature equals ambient temperature, there is essentially ZERO subcooling \u2014 the refrigerant is at its saturation temperature and not being subcooled. This can indicate: low charge, dirty condenser, condenser fan problem, or insufficient condenser capacity."},{id:"a2l_373",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 es el 'approach temperature' y c\xF3mo se usa para diagnosticar el condensador?",opciones:["La temperatura del refrigerante en el compresor","La diferencia entre la temperatura de condensaci\xF3n y la temperatura del aire ENTRANDO al condensador \u2014 un approach alto indica condensador sucio o airflow insuficiente","La temperatura del subcooling","Solo para sistemas comerciales"],respuesta_correcta:1,explicacion:"Approach temperature = temperatura de saturaci\xF3n del condensador - temperatura del aire de entrada. Un approach BAJO (bueno) indica condensador eficiente. Un approach ALTO puede indicar: condensador sucio, airflow insuficiente del ventilador, o temperatura ambiente excesiva. \xDAtil para diagnosticar problemas del lado de alta.",question:"What is 'approach temperature' and how is it used to diagnose the condenser?",options:["The temperature of the air leaving the condenser","Condensing saturation temperature minus outdoor air temperature entering the condenser \u2014 low approach = efficient heat transfer, high approach = dirty condenser, insufficient airflow, or other problem","Only measured in commercial systems","The difference between indoor and outdoor temperature"],explanation:"Approach temperature = condensing saturation temperature - outdoor air temperature entering the condenser. A LOW approach (10-15\xB0F) indicates efficient heat transfer. A HIGH approach (>25-30\xB0F) may indicate dirty condenser, insufficient airflow, or other condenser problems."},{id:"a2l_374",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el rango normal de temperature split en el evaporador para A/C residencial correctamente cargado?",opciones:["5-10\xB0F","16-22\xB0F","25-35\xB0F","40-50\xB0F"],respuesta_correcta:1,explicacion:"Temperature split normal = 16-22\xB0F (diferencia entre temperatura de retorno y temperatura de suministro de aire). Menor a 16\xB0F puede indicar: airflow alto, baja carga de refrigerante, o bajo ratio de latente. Mayor a 22\xB0F puede indicar: airflow bajo, alta carga de refrigerante, o alta humedad relativa.",question:"What is the normal temperature split range across the evaporator for properly charged residential A/C?",options:["5-10\xB0F","16-22\xB0F","25-30\xB0F","There is no normal range"],explanation:"Normal temperature split for properly charged residential A/C with adequate airflow: 16-22\xB0F. Below 16\xB0F may indicate high airflow, low charge, or refrigerant problems. Above 22\xB0F may indicate low airflow."},{id:"a2l_375",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la mejor posici\xF3n para instalar el filtro-drier de l\xEDnea l\xEDquida para mayor vida \xFAtil?",opciones:["Cerca del condensador exterior para acceso f\xE1cil","En interiores, cerca del dispositivo de metering (TXV/pist\xF3n) \u2014 menos exposici\xF3n a temperaturas extremas que en el exterior","Verticalmente con el flujo hacia abajo","No importa la posici\xF3n"],respuesta_correcta:1,explicacion:"El filtro-drier de l\xEDnea l\xEDquida instalado EN INTERIORES, cerca del dispositivo de metering, dura m\xE1s porque: (1) est\xE1 protegido de temperaturas extremas del exterior, (2) se expone a menor temperatura c\xEDclica que degrada el desecante, (3) es m\xE1s f\xE1cil verificar su funcionamiento con manifolds.",question:"What is the best position to install the liquid line filter-drier for maximum life?",options:["Near the condenser outdoors","Indoors near the metering device (TXV/piston) \u2014 less exposure to heat extends the desiccant life","Right at the compressor discharge","Location doesn't matter"],explanation:"The liquid line filter-drier lasts longer installed INDOORS near the metering device. Less exposure to outdoor heat and temperature cycling preserves the desiccant material longer than installation near the outdoor condenser."},{id:"a2l_376",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 establece ASHRAE Standard 15.2 y para qu\xE9 tipo de instalaci\xF3n aplica?",opciones:["Est\xE1ndar para chillers de baja presi\xF3n","Standard espec\xEDficamente para aplicaciones residenciales de A2L \u2014 el companion residencial de ASHRAE 15 (comercial)","Solo para instalaciones en California","Solo para sistemas con m\xE1s de 5 toneladas"],respuesta_correcta:1,explicacion:"ASHRAE Standard 15.2 es el est\xE1ndar espec\xEDficamente dise\xF1ado para aplicaciones RESIDENCIALES de A2L. Es el companion residencial del ASHRAE 15 (que cubre aplicaciones comerciales y cuartos de m\xE1quinas).",question:"What does ASHRAE Standard 15.2 establish and what type of installation does it apply to?",options:["Same as ASHRAE 15","Specifically for RESIDENTIAL A2L applications \u2014 covers installation, service, and disposal requirements for A2L systems in dwellings","Only for industrial applications","Only for systems over 5 tons"],explanation:"ASHRAE Standard 15.2 is specifically for RESIDENTIAL A2L applications. It is the residential companion to ASHRAE 15 (commercial). It covers installation requirements, service procedures, and disposal of A2L refrigerants in residential dwellings."},{id:"a2l_377",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la penalidad m\xE1xima por ventilaci\xF3n intencional de refrigerante bajo la Secci\xF3n 608?",opciones:["$500 por incidente","$5,000 por d\xEDa","$44,539 por violaci\xF3n por d\xEDa","$1,000 por libra liberada"],respuesta_correcta:2,explicacion:"La EPA puede imponer multas de hasta $44,539 por d\xEDa por cada violaci\xF3n de las regulaciones de refrigerantes de la Secci\xF3n 608. Adem\xE1s, las violaciones pueden resultar en procesamiento criminal en casos graves.",question:"What is the maximum penalty for intentional refrigerant venting under Section 608?",options:["$500 per incident","$5,000 per day","Up to $44,539 per violation per day, plus possible criminal prosecution","$100 per pound of refrigerant"],explanation:"The EPA can impose fines of up to $44,539 per violation per day under Section 608. Violations can also result in criminal prosecution. Intentional venting is one of the most serious violations."},{id:"a2l_378",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la diferencia entre la Secci\xF3n 608 y la Secci\xF3n 612 de la Clean Air Act?",opciones:["Son lo mismo con diferente n\xFAmero","608: manejo de refrigerantes (recuperaci\xF3n, certificaci\xF3n t\xE9cnicos). 612: evaluaci\xF3n y aprobaci\xF3n de sustitutos para sustancias que agotan el ozono (programa SNAP)","608 es federal, 612 es estatal","Solo aplica la 608 en la pr\xE1ctica"],respuesta_correcta:1,explicacion:"Secci\xF3n 608 = regula el MANEJO de refrigerantes: proh\xEDbe ventilaci\xF3n, requiere recuperaci\xF3n y certificaci\xF3n de t\xE9cnicos. Secci\xF3n 612 = programa SNAP: eval\xFAa y aprueba sustitutos para sustancias que agotan el ozono. De la 612 salieron las aprobaciones de R-32, R-454B y dem\xE1s A2L.",question:"What is the difference between Section 608 and Section 612 of the Clean Air Act?",options:["They are the same section","Section 608 = refrigerant handling (recovery, certification, venting prohibition). Section 612 = SNAP program (evaluation and approval of substitute refrigerants for ODS)","Section 608 is federal, 612 is state","Section 612 replaced Section 608"],explanation:"Section 608 = refrigerant HANDLING (recovery requirements, technician certification, venting prohibition). Section 612 = SNAP PROGRAM (evaluation and approval of substitute refrigerants for ozone-depleting substances). They are complementary but address different aspects."},{id:"a2l_379",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 regula el CFR T\xEDtulo 49 en relaci\xF3n a refrigerantes A2L?",opciones:["Solo la producci\xF3n de refrigerantes","El transporte de materiales peligrosos incluyendo gases inflamables en TODOS los medios de transporte","Solo el transporte mar\xEDtimo","Solo aplica en instalaciones industriales"],respuesta_correcta:1,explicacion:"CFR T\xEDtulo 49 (DOT) regula el transporte de HAZMAT en todos los medios: carretera, ferrocarril, aire y agua. Incluye: clasificaci\xF3n, embalaje, marcado, documentaci\xF3n y capacitaci\xF3n para materiales peligrosos incluyendo gases inflamables como los A2L.",question:"What does CFR Title 49 regulate in relation to A2L refrigerants?",options:["Only air transport of A2L","Transportation of hazardous materials including flammable gases (A2L) in ALL transport modes \u2014 classification, packaging, marking, documentation, and training requirements","Only production of A2L","Only storage of A2L"],explanation:"CFR Title 49 (DOT) regulates the transportation of hazardous materials including flammable gases (A2L) in ALL transport modes \u2014 road, rail, air, water. Covers classification, packaging, marking, documentation, and HAZMAT training requirements."},{id:"a2l_380",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 cubre UL Standard 60335-2-40 (3a edici\xF3n)?",opciones:["Solo equipos industriales","A/C, bombas de calor y deshumidificadores \u2014 la 3a edici\xF3n (2019) agreg\xF3 especificaciones espec\xEDficas para equipos A2L","Solo refrigeraci\xF3n comercial de alta capacidad","Solo motores el\xE9ctricos para HVAC"],respuesta_correcta:1,explicacion:"UL 60335-2-40, 3a edici\xF3n (2019), cubre dise\xF1o y pruebas para A/C, bombas de calor y deshumidificadores. La 3a edici\xF3n espec\xEDficamente agreg\xF3 requerimientos para equipos que usan refrigerantes A2L e incluye ap\xE9ndice con pr\xE1cticas de servicio recomendadas.",question:"What does UL Standard 60335-2-40 (3rd edition) cover?",options:["Only industrial equipment","A/C, heat pumps, and dehumidifiers \u2014 the 3rd edition specifically added requirements for equipment using A2L refrigerants","Only electric motors","Only commercial refrigeration"],explanation:"UL 60335-2-40, 3rd edition (2019), covers A/C, heat pumps, and dehumidifiers. The 3rd edition SPECIFICALLY added requirements for equipment using A2L refrigerants, including safety tests and design specifications."},{id:"a2l_381",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el programa EPA que espec\xEDficamente aprob\xF3 los refrigerantes A2L para uso residencial en USA?",opciones:["EPA Secci\xF3n 608 \u2014 certificaci\xF3n de t\xE9cnicos","EPA SNAP (Significant New Alternatives Policy) \u2014 Secci\xF3n 612, espec\xEDficamente SNAP 23","EPA Secci\xF3n 613 \u2014 eliminaci\xF3n de HFCs","EPA ARI 700 \u2014 pureza de refrigerantes"],respuesta_correcta:1,explicacion:"EPA SNAP (Significant New Alternatives Policy) bajo la Secci\xF3n 612 es el programa que eval\xFAa y aprueba sustitutos para refrigerantes que agotan el ozono. SNAP 23 (publicado 2022) aprob\xF3 espec\xEDficamente R-32, R-454B, R-452B y otros A2L para uso en equipos de A/C residencial y comercial ligero.",question:"What is the EPA program that specifically approved A2L refrigerants for residential use in the USA?",options:["Section 608","SNAP (Significant New Alternatives Policy) under Section 612 \u2014 specifically SNAP 23 approved A2L refrigerants for residential and light commercial A/C","ASHRAE 15.2","OSHA 10"],explanation:"SNAP (Significant New Alternatives Policy) under Section 612 of the Clean Air Act. Specifically, SNAP Rule 23 approved A2L refrigerants (R-32, R-454B, R-452B, R-454A, R-454C, R-457A) for residential and light commercial A/C use."},{id:"a2l_382",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 establece ASHRAE Standard 34 que no establece ASHRAE 15 o 15.2?",opciones:["Los procedimientos de instalaci\xF3n","Las designaciones num\xE9ricas y clasificaciones de seguridad (A1, A2L, A2, A3, B1, etc.) de refrigerantes y los RCL","Los requisitos de ventilaci\xF3n","Las certificaciones de t\xE9cnicos"],respuesta_correcta:1,explicacion:"ASHRAE 34 es espec\xEDficamente el est\xE1ndar para DESIGNACIONES y CLASIFICACIONES de seguridad de refrigerantes. Define: las designaciones num\xE9ricas (R-32, R-454B), las clases de seguridad (A1, A2L, etc.) y los RCL (Refrigerant Concentration Limits). ASHRAE 15 y 15.2 usan estas clasificaciones pero no las definen.",question:"What does ASHRAE Standard 34 establish that ASHRAE 15 or 15.2 does not?",options:["They establish the same things","ASHRAE 34 establishes refrigerant DESIGNATIONS (numbers), SAFETY CLASSIFICATIONS (A1, A2L, etc.), and RCL values \u2014 15 and 15.2 cover installation and operation requirements","ASHRAE 34 covers installation","ASHRAE 34 covers training"],explanation:"ASHRAE 34 establishes refrigerant DESIGNATIONS (the 'R' numbers like R-32, R-454B), SAFETY CLASSIFICATIONS (A1, A2L, A2, A3, B1, B2L), and REFRIGERANT CONCENTRATION LIMITS (RCL). ASHRAE 15 and 15.2 cover installation and operation \u2014 not classification."},{id:"a2l_383",categoria:"A2L_EXAMEN",pregunta:"\xBFEn qu\xE9 posici\xF3n deben almacenarse los cilindros A2L seg\xFAn DOT y por qu\xE9?",opciones:["Horizontal para ahorrar espacio","VERTICAL \u2014 para que el dispositivo de alivio de presi\xF3n est\xE9 en contacto con el espacio de VAPOR, no con l\xEDquido","Cualquier posici\xF3n con cadenas de seguridad","Inclinados a 45\xB0 para seguridad"],respuesta_correcta:1,explicacion:"Los cilindros A2L deben estar VERTICALES. Si el dispositivo de alivio est\xE1 en contacto con el espacio de vapor: si se activa, solo libera vapor. Si estuviera en contacto con l\xEDquido: liberar\xEDa el l\xEDquido que se vaporizar\xEDa explosivamente. La posici\xF3n vertical es obligatoria por esta raz\xF3n de seguridad.",question:"In what position should A2L cylinders be stored per DOT and why?",options:["Horizontal to save space","VERTICAL (upright) so the pressure relief device contacts the vapor space, not liquid \u2014 if the relief device activates over liquid, it would release more refrigerant","Any position is acceptable","Only horizontal with valve up"],explanation:"VERTICAL (upright) per DOT and safety best practices. This ensures the pressure relief device contacts the VAPOR space, not liquid. If the relief device activates over liquid, it would release significantly more refrigerant than over vapor."},{id:"a2l_384",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 requiere OSHA sobre el almacenamiento de refrigerantes inflamables en enclosures?",opciones:["Se pueden almacenar en cualquier enclosure cerrado","Solo en enclosures SEGUROS y VENTILADOS \u2014 OSHA proh\xEDbe almacenar en lockers cerrados, contenedores o espacios confinados sin ventilaci\xF3n adecuada","Solo con sistema de sprinklers","Solo si son menos de 50 lb"],respuesta_correcta:1,explicacion:"OSHA requiere que el almacenamiento de refrigerantes inflamables en enclosures sea en espacios SEGUROS y VENTILADOS. Los lockers cerrados, contenedores, o espacios confinados sin ventilaci\xF3n est\xE1n PROHIBIDOS. Si hay fuga en un espacio sin ventilaci\xF3n, la concentraci\xF3n puede alcanzar niveles inflamables.",question:"What does OSHA require regarding flammable refrigerant storage in enclosures?",options:["No requirements for enclosures","Enclosures for flammable refrigerant storage MUST be ventilated \u2014 OSHA prohibits storage in closed lockers, containers, or confined spaces without adequate ventilation","Only fire extinguisher required nearby","Only for quantities over 1,000 lb"],explanation:"OSHA requires that enclosures for flammable refrigerant storage MUST be ventilated. Storage in closed lockers, containers, or confined spaces without ventilation is PROHIBITED. Ventilation prevents accumulation of flammable concentrations from small leaks."},{id:"a2l_385",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 es el placard NFPA 704 y qu\xE9 indica el cuadrante ROJO?",opciones:["Un extintor especial para A2L","El diamante de identificaci\xF3n de peligros: el cuadrante ROJO indica el nivel de INFLAMABILIDAD (0=ninguna, 1-4=creciente)","Una certificaci\xF3n de calidad del proceso","Un permiso de almacenamiento"],respuesta_correcta:1,explicacion:"NFPA 704 = diamante de cuatro cuadrantes: Azul (health), Rojo (flammability), Amarillo (reactivity), Blanco (special). El cuadrante ROJO indica el nivel de inflamabilidad del material: 0=no inflamable, 1-2=requiere calentamiento moderado, 3=puede encenderse en condiciones normales, 4=vapor se inflama r\xE1pidamente.",question:"What is the NFPA 704 placard and what does the RED quadrant indicate?",options:["An emergency exit sign","NFPA 704 is the hazard identification diamond \u2014 the RED quadrant indicates FLAMMABILITY: 0=not flammable, 1=requires heating, 2=moderate heating, 3=ignites at ambient, 4=vaporizes and burns rapidly","A recycling symbol","A manufacturer quality mark"],explanation:"NFPA 704 is the hazard identification DIAMOND with four colored sections: blue (health), RED (flammability), yellow (reactivity), white (special). The RED quadrant number indicates flammability level: 0=not flammable to 4=extreme fire hazard. A2L refrigerants typically rate 1-2."},{id:"a2l_386",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1ndo puede aumentarse el l\xEDmite de almacenamiento de refrigerantes inflamables por \xE1rea de control?",opciones:["Cuando se obtiene un permiso especial de la EPA","Cuando se instala un sistema de sprinklers activo \u2014 los c\xF3digos permiten aumentar el l\xEDmite de almacenamiento en presencia de sprinklers","Cuando el local tiene m\xE1s de 2,000 sq ft","No puede aumentarse bajo ninguna circunstancia"],respuesta_correcta:1,explicacion:"Los c\xF3digos (OSHA, locales) permiten aumentar el l\xEDmite de almacenamiento de refrigerantes inflamables por \xE1rea de control cuando se instala un SISTEMA DE SPRINKLERS ACTIVO. La cantidad espec\xEDfica del aumento depende del refrigerante y el c\xF3digo local aplicable.",question:"When can the flammable refrigerant storage limit per control area be increased?",options:["It cannot be increased","When an active fire sprinkler system is installed in the storage area \u2014 sprinklers allow increasing the maximum quantity per control area","Only with OSHA approval letter","Only in buildings over 10,000 sq ft"],explanation:"The storage limit per control area can be INCREASED when an active fire sprinkler system is installed. Sprinklers provide an additional safety measure that justifies allowing more flammable material in the area. The exact increase depends on the refrigerant and local code."},{id:"a2l_387",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1les son los 4 factores que hacen a los A2L m\xE1s seguros que los A3 (propano, isobutano)?",opciones:["Menor GWP, menor presi\xF3n, menor costo, menor toxicidad","Mayor MIE, mayor LFL, menor calor de combusti\xF3n, y menor velocidad de llama","Mayor GWP, mayor presi\xF3n, mayor RCL, menor velocidad","Son igual de peligrosos que los A3"],respuesta_correcta:1,explicacion:"Los 4 factores de seguridad A2L vs A3: (1) MIE m\xE1s ALTO = m\xE1s dif\xEDciles de encender con chispa, (2) LFL m\xE1s ALTO = requieren mayor concentraci\xF3n para inflamarse, (3) Calor de combusti\xF3n m\xE1s BAJO = menor energ\xEDa si se queman, (4) Velocidad de llama m\xE1s BAJA = fuego se propaga m\xE1s lentamente.",question:"What are the 4 factors that make A2L safer than A3 (propane, isobutane)?",options:["Lower GWP, lower cost, wider availability, better efficiency","Higher MIE (harder to ignite), higher LFL (needs more concentration), lower heat of combustion (less fire energy), lower burning velocity (fire spreads slower)","Only their lower toxicity","Only their lower operating pressure"],explanation:"The 4 safety factors making A2L safer than A3: (1) Higher MIE = harder to ignite, (2) Higher LFL = requires higher concentration, (3) Lower heat of combustion = less fire energy, (4) Lower burning velocity = fire spreads more slowly. These combined make A2L significantly safer in practice."},{id:"a2l_388",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 refrigerante aprob\xF3 EPA SNAP 23 para refrigeraci\xF3n comercial de temperatura media en supermercados?",opciones:["Solo R-32 y R-454B","R-448A, R-449A y R-449B (sujetos a condiciones de uso restringidas)","Cualquier A2L sin restricciones","Solo R-1234yf"],respuesta_correcta:1,explicacion:"SNAP 23 aprob\xF3 R-448A, R-449A y R-449B para refrigeraci\xF3n comercial de temperatura media (stand-alone units en supermercados). Todos sujetos a condiciones de uso restringidas incluyendo l\xEDmites de carga y requisitos de instalaci\xF3n.",question:"What refrigerant did EPA SNAP 23 approve for medium-temperature commercial refrigeration in supermarkets?",options:["R-32","R-454B","R-448A, R-449A, R-449B \u2014 as replacements for R-404A","Only R-1234yf"],explanation:"EPA SNAP 23 approved R-448A, R-449A, and R-449B as replacements for R-404A (GWP=3,920) in medium-temperature commercial refrigeration including supermarket systems. These are lower-GWP alternatives for the high-GWP R-404A."},{id:"a2l_389",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 establece la Secci\xF3n 608 sobre refrigerantes exentos del mandato de recuperaci\xF3n?",opciones:["Todos los refrigerantes deben recuperarse sin excepci\xF3n","Los refrigerantes HC naturales (R-290 propano, R-600a isobutano) est\xE1n exentos del mandato de recuperaci\xF3n de la Secci\xF3n 608","Solo los refrigerantes de bajo GWP est\xE1n exentos","Solo los sistemas menores de 5 lb est\xE1n exentos"],respuesta_correcta:1,explicacion:"R-290 (propano) y R-600a (isobutano) \u2014 hidrocarburos naturales \u2014 est\xE1n exentos del mandato de recuperaci\xF3n de la Secci\xF3n 608. Para m\xE1s informaci\xF3n sobre sustitutos exentos: epa.gov/snap. Todos los HFC, HCFC, CFC y HFO sint\xE9ticos s\xED deben recuperarse.",question:"What does Section 608 establish about refrigerants exempt from the recovery mandate?",options:["All A2L are exempt","R-290 (propane) and R-600a (isobutane) are natural hydrocarbons EXEMPT from the recovery mandate \u2014 see epa.gov/snap for more information","Only R-32 is exempt","No refrigerants are exempt"],explanation:"Section 608 exempts R-290 (propane) and R-600a (isobutane) from the recovery mandate because they are natural hydrocarbons. All other regulated refrigerants (CFCs, HCFCs, HFCs, HFOs) MUST be recovered before service."},{id:"a2l_390",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1ndo puede el refrigerante A2L recuperado y reciclado usarse en un sistema diferente al original?",opciones:["En cualquier momento si es el mismo tipo de refrigerante","Solo si el otro sistema es propiedad del MISMO due\xF1o o entidad \u2014 para venderse a otros debe pasar por reclamaci\xF3n ARI 700","Solo si lo autoriza el fabricante","Nunca \u2014 el recuperado solo puede reutilizarse en el mismo sistema"],respuesta_correcta:1,explicacion:"El refrigerante recuperado y reciclado puede reutilizarse en: (1) el mismo sistema del que vino, o (2) otro sistema del MISMO due\xF1o o entidad. Para venderse a terceros, debe pasar por RECLAMACI\xD3N (proceso industrial) y cumplir AHRI Standard 700 (pureza equivalente a nuevo).",question:"When can recovered and recycled A2L refrigerant be used in a system different from the original?",options:["Anytime \u2014 recycled refrigerant is universal","Only when it has been RECLAIMED to ARI 700 purity standard at a certified facility \u2014 recycled refrigerant can only be reused in the same owner's equipment or the original system","After passing a simple field test","After being stored for 30 days"],explanation:"Recovered and recycled A2L refrigerant can only be reused in the same owner's equipment or the original system. To be used in a DIFFERENT system/owner, it must be RECLAIMED to ARI 700 purity standard at a certified reclamation facility."},{id:"a2l_391",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 \xE1cido corrosivo puede formarse en el aceite de sistemas con R-454B si hay humedad presente (hidr\xF3lisis del POE)?",opciones:["\xC1cido fluorh\xEDdrico (HF)","\xC1cidos org\xE1nicos por hidr\xF3lisis del POE \u2014 pueden da\xF1ar componentes met\xE1licos y el barniz del motor del compresor","\xC1cido sulf\xFArico","Solo agua \u2014 no hay formaci\xF3n de \xE1cidos"],respuesta_correcta:1,explicacion:"La hidr\xF3lisis del aceite POE (POE + humedad = \xE1cidos org\xE1nicos + esters + alcohol) produce \xE1cidos org\xE1nicos que pueden: (1) corroer componentes met\xE1licos, (2) da\xF1ar el barniz aislante del motor del compresor, (3) tapar orificios de v\xE1lvulas y filtros. Por esto el POE debe mantenerse libre de humedad.",question:"What corrosive acid can form in the oil of R-454B systems if moisture is present (POE hydrolysis)?",options:["Acetic acid (mild)","Organic acids from POE hydrolysis \u2014 can corrode metals, damage compressor motor varnish, and clog valve orifices and filters","Hydrochloric acid","No acids form in POE systems"],explanation:"POE hydrolysis in the presence of moisture produces organic acids (including formic and acetic acids) that can corrode copper tubing, damage compressor motor varnish, and clog metering device orifices and filter-drier screens. This is why moisture control is critical in POE systems."},{id:"a2l_392",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 clasificaci\xF3n de ambiente inflamable asigna NFPA 70 (NEC) a los espacios con gases A2L?",opciones:["Divisi\xF3n 1 \u2014 siempre peligroso","Clase I Divisi\xF3n 2 \u2014 peligroso solo bajo condiciones anormales (como una fuga)","Solo en cuartos de m\xE1quinas industriales","No hay clasificaci\xF3n espec\xEDfica para A2L"],respuesta_correcta:1,explicacion:"Los espacios con potencial de gases inflamables de refrigerante A2L se clasifican como Clase I Divisi\xF3n 2 (NFPA 70/NEC) \u2014 ambiente inflamable solo bajo condiciones anormales (fuga). Esto requiere herramientas y equipos spark-free certificados para Clase I Divisi\xF3n 2.",question:"What flammable atmosphere classification does NFPA 70 (NEC) assign to spaces with A2L gases?",options:["Class II Division 1","Class I Division 2 \u2014 flammable gas environment requiring spark-free, arc-free tools and equipment","No special classification","Class III Division 2"],explanation:"NFPA 70 (NEC) classifies spaces with A2L gases as Class I Division 2 \u2014 a flammable gas environment. This classification requires all tools and electrical equipment in the area to be certified spark-free and arc-free for flammable atmospheres."},{id:"a2l_393",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 cubre UL 60335-2-89 en relaci\xF3n a sistemas A2L?",opciones:["A/C residencial dom\xE9stico","Sistemas de refrigeraci\xF3n comercial split-type con unidades condensadoras remotas que pueden usar A2L","Solo chillers de agua","Solo equipos industriales de alta capacidad"],respuesta_correcta:1,explicacion:"UL 60335-2-89 ('2-89') cubre el dise\xF1o y especificaciones de prueba para sistemas de refrigeraci\xF3n comercial SPLIT-TYPE con unidades condensadoras remotas \u2014 walk-in coolers, refrigeraci\xF3n de supermercados y similares que pueden usar A2L.",question:"What does UL 60335-2-89 cover in relation to A2L systems?",options:["Only industrial refrigeration","Design and test specifications for SPLIT-TYPE commercial refrigeration equipment (walk-in coolers, supermarket systems) that use A2L refrigerants","Only residential A/C","Only heat pumps"],explanation:"UL 60335-2-89 covers the design and test specifications for SPLIT-TYPE commercial refrigeration systems \u2014 equipment with remote condensing units such as walk-in coolers, display cases, and supermarket refrigeration systems that use A2L refrigerants."},{id:"a2l_394",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 documentaci\xF3n debe preparar un negocio que almacena refrigerantes A2L para cumplir con regulaciones locales?",opciones:["Solo el inventario de cantidad","Plan de Manejo de Materiales Peligrosos (HMMP), inventario HMIS, SDS de cada refrigerante, y cumplir con requerimientos del oficial de bomberos","Solo las facturas de compra","No se requiere documentaci\xF3n especial para refrigerantes"],respuesta_correcta:1,explicacion:"Para almacenamiento comercial de A2L: (1) Plan de Manejo de Materiales Peligrosos (HMMP), (2) Hazardous Materials Inventory Statement (HMIS) disponible, (3) Safety Data Sheets (SDS) de cada refrigerante, y (4) cumplir con los requisitos del oficial de bomberos local (que puede requerir permiso, placards NFPA 704, etc.).",question:"What documentation must a business storing A2L refrigerants prepare to comply with local regulations?",options:["Only purchase invoices","Hazardous Materials Management Plan (HMMP), Hazardous Materials Inventory Statement (HMIS), and current SDS for each refrigerant type stored","Only the business license","No documentation is required"],explanation:"For compliance with local regulations, a business storing A2L must prepare: (1) Hazardous Materials Management Plan (HMMP), (2) Hazardous Materials Inventory Statement (HMIS) available on-site, and (3) current Safety Data Sheets (SDS) for each refrigerant type stored."},{id:"a2l_395",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el prop\xF3sito del est\xE1ndar AHRI 700?",opciones:["Certificar t\xE9cnicos de refrigeraci\xF3n","Definir los est\xE1ndares de pureza para refrigerante reclamado para que sea equivalente a refrigerante nuevo y pueda venderse como tal","Establecer precios de refrigerantes","Regular el transporte de refrigerantes"],respuesta_correcta:1,explicacion:"AHRI Standard 700 establece los niveles de pureza que debe cumplir el refrigerante reclamado para ser equivalente a refrigerante nuevo y poder venderse o distribuirse como si fuera nuevo. Solo instalaciones certificadas de reclamaci\xF3n pueden producir refrigerante a est\xE1ndar ARI 700.",question:"What is the purpose of the AHRI 700 standard?",options:["Certification of HVAC technicians","Establishing purity specifications that RECLAIMED refrigerant must meet to be sold as equivalent to new \u2014 the standard for reclaimed refrigerant quality","Rating equipment efficiency","Classifying refrigerant safety"],explanation:"AHRI Standard 700 establishes the PURITY SPECIFICATIONS that RECLAIMED refrigerant must meet to be sold as equivalent to new product. It defines acceptable levels of moisture, non-condensables, acidity, and other contaminants in reclaimed refrigerant."},{id:"a2l_396",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 l\xEDmite de HC (hidrocarburo A3) establece la regulaci\xF3n para cargas en sistemas residenciales en USA?",opciones:["Sin l\xEDmite \u2014 igual que A1","T\xEDpicamente 5.3 oz (150g) o menos","50 lb igual que cualquier refrigerante","Solo limitado por el volumen del espacio"],respuesta_correcta:1,explicacion:"Los HC (R-290 propano, R-600a isobutano) por su alta inflamabilidad (A3) est\xE1n limitados a cargas muy peque\xF1as en USA \u2014 t\xEDpicamente 5.3 oz (150g) o menos. Esto limita su aplicaci\xF3n principalmente a refrigeraci\xF3n dom\xE9stica peque\xF1a y equipos especialmente dise\xF1ados.",question:"What HC (A3 hydrocarbon) charge limit does regulation establish for residential systems in the USA?",options:["No charge limit for HC in USA","Maximum 150g (approximately 5.3 oz) per refrigerant circuit for A3 hydrocarbons in residential self-contained equipment","1 pound per system","5 pounds per system"],explanation:"For A3 hydrocarbon refrigerants (propane R-290, isobutane R-600a) in residential self-contained equipment in the USA: maximum charge of 150 grams (approximately 5.3 oz) per refrigerant circuit. This severely limits applications to very small systems."},{id:"a2l_397",categoria:"A2L_EXAMEN",pregunta:"\xBFQu\xE9 responsabilidad asume el t\xE9cnico que instala un sistema A2L sin seguir label matching ni los c\xF3digos de instalaci\xF3n?",opciones:["Ninguna \u2014 es responsabilidad del fabricante","Responsabilidad legal significativa: civil (da\xF1os a propiedad y personas), posible p\xE9rdida de licencia/certificaci\xF3n, y en casos de negligencia grave con lesiones, potencial responsabilidad criminal","Solo pierde la garant\xEDa del fabricante","Solo si firma un contrato de responsabilidad"],respuesta_correcta:1,explicacion:"El t\xE9cnico que instala sin seguir label matching, c\xF3digos ASHRAE 15.2, UL, y dem\xE1s requisitos asume responsabilidad legal si hay un incidente: (1) responsabilidad civil por da\xF1os, (2) posible p\xE9rdida de licencia y certificaciones, (3) en casos de negligencia grave con lesiones o muerte, potencial responsabilidad criminal.",question:"What liability does a technician assume who installs an A2L system without following label matching or installation codes?",options:["No responsibility \u2014 they followed general installation practices","Full legal liability for code violations, potential criminal prosecution if an incident occurs, voided manufacturer warranty, and possible loss of EPA certification","Only the manufacturer is responsible","Only financial responsibility for the equipment cost"],explanation:"Full legal liability: code violations, potential criminal prosecution if an incident causes injury or death, voided manufacturer warranty, possible loss of EPA 608 certification, and personal/company civil liability for all resulting damages."},{id:"a2l_398",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el per\xEDodo de vigencia de los cilindros de recuperaci\xF3n DOT antes de la prueba hidrost\xE1tica obligatoria?",opciones:["2 a\xF1os","5 a\xF1os","10 a\xF1os","Son permanentes"],respuesta_correcta:1,explicacion:"Los cilindros de recuperaci\xF3n DOT tienen un per\xEDodo de certificaci\xF3n de 5 a\xF1os antes de requerir prueba hidrost\xE1tica. La fecha de fabricaci\xF3n y la fecha de retest est\xE1n estampadas en el collar del cilindro. Un cilindro con per\xEDodo vencido NO puede usarse legalmente.",question:"What is the validity period of DOT recovery cylinders before mandatory hydrostatic testing?",options:["2 years","5 years \u2014 the manufacture date and retest date are stamped on the cylinder collar","10 years","They never expire"],explanation:"DOT recovery cylinders must undergo hydrostatic testing every 5 YEARS. The manufacture date and retest date are stamped on the cylinder collar. An expired cylinder cannot be legally used for recovery or transport of refrigerant."},{id:"a2l_399",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es la evaluaci\xF3n m\xEDnima que debe realizar el t\xE9cnico al llegar a una nueva instalaci\xF3n A2L seg\xFAn ASHRAE 15.2?",opciones:["Solo verificar que el equipo quepa f\xEDsicamente","Evaluar: volumen del espacio (dispersal volume), clasificaci\xF3n de ocupaci\xF3n, fuentes de ignici\xF3n cercanas, y verificar que la carga del sistema no exceda los l\xEDmites m1 o m2 para esa ubicaci\xF3n espec\xEDfica","Solo verificar el acceso el\xE9ctrico","Solo verificar que el cliente firm\xF3 el contrato"],respuesta_correcta:1,explicacion:"ASHRAE 15.2 requiere que antes de instalar un sistema A2L en una ubicaci\xF3n residencial, el t\xE9cnico eval\xFAe: (1) volumen del espacio para verificar dispersal volume suficiente, (2) clasificaci\xF3n de ocupaci\xF3n, (3) fuentes potenciales de ignici\xF3n, y (4) que la carga del sistema no exceda los l\xEDmites m1 o m2 aplicables.",question:"What is the minimum evaluation the technician must perform upon arriving at a new A2L installation per ASHRAE 15.2?",options:["Only check that the equipment is the right size","Evaluate: space volume (dispersal volume), occupancy classification, potential ignition sources, maximum charge compliance (m1/m2), and verify the site meets ASHRAE 15.2 requirements before beginning installation","Only check electrical connections","Only verify the refrigerant type"],explanation:"Per ASHRAE 15.2, the technician must evaluate: (1) space volume (dispersal volume), (2) occupancy classification, (3) potential ignition sources nearby, (4) maximum charge compliance (m1 without mitigation, m2 with mitigation), and (5) verify the site meets all ASHRAE 15.2 requirements before starting."},{id:"a2l_400",categoria:"A2L_EXAMEN",pregunta:"\xBFCu\xE1l es el resumen completo de los pasos obligatorios para una instalaci\xF3n A2L que cumple todos los c\xF3digos?",opciones:["Solo instalar y conectar","Evaluar sitio \u2192 label matching \u2192 instalar con purga N2 \u2192 prueba presi\xF3n N2 60min \u2192 evacuaci\xF3n 500\xB5 \u2192 decay test \u2192 cargar \u2192 etiqueta UL permanente \u2192 entregar manuales al propietario","Solo obtener permiso y cargar el refrigerante","Solo verificar la placa de datos del equipo"],respuesta_correcta:1,explicacion:"Instalaci\xF3n A2L compliant: (1) Evaluar sitio (ASHRAE 15.2), (2) Label matching TODOS los componentes, (3) Instalaci\xF3n con purga de N2 durante brazado, (4) Prueba de presi\xF3n N2 m\xEDnimo 60 minutos \u2014 cero ca\xEDda, (5) Evacuaci\xF3n a 500 micrones, (6) Decay test \u2014 no m\xE1s de 1,500 \xB5 en 10 min, (7) Cargar refrigerante correctamente, (8) Llenar etiqueta permanente UL, (9) Entregar manuales al propietario.CLAVE DE RESPUESTAS \u2014 EXAMEN OFICIAL A2L1. C2. B3. C4. B5. B6. B7. B8. B9. C10. C11. B12. B13. B14. B15. B16. C17. B18. B19. B20. C21. C22. B23. B24. B25. C26. C27. C28. B29. B30. B31. D32. B33. C34. B35. C36. C37. B38. C39. B40. B41. D42. C43. B44. D45. C46. C47. C48. B49. B50. B51. B52. B53. B54. B55. B56. B57. B58. B59. B60. B61. B62. B63. B64. B65. B66. B67. B68. B69. B70. B71. B72. B73. B74. B75. B76. B77. C78. B79. B80. B81. B82. B83. B84. B85. B86. B87. B88. B89. B90. B91. B92. B93. B94. B95. B96. B97. B98. B99. B100. BARRAY JAVASCRIPT \u2014 PEGA EN questions.js (EXAMEN OFICIAL)export const A2L_EXAM_QUESTIONS = [ { id:&quot;a2l_exam_1&quot;, categoria:&quot;A2L_EXAMEN&quot;, seccion:&quot;",question:"What is the complete summary of mandatory steps for an A2L installation that complies with all codes?",options:["Install \u2192 charge \u2192 done","Evaluate site \u2192 label matching \u2192 install with N2 purge \u2192 pressure test (60 min zero drop) \u2192 evacuate to 500 microns \u2192 decay test (\u22641,500 micron rise in 10 min) \u2192 charge by weight \u2192 permanent UL label \u2192 documentation to owner","Evacuate \u2192 charge \u2192 test","Only follow manufacturer quick-start guide"],explanation:"Complete A2L installation steps: (1) Site evaluation per ASHRAE 15.2, (2) Label matching ALL components, (3) Install with N2 purge during brazing, (4) N2 pressure test (60 min, zero drop), (5) Evacuate to 500 microns, (6) Decay test (\u22641,500 micron rise in 10 min), (7) Charge by weight, (8) Permanent UL label, (9) Deliver documentation to owner."}],A2L_CATEGORIAS={A2L_CONCEPTOS:{nombre:"Nivel 1 \u2014 Conceptos B\xE1sicos",en:"Level 1 \u2014 Basic Concepts",icon:"\u{1F4D8}",color:"#1565C0",count:100},A2L_CAMPO:{nombre:"Nivel 2 \u2014 Aplicaci\xF3n en Campo",en:"Level 2 \u2014 Field Application",icon:"\u{1F527}",color:"#E65100",count:100},A2L_AVANZADO:{nombre:"Nivel 3 \u2014 Diagn\xF3stico Avanzado",en:"Level 3 \u2014 Advanced Diagnostics",icon:"\u26A1",color:"#4527A0",count:100},A2L_EXAMEN:{nombre:"Examen Oficial ACVOLT",en:"Official ACVOLT Exam",icon:"\u{1F4DD}",color:"#2E7D32",count:100}};
